\section{Virtual double categories and enrichment over them}\label{sec:vdbl-and-enrichment}

\subsection{Virtual double categories}\label{subsec:vdbl}
We recall the notions of virtual double category, virtual double functor, and vertical transformation, and fix our notation. Modern references include \cite{Leinster-HOHC,Cruttwell-Shulman-unified}: the name virtual double category was introduced in \cite{Cruttwell-Shulman-unified}; in \cite{Leinster-generalized-enrichment,Leinster-HOHC} they were known as {\em fc-multicategories}.

\begin{definition}
A \emph{virtual double category} $\vdcat{A}$ consists of the following data.
\begin{itemize}
    \item First we have a category $\vdcat{A}_\vc$ called the \emph{vertical category} of $\vdcat{A}$. The objects of $\vdcat{A}_\vc$ are called the \emph{objects} of $\vdcat{A}$ and the morphisms of $\vdcat{A}_\vc$ are called the \emph{vertical morphisms} of $\vdcat{A}$. A typical vertical morphism $u\colon A\to B$ and the identity vertical morphism $\id_A\colon A\to A$ on an object $A$ are denoted by  
\[
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(0) at (0,0.75) {$A$};
      \node(1) at (0,-0.75) {$B$};
      \draw [->] (0) to node[auto, labelsize] {$u$} (1); 
\end{tikzpicture}\qquad \text{and}\qquad 
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(0) at (0,0.75) {$A$};
      \node(1) at (0,-0.75) {$A$};
      \draw [double equal sign distance] (0) to (1); 
\end{tikzpicture}
\]
    respectively.
    \item For each pair of objects $A,A'$ of $\vdcat{A}$, we have a set of \emph{horizontal morphisms} from $A$ to $A'$. A typical horizontal morphism $\Gamma$ from $A$ to $A'$ is denoted by 
\[
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(0) at (0,0) {$A$};
      \node(1) at (1.5,0) {$A'$.};
      \draw [pto] (0) to node[auto, labelsize] {$\Gamma$} (1); 
\end{tikzpicture}
\]
    \item For each natural number $n$ and each configuration
\begin{equation}
\label{eqn:boundary-of-2-cell-in-vdc}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(00) at (0,0.75) {$A_0$};
      \node(01) at (1.5,0.75) {$A_1$};
      \node(02) at (3,0.75) {$\cdots$};
      \node(03) at (4.5,0.75) {$A_n$};
      \node(10) at (0,-0.75) {$B$};
      \node(11) at (4.5,-0.75) {$B'$}; 
      \draw [pto] (00) to node[auto, labelsize] {$\Gamma_1$} (01);  
      \draw [pto] (01) to node[auto, labelsize] {$\Gamma_2$} (02);  
      \draw [pto] (02) to node[auto, labelsize] {$\Gamma_n$} (03);  
      \draw [pto] (10) to node[auto, swap, labelsize] {$\Delta$} (11); 
      \draw [->] (00) to node[auto, swap, labelsize] {$u$} (10); 
      \draw [->] (03) to node[auto,labelsize] {$u'$} (11);
\end{tikzpicture}    
\end{equation}
    in $\vdcat{A}$, we have a set of \emph{multicells} having \eqref{eqn:boundary-of-2-cell-in-vdc} as the boundary. If $\theta$ is such a multicell, we denote it by 
\begin{equation*}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(00) at (0,0.75) {$A_0$};
      \node(01) at (1.5,0.75) {$A_1$};
      \node(02) at (3,0.75) {$\cdots$};
      \node(03) at (4.5,0.75) {$A_n$};
      \node(10) at (0,-0.75) {$B$};
      \node(11) at (4.5,-0.75) {$B'$.}; 
      \draw [pto] (00) to node[auto, labelsize] {$\Gamma_1$} (01);  
      \draw [pto] (01) to node[auto, labelsize] {$\Gamma_2$} (02);  
      \draw [pto] (02) to node[auto, labelsize] {$\Gamma_n$} (03);  
      \draw [pto] (10) to node[auto, swap, labelsize] {$\Delta$} (11); 
      \draw [->] (00) to node[auto, swap, labelsize] {$u$} (10); 
      \draw [->] (03) to node[auto,labelsize] {$u'$} (11);
      \node at (2.25,0) {$\theta$}; 
\end{tikzpicture}
\end{equation*}
    Notice that in the special case $n=0$, we have 
\begin{equation*}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(00) at (0.75,0.75) {$A_0$};
      \node(10) at (0,-0.75) {$B$};
      \node(11) at (1.5,-0.75) {$B'$.}; 
      \draw [pto] (10) to node[auto, swap, labelsize] {$\Delta$} (11); 
      \draw [->] (00) to node[auto, swap, labelsize] {$u$} (10); 
      \draw [->] (00) to node[auto,labelsize] {$u'$} (11);
      \node at (0.75,-0.2) {$\theta$}; 
\end{tikzpicture}
\end{equation*}
    A \emph{cell} in $\vdcat{A}$ is a multicell in $\vdcat{A}$ of the form   
    \begin{equation*}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(00) at (0,0.75) {$A_0$};
      \node(01) at (1.5,0.75) {$A_1$};
      \node(10) at (0,-0.75) {$B$};
      \node(11) at (1.5,-0.75) {$B'$.}; 
      \draw [pto] (00) to node[auto, labelsize] {$\Gamma_1$} (01);  
      \draw [pto] (10) to node[auto, swap, labelsize] {$\Delta$} (11); 
      \draw [->] (00) to node[auto, swap, labelsize] {$u$} (10); 
      \draw [->] (01) to node[auto, labelsize] {$u'$} (11);
      \node at (0.75,0) {$\theta$}; 
\end{tikzpicture}
\end{equation*}
    \item For each horizontal morphism $\Gamma\colon A\pto A'$ in $\vdcat{A}$, we have a cell
\begin{equation*}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(00) at (0,0.75) {$A$};
      \node(01) at (1.5,0.75) {$A'$};
      \node(10) at (0,-0.75) {$A$};
      \node(11) at (1.5,-0.75) {$A'$}; 
      \draw [pto] (00) to node[auto, labelsize] {$\Gamma$} (01);  
      \draw [pto] (10) to node[auto, swap, labelsize] {$\Gamma$} (11); 
      \draw [double equal sign distance] (00) to (10); 
      \draw [double equal sign distance] (01) to (11);
      \node at (0.75,0) {$\id_\Gamma$}; 
\end{tikzpicture}
\end{equation*}
    called the \emph{vertical identity cell} of $\Gamma$. We often denote it by 
\begin{equation*}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(00) at (0,0.75) {$A$};
      \node(01) at (1.5,0.75) {$A'$};
      \node(10) at (0,-0.75) {$A$};
      \node(11) at (1.5,-0.75) {$A'$.}; 
      \draw [pto] (00) to node[auto, labelsize] {$\Gamma$} (01);  
      \draw [pto] (10) to node[auto, swap, labelsize] {$\Gamma$} (11); 
      \draw [double equal sign distance] (00) to (10); 
      \draw [double equal sign distance] (01) to (11); 
\end{tikzpicture}
\end{equation*}
    \item For each natural number $m$, each $m$-tuple of natural numbers $(n_1,\dots,n_m)$, and each configuration 
\begin{equation}
\label{eqn:composable-multicells-A}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(00) at (0,1.5) {$A_{1,0}$};
      \node(01) at (2,1.5) {$\cdots$};
      \node(02) at (4,1.5) {$A_{1,n_1}$};
      \node(03) at (6,1.5) {$\cdots$};
      \node(04) at (8,1.5) {$A_{m,0}$};
      \node(05) at (10,1.5) {$\cdots$};
      \node(06) at (12,1.5) {$A_{m,n_m}$};
      \node(10) at (0,0) {$B_0$};
      \node(11) at (4,0) {$B_1$}; 
      \node(12) at (6,0) {$\cdots$}; 
      \node(13) at (8,0) {$B_{m-1}$};
      \node(14) at (12,0) {$B_m$}; 
      \node(20) at (0,-1.5) {$C$};
      \node(21) at (12,-1.5) {$C'$}; 
      \draw [pto] (00) to node[auto, labelsize] {$\Gamma_{1,1}$} (01);  
      \draw [pto] (01) to node[auto, labelsize] {$\Gamma_{1,n_1}$} (02);  
      \draw [pto] (02) to node[auto, labelsize] {$\Gamma_{2,1}$} (03);  
      \draw [pto] (03) to node[auto, labelsize] {$\Gamma_{m-1,n_{m-1}}$} (04);  
      \draw [pto] (04) to node[auto, labelsize] {$\Gamma_{m,1}$} (05);  
      \draw [pto] (05) to node[auto, labelsize] {$\Gamma_{m,n_{m}}$} (06);  
      \draw [pto] (10) to node[auto, labelsize] {$\Delta_1$} (11); 
      \draw [pto] (11) to node[auto, labelsize] {$\Delta_2$} (12); 
      \draw [pto] (12) to node[auto, labelsize] {$\Delta_{m-1}$} (13); 
      \draw [pto] (13) to node[auto, labelsize] {$\Delta_m$} (14); 
      \draw [pto] (20) to node[auto, swap,labelsize] {$\Lambda$} (21); 
