\begin{remark}\label{rmk:vdbl-cat-as-T-cat}
    One can identify virtual double categories with \emph{$T$-categories} \cite{Burroni-T-cats,Leinster-HOHC}, where $T$ is the free category monad on the category $\mathbf{Gph}$ of graphs.
    In particular, a virtual double category $\vdcat{A}$ has an underlying \emph{$T$-graph}, which is a diagram 
\begin{equation*}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(0) at (0,0) {$TA_0$};
      \node(1)at (2,0) {$A_1$};
      \node(2) at (4,0) {$A_0$};
      \draw [->] (1) to node[auto,swap, labelsize] {$d_1$}  (0);
      \draw [->] (1) to node[auto,labelsize] {$d_0$}  (2);
\end{tikzpicture}
\end{equation*}
    in $\mathbf{Gph}$. The graph $A_0$ has objects and horizontal morphisms of $\vdcat{A}$ as its vertices and edges, respectively, whereas the graph $A_1$ has vertical morphisms and multicells of $\vdcat{A}$ as its vertices and edges.
    See \cite[III.3]{Burroni-T-cats} or \cite[Chapter~5]{Leinster-HOHC} for details.
\end{remark}


\begin{definition}
Given virtual double categories $\vdcat{A}$ and $\vdcat{B}$, a \emph{virtual double functor} $F\colon\vdcat{A}\to\vdcat{B}$ consists of the following data.
\begin{itemize}
    \item First we have a functor $F_\vc\colon\vdcat{A}_\vc\to\vdcat{B}_\vc$ between the vertical categories. We write the image of an object $A$ or a vertical morphism $u$ in $\vdcat{A}$ under $F_\vc$ simply as $FA$ and $Fu$, respectively.
    \item We have a function mapping each horizontal morphism $\Gamma\colon A\pto A'$ in $\vdcat{A}$ to a horizontal morphism $F\Gamma\colon FA\pto FA'$ in $\vdcat{B}$.
    \item We have a function mapping each multicell 
\begin{equation*}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(00) at (0,0.75) {$A_0$};
      \node(01) at (1.5,0.75) {$A_1$};
      \node(02) at (3,0.75) {$\cdots$};
      \node(03) at (4.5,0.75) {$A_n$};
      \node(10) at (0,-0.75) {$A$};
      \node(11) at (4.5,-0.75) {$A'$}; 
      \draw [pto] (00) to node[auto, labelsize] {$\Gamma_1$} (01);  
      \draw [pto] (01) to node[auto, labelsize] {$\Gamma_2$} (02);  
      \draw [pto] (02) to node[auto, labelsize] {$\Gamma_n$} (03);  
      \draw [pto] (10) to node[auto, swap, labelsize] {$\Gamma$} (11); 
      \draw [->] (00) to node[auto, swap, labelsize] {$u$} (10); 
      \draw [->] (03) to node[auto,labelsize] {$u'$} (11);
      \node at (2.25,0) {$\theta$}; 
\end{tikzpicture}
\end{equation*}
    in $\vdcat{A}$ to a multicell 
\begin{equation*}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(00) at (0,0.75) {$FA_0$};
      \node(01) at (1.5,0.75) {$FA_1$};
      \node(02) at (3,0.75) {$\cdots$};
      \node(03) at (4.5,0.75) {$FA_n$};
      \node(10) at (0,-0.75) {$FA$};
      \node(11) at (4.5,-0.75) {$FA'$}; 
      \draw [pto] (00) to node[auto, labelsize] {$F\Gamma_1$} (01);  
      \draw [pto] (01) to node[auto, labelsize] {$F\Gamma_2$} (02);  
      \draw [pto] (02) to node[auto, labelsize] {$F\Gamma_n$} (03);  
      \draw [pto] (10) to node[auto, swap, labelsize] {$F\Gamma$} (11); 
      \draw [->] (00) to node[auto, swap, labelsize] {$Fu$} (10); 
      \draw [->] (03) to node[auto,labelsize] {$Fu'$} (11);
      \node at (2.25,0) {$F\theta$}; 
\end{tikzpicture}
\end{equation*}
    in $\vdcat{B}$.
\end{itemize}
These data are subject to the following axioms. 
\begin{itemize}
    \item For each horizontal morphism $\Gamma$ in $\vdcat{A}$, we have $F(\id_\Gamma)=\id_{F\Gamma}$.
    \item For each configuration \eqref{eqn:composable-multicells-A} in $\vdcat{A}$, we have $F\bigl(\kappa\circ(\theta_1,\theta_2,\dots,\theta_m)\bigr)=F\kappa\circ(F\theta_1,F\theta_2,\dots,F\theta_m)$. 
\end{itemize}
\end{definition}

\begin{definition}
Given a parallel pair of virtual double functors $F,G\colon\vdcat{A}\to\vdcat{B}$, a \emph{vertical transformation} $\alpha\colon F\to G$ consists of the following data.
\begin{itemize}
    \item First we have a natural transformation $\alpha_\vc\colon F_\vc\to G_\vc$. For each object $A$ in $\vdcat{A}$, its component at $A$ is a vertical morphism
\[
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(0) at (0,0.75) {$FA$};
      \node(1) at (0,-0.75) {$GA$};
      \draw [->] (0) to node[auto, labelsize] {$\alpha_A$} (1); 
\end{tikzpicture}
\]
    in $\vdcat{B}$.
    \item For each horizontal morphism $\Gamma\colon A\pto A'$ in $\vdcat{A}$, we have a cell
\begin{equation*}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(00) at (0,0.75) {$FA$};
      \node(01) at (1.5,0.75) {$FA'$};
      \node(10) at (0,-0.75) {$GA$};
      \node(11) at (1.5,-0.75) {$GA'$}; 
      \draw [pto] (00) to node[auto, labelsize] {$F\Gamma$} (01);  
      \draw [pto] (10) to node[auto, swap, labelsize] {$G\Gamma$} (11); 
      \draw [->] (00) to node[auto, swap, labelsize] {$\alpha_A$} (10); 
      \draw [->] (01) to node[auto, labelsize] {$\alpha_{A'}$} (11);
      \node at (0.75,0) {$\alpha_\Gamma$}; 
\end{tikzpicture}
\end{equation*}
    in $\vdcat{B}$.
\end{itemize}
These data are subject to the following axiom.
\begin{itemize}
    \item For each multicell 
\begin{equation*}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(00) at (0,0.75) {$A_0$};
      \node(01) at (1.5,0.75) {$A_1$};
      \node(02) at (3,0.75) {$\cdots$};
      \node(03) at (4.5,0.75) {$A_n$};
      \node(10) at (0,-0.75) {$A$};
      \node(11) at (4.5,-0.75) {$A'$}; 
      \draw [pto] (00) to node[auto, labelsize] {$\Gamma_1$} (01);  
      \draw [pto] (01) to node[auto, labelsize] {$\Gamma_2$} (02);  
      \draw [pto] (02) to node[auto, labelsize] {$\Gamma_n$} (03);  
      \draw [pto] (10) to node[auto, swap, labelsize] {$\Gamma$} (11); 
      \draw [->] (00) to node[auto, swap, labelsize] {$u$} (10); 
      \draw [->] (03) to node[auto,labelsize] {$u'$} (11);
      \node at (2.25,0) {$\theta$}; 
\end{tikzpicture}
\end{equation*}
    in $\vdcat{A}$, we have the equality $\alpha_{\Gamma}\circ (F\theta)= G\theta\circ(\alpha_{\Gamma_1},\alpha_{\Gamma_2},\dots,\alpha_{\Gamma_n})$ in $\vdcat{B}$.
\end{itemize}
\end{definition}

Large virtual double categories, virtual double functors, and vertical transformations form a 2-category $\VDbl$.

\subsection{Enrichment over a virtual double category}\label{subsec:enrichment-over-vdbl}
We recall enriched category theory over a virtual double category, following \cite{Leinster-generalized-enrichment}.
Let $\vdcat{A}$ be a virtual double category.
\begin{definition}
    An \emph{$\vdcat{A}$-category} $\ecat{C}$ consists of the following data.
    \begin{itemize}
        \item We have a set $\ob(\ecat{C})$ of \emph{objects} of $\ecat{C}$. We write $c\in \ecat{C}$ to mean $c\in \ob(\ecat{C})$. We call the $\vdcat{A}$-category $\ecat{C}$ \emph{small} if $\ob(\ecat{C})$ is a small set.
        \item For each object $c\in \ecat{C}$, we have an object $|c|^\ecat{C}$ of $\vdcat{A}$, which is called the \emph{extent} of $c$. 
        \item For each $c,c'\in\ecat{C}$, we have a horizontal morphism $\ecat{C}(c,c')\colon |c|^\ecat{C}\pto |c'|^\ecat{C}$ in $\vdcat{A}$. 
        \item For each $c\in \ecat{C}$, we have a multicell
    \begin{equation*}
    \begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(20) at (1,0.75) {$|c|^\ecat{C}$};
