      \node(01) at (2,-0.75) {$|c|^\ecat{C}$}; 
      \draw [pto] (00) to node[auto,swap,labelsize] {$\ecat{C}(c,c)$} (01);
      \draw [double equal sign distance] (20) to (00); 
      \draw [double equal sign distance] (20) to (01); 
      \node at (1,-0.2) {$\eta_c^\ecat{C}$};
\end{tikzpicture}
    \end{equation*}
        in $\vdcat{A}$. 
        \item For each $c_0,c_1,c_2\in\ecat{C}$, we have a multicell 
\begin{equation*}
      \begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
