      \node(02) at (4,0.75) {$|c_2|^\ecat{C}$};
      \node(10) at (0,-0.75) {$|c_0|^\ecat{C}$};
      \node(11) at (4,-0.75) {$|c_2|^\ecat{C}$}; 
