      \draw [pto] (01) to node[auto,labelsize] {$\ecat{C}(c_1,c_2)$} (02);
      \draw [pto] (10) to node[auto, swap, labelsize] {$\ecat{C}(c_0,c_2)$} (11); 
      \draw [double equal sign distance] (00) to (10); 
      \draw [double equal sign distance] (02) to (11);
      \node at (2,0) {$\mu_{c_0,c_1,c_2}^\ecat{C}$}; 
\end{tikzpicture}
\end{equation*}
        in $\vdcat{A}$. 
    \end{itemize}
    These data are subject to the following axioms. 
    \begin{itemize}
        \item For each $c,c'\in\ecat{C}$, we have 
        \begin{equation*}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
