      \draw [double equal sign distance] (21) to (02); 
      \draw [double equal sign distance] (00) to (10); 
      \draw [double equal sign distance] (02) to (11);
      \node at (1,0.5) {$\eta_c^\ecat{C}$};
      \node at (2,-0.75) {$\mu_{c,c,c'}^\ecat{C}$}; 
\end{tikzpicture}
\quad = \quad \id_{\ecat{C}(c,c')} \quad = \quad
    \begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(20) at (1,1.5) {$|c|^\ecat{C}$};
