\begin{definition}
    Let $\ecat{C}$ and $\ecat{D}$ be $\vdcat{A}$-categories. An \emph{$\vdcat{A}$-functor} $f\colon \ecat{C}\to \ecat{D}$ consists of the following data. 
    \begin{itemize}
        \item First we have a function $\ob(f)\colon \ob(\ecat{C})\to \ob(\ecat{D})$. We write the image of $c\in \ecat{C}$ under this function as $fc\in \ecat{D}$. 
        \item For each $c\in \ecat{C}$, we have a vertical morphism 
\begin{equation*}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(00) at (0,0.75) {$|c|^\ecat{C}$};
      \node(10) at (0,-0.75) {$|fc|^\ecat{D}$};
      \draw [->] (00) to node[auto, labelsize] {$f_c$} (10); 
\end{tikzpicture}
\end{equation*}
    in $\vdcat{A}$. 
    \item For each $c,c'\in\ecat{C}$, we have a cell
        \begin{equation*}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(00) at (0,0.75) {$|c|^\ecat{C}$};
      \node(01) at (2,0.75) {$|c'|^\ecat{C}$};
