Small $\vdcat{A}$-categories, $\vdcat{A}$-functors, and $\vdcat{A}$-natural transformations form a 2-category $\enCat{\vdcat{A}}$. The assignment $\vdcat{A}\mapsto \enCat{\vdcat{A}}$ routinely extends to a 2-functor $\Enr\colon \VDbl\to \twoCAT$. 

In particular, if we consider the case where $\vdcat{A}$ is the terminal virtual double category $1$, then $\Enr(1)$ (i.e., $\enCat{1}$; however, we will avoid the latter misleading notation) is the locally chaotic\footnote{A category is \emph{chaotic} (also known as indiscrete or codiscrete) if each of its hom-sets is a singleton. A $2$-category is \emph{locally chaotic} if each of its hom-categories is chaotic.} $2$-category whose underlying category is the category $\Set$ of small sets. 
For this reason, we write the $2$-category $\Enr(1)$ as $\Setlc$. 

\section{Explicit description of \texorpdfstring{$\vdcat{L}$}{L}}
\label{sec:L-explicitly}
In this section, we describe the left $2$-adjoint $\vdcat{L}$ of the $2$-functor $\Enr_1\colon \VDbl\to \twoCAT/\Enr(1)=\twoCAT/\Setlc$ explicitly.
First observe that for any $\vdcat{A}\in\VDbl$, the object $\Enr_1(\vdcat{A})\in \twoCAT/\Setlc$ is given by the $2$-functor $\ob\colon \enCat{\vdcat{A}}\to \Setlc$, sending each $\vdcat{A}$-category $\ecat{C}$ to its set $\ob(\ecat{C})$ of objects. 

Suppose that we are given $(F\colon \tcat{K}\to\Setlc)\in \twoCAT/\Setlc$. 
(In view of the (2-)adjunction
\[\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(0) at (0,0) {$\twoCAT$};
      \node(2) at (3,0) {$\CAT$,};
      \draw [->, transform canvas={yshift=5}] (0) to node[auto, labelsize] {$(-)_0$} (2); 
      \draw [<-, transform canvas={yshift=-5}] (0) to node[auto, swap, labelsize] {$(-)_\mathrm{lc}$} (2); 
      \path(0) to node[rotate=-90] {$\dashv$} (2);
\end{tikzpicture}\]
the $2$-functor $F\colon \tcat{K}\to \Setlc$ corresponds to a functor $\hat F\colon \tcat{K}_0\to \Set$ from the underlying category $\tcat{K}_0$ of $\tcat{K}$.)
We construct the virtual double category $\vdcat{L}F$ as follows.
\begin{itemize}
    \item An object of $\vdcat{L}F$ is a pair $(K,x)$ consisting of an object $K\in\tcat{K}$ and an element $x\in FK$.
    \item A vertical morphism of $\vdcat{L}F$ from $(K,x)$ to $(L,y)$ is a $1$-cell $f\colon K\to L$ of $\tcat{K}$ such that $(Ff)x=y$.
    (Thus the vertical category $(\vdcat{L}F)_\vc$ of $\vdcat{L}F$ is the category of elements $\Elts(\hat F)$ of the functor $\hat F\colon \tcat{K}_0\to \Set$ corresponding to the $2$-functor $F\colon \tcat{K}\to \Setlc$.)
    \item There exists at most one horizontal morphism between any given pair of objects of $\vdcat{L}F$;
    a horizontal morphism from $(K,x)$ to $(K',x')$ exists in $\vdcat{L}F$ if and only if $K=K'$.
    \item Given a configuration 
    \[\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(00) at (-0.5,0.75) {$(K,x_0)$};
      \node(01) at (1.5,0.75) {$(K,x_1)$};
      \node(02) at (3,0.75) {$\cdots$};
      \node(03) at (4.5,0.75) {$(K,x_n)$};
      \node(10) at (-0.5,-0.75) {$(L,y)$};
      \node(11) at (4.5,-0.75) {$(L,y')$}; 
      \draw [pto] (00) to node[auto, labelsize] {} (01);  
      \draw [pto] (01) to node[auto, labelsize] {} (02);  
      \draw [pto] (02) to node[auto, labelsize] {} (03);  
      \draw [pto] (10) to node[auto, swap, labelsize] {} (11); 
      \draw [->] (00) to node[auto, swap, labelsize] {$f$} (10); 
      \draw [->] (03) to node[auto,labelsize] {$f'$} (11);
    \end{tikzpicture}\]
    in $\vdcat{L}F$ (where the horizontal morphisms are left unnamed because they are determined by their domain and codomain), the multicells having this as a boundary are in bijection with the $2$-cells $f\to f'$ in $\tcat{K}$. 
\end{itemize}
Using suitable pasting of $2$-cells in $\tcat{K}$, it is straightforward to make $\vdcat{L}F$ into a virtual double category.

\begin{theorem}\label{thm:L}
This construction gives rise to the left $2$-adjoint of $\Enr_1$.  
\end{theorem}

\begin{proof}
    For any $(F\colon \tcat{K}\to\Setlc)\in \twoCAT/\Setlc$, 
there is a canonical $2$-functor $\eta_F\colon \tcat{K}\to \Enr(\vdcat{L}F)$ making the diagram
\begin{equation*}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(00) at (0,0.75) {$\tcat{K}$};
      \node(01) at (2,0.75) {$\enCat{\vdcat{L}F}$};
      \node(10) at (1,-0.75) {$\Setlc$}; 
      \draw [->] (00) to node[auto, labelsize] {$\eta_F$} (01);  
      \draw [->] (00) to node[auto, swap, labelsize] {$F$} (10); 
      \draw [->] (01) to node[auto, labelsize] {$\ob$} (10);
\end{tikzpicture}
\end{equation*}
commute. 
On objects, $\eta_F$ sends each $K\in\tcat{K}$ to a canonical $\vdcat{L}F$-category $\eta_F(K)$ with $\ob\bigl(\eta_F(K)\bigr)=FK$, such that the extent of $x\in FK$ is $(K,x)\in \vdcat{L}F$;
its action on $1$- and $2$-cells of $\tcat{K}$ is evident. 
It suffices to show that for any $\vdcat{A}\in\VDbl$, the composite 
\begin{multline*}
\VDbl(\vdcat{L}F,\vdcat{A})\xrightarrow{(\Enr_1)_{\vdcat{L}F,\vdcat{A}}}
\twoCAT/\Setlc\bigl(\Enr_1(\vdcat{L}F),\Enr_1(\vdcat{A}) \bigr)\\
\xrightarrow{\twoCAT/\Setlc(\eta_F,\Enr_1(\vdcat{A}))}
\twoCAT/\Setlc\bigl(F,\Enr_1(\vdcat{A}) \bigr)
\end{multline*}
is an isomorphism of categories.
We omit the details as one can also obtain the $2$-adjunction $\vdcat{L}\dashv \Enr_1$ by combining the results proved in what follows.
\end{proof}

\begin{remark}
    The $2$-category $\VDbl$ admits a fully faithful $2$-functor $\PsDbl\to \VDbl$ from the $2$-category $\PsDbl$ of (large) pseudo double categories, lax double functors, and vertical natural transformations.
    The essential image of $\PsDbl\to \VDbl$ consists of all \emph{representable} virtual double categories; see e.g.\ \cite[Theorem~5.2]{Cruttwell-Shulman-unified}.
    Now, in the virtual double category $\vdcat{L}F$ constructed above, any multicell corresponding to the identity $2$-cell on an identity $1$-cell in $\tcat{K}$ is opcartesian (in the sense of \cite[Definition~5.1]{Cruttwell-Shulman-unified}).
    It follows that $\vdcat{L}F$ is representable.
    Hence the $2$-functor $\vdcat{L}\colon \twoCAT/\Setlc\to \VDbl$ factors through $\PsDbl$ (in fact, its full sub-2-category $\StrDbl$ consisting of \emph{strict} double categories).
    Therefore it follows that the $2$-functor $\Enr\colon \PsDbl\to \twoCAT$ is also a parametric right $2$-adjoint. 
    For examples of categories enriched over a pseudo double category, see e.g.\ \cite{Cockett-Garner-restriction} and \cite[Definition~5.1]{Shulman-enriched-indexed}.
\end{remark}

\begin{remark}\label{rmk:BICAT-not-pra}
    The $2$-functor $\Enr\colon \BICAT\to \twoCAT$ is not a parametric right $2$-adjoint, i.e., the $2$-functor $\Enr_1\colon \BICAT\to \twoCAT/\Setlc$ does not have a left $2$-adjoint. 
    (See e.g.\ \cite{Street-cohomology} for the definitions of categories, functors, and natural transformations enriched over a bicategory; these are a special case of \cref{subsec:enrichment-over-vdbl}, where a bicategory is regarded as a virtual double category whose vertical category is discrete, and whose horizontal morphisms correspond to the $1$-cells of the original bicategory.)
    In \cite[Theorem~2.1]{Fujii_Lack}, we showed that $\Enr_1\colon \BICAT\to \twoCAT/\Setlc$ preserves all (weighted) limits which happen to exist in $\BICAT$. 
    Thus we cannot use arguments based on non-preservation of limits. Instead, we argue as follows.

Let $\cat{C}$ be the category with objects $x,y,z$ and non-identity
arrows $f\colon x\to z$ and $g\colon y\to z$. Regard it as a locally
discrete 2-category, and equip it with the 2-functor
$\Delta_1\colon\cat{C}\to\Setlc$ which is constant at the singleton
$1\in\Setlc$. This now determines an object $(\cat{C},\Delta_1)$ of $\twoCAT/\Setlc$. 
We claim that the $2$-functor 
\begin{equation}\label{eqn:Bicat-non-representable-functor}
\BICAT\xrightarrow{\Enr_1} \twoCAT/\Setlc\xrightarrow{\twoCAT/\Setlc((\cat{C},\Delta_1),-)}\CAT
\end{equation}
is not representable.
For
a bicategory $\bcat{B}$, to give a map
$(\cat{C},\Delta_1)\to\Enr_1(\bcat{B})$ in $\twoCAT/\Setlc$ we should give three one-object
$\bcat{B}$-categories --- in other words, three monads in $\bcat{B}$
--- and two $\bcat{B}$-functors between them. But
$\bcat{B}$-functors respect extent, and so the three one-object
$\bcat{B}$-categories would all have to live on the same object of
$\bcat{B}$.
Now, suppose to the contrary that the $2$-functor \eqref{eqn:Bicat-non-representable-functor} were representable by $\bcat{B}\in\BICAT$.

\subsection*{Step 1: the bicategory $\bcat{B}$ has a single object.}

We have a $2$-adjunction 
\[\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(0) at (0,0) {$\mathbf{SET}_\mathrm{ld}$};
      \node(2) at (3,0) {$\BICAT$,};
      \draw [<-, transform canvas={yshift=5}] (0) to node[auto, labelsize] {$\ob$} (2); 
      \draw [->, transform canvas={yshift=-5}] (0) to node[auto, swap, labelsize] {$(-)_\mathrm{ch}$} (2); 
      \path(0) to node[rotate=-90] {$\dashv$} (2);
\end{tikzpicture}\]
where $\mathbf{SET}_\mathrm{ld}$ is the locally discrete $2$-category whose underlying category is the category $\mathbf{SET}$ of large sets, $\ob$ maps each bicategory to its set of objects, and $(-)_\mathrm{ch}$ maps each set $E$ to the \emph{chaotic} bicategory $E_\mathrm{ch}$ whose set of objects is $E$ and each of whose hom-categories is the terminal category. 
Our assumption on $\bcat{B}$ implies that we have isomorphisms of categories 
\[
\mathbf{SET}_\mathrm{ld}\bigl(\ob(\bcat{B}),E\bigr)\cong 
\BICAT(\bcat{B},E_\mathrm{ch})\cong
\twoCAT/\Setlc\bigl((\cat{C},\Delta_1),\Enr_1(E_\mathrm{ch})\bigr)
\]
for each $E\in\mathbf{SET}_\mathrm{ld}$.
Since $\cat{C}$ is connected, the rightmost term is the discrete category whose set of objects is $E$. Hence $\ob(\bcat{B})$ is a singleton.

Therefore $\bcat{B}$ corresponds to a monoidal category $\cat{V}$.
We thus have a universal monoidal category $\cat{V}$ equipped with
a functor $N\colon\cat{C}\to \mathrm{Mon}(\cat{V})$.

\subsection*{Step 2: the unit $I$ of $\cat{V}$ must be initial.}
Next consider $I/\cat{V}$ with the lifted monoidal structure from
$\cat{V}$. 
The (strict monoidal) forgetful functor $U\colon I/\cat{V}\to \cat{V}$ induces an isomorphism of categories $\mathrm{Mon}(U)\colon \mathrm{Mon}(I/\cat{V})\to\mathrm{Mon}(\cat{V})$. 
Consider the composite $\cat{C}\xrightarrow{N}\mathrm{Mon}(\cat{V})\xrightarrow{\mathrm{Mon}(U)^{-1}}\mathrm{Mon}(I/\cat{V})$. By the universal property of $N$, there exists a unique lax monoidal functor $H\colon \cat{V}\to I/\cat{V}$ such that $\mathrm{Mon}(U)^{-1}N=\mathrm{Mon}(H)N$, i.e., $N=\mathrm{Mon}(UH)N$. 
The uniqueness part of the universal property of $N$ implies $UH=1_\cat{V}$. 
Therefore we have $\mathrm{Mon}(U)\mathrm{Mon}(H)=1_{\mathrm{Mon}(\cat{V})}$, and since $\mathrm{Mon}(U)$ is an isomorphism, $\mathrm{Mon}(U)^{-1}=\mathrm{Mon}(H)$ holds. 
Since $\mathrm{Mon}(U)$ maps the unit monoid on $(1_I\colon I\to I) \in I/\cat{V}$ to the unit monoid on $I\in\cat{V}$, the functor $H$ must map the object $I\in\cat{V}$ to $(1_I\colon I\to I)$. 
Now, $UH=1_\cat{V}$ implies that $H$ corresponds to a cone $(\tau_X\colon I\to X)_{X\in\cat{V}}$ over the identity functor $1_\cat{V}$, and $HI=1_I$ means that we have $\tau_I=1_I$. 
Hence $I$ is initial in $\cat{V}$. 

\subsection*{Step 3: the unit monoid $I$ must be in the image of $N$.}

Now let $\cat{V}'$ be the monoidal category obtained from $\cat{V}$ by
adjoining a new object $I'$ isomorphic to $I$. The inclusion
$K\colon\cat{V}\to\cat{V}'$ is lax monoidal, as is the functor $K'\colon
\cat{V}\to\cat{V}'$ which is identical to $K$ except that
$K'I=I'$. Since $K\neq K'$ we must have $\mathrm{Mon}(K)N\neq
\mathrm{Mon}(K')N$. But $K$ and $K'$ are identical except at $I$, and since $I$ is initial in $\cat{V}'$,
this can only happen if $I$ is in the image of $N$. 

\subsection*{Step 4: this is impossible.}

We now know that $NW=I$ for some object $W\in\cat{C}$.
Finally consider the cocartesian monoidal category
$\Fam(\cat{C})$ and the fully faithful inclusion
$J\colon\cat{C}\to\Fam(\cat{C})=\mathrm{Mon}(\Fam(\cat{C}))$. There would then
have to be a unique monoidal functor $L\colon\cat{V}\to\Fam(\cat{C})$
such that $\mathrm{Mon}(L)N=J$. For any object $C\in\cat{C}$ we have a
map $I=NW\to NC$ in $\mathrm{Mon}(\cat{V})$, and so a map
$JW=\mathrm{Mon}(L)NW\to \mathrm{Mon}(L)NC=JC$; and so, since $J$ is
full, a map $W\to C$ in $\cat{C}$. But there is no object in
$\cat{C}$ with a map to every other object. 
\end{remark}

\begin{remark}\label{rmk:MonCAT-not-pra}
    The $2$-functor $\Enr\colon \MonCAT\to \twoCAT$ is not a parametric right $2$-adjoint.
    In this case, we can show that the $2$-functor $\Enr_1\colon \MonCAT\to \twoCAT/\Setlc$ does not preserve a certain (fortuitous) equalizer in $\MonCAT$.
    Consider the parallel pair of morphisms 
\[
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(0) at (0,0) {$\mathbb{Z}$};
      \node(1) at (3,0) {$\{a,b\}_\mathrm{ch}$};
      \draw [->, transform canvas={yshift=3}] (0) to node[auto, labelsize] {$f$}  (1);  
      \draw [->, transform canvas={yshift=-3}] (0) to node[auto, swap, labelsize] {$g$}  (1); 
\end{tikzpicture}
\]
    in $\MonCAT$, where 
    \begin{itemize}
        \item $\mathbb{Z}$ is the additive monoid (in fact group) of integers regarded as a discrete monoidal category,
        \item $\{a,b\}_\mathrm{ch}$ is the chaotic category with two objects $a,b$ regarded as a monoidal category (details of the definitions of the unit and monoidal product do not matter),
        \item $f$ is the strong monoidal functor constant at $a$, and
        \item $g$ is the strong monoidal functor sending $-1,0,1\in\mathbb{Z}$ to $a$ and all other objects of $\mathbb{Z}$ to $b$. 
    \end{itemize}
    Then this parallel pair has an equalizer in $\MonCAT$, namely the terminal monoidal category $1$; the limit cone is the unique lax (in fact strict) monoidal functor $e\colon 1\to \mathbb{Z}$, sending the unique object of $1$ to $0\in\mathbb{Z}$. 

    Now, an object of $\Enr(\mathbb{Z})=\enCat{\mathbb{Z}}$ is a set $X$ together with a function $d\colon X\times X\to \mathbb{Z}$ satisfying $d(x,x)=0$ and $d(x,y)+d(y,z)=d(x,z)$. 
    Such an object is in the image of the $2$-functor $\Enr(e)\colon \Enr(1)\to \Enr(\mathbb{Z})$ if and only if $d\colon X\times X\to \mathbb{Z}$ is constant at $0$, whereas it is in the equalizer of $\Enr(f)$ and $\Enr(g)$ if and only if the image of $d\colon X\times X\to \mathbb{Z}$ is contained in $\{-1,0,1\}$. Now, let $X=\{x,y\}$, $d(x,x)=d(y,y)=0$, $d(x,y)=1$, and $d(y,x)=-1$; this object is in the equalizer of $\Enr(f)$ and $\Enr(g)$, but not in the image of $\Enr(e)$.
\end{remark}

\section{Parametric right 2-adjoints, familial 2-functors, and polynomial 2-functors}\label{sec:poly-pra-fam}
In this section, we recall basic facts about these notions.

\subsection{Parametric right $2$-adjoints}\label{subsec:pra}
We start with the notion of \emph{parametric right $2$-adjoint}
\cite{Weber-familial}, which is a $2$-categorical version of the notion of \emph{parametric right adjoint} introduced in \cite[Section~5]{Street-petit-topos}. 
As mentioned in \cref{sec:intro}, a $2$-functor $R\colon \tcat{K}\to\tcat{L}$ from a $2$-category $\tcat{K}$ with a terminal object $1$ is a \emph{parametric right $2$-adjoint} when the $2$-functor $R_1\colon \tcat{K}\to \tcat{L}/R1$ is a right $2$-adjoint.

\begin{proposition}
    For a $2$-functor $R\colon\tcat{K}\to\tcat{L}$ where $\tcat{K}$ has a terminal object, the following are equivalent:
    \begin{enumerate}
    \item $R$ is a parametric right $2$-adjoint
        \item $R_1\colon\tcat{K}\to\tcat{L}/R1$ has a left $2$-adjoint
        \item $R_X\colon\tcat{K}/X\to\tcat{L}/RX$ has a left $2$-adjoint for every object $X$ of $\tcat{K}$.
    \end{enumerate}
\end{proposition}

\begin{proof}
    The equivalence of (1) and (2) is just the definition of parametric right $2$-adjoint. The equivalence of (2) and (3) is part of \cite[Proposition~2.6]{Weber-familial}.
\end{proof}

A straightforward consequence is the following.
\begin{proposition}
    Parametric right $2$-adjoints are closed under composition.
\end{proposition}
\begin{proof}
    Use the characterization (3) in the previous proposition.
\end{proof}
\begin{proposition}\label{2-adj-is-para-2-adj}
    If $\tcat{K}$ is a $2$-category with terminal object, any right $2$-adjoint $R\colon \tcat{K}\to \tcat{L}$ is a parametric right $2$-adjoint. 
\end{proposition}
\begin{proof}
Up to isomorphism, $R_1$ is just $R$.
\end{proof}

A parametric right 2-adjoint $R\colon\tcat{K}\to\tcat{L}$ factorizes
as a right adjoint $R_1$ followed by the forgetful
$\tcat{L}/R1\to\tcat{L}$, and so will preserve any type of limit which
is preserved by the forgetful; in particular, it will preserve any
pullbacks and equalizers which exist in $\tcat{K}$. But it may not
preserve some 2-categorical or bicategorical limits that we would like to be
preserved. To deal with this, we now turn to the stronger notion of
familial 2-functor \cite{Weber-familial}.

\subsection{Familial $2$-functors}
\label{subsec:familial}

Familial 2-functors rely on the idea of split fibration in a
2-category, which we now recall. A morphism $p\colon E\to B$ in a
2-category $\tcat{K}$ is said to be a {\em split fibration} when
\begin{itemize}
\item for each object $X$, the induced functor
  $\tcat{K}(X,p)\colon\tcat{K}(X,E)\to\tcat{K}(X,B)$ is equipped with the
  structure of a split fibration, so that in particular for any
  $e\colon X\to E$, $b\colon X\to B $, and $\beta\colon b\to pe$ there
  is a chosen cartesian lift $\overline\beta\colon \beta^\ast e\to e$
  \item for each $f\colon Y\to X$, the induced functor
    $\tcat{K}(f,E)\colon\tcat{K}(X,E)\to\tcat{K}(Y,E)$ preserves chosen
    cartesian lifts.
\end{itemize}
In the case $\tcat{K}=\CAT$ we recover the usual notion of split fibration.
Being a split fibration is structure that a morphism may bear, not
just a property: there can be more than one choice of cartesian lifts.

Given an object $B$ of the 2-category $\tcat{K}$, there is a
2-category $\Spl(B)$ equipped with a forgetful 2-functor
$U_B\colon\Spl(B)\to\tcat{K}/B$ consisting of the split fibrations $p\colon
E\to B$, morphisms between these preserving chosen cartesian lifts,
and the 2-cells are defined as in $\tcat{K}/B$; see
\cite[Section~3]{Weber-familial}. We may also write
$\Spl_{\tcat{K}}(B)$ rather than $\Spl(B)$ if there is any doubt about
the 2-category
$\tcat{K}$ in question. 

An important special case is where each
$\tcat{K}(X,p)$ has a unique lift, i.e., is a discrete fibration of categories; then the preservation condition is
automatic, and $p$ is said to be a discrete fibration. There are analogous definitions of split opfibration and discrete opfibration. All of these notions are defined representably, being defined via the corresponding notions in $\CAT$, and one sometimes speaks of representable discrete fibration, and so on, if there might be doubt as to which notion is meant. 

In particular, in the following section we shall meet a notion of discrete opfibration for virtual double categories that is strictly stronger than the one defined representably in $\VDbl$. In this paper, we shall always use {\em representable discrete opfibration} to refer to the notion defined here, namely a morphism $p\colon E\to B$ for which each $\tcat{K}(X,p)\colon \tcat{K}(X,E)\to\tcat{K}(X,B)$ is a discrete opfibration in $\CAT$.

We are now ready to make the definition.

\begin{definition}
  Let $\tcat{K}$ be a 2-category with a terminal object. A 2-functor
  $R\colon \tcat{K}\to\tcat{L}$ is {\em familial} if it is a
  parametric right $2$-adjoint, and the $2$-functor
  $R_1\colon\tcat{K}\to\tcat{L}/R1$ factorizes as
  \[
    \begin{tikzcd}
      \tcat{K} \rar["\overline{R}_1"] & \Spl(R1)
      \rar["U_{R1}"] & \tcat{L}/R1.
    \end{tikzcd}
  \]
\end{definition}
This means that:
\begin{itemize}
\item The image $RA\to R1$ of the unique $A\to 1$ under $R$ is given
  the structure of a split fibration in $\tcat{L}$
  \item The map $Rf\colon RA\to RB$ preserves chosen cartesian lifts,
    for each $f\colon A\to B$.
\end{itemize}


It follows as in \cite{Weber-familial} that any familial 2-functor
preserves isocomma objects up to equivalence, and so
preserves bicategorical pullbacks. The key point is that the forgetful
$\Spl(R1)\to\tcat{L}$ has better limit-preservation properties than
$\tcat{L}/R1\to\tcat{L}$. It also follows that $R$ preserves
fibrations, bicategorical fibrations, iso-fibrations, and so
on. It follows from \cite[Theorem~6.6]{Weber-familial} that familial 2-functors are closed under composition.

The motivating example is the 2-functor $\Fam\colon\CAT\to\CAT$; this
and many others can be found in \cite{Weber-familial}. 
The following somewhat degenerate example will nevertheless be important in what follows.

\begin{example}\label{ex:right-adj-familial}
    If $1$ is a terminal object in $\tcat{L}$ then $\Spl_{\tcat{L}}(1)\cong\tcat{L}$. Thus any right 2-adjoint between 2-categories with terminal objects is familial.
\end{example}

We shall see various further examples in later sections of the paper.

\subsection{Polynomial $2$-functors}
\label{subsec:poly}

Let $\tcat{K}$ be a $2$-category with $2$-pullbacks. Then for any $1$-cell $p\colon X\to Y$ in $\tcat{K}$, we have a $2$-adjunction 
\[
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(0) at (0,0) {$\tcat{K}/X$};
      \node(1) at (4,0) {$\tcat{K}/Y$};
      \draw [->, transform canvas={yshift=5}] (0) to node[auto, labelsize] {$\sum_p$}  (1);  
      \draw [->, transform canvas={yshift=-5}] (1) to node[auto, labelsize] {$p^\ast$}  (0); 
      \path(0) to node[rotate=-90] {$\dashv$} (1);
\end{tikzpicture}
\]
between the (strict) slice $2$-categories, 
where $\sum_p$ maps each $(f\colon A\to X)$ to $(pf\colon {A}\to {Y})$ and 
$p^\ast$ maps each $(g\colon {B}\to {Y})$ to $(p^\ast g\colon p^\ast {B}\to {X})$ defined as the pullback
\begin{equation*}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(00) at (0,0.75) {$p^\ast {B}$};
      \node(01) at (1.5,0.75) {${B}$};
      \node(10) at (0,-0.75) {${X}$};
      \node(11) at (1.5,-0.75) {${Y}$}; 
      \draw [->] (00) to node[auto, labelsize] {} (01);  
      \draw [->] (10) to node[auto, swap, labelsize] {$p$} (11); 
      \draw [->] (00) to node[auto, swap, labelsize] {$p^\ast g$} (10); 
      \draw [->] (01) to node[auto, labelsize] {$g$} (11);
      \draw (0.2,0.25) to (0.5,0.25) to (0.5,0.55);
\end{tikzpicture}
\end{equation*}
in $\tcat{K}$. (Strictly speaking, the notation $p^\ast {B}$ is not precise because it also depends on $g$. The same remark applies to the notation $\prod_P{\vdcat{A}}$ introduced in the proof of \cref{prop:disc-opfib-powerful} below.)

We say that the $1$-cell $p\colon X\to Y$ in $\tcat{K}$ is
\emph{powerful} (or \emph{exponentiable}) if the $2$-functor
$p^\ast\colon\tcat{K}/Y\to\tcat{K}/X$ has a right $2$-adjoint
$\prod_p$.

If $\tcat{K}$ is a 2-category with pullbacks and we are given
morphisms
\[
  \begin{tikzcd}
    I & E \lar["s" '] \rar["p"] & B \rar["t"] & J
  \end{tikzcd}
\]
in $\tcat{K}$ with $p$ powerful (in which case the above diagram is called a \emph{polynomial} in $\tcat{K}$), then there is an induced 2-functor
\[
  \begin{tikzcd}
    \tcat{K}/I \rar["s^{*}"] & \tcat{K}/E \rar["\prod_p"] & \tcat{K}/B \rar["\sum_t"]
    & \tcat{K}/J
  \end{tikzcd}
\]
which we call $\mathcal{P}(s,p,t)$, 
and a 2-functor arising in this way is said to be {\em polynomial}. In
the important special case where $I=J=1$, so that $s$ and $t$ are
uniquely determined by their domains, we write $\mathcal{P}(p)$ rather
than $\mathcal{P}(s,p,t)$.

\begin{proposition}
  Any polynomial $2$-functor is a parametric right adjoint.
\end{proposition}

\begin{proof}
$\mathcal{P}(s,p,t)_1$ is just $\prod_p s^{*}$ which is right adjoint to
$\sum_s p^{*}$. 
\end{proof}

\begin{proposition}\label{prop:poly-familial}
  Let $\tcat{K}$ be a $2$-category with finite limits, and $p\colon E\to
  B$ a morphism in $\tcat{K}$ which is both powerful and 
  a representable discrete opfibration.
  Then $\mathcal{P}(p)\colon \tcat{K}\to\tcat{K}$ is a
  familial $2$-functor.
\end{proposition}

\begin{proof}
  This is a special case of \cite[Proposition~4.4.5]{Weber-polynomials}.
\end{proof}

\section{Powerfulness of discrete opfibrations}\label{sec:dof}
The aim of this section is to show that any discrete opfibration between virtual double categories is powerful in the $2$-dimensional sense defined in \cref{subsec:poly} (\cref{prop:disc-opfib-powerful}).
We note that the $1$-dimensional aspect of this is a special case of a result of Bowler: combining Section~2.3 and Proposition~3.1.6 of \cite{Bowler-PhD}, one concludes that all \emph{discrete Conduch\'e fibrations} (as in the latter proposition) between virtual double categories are powerful in the $1$-dimensional sense. 
We give an explicit description of the $2$-functor $\prod_P$ induced by a discrete opfibration $P$ of virtual double categories, as this is a key ingredient in the various constructions for virtual double categories we will study below.

We now introduce the notion of discrete opfibration of virtual double categories, strictly stronger than the representable notion, that was referred to in \cref{subsec:familial}.

\begin{definition}[{\cite[IV.2]{Burroni-T-cats} and \cite[Section~6.3]{Leinster-HOHC}}]
\label{def:disc-opfib}
    A virtual double functor $P\colon \vdcat{X}\to\vdcat{Y}$ is a \emph{discrete opfibration} if the following conditions are satisfied. 
    \begin{itemize}
        \item For each object $X\in \vdcat{X}$ and each vertical morphism $v\colon PX\to Y$ in $\vdcat{Y}$, there exists a unique vertical morphism $\overline{v}_X\colon X\to v_\ast X$ in $\vdcat{X}$ with $P\overline v_X=v$. (That is, the functor $P_\vc\colon \vdcat{X}_\vc\to \vdcat{Y}_\vc$ is a discrete opfibration of categories.)
        \item For each sequence of horizontal morphisms 
        \begin{equation*}
            \begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(00) at (0,0) {$X_0$};
      \node(01) at (1.5,0) {$X_1$};
      \node(02) at (3,0) {$\cdots$};
      \node(03) at (4.5,0) {$X_n$}; 
      \draw [pto] (00) to node[auto, labelsize] {$\Phi_1$} (01);  
      \draw [pto] (01) to node[auto, labelsize] {$\Phi_2$} (02);  
      \draw [pto] (02) to node[auto, labelsize] {$\Phi_n$} (03);    
\end{tikzpicture}
        \end{equation*}
        in $\vdcat{X}$ and each multicell 
        \begin{equation*}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(00) at (0,0.75) {$PX_0$};
      \node(01) at (1.5,0.75) {$PX_1$};
      \node(02) at (3,0.75) {$\cdots$};
      \node(03) at (4.5,0.75) {$PX_n$};
      \node(10) at (0,-0.75) {$Y$};
      \node(11) at (4.5,-0.75) {$Y'$}; 
      \draw [pto] (00) to node[auto, labelsize] {$P\Phi_1$} (01);  
      \draw [pto] (01) to node[auto, labelsize] {$P\Phi_2$} (02);  
      \draw [pto] (02) to node[auto, labelsize] {$P\Phi_n$} (03);  
      \draw [pto] (10) to node[auto, swap, labelsize] {$\Psi$} (11); 
      \draw [->] (00) to node[auto, swap, labelsize] {$v$} (10); 
      \draw [->] (03) to node[auto,labelsize] {$v'$} (11);
      \node at (2.25,0) {$\nu$}; 
\end{tikzpicture}
\end{equation*}
    in $\vdcat{Y}$, there exists a unique multicell 
            \begin{equation*}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(00) at (0,0.75) {$X_0$};
      \node(01) at (1.5,0.75) {$X_1$};
      \node(02) at (3,0.75) {$\cdots$};
      \node(03) at (4.5,0.75) {$X_n$};
      \node(10) at (0,-0.75) {$v_\ast X_0$};
      \node(11) at (4.5,-0.75) {$v'_\ast X_n$}; 
      \draw [pto] (00) to node[auto, labelsize] {$\Phi_1$} (01);  
      \draw [pto] (01) to node[auto, labelsize] {$\Phi_2$} (02);  
      \draw [pto] (02) to node[auto, labelsize] {$\Phi_n$} (03);  
      \draw [pto] (10) to node[auto, swap, labelsize] {$\nu_\ast (\Phi_1,\dots,\Phi_n)$} (11); 
      \draw [->] (00) to node[auto, swap, labelsize] {$\overline v_{X_0}$} (10); 
      \draw [->] (03) to node[auto,labelsize] {$\overline{v'}_{X_n}$} (11);
      \node at (2.25,0) {$\overline \nu_{\Phi_1,\dots,\Phi_n}$}; 
\end{tikzpicture}
\end{equation*}
    in $\vdcat{Y}$ with $P\overline \nu_{\Phi_1,\dots,\Phi_n}=\nu$.
    \end{itemize}
\end{definition}

\begin{remark}\label{rmk:dof-for-T-cats}
    Regarding virtual double categories as $T$-categories (see \cref{rmk:vdbl-cat-as-T-cat}), a virtual double functor $P\colon \vdcat{X}\to \vdcat{Y}$ is a discrete opfibration in the sense of \cref{def:disc-opfib} if and only if the left square in the following commutative diagram is a pullback in $\mathbf{Gph}$:
\begin{equation*}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(0) at (0,0) {$TX_0$};
      \node(1)at (2,0) {$X_1$};
      \node(2) at (4,0) {$X_0$};
      \node(00) at (0,-1.5) {$TY_0$};
      \node(01)at (2,-1.5) {$Y_1$};
      \node(02) at (4,-1.5) {$Y_0$.};
      \draw [->] (1) to node[auto,swap, labelsize] {$d_1$}  (0);
      \draw [->] (1) to node[auto,labelsize] {$d_0$}  (2);
      \draw [->] (01) to node[auto, labelsize] {$d_1$}  (00);
      \draw [->] (01) to node[auto,swap,labelsize] {$d_0$}  (02);
      \draw [->] (0) to node[auto,swap, labelsize] {$TP_0$}  (00);
      \draw [->] (1) to node[auto,labelsize] {$P_1$}  (01);
      \draw [->] (2) to node[auto,labelsize] {$P_0$}  (02);
\end{tikzpicture}
\end{equation*}
    Discrete opfibrations are defined in these terms in \cite[IV.2]{Burroni-T-cats} (where they are said to be \emph{\'etale}) and \cite[Section~6.3]{Leinster-HOHC}, and further studied in \cite{Tholen-Yeganeh}.
\end{remark}

The proof of the following fact is straightforward. 

\begin{proposition}\label{dof-between-vdbl-is-internal-dof}
    Any discrete opfibration of virtual double categories in the sense of \cref{def:disc-opfib} is a representable discrete opfibration in $\VDbl$. 
\end{proposition}

\begin{remark}\label{rmk:dof-vs-internal-dof}
    The converse of \cref{dof-between-vdbl-is-internal-dof} does not hold. 
    For example, for any virtual double category $\vdcat{Y}$, let $\vdcat{X}$ be the virtual double subcategory of $\vdcat{Y}$ obtained by discarding all multicells which are not cells, while retaining all objects, vertical morphisms, horizontal morphisms, and cells. Then the inclusion $P\colon \vdcat{X}\to \vdcat{Y}$ is a representable discrete opfibration in $\VDbl$. (That is, the functor $\VDbl(\vdcat{A},P)\colon \VDbl(\vdcat{A},\vdcat{X})\to \VDbl(\vdcat{A},\vdcat{Y})$ is a discrete opfibration for any $\vdcat{A}\in \VDbl$. To see this, observe that if $\vdcat{A}$ has a multicell which is not a cell, then the category $\VDbl(\vdcat{A},\vdcat{X})$ is empty, and otherwise, $\VDbl(\vdcat{A},P)$ is an isomorphism of categories.) 
    However, $P\colon \vdcat{X}\to\vdcat{Y}$ fails to be a discrete opfibration in the sense of \cref{def:disc-opfib} whenever $\vdcat{Y}$ has a multicell which is not a cell. 
\end{remark}

In what follows, whenever we talk about discrete opfibrations between virtual double categories, we mean those in the sense of \cref{def:disc-opfib} rather than representable discrete opfibrations in $\VDbl$.

\begin{proposition}
    \label{prop:disc-opfib-powerful}
    Every discrete opfibration $P\colon \vdcat{X}\to\vdcat{Y}$ between virtual double categories is powerful; that is, we have a $2$-adjunction 
    \begin{equation}
\label{eqn:prod-ast}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(0) at (0,0) {$\VDbl/\vdcat{X}$};
      \node(1) at (4,0) {$\VDbl/\vdcat{Y}$.};
      \draw [<-, transform canvas={yshift=5}] (0) to node[auto, labelsize] {$P^\ast$}  (1);  
      \draw [<-, transform canvas={yshift=-5}] (1) to node[auto, labelsize] {$\prod_P$}  (0); 
      \path(0) to node[rotate=-90] {$\dashv$} (1);
\end{tikzpicture}
\end{equation}
\end{proposition}
\begin{proof}
We proceed as follows. First, for any $(F\colon \vdcat{A}\to \vdcat{X})\in\VDbl/\vdcat{X}$, we define $(\prod_PF\colon \prod_P\vdcat{A}\to \vdcat{Y})\in\VDbl/\vdcat{Y}$ and a morphism $\varepsilon_{F}\colon (P^\ast\prod_PF\colon P^\ast \prod_P\vdcat{A}\to \vdcat{X})\to (F\colon \vdcat{A}\to \vdcat{X})$ in $\VDbl/\vdcat{X}$. We then see that for any $(G\colon \vdcat{B}\to \vdcat{Y})\in \VDbl/\vdcat{Y}$, the composite
\begin{multline}
\label{eqn:composite-epsilon-powerful}
(\VDbl/\vdcat{Y})\left(
\left(
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(00) at (0,0.4) {$\vdcat{B}$};
      \node(10) at (0,-0.4) {$\vdcat{Y}$}; 
      \draw [->] (00) to node[auto, labelsize] {$G$} (10);  
\end{tikzpicture}
\right),
\left(
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(00) at (0,0.4) {$\prod_P\vdcat{A}$};
      \node(10) at (0,-0.4) {$\vdcat{Y}$}; 
      \draw [->] (00) to node[auto, labelsize] {$\prod_PF$} (10);  
\end{tikzpicture}
\right)\right)
\xrightarrow{P^\ast_{G,\prod_PF}}
(\VDbl/\vdcat{X})\left(
\left(
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(00) at (0,0.4) {$P^\ast\vdcat{B}$};
