\right),
\left(
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(00) at (0,0.4) {$P^\ast \prod_P\vdcat{A}$};
      \node(10) at (0,-0.4) {$\vdcat{X}$}; 
      \draw [->] (00) to node[auto, labelsize] {$P^\ast \prod_PF$} (10);  
\end{tikzpicture}
\right)\right)\\
\xrightarrow{(\VDbl/\vdcat{X})(1,\varepsilon_F)}
(\VDbl/\vdcat{X})\left(
\left(
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(00) at (0,0.4) {$P^\ast\vdcat{B}$};
