is an isomorphism of categories. 
It then follows that the assignment $(\vdcat{A},F)\mapsto (\prod_P\vdcat{A},\prod_PF)$ uniquely extends to a $2$-functor so that $\varepsilon$ becomes $2$-natural, and becomes the counit of the $2$-adjunction \cref{eqn:prod-ast}. 

For each object $Y\in\vdcat{Y}$, we denote by $P^{-1}(Y)$ the set of all objects $X\in\vdcat{X}$ with $PX=Y$, and for each horizontal morphism $\Psi$ in $\vdcat{Y}$, we denote by $P^{-1}(\Psi)$ the set of all horizontal morphisms $\Phi$ in $\vdcat{X}$ with $P\Phi=\Psi$.
Take any $(F\colon \vdcat{A}\to \vdcat{X})\in \VDbl/\vdcat{X}$. We define the virtual double category $\prod_P\vdcat{A}$ as follows. 
\begin{itemize}
    \item An object in $\prod_P\vdcat{A}$ is a pair $(Y,\vect{A})$ of an object $Y\in\vdcat{Y}$ and a family $\vect{A}=(A_X)_{X\in P^{-1}(Y)}$ of objects in $\vdcat{A}$, satisfying $FA_X=X$ for each $X\in P^{-1}(Y)$.
    \item A vertical morphism in $\prod_P\vdcat{A}$ from $(Y,\vect{A})$ to $(Y',\vect{A}')$ is a pair $(v,\vect{f})$ of a vertical morphism $v\colon Y\to Y'$ in $\vdcat{Y}$ and a family $\vect{f}=(f_X\colon A_X\to A'_{v_\ast X})_{X\in P^{-1}(Y)}$ of vertical morphisms in $\vdcat{A}$, satisfying $Ff_X= \overline v_X\colon X\to v_\ast X$ for each $X\in P^{-1}(Y)$.
    (The vertical category $(\prod_P\vdcat{A})_\vc$ of $\prod_P\vdcat{A}$ is the category $\prod_{P_\vc}\vdcat{A}_\vc$ obtained by applying the $2$-functor $\prod_{P_\vc}\colon\CAT/\vdcat{X}_\vc\to \CAT/\vdcat{Y}_\vc$ to the object $(F_\vc\colon \vdcat{A}_\vc\to \vdcat{X}_\vc)\in \CAT/\vdcat{X}_\vc$.)
    \item A horizontal morphism in $\prod_P\vdcat{A}$ from $(Y,\vect{A})$ to $(Y',\vect{A}')$ is a pair $(\Psi,\vect{\Gamma})$ of a horizontal morphism $\Psi\colon Y\pto Y'$ in $\vdcat{Y}$ and a family $\vect{\Gamma}$ of horizontal morphisms which consists of, for each $(\Phi\colon X\pto X')\in P^{-1}(\Psi)$, a horizontal morphism $\Gamma_\Phi\colon A_X\pto A'_{X'}$ in $\vdcat{A}$ satisfying $F\Gamma_\Phi=\Phi$.
    \item A multicell in $\prod_P\vdcat{A}$ of type
\begin{equation}
\label{eqn:multicell-in-ProdP}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(00) at (0,0.75) {$(Y_0,\vect{A}_0)$};
      \node(01) at (2.5,0.75) {$(Y_1,\vect{A}_1)$};
      \node(02) at (5,0.75) {$\cdots$};
      \node(03) at (7.5,0.75) {$(Y_n,\vect{A}_n)$};
      \node(10) at (0,-0.75) {$(Y,\vect{A})$};
      \node(11) at (7.5,-0.75) {$(Y',\vect{A}')$};
      \draw [pto] (00) to node[auto, labelsize] {$(\Psi_1,\vect{\Gamma}_1)$} (01);
      \draw [pto] (01) to node[auto, labelsize] {$(\Psi_2,\vect{\Gamma}_2)$} (02);
      \draw [pto] (02) to node[auto, labelsize] {$(\Psi_n,\vect{\Gamma}_n)$} (03);
      \draw [pto] (10) to node[auto, swap, labelsize] {$(\Psi,\vect{\Gamma})$} (11);
      \draw [->] (00) to node[auto, swap, labelsize] {$(v,\vect{f})$} (10); 
      \draw [->] (03) to node[auto,labelsize] {$(v',\vect{f}')$} (11);
      \node at (3.75,0) {$(\nu,\vect{\alpha})$};
\end{tikzpicture}
\end{equation}
is a pair of a multicell 
\begin{equation*}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(00) at (0,0.75) {$Y_0$};
      \node(01) at (1.5,0.75) {$Y_1$};
      \node(02) at (3,0.75) {$\cdots$};
      \node(03) at (4.5,0.75) {$Y_n$};
