      \draw [pto] (10) to node[auto, swap, labelsize] {$\Psi$} (11); 
      \draw [->] (00) to node[auto, swap, labelsize] {$v$} (10); 
      \draw [->] (03) to node[auto,labelsize] {$v'$} (11);
      \node at (2.25,0) {$\nu$}; 
\end{tikzpicture}
\end{equation*}
in $\vdcat{Y}$ and a family $\vect{\alpha}$ of multicells which consists of, for each sequence of horizontal morphisms 
\begin{equation*}
    \begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(00) at (0,0) {$X_0$};
      \node(01) at (1.5,0) {$X_1$};
