a multicell 
\begin{equation*}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(00) at (0,0.75) {$A_{0,X_0}$};
      \node(01) at (2,0.75) {$A_{1,X_1}$};
      \node(02) at (4,0.75) {$\cdots$};
