\end{equation*}
in $\VDbl$.
Explicitly, the virtual double category $P^\ast \prod_P\vdcat{A}$ can be described as follows. 
\begin{itemize}
    \item An object in $P^\ast \prod_P\vdcat{A}$ is a triple $(Y,\vect{A},\dot{X})$ consisting of an object $(Y,\vect{A})$ in $\prod_P\vdcat{A}$ and an object $\dot{X}\in \vdcat{X}$ satisfying $(\prod_PF)(Y,\vect{A})=P\dot{X}$, or equivalently, $\dot{X}\in P^{-1}(Y)$. 
    \item A vertical morphism in $P^\ast \prod_P\vdcat{A}$ from $(Y,\vect{A},\dot{X})$ to $(Y',\vect{A}',\dot{X}')$ is a triple $(v,\vect{f},u)$ consisting of a vertical morphism $(v,\vect{f})\colon (Y,\vect{A})\to (Y',\vect{A}')$ in $\prod_P\vdcat{A}$ and a vertical morphism $u\colon \dot{X}\to\dot{X}'$ in $\vdcat{X}$ satisfying $(\prod_PF)(v,\vect{f})=Pu$. Notice that we necessarily have $u=\overline v_{\dot{X}}$, and hence a vertical morphism in $P^\ast \prod_P\vdcat{A}$ from $(Y,\vect{A},\dot{X})$ to $(Y',\vect{A}',\dot{X}')$ can be equivalently given by a vertical morphism $(v,\vect{f})\colon (Y,\vect{A})\to (Y',\vect{A}')$ in $\prod_P\vdcat{A}$ satisfying $v_\ast \dot{X} = \dot{X}'$. 
    \item A horizontal morphism in $P^\ast \prod_P\vdcat{A}$ from $(Y,\vect{A},\dot{X})$ to $(Y',\vect{A}',\dot{X}')$ is a triple $(\Psi,\vect{\Gamma},\dot{\Phi})$ consisting of a horizontal morphism $(\Psi,\vect{\Gamma})\colon (Y,\vect{A})\pto (Y',\vect{A}')$ in $\prod_P\vdcat{A}$ and a horizontal morphism $\dot{\Phi}\colon \dot{X}\pto \dot{X}'$ in $\vdcat{X}$ satisfying $(\prod_PF)(\Psi,\vect{\Gamma})=P\dot{\Phi}$, or equivalently, $\dot{\Phi}\in P^{-1}(\Psi)$.
    \item A multicell in $P^\ast\prod_P\vdcat{A}$ of type
        \begin{equation}
\label{eqn:multicell-in-PastProdP}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(00) at (0,0.75) {$(Y_0,\vect{A}_0,\dot{X}_0)$};
      \node(01) at (3.5,0.75) {$(Y_1,\vect{A}_1,\dot{X}_1)$};
      \node(02) at (6.5,0.75) {$\cdots$};
      \node(03) at (9.5,0.75) {$(Y_n,\vect{A}_n,\dot{X}_n)$};
      \node(10) at (0,-0.75) {$(Y,\vect{A},\dot{X})$};
      \node(11) at (9.5,-0.75) {$(Y',\vect{A}',\dot{X}')$}; 
      \draw [pto] (00) to node[auto, labelsize] {$(\Psi_1,\vect{\Gamma}_1,\dot{\Phi}_1)$} (01);    
      \draw [pto] (01) to node[auto, labelsize] {$(\Psi_2,\vect{\Gamma}_2,\dot{\Phi}_2)$} (02);   
      \draw [pto] (02) to node[auto, labelsize] {$(\Psi_n,\vect{\Gamma}_n,\dot{\Phi}_n)$} (03);  
      \draw [pto] (10) to node[auto, swap, labelsize] {$(\Psi,\vect{\Gamma},\dot{\Phi})$} (11); 
      \draw [->] (00) to node[auto, swap, labelsize] {$(v,\vect{f},u)$} (10); 
      \draw [->] (03) to node[auto,labelsize] {$(v',\vect{f}',u)$} (11);
      \node at (4.75,0) {$(\nu,\vect{\alpha},\chi)$}; 
\end{tikzpicture}
\end{equation}
    consists of a multicell \eqref{eqn:multicell-in-ProdP} in $\prod_P\vdcat{A}$ and a multicell 
    \begin{equation*}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(00) at (0,0.75) {$\dot{X}_0$};
      \node(01) at (1.5,0.75) {$\dot{X}_1$};
      \node(02) at (3,0.75) {$\cdots$};
      \node(03) at (4.5,0.75) {$\dot{X}_n$};
      \node(10) at (0,-0.75) {$v_\ast \dot{X}_0$};
      \node(11) at (4.5,-0.75) {$v'_\ast \dot{X}_n$}; 
      \draw [pto] (00) to node[auto, labelsize] {$\dot{\Phi}_1$} (01);  
      \draw [pto] (01) to node[auto, labelsize] {$\dot{\Phi}_2$} (02);  
      \draw [pto] (02) to node[auto, labelsize] {$\dot{\Phi}_n$} (03);  
      \draw [pto] (10) to node[auto, swap, labelsize] {$\dot{\Phi}$} (11); 
      \draw [->] (00) to node[auto, swap, labelsize] {$\overline v_{\dot{X}_0}$} (10); 
      \draw [->] (03) to node[auto,labelsize] {$\overline{v'}_{\dot{X}_n}$} (11);
      \node at (2.25,0) {$\chi$}; 
\end{tikzpicture}
\end{equation*}
    in $\vdcat{X}$ satisfying $(\prod_PF)(\nu,\vect{\alpha})=P\chi$. Notice that we necessarily have $\chi=\overline \nu_{\dot{\Phi}_1,\dots,\dot{\Phi}_n}$, and hence the multicell $(\nu,\vect{\alpha},\chi)$ can be equivalently given by the multicell $(\nu,\vect{\alpha})$ in $\prod_P\vdcat{A}$ satisfying $\nu_\ast (\dot{\Phi}_1,\dots,\dot{\Phi}_n)=\dot{\Phi}$. 
\end{itemize}
The virtual double functor $P^\ast \prod_PF\colon P^\ast\prod_P\vdcat{A}\to \vdcat{X}$ is given by the third projection. 

Next we define the morphism $\varepsilon_{F}\colon (P^\ast\prod_PF\colon P^\ast \prod_P\vdcat{A}\to \vdcat{X})\to (F\colon \vdcat{A}\to \vdcat{X})$ in $\VDbl/\vdcat{X}$, i.e., a virtual double functor $\varepsilon_F\colon P^\ast\prod_P\vdcat{A}\to \vdcat{A}$ making the diagram 
\begin{equation*}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(00) at (0,0.75) {$P^\ast \prod_P\vdcat{A}$};
      \node(01) at (2,0.75) {$\vdcat{A}$};
      \node(10) at (1,-0.75) {$\vdcat{X}$};
      \draw [->] (00) to node[auto, labelsize] {$\varepsilon_F$} (01);   
      \draw [->] (00) to node[auto, swap, labelsize] {$P^\ast \prod_PF$} (10); 
      \draw [->] (01) to node[auto, labelsize] {$F$} (10);
\end{tikzpicture}
\end{equation*}
commute. 
\begin{itemize}
    \item An object $(Y,\vect{A},\dot{X})\in P^\ast\prod_P\vdcat{A}$ is mapped by $\varepsilon_F$ to $A_{\dot{X}}\in\vdcat{A}$. 
    \item A vertical morphism $(v,\vect{f},u)\colon (Y,\vect{A},\dot{X})\to (Y',\vect{A}',\dot{X}')$ in $P^\ast \prod_P\vdcat{A}$ is mapped by $\varepsilon_F$ to $f_{\dot{X}}\colon A_{\dot{X}}\to A'_{v_\ast \dot{X}}=A'_{\dot{X}'}$ in $\vdcat{A}$.
    \item A horizontal morphism $(\Psi,\vect{\Gamma},\dot{\Phi})\colon (Y,\vect{A},\dot{X})\pto (Y',\vect{A}',\dot{X}')$ in $P^\ast \prod_P\vdcat{A}$ is mapped by $\varepsilon_F$ to $\Gamma_{\dot{\Phi}}\colon A_{\dot{X}}\pto A'_{\dot{X}'}$ in $\vdcat{A}$. 
    \item A multicell \eqref{eqn:multicell-in-PastProdP} in $P^\ast \prod_P\vdcat{A}$ is mapped by $\varepsilon_F$ to 
    \begin{equation*}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(00) at (0,0.75) {$A_{0,\dot{X}_0}$};
      \node(01) at (2,0.75) {$A_{1,\dot{X}_1}$};
      \node(02) at (4,0.75) {$\cdots$};
      \node(03) at (6,0.75) {$A_{n,\dot{X}_n}$};
      \node(10) at (0,-0.75) {$A_{\dot{X}}$};
      \node(11) at (6,-0.75) {$A'_{\dot{X}'}$}; 
      \draw [pto] (00) to node[auto, labelsize] {${\Gamma}_{1,\dot{\Phi}_1}$} (01);  
      \draw [pto] (01) to node[auto, labelsize] {${\Gamma}_{2,\dot{\Phi}_2}$} (02);  
      \draw [pto] (02) to node[auto, labelsize] {${\Gamma}_{n,\dot{\Phi}_n}$} (03);  
      \draw [pto] (10) to node[auto, swap, labelsize] {${\Gamma}_{\dot{\Phi}}$} (11); 
      \draw [->] (00) to node[auto, swap, labelsize] {$f_{\dot{X}_0}$} (10); 
      \draw [->] (03) to node[auto,labelsize] {$f'_{\dot{X}_n}$} (11);
      \node at (3,0) {$\alpha_{\dot{\Phi}_1,\dots,\dot{\Phi}_n}$}; 
\end{tikzpicture}
\end{equation*}
in $\vdcat{A}$.
\end{itemize}

Now it is straightforward to check that \eqref{eqn:composite-epsilon-powerful} is an isomorphism of categories.
\end{proof}

In a forthcoming paper \cite{TCat-Conduche}, we give a far larger class of virtual double functors which are powerful. In fact we work in the more general setting of $T$-categories for a monad $T$, subject to various conditions. As recalled in \cref{rmk:vdbl-cat-as-T-cat}, virtual double categories correspond to the case where $T$ is the monad on $\Gph$ whose Eilenberg--Moore category is $\Cat$.

\section{The polynomial 2-functor \texorpdfstring{$\MMat$}{Mat}}
\label{sec:MMat}
In this section, we define the $2$-functor $\MMat\colon \VDbl\to \VDbl$ which appears as the first factor in the decomposition \eqref{eqn:Enr-decomposition} of $\Enr\colon \VDbl\to\twoCAT$.

First observe that the $2$-functor $(-)_\vc\colon \VDbl\to\CAT$, mapping each virtual double category $\vdcat{A}$ to its vertical category $\vdcat{A}_\vc$, has a right $2$-adjoint:
\begin{equation*}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(0) at (0,0) {$\VDbl$};
      \node(0a)at (4,0) {$\CAT$.};
      \draw [->, transform canvas={yshift=5}] (0) to node[auto, labelsize] {$(-)_\vc$}  (0a);
      \draw [->, transform canvas={yshift=-5}] (0a) to node[auto, labelsize] {$(-)_\hc$}  (0);
      \path(0) to node[rotate=-90] {$\dashv$} (0a);
\end{tikzpicture}
\end{equation*}
The right $2$-adjoint $(-)_\hc$ maps each category $\cat{C}$ to the virtual double category $\cat{C}_\hc$ whose vertical category is $\cat{C}$, and such that 
\begin{itemize}
    \item for each pair $C,C'$ of objects of $\cat{C}$, there exists precisely one horizontal morphism $C\pto C'$ in $\cat{C}_\hc$, and 
    \item for each configuration 
\begin{equation}
\label{eqn:boundary-of-2-cell-in-C-hc}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(00) at (0,0.75) {$C_0$};
      \node(01) at (1.5,0.75) {$C_1$};
      \node(02) at (3,0.75) {$\cdots$};
      \node(03) at (4.5,0.75) {$C_n$};
      \node(10) at (0,-0.75) {$C$};
      \node(11) at (4.5,-0.75) {$C'$}; 
      \draw [pto] (00) to node[auto, labelsize] {} (01);  
      \draw [pto] (01) to node[auto, labelsize] {} (02);  
      \draw [pto] (02) to node[auto, labelsize] {} (03);  
      \draw [pto] (10) to node[auto, swap, labelsize] {} (11); 
      \draw [->] (00) to node[auto, swap, labelsize] {$f$} (10); 
      \draw [->] (03) to node[auto,labelsize] {$f'$} (11);
\end{tikzpicture}    
\end{equation}
    in $\cat{C}_\hc$, there exists precisely one multicell having \cref{eqn:boundary-of-2-cell-in-C-hc} as the boundary. 
\end{itemize}
We call a virtual double category \emph{horizontally chaotic} if it is in the essential image of $(-)_\hc$.

\begin{remark}
    Although we shall not use this fact, the $2$-functor $(-)_\vc$ also has a left $2$-adjoint $(-)_\he\colon \CAT\to \VDbl$, mapping each category $\cat{C}$ to the ``horizontally empty'' virtual double category $\cat{C}_\he$ whose vertical category is $\cat{C}$, and such that there is no horizontal morphisms (and hence no multicells) in $\cat{C}_\he$. Note that we have $(-)_\vc\cong \VDbl(1_\he,-)$, where $1$ denotes the terminal category.

    The composite 
    \begin{equation*}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(0) at (0,0) {$\VDbl$};
      \node(1)at (2,0) {$\CAT$};
      \node(2) at (4,0) {$\VDbl$};
      \draw [->] (0) to node[auto, labelsize] {$(-)_\vc$}  (1);
      \draw [->] (1) to node[auto,labelsize] {$(-)_\he$}  (2);
\end{tikzpicture}
\end{equation*}
    coincides with the product $1_\he\times(-)\colon\VDbl\to\VDbl$ with $1_\he$, and hence its right $2$-adjoint, namely the composite 
    \begin{equation*}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(0) at (0,0) {$\VDbl$};
      \node(1)at (2,0) {$\CAT$};
      \node(2) at (4,0) {$\VDbl$,};
      \draw [->] (0) to node[auto, labelsize] {$(-)_\vc$}  (1);
      \draw [->] (1) to node[auto,labelsize] {$(-)_\hc$}  (2);
\end{tikzpicture}
\end{equation*}
    is the exponentiation $(-)^{1_\he}\colon \VDbl\to\VDbl$ by $1_\he$. (Although $\VDbl$ is not cartesian closed, the object $1_\he$ is powerful. In fact, for any $\cat{C}\in\CAT$, the object $\cat{C}_\he\in\VDbl$ is powerful in $\VDbl$, as the $2$-functor $\cat{C}_\he\times (-)\colon\VDbl\to \VDbl$ is the composite 
    \begin{equation*}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(0) at (0,0) {$\VDbl$};
      \node(1) at (2,0) {$\CAT$};
      \node(2) at (4,0) {$\CAT$};
      \node(3) at (6,0) {$\VDbl$};
      \draw [->] (0) to node[auto, labelsize] {$(-)_\vc$}  (1);
