\begin{proof}
    Apply the uniqueness part of the universal property of opcartesian multicells of the form $\widetilde\eta_D$ repeatedly.
\end{proof}

Thus for any unital virtual double category $\vdcat{D}$, we obtain a unital virtual double functor $\Inc_\vdcat{D}\colon \vdcat{D}\to \MMod(\UU\vdcat{D})$. 
The $2$-naturality of $\Inc\colon 1_\VDbln\to \MMod\UU$ follows from the following proposition.

\begin{proposition}
\label{prop:strictly-unital-pres-mu-omega-lambda-rho}
    Let $\vdcat{D}$ and $\vdcat{E}$ be unital virtual double categories, and $F\colon \vdcat{D}\to \vdcat{E}$ be a unital virtual double functor. 
    \begin{enumerate}
        \item For each object $D$ in $\vdcat{D}$, we have $F\widetilde\mu^\vdcat{D}_D = \widetilde\mu_{FD}^\vdcat{E}$. 
        \item For each vertical morphism $u$ in $\vdcat{D}$, we have $F\widetilde\omega_u^\vdcat{D} = \widetilde \omega_{Fu}^\vdcat{E}$.
        \item For each horizontal morphism $\Gamma$ in $\vdcat{D}$, we have $F\widetilde\lambda_\Gamma^\vdcat{D}=\widetilde\lambda_{F\Gamma}^\vdcat{E}$ and $F\widetilde\rho_{\Gamma}^\vdcat{D}=\widetilde\rho_{F\Gamma}^\vdcat{E}$. 
    \end{enumerate}
    If in addition we have a unital virtual double functor $G\colon\vdcat{D}\to \vdcat{E}$ and a vertical transformation $\alpha\colon F\to G$, then we have $\alpha_{\hu^\vdcat{D}_D}=\widetilde\omega^\vdcat{E}_{\alpha_D}$ for each object $D$ in $\vdcat{D}$.
\end{proposition}

Finally, we check the triangle identities.
That $\Und_{\UU\vdcat{D}}. \UU\Inc_\vdcat{D}=1_{\UU\vdcat{D}}$ holds for each unital virtual double category $\vdcat{D}$ is obvious.
The other triangle identity is a consequence of the following. 

\begin{proposition}
\label{prop:tilde-in-Mod}
    Let $\vdcat{A}$ be a virtual double category. 
    In the unital virtual double category $\MMod(\vdcat{A})$, the multicells introduced in \cref{def:omega-lambda-rho-in-unital-vdbl,defining-Inc} satisfy the following. 
    \begin{enumerate}
        \item For each object $\mnd{T}=(A,T,\eta,\mu)$ in $\MMod(\vdcat{A})$, we have $\widetilde\mu_\mnd{T}=\mu$.
        \item For each vertical morphism $\vmm{u}=(u,\omega)$ in $\MMod(\vdcat{A})$, we have $\widetilde\omega_{\vmm{u}}=\omega$. 
        \item For each horizontal morphism $\hbm{\Gamma}=(\Gamma,\lambda,\rho)$ in $\MMod(\vdcat{A})$, we have $\widetilde\lambda_{\hbm{\Gamma}}=\lambda$ and $\widetilde\rho_{\hbm{\Gamma}}=\rho$. 
    \end{enumerate}
\end{proposition}

This completes the construction of the $2$-adjunction \cref{eqn:U-Mod-adjunction}. 

As mentioned in \cref{sec:intro}, we define $\EEnr$ as the composite $2$-functor 
\begin{equation*}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(0) at (0,0)  {$\VDbl$};
      \node(1) at (3,0)  {$\VDbl$};
      \node(2) at (6.5,0)  {$\VDbln$.};
      \draw [->] (0) to node[auto, labelsize] {$\MMat$}  (1);
      \draw [->] (1) to node[auto, labelsize] {$\MMod$}  (2);
\end{tikzpicture}
\end{equation*}
For each $\vdcat{A}\in \VDbl$, the unital virtual double category $\EEnr(\vdcat{A})=\MMod(\enMMat{\vdcat{A}})$ is also denoted by $\PProf{\vdcat{A}}$ (see \cite[Example~2.9]{Cruttwell-Shulman-unified}).
The objects and vertical morphisms of $\PProf{\vdcat{A}}$ coincide with the small $\vdcat{A}$-categories and $\vdcat{A}$-functors defined in \cref{subsec:enrichment-over-vdbl}, whereas 
the $\vdcat{A}$-natural transformations appear as special cases of multicells in $\PProf{\vdcat{A}}$ (see \cref{subsec:VV-V} for details).
The horizontal morphisms of $\PProf{\vdcat{A}}$ are called the \emph{$\vdcat{A}$-profunctors}.

\begin{theorem}\label{EEnr-is-familial}
    The $2$-functor $\EEnr\colon \VDbl\to \VDbln$ sending $\vdcat{A}$ to $\PProf{\vdcat{A}}$ is given by the composite $\MMod\circ\MMat$ and so is familial.
\end{theorem}

\begin{proof}
    $\MMat$ is familial by \cref{prop:MMat} while $\MMod$ is a right $2$-adjoint and so familial by \cref{ex:right-adj-familial}.
    The claim follows from the fact that familial $2$-functors are closed under composition. 
\end{proof}

\begin{remark}
    In fact, for any unital virtual double category $\vdcat{D}$, the virtual double functors $\UU\Inc_\vdcat{D}$ and $\Und_{\UU\vdcat{D}}$ form an adjunction
    \begin{equation*}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(0) at (0,0) {$\UU\vdcat{D}$};
      \node(1) at (4,0) {$\UU\MMod(\UU\vdcat{D})$};
      \draw [->, transform canvas={yshift=5}] (0) to node[auto, labelsize] {$\UU\Inc_\vdcat{D}$}  (1);  
      \draw [->, transform canvas={yshift=-5}] (1) to node[auto, labelsize] {$\Und_{\UU\vdcat{D}}$}  (0); 
      \path(0) to node[rotate=-90] {$\dashv$} (1);
\end{tikzpicture}
\end{equation*}
    with identity unit in $\VDbl$.
\end{remark}

\subsection{The 2-adjunction $\FF\dashv \UU$}
Here we show that 
the forgetful $2$-functor $\UU\colon \VDbln\to \VDbl$ has a left $2$-adjoint $\FF\colon \VDbl\to \VDbln$ as well. 
Given a virtual double category $\vdcat{A}$, define the virtual double category $\FF\vdcat{A}$ as follows.
\begin{itemize}
    \item The vertical category of $\FF\vdcat{A}$ is identical to the vertical category of $\vdcat{A}$. 
    \item The horizontal morphisms of $\FF\vdcat{A}$ are those of $\vdcat{A}$ together with a new horizontal morphism $\hu_A\colon A\pto A$ for each object $A\in\vdcat{A}$. 
    \item Given a configuration 
    \begin{equation}
\label{eqn:boundary-of-2-cell-in-FA}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(00) at (0,0.75) {$A_0$};
      \node(01) at (1.5,0.75) {$A_1$};
      \node(02) at (3,0.75) {$\cdots$};
      \node(03) at (4.5,0.75) {$A_n$};
      \node(10) at (0,-0.75) {$B$};
      \node(11) at (4.5,-0.75) {$B'$}; 
      \draw [pto] (00) to node[auto, labelsize] {$\Gamma_1$} (01);  
      \draw [pto] (01) to node[auto, labelsize] {$\Gamma_2$} (02);  
      \draw [pto] (02) to node[auto, labelsize] {$\Gamma_n$} (03);  
      \draw [pto] (10) to node[auto, swap, labelsize] {$\Delta$} (11); 
      \draw [->] (00) to node[auto, swap, labelsize] {$u$} (10); 
      \draw [->] (03) to node[auto,labelsize] {$u'$} (11);
\end{tikzpicture}    
\end{equation}
    in $\FF\vdcat{A}$, if $\Delta\neq\hu_B$, then 
    the multicells in $\FF\vdcat{A}$ having \eqref{eqn:boundary-of-2-cell-in-FA} as the boundary are in bijection with the multicells in $\vdcat{A}$ having ``\eqref{eqn:boundary-of-2-cell-in-FA} with $\hu_A$'s erased'' as the boundary. 
    If $\Delta=\hu_B$, then there exists at most one multicell in $\FF\vdcat{A}$ having \eqref{eqn:boundary-of-2-cell-in-FA} as the boundary, and such a multicell exists in $\FF\vdcat{A}$ if and only if $u=u'$ and each horizontal morphism $\Gamma_i$ is of the form $\hu_A$. 
\end{itemize}
Then $\FF\vdcat{A}$ has the evident structure of a virtual double category. 
Moreover, for each object $A$, the unique multicell in $\FF\vdcat{A}$ having 
\begin{equation*}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(00) at (0.75,0.75) {$A$};
      \node(10) at (0,-0.75) {$A$};
      \node(11) at (1.5,-0.75) {$A$}; 
      \draw [pto] (10) to node[auto, swap, labelsize] {$\hu_A$} (11); 
      \draw [double equal sign distance] (00) to (10); 
      \draw [double equal sign distance] (00) to (11); 
\end{tikzpicture}
\end{equation*}
as the boundary, is opcartesian in $\FF\vdcat{A}$. Hence $\FF\vdcat{A}$ is a unital virtual double category.
We have the canonical inclusion virtual double functor $\vdcat{A}\to \UU\FF\vdcat{A}$, which can be easily seen to have the required universal property. 

Therefore $\UU\colon\VDbln\to \VDbl$ is a right $2$-adjoint, and we obtain the following variants of \cref{EEnr-is-familial}. 
\begin{proposition}
    The $2$-functors $\VDbl\xrightarrow{\EEnr}\VDbln\xrightarrow{\UU}\VDbl$, $\VDbln\xrightarrow{\UU}\VDbl\xrightarrow{\EEnr}\VDbln$, and $\VDbln\xrightarrow{\UU}\VDbl\xrightarrow{\EEnr}\VDbln\xrightarrow{\UU}\VDbl$ are familial.
\end{proposition}
\begin{proof}
    These are all composites of familial $2$-functors.
\end{proof}

\subsection{The 2-adjunction $\VV\dashv\V$}\label{subsec:VV-V}
In this subsection, we establish the 2-adjunction
\[
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(0) at (0,0) {$\VDbln$};
      \node(1) at (4,0) {$\twoCAT$.};
      \draw [<-, transform canvas={yshift=5}] (0) to node[auto, labelsize] {$\VV$}  (1);  
      \draw [<-, transform canvas={yshift=-5}] (1) to node[auto, labelsize] {$\V$}  (0); 
      \path(0) to node[rotate=-90] {$\dashv$} (1);
\end{tikzpicture}
\]

Given a 2-category $\tcat{K}$, we define the virtual double category $\VV\tcat{K}$ as follows. 
\begin{itemize}
    \item The vertical category $(\VV\tcat{K})_\vc$ of $\VV\tcat{K}$ is the underlying category $\tcat{K}_0$ of $\tcat{K}$.
    \item For each object $K$ in $\tcat{K}$, there is a horizontal morphism $\hu_K\colon K\pto K$ in $\VV\tcat{K}$; there are no other horizontal morphisms in $\VV\tcat{K}$.
    \item For each configuration 
\begin{equation}
\label{eqn:boundary-VV-K}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(00) at (0,0.75) {$K$};
      \node(01) at (1.5,0.75) {$K$};
      \node(02) at (3,0.75) {$\cdots$};
      \node(03) at (4.5,0.75) {$K$};
      \node(10) at (0,-0.75) {$L$};
      \node(11) at (4.5,-0.75) {$L$}; 
      \draw [pto] (00) to node[auto, labelsize] {$\hu_K$} (01);  
      \draw [pto] (01) to node[auto, labelsize] {$\hu_K$} (02);  
      \draw [pto] (02) to node[auto, labelsize] {$\hu_K$} (03);  
      \draw [pto] (10) to node[auto, swap, labelsize] {$\hu_L$} (11); 
      \draw [->] (00) to node[auto, swap, labelsize] {$f$} (10); 
      \draw [->] (03) to node[auto,labelsize] {$f'$} (11);
\end{tikzpicture}
\end{equation}
    in $\VV\tcat{K}$, where there are $n$ copies of $\hu_K$ with $n\in\mathbb{N}$, the multicells in $\VV\tcat{K}$ having \eqref{eqn:boundary-VV-K} as the boundary are in bijection with the 2-cells from $f$ to $f'$ in $\tcat{K}$. 
\end{itemize}
Then $\VV\tcat{K}$ becomes a virtual double category under the natural operations.
Moreover, each multicell in $\VV\tcat{K}$ corresponding to the identity $2$-cell on an identity $1$-cell of $\tcat{K}$ is opcartesian. Hence we can make $\VV\tcat{K}$ into an object of $\VDbln$. 

On the other hand, given $\vdcat{D}\in\VDbln$, with chosen horizontal units $\bigl((\hu_D,\widetilde\eta_D)\bigr)_{D\in\vdcat{D}}$,
we define the 2-category $\V\vdcat{D}$ as follows. 
\begin{itemize}
    \item The underlying category $(\V\vdcat{D})_0$ of $\V\vdcat{D}$ is the vertical category $\vdcat{D}_\vc$ of $\vdcat{D}$. 
    \item For each parallel pair of morphisms $u,u'\colon D\to E$ in $(\V\vdcat{D})_0$, the set of all 2-cells from $u$ to $u'$ in $\V\vdcat{D}$ is the set of all cells 
    \begin{equation}
    \label{eqn:theta-in-VA}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(20) at (0,0.75) {$D$};
      \node(21) at (1.5,0.75) {$D$};
      \node(00) at (0,-0.75) {$E$};
      \node(01) at (1.5,-0.75) {$E$}; 
      \draw [pto] (20) to node[auto,labelsize] {$\hu_{D}$} (21);
      \draw [pto] (00) to node[auto,swap,labelsize] {$\hu_E$} (01);
      \draw [->] (20) to node[auto,swap,labelsize] {$u$} (00); 
      \draw [->] (21) to node[auto,labelsize] {$u'$} (01); 
      \node at (0.75,0) {$\theta$}; 
\end{tikzpicture}
\end{equation}
    in $\vdcat{D}$. 
\end{itemize}

Then one can make $\V\vdcat{D}$ into a $2$-category \cite[Proposition~6.1]{Cruttwell-Shulman-unified}. 

It is straightforward to see that we have a $2$-adjunction $\VV\dashv \V$.

Moreover, the composite $2$-functor $\VDbl\xrightarrow{\EEnr}\VDbln\xrightarrow{\V}\twoCAT$ is isomorphic to the $2$-functor $\Enr$ defined in \cref{subsec:enrichment-over-vdbl}; cf.\ \cite[Example~6.4]{Cruttwell-Shulman-unified}.
In particular, for any virtual double category $\vdcat{A}$, the $\vdcat{A}$-natural transformations correspond to the cells of the form \eqref{eqn:theta-in-VA} in $\PProf{\vdcat{A}}$.
Therefore we deduce the following.

\begin{theorem}
    The $2$-functor $\Enr\colon \VDbl\to \twoCAT$ is familial.
\end{theorem}

\section{The polynomial 2-functor \texorpdfstring{$\FFam$}{Fam} and virtual double categories of elements}
\label{sec:FFam}

For any category $\cat{C}$ with pullbacks, we have the virtual double category $\SSpan(\cat{C})$ 
whose vertical category is $\cat{C}$ and whose horizontal morphisms are spans in $\cat{C}$
\cite[Example~2.7]{Cruttwell-Shulman-unified}.
This construction defines a $2$-functor $\SSpan(-)\colon \CATpb\to \VDbl$, where $\CATpb$ is the $2$-category of large categories with pullbacks, pullback-preserving functors, and arbitrary natural transformations. 
We write the virtual double category $\SSpan(\Set)$ (resp.\ $\SSpan(\Set_\ast)$) as $\SSpan$ (resp.\ $\SSpan_\ast$). 

It is not difficult to see that the $2$-functor $\SSpan(-)\colon \CATpb\to \VDbl$ sends (pullback-preserving) discrete opfibrations between categories to discrete opfibrations between virtual double categories (in the sense of \cref{def:disc-opfib}). 
Therefore the forgetful functor $\Set_\ast\to \Set$ gives rise to a discrete opfibration $\SSpan_\ast\to \SSpan$ between virtual double categories, which we denote by $Q$. 

We define the $2$-functor $\FFam\colon\VDbl\to \VDbl$ as the composite 
\begin{equation}\label{eqn:FFam-composite}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(0) at (0,0)  {$\VDbl$};
      \node(1) at (4,0)  {$\VDbl/\SSpan_\ast$};
      \node(2) at (8,0)  {$\VDbl/\SSpan$};
      \node(3) at (12,0)  {$\VDbl$.};
      \draw [->] (0) to node[auto,labelsize] {$\SSpan_\ast\times (-)$}  (1);
      \draw [->] (1) to node[auto,labelsize] {$\prod_{Q}$}  (2);
      \draw [->] (2) to node[auto,labelsize] {forgetful}  (3);
\end{tikzpicture}
\end{equation}
That is, $\FFam$ is the polynomial $2$-functor $\mathcal{P}(Q)$ (see \cref{subsec:poly}). 
Using the construction given in the proof of \cref{prop:disc-opfib-powerful}, we can describe the virtual double category $\FFam(\vdcat{A})$ for $\vdcat{A}\in \VDbl$ as follows.
