The virtual double functor $P_F\colon \EElts(F)\to \vdcat{A}$ is given by the projection, and is a discrete opfibration (in the sense of \cref{def:disc-opfib}) because it is a pullback of a discrete opfibration $Q$.

Recall that the forgetful functor $\Set_\ast\to \Set$ is a universal discrete opfibration with small fibers in $\CAT$, in the sense that any discrete opfibration with small fibers in $\CAT$ can be obtained as a pullback of it.
We now show that $Q\colon \SSpan_\ast\to \SSpan$ is a universal discrete opfibration with small fibers in $\VDbl$. 
\begin{definition}
    A discrete opfibration $P\colon \vdcat{X}\to \vdcat{Y}$ between virtual double categories is said to have \emph{small fibres} if the following conditions are satisfied.
    \begin{itemize}
        \item For each object $Y\in\vdcat{Y}$, the set $P^{-1}(Y)$ of all objects $X\in \vdcat{Y}$ with $PX=Y$ is a small set. 
        \item For each horizontal morphism $\Psi$ in $\vdcat{Y}$, the set $P^{-1}(\Psi)$ of all horizontal morphisms $\Phi$ in $\vdcat{X}$ with $P\Phi=\Psi$ is a small set.
    \end{itemize}
\end{definition}

\begin{definition}\label{def:DP}
    Let $P\colon \vdcat{X}\to \vdcat{Y}$ be a discrete opfibration between virtual double categories having small fibres. Define a virtual double functor $D_P\colon \vdcat{Y}\to \SSpan$ as follows. 
    \begin{itemize}
        \item An object $Y$ of $\vdcat{Y}$ is mapped by $D_P$ to the set $P^{-1}(Y)$. 
        \item A vertical morphism $v\colon Y\to Y'$ of $\vdcat{Y}$ is mapped by $D_P$ to the function $v_\ast\colon P^{-1}(Y)\to P^{-1}(Y')$.
        \item A horizontal morphism $\Psi\colon Y\pto Y'$ of $\vdcat{Y}$ is mapped by $D_P$ to the span 
\[\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(0) at (0,-0.75) {$P^{-1}(Y)$};
      \node(10) at (1.5,0.75) {$P^{-1}(\Psi)$};
      \node(1) at (3,-0.75) {$P^{-1}(Y')$}; 
      \draw [->] (10) to node[auto, swap, labelsize] {$(-)_-$} (0); 
      \draw [->] (10) to node[auto, labelsize] {$(-)_+$} (1); 
\end{tikzpicture}\]
        of sets, where for each $(\Phi\colon X\pto X')\in P^{-1}(\Psi)$, we set $\Phi_-=X$ and $\Phi_+=X'$.
        \item A multicell 
        \begin{equation*}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(00) at (0,0.75) {$Y_0$};
      \node(01) at (1.5,0.75) {$Y_1$};
      \node(02) at (3,0.75) {$\cdots$};
      \node(03) at (4.5,0.75) {$Y_n$};
      \node(10) at (0,-0.75) {$Y$};
      \node(11) at (4.5,-0.75) {$Y'$}; 
      \draw [pto] (00) to node[auto, labelsize] {$\Psi_1$} (01);  
      \draw [pto] (01) to node[auto, labelsize] {$\Psi_2$} (02);  
      \draw [pto] (02) to node[auto, labelsize] {$\Psi_n$} (03);  
      \draw [pto] (10) to node[auto, swap, labelsize] {$\Psi$} (11); 
      \draw [->] (00) to node[auto, swap, labelsize] {$v$} (10); 
      \draw [->] (03) to node[auto,labelsize] {$v'$} (11);
      \node at (2.25,0) {$\nu$}; 
\end{tikzpicture}
\end{equation*}
in $\vdcat{Y}$ is mapped by $D_P$ to the function $\nu_\ast\colon P^{-1}(\Psi_1)\times_{P^{-1}(Y_1)}P^{-1}(\Psi_2)\times_{P^{-1}(Y_2)}\dots\times_{P^{-1}(Y_{n-1})}P^{-1}(\Psi_n)\to P^{-1}(\Psi)$.
    \end{itemize}
      It is straightforward to see that $D_P$ is indeed a virtual double functor.
\end{definition}


It is not hard to see that for any discrete opfibration $P\colon \vdcat{X}\to \vdcat{Y}$ with small fibers, we have 
a canonical isomorphism $(P_{D_P}\colon \EElts(D_P)\to \vdcat{Y})\cong (P\colon \vdcat{X}\to\vdcat{Y})$ in $\VDbl/\vdcat{Y}$. 
