      \draw [->] (0) to node[auto, swap, labelsize] {$D_P$} (2); 
\end{tikzpicture}
\end{equation*}
commute. 
\begin{proposition}
    In this situation, for any $(F\colon \vdcat{A}\to \vdcat{X})\in \VDbl/\vdcat{X}$, we have a pullback 
        \[
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
