      \draw [->] (10) to node[auto, swap, labelsize] {$\overline P$} (11); 
      \draw [->] (00) to node[auto, swap, labelsize] {$\prod_PF$} (10); 
      \draw [->] (01) to node[auto,labelsize] {$\FFam(F)$} (11);
      \draw (0.2,0.25) to (0.5,0.25) to (0.5,0.55);
\end{tikzpicture}
\]  
    in $\VDbl$.
\end{proposition}
    See \cite[Lemma~2.1]{Weber-operad-poly} for an analogous result for categories. 
\begin{proof}
    It suffices to show that the diagram 
\begin{equation}
\label{eqn:prod-p-via-fam}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(0) at (0,-0.75) {$\VDbl/\vdcat{X}$};
      \node(1) at (1.5,0.75) {$\VDbl/\FFam(\vdcat{X})$};
      \node(2) at (3,-0.75) {$\VDbl/\vdcat{Y}$};
      \draw [->] (0) to node[auto, labelsize] {$\FFam_\vdcat{X}$}  (1);  
      \draw [<-] (2) to node[auto, swap, labelsize] {$\overline P^\ast$}  (1); 
      \draw [->] (0) to node[auto, swap, labelsize] {$\prod_P$} (2); 
\end{tikzpicture}
\end{equation}
    commutes up to isomorphism. This is equivalent to the statement that the diagram
    \begin{equation}\label{eqn:prod-p-via-fam-left}
\begin{tikzpicture}[baseline=-\the\dimexpr\fontdimen22\textfont2\relax ]
      \node(0) at (0,-0.75) {$\VDbl/\vdcat{X}$};
