      \draw [<-] (0) to node[auto, labelsize] {$\overline \EElts_\vdcat{X}$}  (1);  
      \draw [->] (2) to node[auto, swap, labelsize] {$\sum_{\overline P}$}  (1); 
      \draw [<-] (0) to node[auto, swap, labelsize] {$P^\ast$} (2); 
\end{tikzpicture}
    \end{equation}
    obtained by taking the left 2-adjoints of the arrows in \cref{eqn:prod-p-via-fam}, commutes up to isomorphism.
