\partial_t \tilde{E} - \nabla \times \tilde{B} + \partial_t \lambda (\tilde{E} - E_d) - \nabla \lambda \times (\tilde{B} - B_d) &= 0, \qquad \text{generalized Ampère's Law};\label{eq:Max_tang_2}\\
\partial_t \tilde{B} + \nabla \times \tilde{E} + \partial_t \lambda (\tilde{B} - B_d) + \nabla \lambda \times (\tilde{E} - E_d) &= 0, \qquad \text{generalized Faraday Law};\label{eq:Max_tang_3}\\
\nabla \cdot \tilde{B} = 0, \quad \text{for } \nabla \cdot B_d &= 0,\label{eq:Max_tang_4} \qquad \text{Gauss's Law for Magnetism}.
\end{empheq}
And since both the four-velocity vector $u^\mu$ and the electromagnetic field $F^{\mu\nu}$ are modified, the Lorentz force $f^\mu_L$ changes to: 
\begin{equation}
\tilde{f}^\mu_L=e^{-\lambda(x)}q\tilde{F}^{\mu\nu}u_\nu,
\end{equation} 
showing a modification in the Lorentz force.

This formulation offers a homothetically covariant generalization of electromagnetism. A distinguishing feature of this system is that it is {\bf sourceless}. In fact, the emergence of penalty terms, with geometric origins, enable us to derive the dynamics of electromagnetic fields without the need for source terms. This point will be discussed further in $\S$~\ref{sub-section:6.3}.
