\section{A functional-analytic proof for the homothetic Hodge decomposition~(\ref{Hom_Hodg_Dec})}
\label{app:hodge_proof}

Throughout this appendix $(M,g)$ denotes a \emph{compact} oriented
$n$-manifold without boundary; the case with boundary is analogous
once standard Dirichlet or Neumann data are imposed.  Fix a smooth
homothetic gauge potential $\lambda\in C^\infty(M)$ and abbreviate
\[
   d_\lambda\;:=\;e^{-\lambda}d\,e^{\lambda},
   \qquad
   \delta_\lambda\;:=\;e^{\lambda}\delta\,e^{-\lambda},
   \qquad
   \Delta_\lambda\;:=\;\delta_\lambda d_\lambda + d_\lambda\delta_\lambda.
\]
We adopt Sobolev norms $\|\cdot\|_{H^{s}}$ based on the Levi-Civita
connection; all statements are independent of that choice.

\begin{lemma}[Ellipticity]\label{lem:elliptic}
The operator $\Delta_\lambda:\Omega^{k}(M)\to\Omega^{k}(M)$ is a
second-order \emph{strongly elliptic} differential operator with the
same principal symbol as the ordinary Laplace–de Rham operator
$\Delta_g$.
\end{lemma}

\begin{proof}
Write $d_\lambda = d + (\,d\lambda\wedge\cdot\,)$; the added
zeroth-order term does \emph{not} affect the principal symbol, hence
$\sigma_2(\Delta_\lambda)=\sigma_2(\Delta_g)$.  Strong ellipticity
follows because $\Delta_g$ is strongly elliptic (positive-definite
symbol) and lower-order terms preserve that property
\cite{TaylorPDEI}.
\end{proof}

\begin{lemma}[Gårding–type estimate]\label{lem:garding}
For every $s\in {\Bbb N}$ there exists $C_s>0$ such that
\[
   \|\xi\|_{H^{s+2}}
   \;\le\;
   C_s\bigl(\,\|\Delta_\lambda\xi\|_{H^{s}}+\|\xi\|_{H^{s}}\bigr),
   \quad\forall\,\xi\in C^\infty\Omega^{\bullet}(M).
\]
\end{lemma}

\begin{proof}
Combine ellipticity (Lemma~\ref{lem:elliptic}) with an
Agmon–Douglis–Nirenberg parametrix construction
\cite{HormanderIII}.  The lower-order terms introduced by
$\lambda$ change only the constant in the estimate.
\end{proof}

\begin{corollary}[Fredholmness]\label{cor:fredholm}
$\Delta_\lambda:H^{s+2}\!\to\!H^{s}$ is Fredholm with index
$0$ for every $s\in {\Bbb N}$.
\end{corollary}

\begin{proof}
Lemma~\ref{lem:garding} implies compact embedding of the unit ball of
$H^{s+2}$ in $H^{s+1}$, whence Rellich compactness yields a
parametrix $P:H^{s}\!\to\!H^{s+2}$ modulo compact terms.  Fredholm
index is stable under compact perturbations and $\ker\Delta_\lambda$
is finite-dimensional.
\end{proof}

\begin{proof}[Homothetic Hodge Decomposition (\ref{Hom_Hodg_Dec})]
Equip\footnote{Because $e^{\pm\lambda}$ are bounded on compact $M$,
$\langle\!\cdot,\cdot\!\rangle_\lambda$ is equivalent to the usual
$L^{2}$ inner product.} $\Omega^{\bullet}(M)$ with the inner product
$\langle\!\alpha,\beta\!\rangle_\lambda
=\!\int_M\alpha\wedge*e^{-2\lambda}\!\beta$
and observe
$\delta_\lambda$ is the formal adjoint of $d_\lambda$.  By
Cor.~\ref{cor:fredholm}, $\Delta_\lambda$ extends to a self-adjoint
unbounded operator in $L^{2}$
with compact resolvent; hence its spectrum is discrete and every
$\xi\in L^{2}\Omega^{\bullet}$ decomposes orthogonally as
\[
   \xi \;=\; d_\lambda\alpha \;+\; \delta_\lambda\beta \;+\; \gamma,
   \quad
   \gamma\in\ker\Delta_\lambda,
\]
where $\alpha,\beta$ are unique \emph{up to} the kernel of
$\delta_\lambda$ and $d_\lambda$, respectively.  Regularity theory
implies $\alpha,\beta,\gamma$ are smooth whenever $\xi$ is, completing
the Hodge decomposition.  Harmonic forms
$\gamma$ constitute a finite-dimensional
vector space isomorphic to the de Rham cohomology $H^{\bullet}(M,R)$
because $d_\lambda$ is cohomologous to $d$.  \hfill$\square$
\end{proof}

\begin{remark}
If $\partial M\neq\varnothing$, impose absolute
($\imath_\nu\xi=0,\;\imath_\nu d_\lambda\xi=0$) or relative
($\xi|_{\partial M}=0,\;d_\lambda\xi|_{\partial M}=0$) boundary
conditions; Lemma~\ref{lem:garding} adapts following
\cite{SchwarzHodge} and the decomposition remains valid.
\end{remark}

