\section{Conclusion} \label{sec:6}
This paper develops a novel two-stage algorithm for solving sparse quadratic systems  $y_i=\x^{\TT}\A_i\x$ under the Gaussian measurements. Theoretically, we prove that the proposed algorithm achieves a quadratic convergence rate after a finite number of iterations, with a sampling complexity of $m=O(s^2\log{n})$. In the presence of noise, our algorithm remains robust and attains the optimal error bound. Numerical experiments indicate that the proposed algorithm outperforms state-of-the-art methods in terms of convergence speed and sampling efficiency. While the initialization stage currently limits sample efficiency, our findings highlight the potential for further improvements through more advanced initialization schemes, offering a promising direction for future research in high-dimensional quadratic inverse problems.

\section{Appendix: Proofs of main results} \label{sec:diszkl} \label{sec:7}
\subsection{ Proof of Theorem \ref{Theorem4}}
\label{sec: realmeas}
\begin{proof}
	Note that the set of all $\{\A_i\}_{i=1}^m \in \mathbb R^{m\times n^2}$ has real dimension $mn^2$. From the definition of generic, to prove the result, we only need to show that the set of $\{\A_i\}_{i=1}^m$ such that $\mathbf{M}_{\mathcal A}$ is not injective on $\Sigma_s ({\mathbb R}^n)$ lies in a finite union of subsets with dimension strictly less than $mn^2$.  


	Note that $\mathbf{M}_{\mathcal A}(\x)=\mathbf{M}_{\mathcal A}(\z)$ if and only if $\mathbf{M}_{\mathcal A}(a\x)=\mathbf{M}_{\mathcal A}(a\z)$  for any $a \in \R$. Therefore, for any subset of indices $I, J\subset [n]$ with $|I|\le s$, $|J|\le s$, we define  $\mathcal G_{I,J}$ be the set of all $(\A_1,\ldots,\A_m, \x,\z) \in \mathbb P(\R^{n \times n} \times \cdots \times \R^{n \times n}) \times \mathbb P(\R^n \times \R^n)$ such that $\x\neq \pm \z$ and
	\[
	\mbox{supp}(\x) \subset I, \quad \mbox{supp}(\z) \subset J,  \quad \mathbf{M}_{\mathcal A}(\x)=\mathbf{M}_{\mathcal A}(\z).
	\]
	Then $\mathcal G_{I,J}$ is a well-defined real projective variety because the defining equations are homogeneous polynomials.
	We next consider the dimension of this projective variety $\mathcal G_{I,J}$. To this end, let $\pi_1$ be projections on the first $m$ coordinates of $\mathcal G_{I,J}$ and $\pi_2$ be projections on the last two coordinates of $\mathcal G_{I,J}$, namely, 
	\[
	\pi_1(\A_1,\ldots,\A_m, \x,\z)=(\A_1,\ldots,\A_m) \qquad \mbox{and} \qquad \pi_2(\A_1,\ldots,\A_m, \x,\z)=(\x,\z).
	\]
	For any $\x_0 \neq \pm \z_0$ and any fixed $j$, the equation $\x_0^{\TT}\A_j\x_0 =\z_0^{\TT}\A_j\z_0$ defines a nonzero homogeneous polynomial, which constraints the set of $\A_j$ to lie on a real projective variety of codimension $1$. Note that there are $m$  such constrains.
	Hence, for any $\x_0 \neq \z_0$ in $\R^n$ with $\mbox{supp}(\x_0) \subset I$, $ \mbox{supp}(\z_0) \subset J$, the preimage $\pi_2^{-1}(\x_0,\z_0)$ has dimension $mn^2-m-1$. It follows from \cite[Cor. 11.13]{Fiber} that 
	\[
	\mbox{dim}(\mathcal G_{I,J})\le \mbox{dim}(\pi_2^{-1}(\x_0,\z_0))+|I|+|J|-1\le mn^2-m-1+2s-1.
	\]
	If $m\ge 2s$, then
	\[
	\mbox{dim}(\pi_1(\mathcal G_{I,J})) \le \mbox{dim}(\mathcal G_{I,J}) \le mn^2-2<mn^2-1=\mbox{dim}(\mathbb P(\R^{n \times n} \times \cdots \times \R^{n \times n})).
	\]
	Note that $\pi_1(\mathcal G_{I,J})$ contains precisely those $(\A_1,\ldots,\A_m) \in \R^{n \times n} \times \cdots \times \R^{n \times n}$ such that $\mathbf{M}_{\mathcal A}$ is not injective for signals $\x,\z$ with $\mbox{supp}(\x) \subset I$, $\mbox{supp}(\z) \subset J$. Thus, a generic $(\A_1,\ldots,\A_m) \in \R^{n \times n} \times \cdots \times \R^{n \times n}$ guarantees the injective for all $\x,\z$ with $\mbox{supp}(\x) \subset I$, $\mbox{supp}(\z) \subset J$. 

	Finally, there are only finitely many indices subsets $I,J$. The theorem is then proved.
\end{proof}

\subsection{ Proof of Theorem \ref{Theorem5}}
\label{sec: complexmeas}
\begin{proof}
	The proof is similar to that in the real case. The set of all $\{\A_i\}_{i=1}^m \in \mathcal H^{n\times n} \times \cdots \times \mathcal H^{n\times n}$ has real dimension $\mbox{dim}_{\R}(\mathcal H^{n\times n} \times \cdots \times \mathcal H^{n\times n})=mn^2$. Next, we  show that the set of $\{\A_i\}_{i=1}^m$ such that $\mathbf{M}_{\mathcal A}$ is not injective on $\Sigma_s ({\mathbb C}^n)$ lies in a finite union of subsets with dimension strictly less than $mn^2$.  


	Note that $\mathbf{M}_{\mathcal A}(\x)=\mathbf{M}_{\mathcal A}(\z)$ if and only if $\mathbf{M}_{\mathcal A}(a\x)=\mathbf{M}_{\mathcal A}(a\omega \z)$  for any $a \in \R$ and $\omega\in \mathbb C$ with $|\omega|=1$. Therefore, for any $\x,\z \in \mathbb C^n$, if $\mathbf{M}_{\mathcal A}(\x)=\mathbf{M}_{\mathcal A}(\z)$, then we can find $\x_0, \z_0 \in \mathbb C^n$ such that the following holds:
	\begin{itemize}
		\item[(i)] $\mathbf{M}_{\mathcal A}(\x_0)=\mathbf{M}_{\mathcal A}(\z_0)$;
		\item[(ii)] The first nonzero entry of $\x_0$ is $1$;
		\item[(iii)] The first nonzero entry of $\z_0$ is real. 
	\end{itemize}
	For convenience, we denote $X$ the  subset of $\mathbb C^n$ consisting of elements $\x \in \mathbb C^n$ whose first nonzero entry is $1$, and  denote $Z$ the subset of $\mathbb C^n$ consisting of elements $\z\in \mathbb C^n$ whose first nonzero entry is real.  Moreover, let $\mathbb C_{I}^n$ denote the set of vectors $\x \in \mathbb C^n$ such that $\mbox{supp}(\x) \subset I$.
	Now,  for any subset of indices $I, J\subset [n]$ with $|I|\le s$, $ |J|\le s$, we define  $\mathcal G_{I,J}$ be the set of all $(\A_1,\ldots,\A_m, \x,\z) \in \mathcal H^{n\times n} \times \cdots \times \mathcal H^{n\times n} \times \mathbb{C}^n \times \mathbb{C}^n$ such that $\x \neq  \omega \z$ for any $\omega\in \mathbb C$ with $|\omega|=1$ and
	\[
	\x \in X \cap \mathbb C_{I}^n, \quad \z \in Z \cap \mathbb C_{J}^n, \quad  \mathbf{M}_{\mathcal A}(\x)=\mathbf{M}_{\mathcal A}(\z).
	\]
	Let $\pi_1$ be projections on the first $m$ coordinates of $\mathcal G_{I,J}$ and $\pi_2$ be projections on the last two coordinates of $\mathcal G_{I,J}$, namely, 
	\[
	\pi_1(\A_1,\ldots,\A_m, \x,\z)=(\A_1,\ldots,\A_m) \qquad \mbox{and} \qquad \pi_2(\A_1,\ldots,\A_m, \x,\z)=(\x,\z).
	\]
	For any fixed $\x_0, \z_0 \in \mathbb C^n$ and each fixed $j$, if $\x_0 \neq  \omega \z_0$ for any $\omega\in \mathbb C$ with $|\omega|=1$, then the equation $\x_0^{\TT}\A_j\x_0 =\z_0^{\TT}\A_j\z_0$ defines a nonzero homogeneous polynomial, which constraints the set of $\A_j$ to lie on a real algebraic variety of codimension $1$. Hence, for any $\x_0 \neq  \omega \z_0$ in $\mathbb C^n$ with $ \x \in X \cap \mathbb C_{I}^n, \; \z \in Z \cap \mathbb C_{J}^n$, the preimage $\pi_2^{-1}(\x_0,\z_0)$ has real dimension 
	\[
	\mbox{dim}_{\R}(\pi_2^{-1}(\x_0,\z_0))=mn^2-m.
	\]
	It follows that 
	\begin{eqnarray*}
		\mbox{dim}_{\R}(\mathcal G_{I,J}) & \le &  \mbox{dim}_{\R}(\pi_2^{-1}(\x_0,\z_0))+\mbox{dim}_{\R}(X\cap \mathbb C_{I}^n)+\mbox{dim}_{\R}(Y \cup \mathbb C_{I}^n) \\
		&= &  mn^2-m+2s-2+2s-1.
	\end{eqnarray*}
	Therefore, if $m\ge 4s-2$, then
	\[
	\mbox{dim}_{\R}(\pi_1(\mathcal G_{I,J})) \le \mbox{dim}_{\R}(\mathcal G_{I,J}) \le mn^2-1<mn^2=\mbox{dim}_{\R}(\mathcal H^{n\times n} \times \cdots \times \mathcal H^{n\times n}).
	\]
	Since $\pi_1(\mathcal G_{I,J})$ contains precisely those $(\A_1,\ldots,\A_m) \in \mathcal H^{n\times n} \times \cdots \times \mathcal H^{n\times n}$ such that $\mathbf{M}_{\mathcal A}$ is not injective for signals $\x,\z$ with $\mbox{supp}(\x) \subset I$, $\mbox{supp}(\z) \subset J$.  Thus, a generic $(\A_1,\ldots,\A_m) \in \mathcal H^{n\times n} \times \cdots \times \mathcal H^{n\times n}$ guarantees the injective of $\mathbf{M}_{\mathcal A}$ for all $\x,\z$ with $\mbox{supp}(\x) \subset I$, $\mbox{supp}(\z) \subset J$. 

	Finally, there are only finitely many indices subsets $I,J$ with $|I|\le s, |J|\le s$. The theorem is  proved.
\end{proof}

\subsection{ Proof of Theorem \ref{Theorem1}} \label{sec:appA}
Before proving Theorem \ref{Theorem1}, we first introduce some auxiliary lemmas and notations.

\begin{definition}
	\cite[$\epsilon$-net]{vershynin2018high}
	Let $(X,d)$ be a metric space. $S$ is a subset of $X$ and let $\epsilon >0$. If $\mcalN \subseteq S$ satisfies
	\begin{equation*}
		\forall x \in S, \quad \exists \  x_0 \in \mcalN, \quad s.t. \quad d(x,x_0) \le \epsilon,
	\end{equation*}
	then we call $\mcalN$ an $\epsilon$-net of $S$. Here, $d(x,x_0)$ denotes the distance between $x$ and $x_0$.
\end{definition}

\begin{lemma}
	\cite[Product of sub-gaussians is sub-exponential]{vershynin2018high} Let $X$ and $Y$ be sub-gaussian random variables. Then $XY$ is sub-exponential. Moreover, 
	\begin{equation*}
		\norm{XY}_{\psi_1} \le \norm{X}_{\psi_2}\norm{Y}_{\psi_2}.
	\end{equation*}
\end{lemma}

\begin{lemma} \cite[Hoeffding’s inequality]{vershynin2018high} \label{le:Hoeff}
	Let $X_1,...,X_N$ be independent, mean zero, sub-gaussian random variables, and $a=(a_1,\ldots,a_N) \in \mbbR^N$ Then, for every $t \ge 0$, we have
	\begin{equation*}
		\mbbP\left(\abs{\sum\limits_{i=1}^{N}a_iX_i} \ge t\right) \le 2\exp\left(-\frac{Ct^2}{K^2\norm{a}^2}\right)
	\end{equation*}
	where $K=\max\limits_i \norm{X_i}_{\psi_2}$ and $C>0$ is a universal constant.
\end{lemma}


\begin{lemma} \cite[Bernstein’s inequality]{vershynin2018high} \label{le:bern}
	Let $X_1,...,X_N$ be independent, mean zero, sub-exponential random variables. Then, for every $t \ge 0$, we have
	\begin{equation*}
		\mbbP\left(\abs{\frac{1}{N}\sum\limits_{i=1}^{N}X_i} \ge t\right) \le 2\exp\left(-C \min\left(\frac{t^2}{K^2},\frac{t}{K}\right)N\right)
	\end{equation*}
	where $K=\max\limits_i \norm{X_i}_{\psi_1}$ and $C>0$ is a universal constant.
\end{lemma}

\begin{lemma}\cite[Weyl's inequality, singular values]{Weyl}
	\label{le: Weyl}
	Let $\M, \N \in \mathbb R^{m \times n}$ be two matrices with $m \le n$, The singular values of $\M$ and $\N$ are denoted as $\sigma_1(\M)\ge \ldots \ge \sigma_m(\M)$ and $\sigma_1(\N)\ge \ldots \ge \sigma_m(\N)$, respectively. Then we have
	\begin{eqnarray*}
		|\sigma_i(\M+\N)-\sigma_i(\M)| \le \sigma_1(\N) \quad \mbox{for} \quad 1 \le i \le m.
	\end{eqnarray*}
	Consequently, 
	\begin{eqnarray*}
		\sigma_i(\M)-\sigma_{i+1}(\M+\N) \ge \sigma_i(\M)-\sigma_{i+1}(\M)- \sigma_1(\N) \quad \mbox{for} \quad 1 \le i \le m.
	\end{eqnarray*}


