	\end{lemma}



	\begin{lemma}	\cite[Lemma 4]{chen2025solving} \label{le:normphi}
		Let $\{\A_i\}_{i=1}^m$ be i.i.d. standard Gaussian random matrices with $\A_i \sim \mcalN^{n\times n}(0,1)$. 
		For any $\delta>0$, with probability at least $1-2\exp(-c\delta^2 m)$, it holds
		\[
		\abs{\frac1m \sum_{i=1}^m (\x^\TT \A_i \x)^2-\norm{\x}^4} \le \delta\norm{\x}^4.
		\]	
	\end{lemma}

	Recall that $\phi = (\frac{1}{m}\sum\limits_{i=1}^{m}y_i^2)^{1/4} = (\frac1m \sum\limits_{i=1}^m (\x^\TT \A_i \x)^2)^{1/4}$ and $\norm{\x^0}=\phi$, thus Lemma \ref{le:normphi} states that $(1-\delta)^{\frac{1}{4}}\norm{\x} \le \norm{\x^0} \le (1+\delta)^{\frac{1}{4}}\norm{\x}$ with probability ate least $1-2\exp(-c\delta^2m)$.


	\begin{lemma} \label{le:epAi}
		Suppose that $\{\epsilon_i\}_{i=1}^m$ are independent sub-exponential random variables with $\max\limits_i\norm{\epsilon_i}_{\psi_1}=\sigma$.  Assume that $\A_i \sim \mcalN^{n\times n}(0,1)$. Then with probability at least $1-2\exp(-c' s)$, it holds
		\[
		\norm{\frac{1}{m}\sum\limits_{i=1}^{m} \epsilon_i  [\A_i]_{\mcalS,\mcalS} } \le C_0 \sigma \sqrt{ \frac{s \log(en/s)}m}
		\]
		for all $\mcalS\subset [n]$ with $|\mcalS| \le 3s$. Here, $c'$ and $C_0$ are universal positive constants.
	\end{lemma}
	\begin{proof}
		For any fixed $\mcalS\subset [n]$ with $|\mcalS| \le 3s$,  define 
		\begin{equation*}
			\mcalX_{\mcalS} = \{\u \in \mbbS^{n-1}:{\rm supp}(\u) \subset \mcalS \},
		\end{equation*}
		where $\mathbb S^{n-1}:=\{\z \in \mathbb R^n : \norm{\z}=1\}$.
		Let $\mathcal{N}_{1/4}$ be a $1/4$-net of $\mcalX_{\mcalS} $ with cardinality $\abs{\mathcal{N}_{1/4}} \le 9^{3s}$. Then 
		\[
		\norm{\frac{1}{m}\sum\limits_{i=1}^{m} \epsilon_i  [\A_i]_{\mcalS,\mcalS} } \le 2\sup\limits_{\u,\v \in \mathcal{N}_{1/4}} \frac{1}{m}\sum\limits_{i=1}^{m} \epsilon_i  \u^\TT \A_i \v.
		\]
		Since $\u^\TT \A_i \v, i=1,\ldots, m$, are independent standard Gaussian random variables, Lemma \ref{le:Hoeff} gives
		\[
		\abs{\sum\limits_{i=1}^{m} \epsilon_i  \u^\TT \A_i \v} \le C_1 \norm{\bm \epsilon}\sqrt{s \log(en/s)} \le C_2 \sigma \sqrt{m s \log(en/s)}
		\]
		holds with probability at least $1-2\exp(-c_0 s \log (en/s))$. Here, we use \cite[Lemma A.7]{cai2016optimal}  in the last inequality, and $C_1, C_2>0, c_0>100$ are universal constants.  Combining the above estimators together and taking the union bound, we obtain that with probability at least $1-2\exp(-c'_0 s \log (mn))$, it holds
		\[
		\norm{\frac{1}{m}\sum\limits_{i=1}^{m} \epsilon_i  [\A_i]_{\mcalS,\mcalS} } \le 2 C_2 \sigma \sqrt{ \frac{s \log(en/s)}m}
		\]
		for any fixed $\mcalS\subset [n]$ with $|\mcalS| \le 3s$. Finally, taking the union bound over all  $\mcalS\subset [n]$ with $|\mcalS| \le 3s$ and noting that $\sum\limits_{k=1}^{3s} \left(\begin{array}{c} n\\k\end{array} \right) \le \left(en/s\right)^{3s}$, we arrive at the conclusion.

	\end{proof}


	\begin{lemma} \label{lemma2}
		Assume that $m\ge c \log{n}$ for some  constant $c>0$. 
		$
		y_i = \x^{\TT}\A_i\x + \epsilon_i, i = 1, \dots,m,
		$
		where the noise $\{\epsilon_i\}_{i=1}^m$ are independent sub-exponential random variables with \\ $\max\limits_i \norm{\epsilon_i}_{\psi_1}=\sigma$. Then with probability at least $1-4n^{-5}$,  it holds
		\begin{equation}
			\abs{Y_{jj}-x_j^2} \le C\left(1 +\frac{\sigma}{\norm{\x}^2}\right) \norm{\x}^2 \sqrt{\frac{\log{(mn)}}{m}} \quad \mbox{for} \quad j=1,\ldots,n.
			\label{eq:bound1}
		\end{equation}
		Here, $C>0$ is an absolute constant and $Y_{jj}$ is defined in Algorithm \ref{algorithm1:Initialization}.
		In particular, for all $j \in \mcalS^c$, here $\mcalS=\mbox{supp}(\x)$, with probability exceeding $1-4n^{-5}$, one has
		\begin{equation}
			Y_{jj}  \le C  \left(1 +\frac{\sigma}{\norm{\x}^2}\right) \norm{\x}^2 \sqrt{\frac{\log{(mn)}}{m}}. 
			\label{eq:bound2}
		\end{equation}
	\end{lemma}
	\begin{proof}  
		Denote the noise vector as ${\bm \epsilon} = (\epsilon_1,...,\epsilon_m)^{\TT}$.
		Note that 
		\[
		Y_{jj} = \frac{1}{m}\sum\limits_{i=1}^{m}y_ia_{jj}^i = \frac{1}{m}\sum\limits_{i=1}^{m}  (\x^{\TT}\A_i\x) a_{jj}^i+ \frac{1}{m}\sum\limits_{i=1}^{m}\epsilon_ia_{jj}^i.
		\]
		For the first term, 
		a simple calculation gives that the expectation   $\mbbE[Y_{jj}]=x_j^2$. Since $(\x^{\TT}\A_i\x)a_{jj}^i, i=1,\ldots,m$ are independent sub-exponential random variables with \begin{equation*}
			\norm{(\x^{\TT}\A_i\x) a^i_{jj}}_{\psi_1} \le \norm{(\x^{\TT}\A_i\x)}_{\psi_2}\norm{a^i_{jj}}_{\psi_2} \le c_1\norm{\x}^2
		\end{equation*}
		for some constant $c_1\ge 1$, it then follows from Lemma \ref{le:bern} that for any $t_1 \ge 0$,
		\begin{equation*}
			\mbbP\left(\abs{\frac{1}{m}\sum\limits_{i=1}^{m}(\x^{\TT}\A_i\x)a_{jj}^i-x_j^2} > t_1\right) \le 2\exp\left(-C_1\min\left(\frac{t_1^2}{c_1^2 \norm{\x}^4},\frac{t_1}{c_1 \norm{\x}^2}\right)m\right),
		\end{equation*}
		where $C_1>0$ is a universal constant. Setting $\textstyle t_1=c_1\norm{\x}^2\sqrt{\displaystyle\frac{6\log{(mn)}}{C_1m}} $, we have 
		\[
		\mbbP\left(\abs{\frac{1}{m}\sum\limits_{i=1}^{m}(\x^{\TT}\A_i\x)a_{jj}^i-x_j^2} >c_1\norm{\x}^2\sqrt{\displaystyle\frac{6\log{(mn)}}{C_1m}}   \right) \le 2 (mn)^{-6},
		\]	
		provided $m\ge 6C_1^{-1}  \log (mn)$.	 Taking the union bound over $j\in [n]$, we obtain that 
		\[
		\sup_{j\in [n]} \quad \abs{\frac{1}{m}\sum\limits_{i=1}^{m}(\x^{\TT}\A_i\x)a_{jj}^i-x_j^2}  \le C_2 \norm{\x}^2\sqrt{\displaystyle\frac{\log{(mn)}}{m}} 
		\]
		holds with probability at least $1-2(mn)^{-5}$.
		For the second term $\frac{1}{m}\sum\limits_{i=1}^{m}\epsilon_ia_{jj}^i$, conditionally on the $\epsilon_i$'s, Lemma \ref{le:Hoeff} gives that 
		\[
		\mbbP\left(\abs{\sum\limits_{i=1}^{m}\epsilon_ia_{jj}^i } > C_3\norm{\bm\epsilon}\sqrt{\log(mn)}\right) \le 2(mn)^{-6}.
		\]
		Taking the union bound over $j\in [n]$, we obtain that
		\[
		\max_{1\le j\le n} \abs{\sum\limits_{i=1}^{m}\epsilon_ia_{jj}^i } \le  C_3 \norm{\bm \epsilon}\sqrt{\log (mn)} \le C_4 \sigma \sqrt{m\log (mn)}
		\]
		holds with probability at least $1-2n^{-5}$,  where we use \cite[Lemma A.7]{cai2016optimal}  in the last inequality, and $C_3, C_4>0$ are universal constants.
		Combining  the two bounds, we obtain that with probability at least $1-4n^{-5}$, it holds
		\begin{equation*}
			\abs{{Y}_{jj}-x_j^2} \le C \left(1 +\frac{\sigma}{\norm{\x}^2}\right) \norm{\x}^2 \sqrt{\frac{\log{(mn)}}{m}} 
		\end{equation*}
		for all $j=1,\ldots,n$. Here, $C>0$ is a universal constant.
		For all $j \in \mcalS^c$, noting that $\mbbE[Y_{jj}]=0$, it gives
		\begin{equation*}
			Y_{jj}  \le C  \left(1 +\frac{\sigma}{\norm{\x}^2}\right) \norm{\x}^2 \sqrt{\frac{\log{(mn)}}{m}}  \quad \mbox{for all} \quad j\in  \mcalS^c.
		\end{equation*} 
		This complete the proof.
	\end{proof} 


	Now, we are ready to prove Theorem \ref{Theorem1}.  
	First, we establish that the true signal $\x$ is well-approximated by its projection $\x_{\widehat{\mathcal{S}}}$ onto the estimated support set $\widehat{\mathcal{S}}$. Second, we demonstrate that this projection $\x_{\widehat{\mathcal{S}}}$ closely approximates our initial estimate $\x^0$. The triangle inequality then yields the desired result.


	\begin{lemma} \label{le:normshat}
		Let $\widehat{\mcalS}$ be the set given in Algorithm \ref{algorithm1:Initialization}. For any $\delta_1 > 0$,
		with probability at least $1-4n^{-5}$,  it holds
		\begin{equation*}
			\norm{\x-\x_{\hat{\mcalS}}} \le \delta_1\norm{\x}
		\end{equation*}
		when $m \ge C(\delta_1)\left(1 +\frac{\sigma}{\norm{\x}^2}\right)^2 s^2 \log (mn)$.
		Here, $C(\delta_1) >0$ is a constant depends only on  $\delta_1$.
		\label{lemma4}
	\end{lemma}
	\begin{proof} 
		Define 
		\begin{equation*}
			\mcalS_+=\left\{j \in \mcalS \mid x_j^2> 2C \left(1 +\frac{\sigma}{\norm{\x}^2}\right) \norm{\x}^2 \sqrt{\frac{\log{(mn)}}{m}} \right\},
		\end{equation*}
		where the constant $C>0$ corresponds exactly to the one in \eqref{eq:bound1}. We first show that with high probability it holds $\mcalS_+ \subset \widehat{\mcalS}$. To this end, for any $ j \in \mcalS_+$, it follows from Lemma \ref{lemma2} that with probability at least $1-4n^{-5}$, one has
		\begin{equation*}
			Y_{jj} \ge x_j^2-\abs{Y_{jj}-x_j^2} \ge C\left(1 +\frac{\sigma}{\norm{\x}^2}\right) \norm{\x}^2 \sqrt{\frac{\log{(mn)}}{m}}.
		\end{equation*}
		And for any $j \in \mcalS^c$, it holds
		\[
		Y_{jj} \le C\left(1 +\frac{\sigma}{\norm{\x}^2}\right) \norm{\x}^2 \sqrt{\frac{\log{(mn)}}{m}}. 
		\]
		Since $\widehat{\mcalS}$ contains the indices of the maximum $s$ elements of $Y_{jj}$, it gives $\mcalS_+ \subset \widehat{\mcalS} \subset \mcalS$. Therefore, we have
		\begin{eqnarray*}
			\norm{\x-\x_{_{\widehat{\mcalS}}}}^2  \le  \norm{\x- \x_{\mcalS_+ }}^2 \le  s\cdot 2C\left(1 +\frac{\sigma}{\norm{\x}^2}\right)\norm{\x}^2\sqrt{\frac{\log{(mn)}}{m}}  \le  \delta_1^2\norm{\x}^2,
		\end{eqnarray*}	
		provided that $m\ge 4C^2 \delta_1^{-4}\left(1 +\frac{\sigma}{\norm{\x}^2}\right)^2 s^2 \log (mn)$. This completes the proof.
	\end{proof}



	\begin{lemma} \label{le:5}
		\label{lemma5}
		For any fixed $0<\delta<1$,  then with probability at least $1-4n^{-5}-4\exp(-c\delta^2 m)-2\exp(-c's)$, we have
		\begin{equation*}
			{\rm dist}\left(\x^0,\x_{_{\widehat{\mcalS}}}\right) := \min\left(\norm{\x^0-\x_{_{\widehat{\mcalS}}}},\norm{\x^0+\x_{_{\widehat{\mcalS}}}}\right)  \le \delta \norm{\x},
		\end{equation*} 
		provided that $m \ge C(\delta)(1+\frac{\sigma}{\norm{x}^2})^2s^2\log(mn)$. Here, $c, c'$ are universal positive constant and $C(\delta)$ is a constant depends on $\delta$.
	\end{lemma}
	\begin{proof} 
		A simple calculation gives
		\begin{equation*}
			\mbbE\left[\Y\right]=\mbbE\left[\frac{1}{m}\sum\limits_{i=1}^{m}y_i\A_i\right]=\x\x^{\TT}.
		\end{equation*}
		This implies that $\mbbE\left[\Y_{\widehat{\mcalS}}\right] =\x_{_{\widehat{\mcalS}}}\x_{_{\widehat{\mcalS}}}^{\TT}$.
		We claim that for any $0<\delta_2<1$, when $m\ge C_0\delta_2^{-2} s \log(en/s)$ with large positive constant $C_0$, with probability at least $1-2\exp(-c_3 \delta_2^2 m)-2\exp(-c's)$,
		\begin{equation} \label{eq:cla1}
			\norm{\Y_{\mcalS'}-\mbbE\left[\Y_{\mcalS'}\right]} \le \delta_2 \norm{\x}^2
		\end{equation}
		holds for all $\mcalS' \subset [n]$ with $|\mcalS'| \le s$.  Note that $|\widehat{\mcalS}|=s$. It implies that 
		\begin{equation} \label{eq:conYsp}
			\norm{\Y_{\widehat{\mcalS}}-\mbbE\left[\Y_{\widehat{\mcalS}}\right]} \le \delta_2 \norm{\x}^2. 
		\end{equation}
		Since $\x^0$ is the leading left singular vector of $\Y_{\widehat{\mcalS}}$, a variant of Wedin's sin$\Theta$ theorem \cite[Theorem 2.1]{Dopico} gives
		\begin{equation} \label{eq:xno1}
			\min_{\alpha=\pm 1}  \norm{\frac{\x^0}{\norm{\x^0}}- \alpha \frac{\x_{\widehat{\mcalS}}}{\norm{\x_{\widehat{\mcalS}}}}}   \le \frac{c_1 \norm{\Y_{\widehat{\mcalS}}-\mbbE\left[\Y_{\widehat{\mcalS}}\right]} }{\sigma_1(\mbbE\left[\Y_{\widehat{\mcalS}}\right])-\sigma_2(\Y_{\widehat{\mcalS}})} \le \frac{c_1 \delta_2 \norm{\x}^2}{\norm{\x}^2- \delta_2 \norm{\x}^2}=\frac{c_1 \delta_2}{1-\delta_2}.
		\end{equation}
		where we use Lemma \ref{le: Weyl} in the second inequality.
		When the variance of the noise is much smaller compared to the magnitude of the measurement, Lemma \ref{le:normphi} still remains valid.
		According to Lemma \ref{le:normphi} and Lemma \ref{le:normshat}, for any $0<\delta_1<1$,  with probability at least $1-4n^{-5}-2\exp(-c\delta_1^2 m)$ we have
		\begin{equation} \label{eq:xno2}
			(1-\delta_1) \norm{\x} \le \max\{\norm{\x^0},\norm{\x_{\widehat{\mcalS}}} \} \le (1+\delta_1)\norm{\x},
		\end{equation}
		provided that $m \ge C(\delta_1)(1+\frac{\sigma}{\norm{x}^2})^2s^2\log{(mn)}$.
		Combining \eqref{eq:xno1} and \eqref{eq:xno2}, we can easily obtain that 
		\begin{eqnarray*}
			\min_{\alpha=\pm 1}  \norm{\x^0- \alpha \x_{_{\widehat{\mcalS}}}} &\le& \min_{\alpha=\pm 1}  \norm{\frac{\x^0}{\norm{\x^0}}- \alpha \frac{\x_{\widehat{\mcalS}}}{\norm{\x_{\widehat{\mcalS}}}}} \norm{\x} +  \abs{\norm{\x^0}-\norm{\x}} + \abs{\norm{\x_{\widehat{\mcalS}}}-\norm{\x}} \\
			& \le &\frac{c_1 \delta_2}{1-\delta_2}\norm{\x}+2\delta_1\norm{\x} \le \delta \norm{\x}
		\end{eqnarray*}
		by letting $\delta_1$ and $\delta_2$ be small enough. This gives the conclusion.

		It remains to prove the claim \eqref{eq:cla1}. By the triangle inequality, we obtain
		\begin{equation*}
			\begin{aligned}
				&\norm{\frac{1}{m}\sum\limits_{i=1}^{m}y_i[\A_i]_{\mcalS',\mcalS'}-\x_{_{\mcalS'}}\x_{_{\mcalS'}}^{\TT}}\\ &\le \norm{\frac{1}{m}\sum\limits_{i=1}^{m}\x^{\TT}\A_i\x[\A_i]_{\mcalS',\mcalS'}-\x_{_{\mcalS'}}\x_{_{\mcalS'}}^{\TT}}+\norm{\frac{1}{m}\sum\limits_{i=1}^{m}\epsilon_i[\A_i]_{\mcalS',\mcalS'}}.
			\end{aligned}
		\end{equation*}
		For any fixed $\mcalS' \subset [n]$ with $|\mcalS'| \le s$. Let $\mathcal{N}_\epsilon$ be a $\frac{1}{4}$-net of the unit sphere $\mathbb S^{s-1}$. For the first term, we have
		\begin{equation*}
			\begin{aligned}
				&\norm{\frac{1}{m}\sum\limits_{i=1}^{m}\x^{\TT}\A_i\x[\A_i]_{\mcalS',\mcalS'}-\x_{_{\mcalS'}}\x_{_{\mcalS'}}^{\TT}} \\
				&\le 2\sup\limits_{\u,\v \in \mcalN_{\1/4}}\left|\frac{1}{m}\sum\limits_{i=1}^{m}\x^{\TT}\A_i\x\u^{\TT}[\A_i]_{\mcalS',\mcalS'}\v-(\u^{\TT}\x_{_{\mcalS'}})(\v^{\TT}\x_{_{\mcalS'}})\right|. 
			\end{aligned}
		\end{equation*}
		Since $\textstyle \x^{\TT}\A_i\x\u^{\TT}[\A_i]_{\mcalS',\mcalS'}\v, \ i=1,...,m$, are independent sub-exponential variables, Lemma \ref{le:bern} gives
		\begin{eqnarray*}
			\mbbP&\left(\left|\frac{1}{m}\sum\limits_{i=1}^{m}\x^{\TT}\A_i\x\u^{\TT}[\A_i]_{\mcalS',\mcalS'}\v-(\u^{\TT}\x_{_{\mcalS'}})(\v^{\TT}\x_{_{\mcalS'}})\right|\ge t_2\right)\\
			& \le 2\exp\left(-C_1 \min\left(\frac{t_2^2}{K_2^2},\frac{t_2}{K_2}\right)m\right),
		\end{eqnarray*}
		where $\textstyle K_2=\max\limits_{i}\norm{\x^{\TT}\A_i\x\u^{\TT}[\A_i]_{\mcalS',\mcalS'}\v-(\u^{\TT}\x_{_{\mcalS'}})(\v^{\TT}\x_{_{\mcalS'}})}_{\psi_1} $ obeys
		\begin{eqnarray*}
			K_2 &\le& c_1\max\limits_{i}\norm{\x^{\TT}\A_i\x\u^{\TT}[\A_i]_{\mcalS',\mcalS'}\v}_{\psi_{1}}\\
			&\le& c_2\norm{\x^{\TT}\A_i\x}_{\psi_{2}}\norm{\u^{\TT}[\A_i]_{\mcalS',\mcalS'}\v}_{\psi_{2}}\le c_2\norm{\x}^2.
		\end{eqnarray*}
		Setting $\textstyle t_2=\frac{\delta_3}{2} \norm{\x}^2$, taking the union bound over $\mathcal{N}_\epsilon$, we obtain that with probability at least $1-2\exp(-c_0 \delta_3^2 m)$ with a universal constant $c_0$, it holds
		\[
		\norm{\frac{1}{m}\sum\limits_{i=1}^{m}\x^{\TT}\A_i\x[\A_i]_{\mcalS',\mcalS'}-\x_{_{\mcalS'}}\x_{_{\mcalS'}}^{\TT}} \le \delta_3 \norm{\x}^2,
		\]
		provided $m\ge C_0\delta_3^{-2} s$ for some large constant $C_0>0$. Note that $\sum\limits_{k=1}^{s} \left(\begin{array}{c} n\\k\end{array} \right) \le \left(en/s\right)^{s}$. Taking the union bound over all $\mcalS'$, we obtain the conclusion that 
		\[
		\norm{\frac{1}{m}\sum\limits_{i=1}^{m}\x^{\TT}\A_i\x[\A_i]_{\mcalS',\mcalS'}-\x_{_{\mcalS'}}\x_{_{\mcalS'}}^{\TT}} \le \delta_3 \norm{\x}^2 \qquad \mbox{for all} \quad |\mcalS' |\le s
		\]
		holds with probability at least 
		\[
		1- \left(en/s\right)^{s}\cdot 2\exp(-c_0 \delta_3^2 m) \ge 1-2\exp(-c_3 \delta^2 m),
		\]
		provided $m\ge C_0\delta^{-2} s \log(en/s)$ with any fixed $0<\delta<1$. Combining with Lemma \ref{le:epAi}, we have 
		\begin{equation*}
			\norm{\frac{1}{m}\sum\limits_{i=1}^{m} \epsilon_i  [\A_i]_{\mcalS,\mcalS} } \le C_0 \sigma \sqrt{ \frac{s \log(en/s)}m} \le \delta_3\norm{\x}^2. 
		\end{equation*}
		We complete the proof.
	\end{proof}


	Now, we are ready to prove Theorem \ref{Theorem1}.

	\begin{proof}[Proof of Theorem \ref{Theorem1}]

		According to Lemma \ref{le:normshat}, with probability at least $1-4n^{-5}$, when $m \ge C(\delta_0)\left(1 +\frac{\sigma}{\norm{\x}^2}\right)^2 s^2 \log (mn)$,  we have
		\begin{equation*}
			\norm{\x-\x_{\hat{\mcalS}}} \le \frac{\delta_0}2\norm{\x}.
		\end{equation*}
		Lemma \ref{le:5} gives that  when $m \ge C(\delta_0)(1+\frac{\sigma}{\norm{\x}^2})^2s^2\log{(mn)}$, with probability at least $1-4n^{-5}-4\exp(-c\delta_0^2 m)-2\exp(-c's)$, it holds
		\begin{equation*}
			\min\left(\norm{\x^0-\x_{_{\widehat{\mcalS}}}},\norm{\x^0+\x_{_{\widehat{\mcalS}}}}\right)  \le \frac{\delta_0}2\norm{\x}.
		\end{equation*} 
		Combining the above estimators and applying the triangle inequality, we immediately obtain that,  with  probability at least $1-8n^{-5}-4\exp(-c\delta_0^2 m)-2\exp(-c's)$, 
		\begin{equation*}
			{\rm dist}\left(\x^0,\x\right)=\min\left(\norm{\x^0-\x},\norm{\x^0+\x}\right) \le \delta_0\norm{\x}
		\end{equation*}
		holds, provided $m \ge C(\delta_0)\left(1 +\frac{\sigma}{\norm{\x}^2}\right)^2 s^2 \log (mn)$. This completes the proof.	
	\end{proof}




