	\begin{lemma} \label{lemma7}
		Assume that $\A_i \sim \mcalN^{n\times n}(0,1)$. For any integer $0<s <n$, if $m\ge C(\delta)s\log{n}$, then with probability at least $\textstyle 1-2\exp(-\gamma_1m)$, it holds
		\begin{equation}
			\sup\limits_{\mcalS \subseteq [n] \atop \abs{\mcalS} \le 4s}	\sup\limits_{\p,\q \in \mcalX_{\mcalS} }\norm{\frac{1}{m}\sum\limits_{i=1}^m [\A_i]_{\mcalS, \mcalS}\p_\mcalS\q_\mcalS^{\TT}[\A_i]_{\mcalS, \mcalS}-\q_\mcalS\p_\mcalS^{\TT}} \le \delta \norm{\p_\mcalS}\norm{\q_\mcalS}
			\label{eq:concentration1}
		\end{equation}
		and
		\begin{equation}
			\sup\limits_{\mcalS \subseteq [n] \atop \abs{\mcalS} \le 4s} \sup\limits_{\p,\q \in \mcalX_{\mcalS} }\norm{\frac{1}{m}\sum\limits_{i=1}^m[\A_i]_{\mcalS, \mcalS}\p_\mcalS\q_\mcalS^{\TT}[\A_i^{\TT}]_{\mcalS, \mcalS}-(\p_\mcalS^{\TT}\q_\mcalS)I_{\mcalS,\mcalS}} \le \delta \norm{\p_\mcalS}\norm{\q_\mcalS}.
			\label{eq:concentration2}
		\end{equation}
		Here $C(\delta)$ is a constant depending on $\delta$, and $\gamma_1>0$ is a universal constant. 
	\end{lemma}
	\begin{proof}
		The proof is similar to that of \cite[Lemma 12]{chen2025solving}, so we only give a brief description.  For any fixed $\mcalS \subseteq [n]$ with $\abs{\mcalS} \le  4s$,  let $\mathcal{N}_{1/4}$ be a $\frac{1}{4}$-net of $\mcalX_{\mcalS}$ with cardinality $\abs{\mcalN_{1/4}} \le 9^{4s}$.  Then for any fixed $\p,\q \in \mcalX_{\mcalS}$,  it holds
		\begin{equation}
			\begin{aligned}
				&\norm{\frac{1}{m}\sum\limits_{i=1}^m [\A_i]_{\mcalS, \mcalS}\p_\mcalS\q_\mcalS^{\TT}[\A_i]_{\mcalS,\mcalS}-\q_\mcalS\p_\mcalS^{\TT}} \\
				&\le 2\sup\limits_{\u,\v \in \mathcal{N}_{1/4}}\abs{\frac{1}{m}\sum\limits_{i=1}^m \u^{\TT}[\A_i]_{\mcalS, \mcalS}\p_\mcalS\q_\mcalS^{\TT}[\A_i]_{\mcalS,\mcalS}\v-\u^{\TT}\q_\mcalS\p_\mcalS^{\TT}\v}.
			\end{aligned}
			\label{eq:normineq1}
		\end{equation}
		It is easy to see that $\textstyle \mbbE\left[\u^{\TT}[\A_i]_{\mcalS,\mcalS}\p_\mcalS\q_\mcalS^{\TT}[\A_i]_{\mcalS,\mcalS}\v\right]=(\u^{\TT}\q_\mcalS)(\p_{\mcalS}^{\TT}\v)$.  Therefore, for any $\textstyle (\u,\v)\in \mathcal{N}_{1/4}$ and $t_3>0$, by Lemma \ref{le:bern}, we obtain 
		\begin{eqnarray*}
			\mbbP&\left(\abs{\frac{1}{m}\sum\limits_{i=1}^m \u^{\TT}[\A_i]_{\mcalS, \mcalS}\p_\mcalS\q_\mcalS^{\TT}[\A_i]_{\mcalS,\mcalS}\v-\u^{\TT}\q_\mcalS\p_\mcalS^{\TT}\v} > t_3\right) \\
			&\le 2\exp\left(-C_1\min\left(\frac{t_3^2}{K_3^2},\frac{t_3}{K_3}\right)m\right),
		\end{eqnarray*}
		where $\textstyle K_3=\max\limits_i\norm{\u^{\TT}[\A_i]_{\mcalS,\mcalS}\p_\mcalS\q_\mcalS^{\TT}[\A_i]_{\mcalS,\mcalS}\v-(\u^{\TT}\q_\mcalS)(\p_{\mcalS}^{\TT}\v)}_{\psi_1} \le  c_2\norm{\p_\mcalS}\norm{\q_\mcalS} $.  Taking the union bound over $\u, \v\in \mcalN_{1/4}$, we immediately have 
		%\begin{equation*}
		%	\begin{aligned}
			%		&\mbbP\left(\sup\limits_{\u,\v \in \mathcal{N}_{1/4}}\abs{\frac{1}{m}\sum\limits_{i=1}^m \u^{\TT}\A^i_{\mcalS, \mcalS}\p_\mcalS\q_\mcalS^{\TT}\A^i_{\mcalS,\mcalS}\v-\u^{\TT}\q_\mcalS\p_\mcalS^{\TT}\v} > t_3\right)\\
			%		&\le 2\exp\left(2s\log{9}-C_1\min\left(\frac{t_3^2}{K_3^2},\frac{t_3}{K_3}\right)m\right),
			%	\end{aligned}
		%\end{equation*}
		%Then we combine this with (\ref{eq:normineq1}) to obtain
		\begin{equation} \label{eq:fixqp}
			\begin{aligned}
				\mbbP&\left(\norm{\frac{1}{m}\sum\limits_{i=1}^m [\A_i]_{\mcalS, \mcalS}\p_\mcalS\q_\mcalS^{\TT}[\A_i]_{\mcalS,\mcalS}-\q_\mcalS\p_\mcalS^{\TT}} > 2t_3\right) \\
				&\le 2\exp\left(8s\log{9}-C_1\min\left(\frac{t_3^2}{K_3^2},\frac{t_3}{K_3}\right)m\right)
			\end{aligned}
		\end{equation}
		for any fixed $\p,\q \in \mcalX_{\mcalS}$.  

		To establish the uniform bound of \eqref{eq:fixqp} for all $\p,\q \in \mcalX_{\mcalS}$, we define 
		\begin{equation}
			\G(\p_\mcalS,\q_\mcalS):=\frac{1}{m}\sum\limits_{i=1}^m [\A_i]_{\mcalS, \mcalS}\p_\mcalS\q_\mcalS^{\TT}[\A_i]_{\mcalS,\mcalS}-\q_\mcalS\p_\mcalS^{\TT}.
		\end{equation}
		According to \eqref{eq:fixqp},  for any $t_3>0$, taking the union bound over $\p,\q \in \mcalN_{1/4}$ yields  
		\begin{equation}
			\mbbP\left(\sup\limits_{\p,\q \in \mcalN_{1/4}}\norm{\G(\p_\mcalS,\q_\mcalS)} > 2t_3\right) \le 2\exp\left(16s\log{9}-C_1\min\left(\frac{t_3^2}{K_3^2},\frac{t_3}{K_3}\right)m\right).
			\label{eq: bernstein1}
		\end{equation}
		Let  $\textstyle \p_\mcalS^{(0)}, \q_\mcalS^{(0)} \in \mcalX_{\mcalS}$ such that 
		$\textstyle \sup\limits_{\p,\q \in  \mcalX_{\mcalS}}\norm{\G(\p_\mcalS,\q_\mcalS)} = \norm{\G(\p_\mcalS^{(0)},\q_\mcalS^{(0)})}
		$. There exist  $\textstyle \p^{(1)}_\mcalS,\q^{(1)}_\mcalS \in \mcalN_{1/4}$ so that $\textstyle \norm{\p_\mcalS^{(1)}-\p_\mcalS^{(0)}}\le \frac{1}{4}$ and $\textstyle \norm{\q_\mcalS^{(1)}-\q_\mcalS^{(0)}} \le \frac{1}{4}$. This gives
		\begin{eqnarray*}
			\norm{\G(\p_\mcalS^{(0)},\q_\mcalS^{(0)})}&= & \norm{\G(\p_\mcalS^{(0)}-\p_\mcalS^{(1)},\q_\mcalS^{(0)})+\G(\p_\mcalS^{(1)},\q_\mcalS^{(0)}-\q_\mcalS^{(1)})+\G(\p_\mcalS^{(1)},\q_\mcalS^{(1)})}\\
			&\le &  \frac{1}{2}\norm{\G(\p_\mcalS^{(0)},\q_\mcalS^{(0)})} + \sup\limits_{\p,\q \in \mcalN_{1/4}}\norm{\G(\p,\q)},
		\end{eqnarray*}	
		where the first equality due to the bilinearity of $\textstyle\G(\p,\q)$ on $\textstyle(\p,\q)$, the last inequality follows by observing $\textstyle \p_\mcalS^{(0)}-\p_\mcalS^{(1)}=r\p_\mcalS^{(2)}$ for some $\textstyle r \in [0,\frac{1}{4}]$ and $\textstyle \p_\mcalS^{(2)} \in \mcalX_{\mcalS}$ (and similar relation for $\textstyle \q_\mcalS^{(0)}-\q_\mcalS^{(1)}$). Therefore, 
		\begin{equation*}
			\norm{\G(\p_\mcalS^{(0)},\q_\mcalS^{(0)})} \le 2\sup\limits_{\p,\q \in \mcalN_{1/4}}\norm{\G(\p,\q)}.
		\end{equation*}
		Recall that $\textstyle \sup\limits_{\p,\q \in \mcalX_{\mcalS}}\norm{\G(\p_\mcalS,\q_\mcalS)} = \norm{\G(\p_\mcalS^{(0)},\q_\mcalS^{(0)})}$. Combined with (\ref{eq: bernstein1}) we have 
		\begin{equation*}
			\mbbP\left(\sup\limits_{\p,\q \in \mcalX_{\mcalS}}\norm{\G(\p_\mcalS,\q_\mcalS)} > 4t_3\right) \le 2\exp\left(16s\log{9}-C_1\min\left(\frac{t_3^2}{K_3^2},\frac{t_3}{K_3}\right)m\right).
		\end{equation*}
		Noting that $K_3 \le c_2\norm{\p_\mcalS}\norm{\q_\mcalS}$ and  setting $\textstyle t_3 = \frac{\delta}{4}\norm{\p_\mcalS}\norm{\q_\mcalS}$,  we immediately obtain that with probability greater than $\textstyle 1-2\exp(-\gamma_1m)$, 
		\begin{equation*}
			\sup\limits_{\p,\q \in \mcalX_{\mcalS}}\norm{\frac{1}{m}\sum\limits_{i=1}^m [\A_i]_{\mcalS, \mcalS}\p_\mcalS\q_\mcalS^{\TT}[\A_i]_{\mcalS,\mcalS}-\q_\mcalS\p_\mcalS^{\TT}} \le \delta \norm{\p_\mcalS}\norm{\q_\mcalS} 
		\end{equation*} 
		holds for any fixed $\mcalS \subseteq [n]$ with $\abs{\mcalS} \le  4s$, provided that $m > C(\delta) s$ with some large constant $C(\delta)>0$. Finally,  taking a union bound over all possible $\mcalS \subseteq [n]$ with $\abs{\mcalS} \le 4s$ and observing $\sum\limits_{k=1}^{4s} \left(\begin{array}{c} n\\k\end{array} \right) \le \left(en/s\right)^{4s}$,  the desired (\ref{eq:concentration1}) follows when $m > C(\delta)s\log{n}$.   (\ref{eq:concentration2}) can be proved similarly, and we omit it.
	\end{proof}	

	\begin{lemma}\cite[Weyl's inequality, eigenvalues]{Weyl}
		\label{le: Weyleigen}
		Let $\M, \N \in \mathbb R^{n\times n}$ be two symmetric matrices. The eigenvalues of $\M$ and $\N$ are denoted as $\lambda_1(\M)\ge \ldots \ge \lambda_n(\M)$ and $\lambda_1(\N)\ge \ldots \ge \lambda_n(\N)$, respectively. Then we have
		\begin{eqnarray*}
			\abs{\lambda_i(\M)-\lambda_i(\N)} \le \norm{\M-\N} \quad \mbox{for} \quad 1 \le i \le n.
		\end{eqnarray*}

	\end{lemma}

	\begin{lemma} \label{lemma8}
		For any fixed $0<\delta \le 1$, assume that events \eqref{eq:concentration1} and \eqref{eq:concentration2} hold. 
		For any subset $\mcalS, \mcalT \subseteq [n]$ with $\abs{\mcalS} \le 2s$ and $\abs{\mcalT} \le 2s$, and for any vector $\p \in \mbbR^n$ with ${\rm supp}(\p) \subseteq \mcalT$, the following holds:
		\begin{itemize}
			\item[(i)]
			\begin{equation} 	\label{A.4}
				(2-\delta) \norm{\p}^2 \le \norm{\J_\mcalS(\p)^{\TT}\J_\mcalS(\p)} \le  (4+\delta) \norm{\p}^2.		
			\end{equation}
			\item[(ii)] $\textstyle \J_{\mcalS}(\p)^{\TT}\J_{\mcalS}(\p)$ is invertible and 
			\begin{equation} \label{A.6}
				\norm{\left(\J_{\mcalS}(\p)^{\TT}\J_{\mcalS}(\p)\right)^{-1}} \le \frac{1}{\left(2-\delta\right)\norm{\p}^2}.
			\end{equation} 
			\item[(iii)] 
			\begin{equation} \label{eq:sec}
				\norm{\J_\mcalS(\p)^{\TT}\J_{\mcalT \backslash \mcalS}(\p)} \le (1+\delta) \norm{\p}^2.
			\end{equation} 
		\end{itemize}
		Here, the matrix $\J(\p)$ is defined in \eqref{eq:Jx}.
	\end{lemma}
	\begin{proof}
		Observe that 
		\begin{equation*}
			\mbbE\left[\J(\p)^{\TT}\J(\p)\right]=\mbbE\left[\frac{1}{m}\sum\limits_{i=1}^m\widetilde{\A}_i\p\p^{\TT}\widetilde{\A}_i\right]=2\p\p^{\TT}+2\norm{\p}^2\I_{n \times n}.
		\end{equation*}
		Define $\mcalR = \mcalT \cup \mcalS$. Note that $\abs{\mcalR } \le 4s$. It then follows from  \eqref{eq:concentration1} and \eqref{eq:concentration2} that  
		\begin{equation*}
			\norm{\J_\mcalR(\p)^{\TT}\J_\mcalR(\p)-\mbbE\left[\J_\mcalR(\p)^{\TT}\J_\mcalR(\p)\right]} \le \delta \norm{\p}^2.
		\end{equation*}
		Observing that $\J_\mcalS(\p)^{\TT}\J_\mcalS(\p)$ is a submatrix of $\J_\mcalR(\p)^{\TT}\J_\mcalR(\p)$, the interlacing inequality together with Lemma \ref{le: Weyleigen} yields
		\begin{eqnarray}
			\lambda_{\min}\left(\J_\mcalS(\p)^{\TT}\J_\mcalS(\p)\right)& \ge & \lambda_{\min}\left(\J_\mcalR(\p)^{\TT}\J_\mcalR(\p)\right) \notag\\
			&\ge &\lambda_{\min}\left(\mbbE\left[\J_\mcalR(\p)^{\TT}\J_\mcalR(\p)\right]\right)-   \delta \norm{\p}^2 \notag \\
			&\ge & (2-\delta) \norm{\p}^2,  \label{eq:lammin}
		\end{eqnarray}
		where the last inequality comes from the fact that $\lambda_{\min}\left(\mbbE\left[\J_\mcalR(\p)^{\TT}\J_\mcalR(\p)\right]\right)=2\norm{\p}^2$. Similarly, we also have 
		\begin{eqnarray}
			\lambda_{\max}\left(\J_\mcalS(\p)^{\TT}\J_\mcalS(\p)\right)& \le & \lambda_{\max}\left(\J_\mcalR(\p)^{\TT}\J_\mcalR(\p)\right) \notag\\
			&\le &\lambda_{\max}\left(\mbbE\left[\J_\mcalR(\p)^{\TT}\J_\mcalR(\p)\right]\right)+   \delta \norm{\p}^2  \notag\\
			&\le & (4+\delta) \norm{\p}^2.  \label{eq:lammax}
		\end{eqnarray}
		%\begin{equation}
		%\abs{\lambda_{\min}\left(\J_\mcalS(\p)^{\TT}\J_\mcalS(\p)\right)-\sigma_{\min}\left(\mbbE\left[\J_\mcalS(\p)^{\TT}\J_\mcalS(\p)\right]\right)}\le \delta \norm{\p}^2
		%	\label{Weyl1}
		%\end{equation}
		%and 
		%\begin{equation}
		%\abs{\sigma_{\max}\left(\J_\mcalS(\p)^{\TT}\J_\mcalS(\p)\right)-\sigma_{\max}\left(\mbbE\left[\J_\mcalS(\p)^{\TT}\J_\mcalS(\p)\right]\right)} \le \delta \norm{\p}^2.
		%	\label{Weyl2}
		%\end{equation}
		%Note that  $\textstyle \sigma_{\min}\left(\mbbE\left[\J_\mcalS(\p)^{\TT}\J_\mcalS(\p)\right]\right)=2\norm{\p}^2$ and $\textstyle \sigma_{\max}\left(\mbbE\left[\J_\mcalS(\p)^{\TT}\J_\mcalS(\p)\right]\right)=4\norm{\p}^2$. 
		Combining the above two inequalities, we immediately have 
		\[
		(2-\delta) \norm{\p}^2 \le \norm{\J_\mcalS(\p)^{\TT}\J_\mcalS(\p)} \le  (4+\delta) \norm{\p}^2
		\]
		and 
		\[
		\norm{\left(\J_{\mcalS}(\p)^{\TT}\J_{\mcalS}(\p)\right)^{-1}}=\frac{1}{\lambda_{\min}\left(\J_\mcalS(\p)^{\TT}\J_\mcalS(\p)\right)} \le \frac{1}{\left(2-\delta\right)\norm{\p}^2}.
		\]
		For the item (iii),  since $\textstyle\J_\mcalS(\p)^{\TT}\J_{\mcalT \backslash \mcalS}(\p)$ is a submatrix of $\textstyle \J_\mcalR(\p)^{\TT}\J_{\mcalR}(\p)-3\norm{\p}^2I$, it implies that 
		\begin{eqnarray*}
			\norm{\J_\mcalS(\p)^{\TT}\J_{\mcalT \backslash \mcalS}(\p)}  &\le& \norm{\J_\mcalR(\p)^{\TT}\J_{\mcalR}(\p)-3\norm{\p}^2I}\\
			&\le &  \max\{ 4+\delta-3, 3-(2-\delta)  \} \norm{\p}^2  \\
			&=& (1+\delta) \norm{\p}^2,
		\end{eqnarray*}
		where the second inequality comes from \eqref{eq:lammin} and \eqref{eq:lammax}. This completes the proof.
	\end{proof}	

