	\begin{lemma} \label{lemma9}
		For any fixed $0<\delta \le 0.01$, assume that events \eqref{eq:concentration1} and \eqref{eq:concentration2} hold.
		Let $\x$ be the target $s$-sparse signal. 
		Given an s-sparse estimate $\x^k$ satisfying $\norm{\x^k-\x} \le \delta \norm{\x}$. Define the vector obtained by one iteration of IHT with stepsize $\mu^k$ to be 
		\begin{equation*}
			\u^k = \mathcal{H}_s\left(\x^k-\mu^k\nabla f(\x^k)\right).
		\end{equation*}
		If the step size 	$\mu^k \in (\frac{\underline\mu}{\norm{\x}^2}, \frac{\overline\mu}{\norm{\x}^2})$ for some universal constants  $\underline\mu, \overline\mu \in (0,1)$, it holds
		\begin{equation*}
			\norm{\u^k-\x} \le \rho \norm{\x^k-\x}+ \frac{\sqrt5+1}{2} \cdot\mu^k \cdot C_0 \sigma (1+\delta)\norm{\x}  \sqrt{ \frac{s \log(en/s)}m},
		\end{equation*}
		where $\rho\in (0,0.95)$ is a constant depending only on $\delta$,  $\underline\mu$ and $\overline\mu$.
	\end{lemma}




	\begin{proof} 
		Define $\mathcal{T}_{k}={\rm supp}(\x) \cup {\rm supp}(\x^k)$, $\mathcal{T}_{k+1}={\rm supp}(\x) \cup  {\rm supp}(\u^k)$, and $\textstyle \v^k=\x^k-\mu^k\nabla f(\x^k)$. Since $\u^k$ is the best $s$-term approximation of $\v^k$, it implies $\u^k$ is also the best $s$-term approximation of $\v^k_{\mathcal{T}_{k+1}}$. Combining with the fact that  $\x_{\mathcal{T}_{k+1}}$ is an $s$-sparse vector,  it then follows \cite[Thoerem 1]{shenjie}  that  
		\begin{equation} \label{eq:2vxt}
			\norm{\u^k-\x}  \le  \frac{\sqrt5+1}{2}\norm{\v^k_{\mathcal{T}_{k+1}}-\x_{\mathcal{T}_{k+1}}}.
		\end{equation}
		Therefore, it suffices to upper bound $\norm{\v^k_{\mathcal{T}_{k+1}}-\x_{\mathcal{T}_{k+1}}}$.  Using the definition of $\v^k$, we have
		\begin{equation}
			\norm{\v^k_{\mathcal{T}_{k+1}}-\x_{\mathcal{T}_{k+1}}}=\norm{\x_{\mathcal{T}_{k+1}}^k-\mu^k\nabla_{\mathcal{T}_{k+1}}f(\x^k)-\x_{\mathcal{T}_{k+1}}}.
			\label{eq1}
		\end{equation}
		In noisy case, by (\ref{eq:gradf}), we have 
		\begin{equation*}
			\nabla f(\x)=\frac{1}{m}\sum\limits_{i=1}^{m}(\x^{\TT}\A_i\x-\x^{\TT}\A_i\x-\epsilon_i)\widetilde{\A}_i\x :=\nabla f_{\mbox{clean}}(\x)- \frac{1}{m}\sum\limits_{i=1}^{m} \epsilon_i \widetilde{\A}_i\x.
		\end{equation*}
		By the definitions of $\J(\x)$ given in \eqref{eq:Jx}, a simple calculation gives
		\begin{eqnarray} \label{eq2}
			\nabla_{\mathcal{T}_{k+1}}f_{\mbox{clean}}(\x^k) &= & \frac{1}{m}\sum\limits_{i=1}^{m}\left(\left(\x^k\right)^{\TT}\A_i \x^k-\x^{\TT}\A_i \x \right)[\widetilde{\A}_i]_{\mcalT_{k+1,:}}\x^k \notag \\
			&= & \frac{1}{2}\J_{\mathcal{T}_{k+1}}\left(\x^k\right)^{\TT}\J\left(\x^k + \x\right) \left(\x^k-\x\right) \notag \\
			&= & \left(\J_{\mathcal{T}_{k+1}}\left(\x^k\right)^{\TT}\J\left(\x^k\right)-\frac{1}{2}\J_{\mathcal{T}_{k+1}}\left(\x^k\right)^{\TT}\J\left(\x^k-\x\right)\right) \cdot \left(\x^k-\x\right),
		\end{eqnarray}
		where the second equality comes from the fact that 
		\[
		\left(\x^k\right)^{\TT}\A_i \x^k-\x^{\TT}\A_i \x=\frac12\cdot (\x^k+\x)^\TT \widetilde{\A}_i (\x^k-\x),
		\]
		and the third equality comes from the linearity of $\J(\x^k)$. For simplicity, we denote $\h^k=\x^k-\x$.  Substituting $\nabla_{\mathcal{T}_{k+1}}f(\x^k)$ into (\ref{eq1}), one has
		\begin{eqnarray*}
			&&\norm{\v^k_{\mathcal{T}_{k+1}}-\x_{\mathcal{T}_{k+1}}} \\
			&= & \Big\|\left(\I-\mu^k\J_{\mathcal{T}_{k+1}}\left(\x^k\right)^{\TT}\J_{\mathcal{T}_{k+1}}\left(\x^k\right)\right)\h^k_{\mcalT_{k+1}} +\frac{\mu^k}{2}\J_{\mathcal{T}_{k+1}}\left(\x^k\right)^{\TT}\J_{\mathcal{T}_k}(\h^k)\\
			&&\cdot\h^k_{\mcalT_k}+\mu^k\J_{\mathcal{T}_{k+1}}(\x^k)^{\TT}\J_{\mathcal{T}_k \backslash \mathcal{T}_{k+1}}(\x^k)\h^k_{\mcalT_k\backslash \mcalT_{k+1}}+ \frac{\mu^k}{m}\sum\limits_{i=1}^{m} \epsilon_i [\widetilde{\A}_i]_{\mathcal{T}_{k+1},:}\x^k\Big\|\\
			&\le&  \underbrace{\norm{\left(\I-\mu^k\J_{\mathcal{T}_{k+1}}\left(\x^k\right)^{\TT}\J_{\mathcal{T}_{k+1}}\left(\x^k\right)\right)\h^k_{\mcalT_{k+1}}}}_{I_1}  + \frac{\mu^k}{2} \underbrace{\norm{\J_{\mathcal{T}_{k+1}}\left(\x^k\right)^{\TT}\J_{\mathcal{T}_k}\left(\h^k\right)\h^k_{\mcalT_k}}}_{I_2}\\
			&&+\mu_k \underbrace{\norm{\J_{\mathcal{T}_{k+1}}(\x^k)^{\TT}\J_{\mathcal{T}_k \backslash \mathcal{T}_{k+1}}(\x^k)\h^k_{\mcalT_k\backslash \mcalT_{k+1}}}}_{I_3}+\mu^k \underbrace{\cdot C_0 \sigma \norm{\x^k}  \sqrt{ \frac{s \log(en/s)}m}}_{I_4}.
		\end{eqnarray*}
		where the inequality comes from the triangle inequality and Lemma \ref{le:epAi} with $\mcalS:=\mathcal{T}_{k+1} \cup \mbox{supp}(\x^k)$. 
		We will estimate $I_1, I_2$ and $I_3$ sequentially.  
		For $I_1$, by the assumption $\norm{\x^k-\x} \le \delta \norm{\x}$, we have
		\begin{equation}
			\label{boundxk}
			\left(1-\delta \right)\norm{\x} \le \norm{\x^k} \le \left(1+\delta\right)\norm{\x}.
		\end{equation} 	
		Applying Lemma \ref{lemma8} with  $\mcalS = \mcalT_{k+1}$, we obtain 
		\begin{eqnarray*} \label{eq:bound xk}
			\norm{\I-\mu^k\J_{\mathcal{T}_{k+1}}(\x^k)^{\TT}\J_{\mathcal{T}_{k+1}}(\x^k)}  & \le  & \max\{ 1-\mu^k(2-\delta) \norm{\x^k}^2,  \mu^k(4+\delta) \norm{\x^k}^2 -1 \}.
		\end{eqnarray*}
		%provided 
		%\begin{equation} \label{eq:mu2}
		% \mu^k \in \left( \frac{1}{3(1-\delta)^2 \norm{\x}^2},  \frac{2}{(4+\delta)(1+\delta)^2 \norm{\x}^2} \right).
		% \end{equation}
	This implies 
	\begin{equation*}
		I_1  \le \norm{\I-\mu^k\J_{\mathcal{T}_{k+1}}(\x^k)^{\TT}\J_{\mathcal{T}_{k+1}}(\x^k)} \| \h^k_{\mcalT_{k+1}}\| \le \max\{1-\mu^k\zeta_1, \mu^k\zeta_2-1 \} \| \h^k_{\mcalT_{k+1}}\|,
	\end{equation*}
	where $\zeta_1:=(2-\delta)(1-\delta)^2\norm{\x}^2$ and  $\zeta_2:=(4+\delta)(1+\delta)^2\norm{\x}^2$. 

	For the second term $I_2$, applying Lemma \ref{lemma8} with   $\mcalS=\mcalT_k$ and by (\ref{boundxk}), we have 
	\begin{equation*}
		\norm{ \J_{\mathcal{T}_k}(\h^k)} \le  \sqrt{\left(4+\delta\right)} \norm{\h^k} \le \sqrt{\left(4+\delta\right)} \delta \norm{\x}
	\end{equation*}
	and 
	\[
	\norm{ \J_{\mathcal{T}_{k+1}}\left(\x^k\right) } \le \sqrt{\left(4+\delta\right)} \norm{\x^k} \le \sqrt{\left(4+\delta\right)} (1+\delta) \norm{\x}.
	\]
	This gives
	\begin{equation*}
		I_2 =\norm{\J_{\mathcal{T}_{k+1}}(\x^k)^{\TT}\J_{\mcalT_k}(\h^k)\h^k_{\mcalT_k}}\le 2\zeta_3\norm{\h^k},
	\end{equation*}
	where $\zeta_3:=(2+\delta/2)(1+\delta)\delta\norm{\x}^2$. 

	For the third term $I_3$, it follows from \eqref{eq:sec} and (\ref{boundxk}) with $\p=\x^k$, $\mcalS = \mcalT_{k+1}$ and $\mcalT = \mcalT_{k}$ that
	\begin{equation*}
		\norm{\J_{\mathcal{T}_{k+1}}(\x^k)^{\TT}\J_{\mathcal{T}_k \backslash{\mathcal{T}_{k+1}}}(\x^k)} \le (1+\delta)\norm{\x^k}^2\le  (1+\delta)^3\norm{\x}^2,
	\end{equation*}
	which implies
	\begin{equation*}
		I_3=\norm{\J_{\mathcal{T}_{k+1}}(\x^k)^{\TT}\J_{\mathcal{T}_k \backslash \mathcal{T}_{k+1}}(\x^k)\h^k_{\mcalT_k\backslash \mcalT_{k+1}}} \le \zeta_4 \norm{\h^k_{\mcalT_k\backslash \mcalT_{k+1}}},
	\end{equation*}
	where $\zeta_4:=(1+\delta)^3\norm{\x}^2$.

	Finally, for the last term $I_4$, according to (\ref{boundxk}), we obtain
	\begin{equation*}
		I_4 \le C_0 \sigma (1+\delta)\norm{\x}  \sqrt{ \frac{s \log(en/s)}m}
	\end{equation*} 
	Combining $I_1$, $I_2$, $I_3$, $I_4$ together with \eqref{eq:2vxt},  we obtain
	\begin{eqnarray*}
		&&\norm{\u^k-\x} \\
		& \le &  \frac{\sqrt5+1}{2} \norm{\v^k_{\mathcal{T}_{k+1}}-\x_{\mathcal{T}_{k+1}}} \\
		&\le &    \frac{\sqrt5+1}{2} \cdot \Big( \max\{1-\mu^k\zeta_1, \mu^k\zeta_2-1 \} \| \h^k_{\mcalT_{k+1}}\| +\mu^k \zeta_3 \norm{\h^k} + \mu^k  \zeta_4 \norm{\h^k_{\mcalT_k\backslash \mcalT_{k+1}}} 
		\Big)  \\
		&&+ \frac{\sqrt5+1}{2} \cdot\mu^k \cdot C_0 \sigma (1+\delta)\norm{\x}  \sqrt{ \frac{s \log(en/s)}m}\\
		& \le &  \frac{\sqrt5+1}{2} \cdot \left( \sqrt2 \max\left\{ \max\{1-\mu^k\zeta_1, \mu^k\zeta_2-1 \}, \mu^k \zeta_4 \right\} + \mu^k \zeta_3 \right) \norm{\h^k} \\
		&&+ \frac{\sqrt5+1}{2} \cdot\mu^k \cdot C_0 \sigma (1+\delta)\norm{\x}  \sqrt{ \frac{s \log(en/s)}m}\\
		&:=& \rho \norm{\x^k-\x}+ \frac{\sqrt5+1}{2} \cdot\mu^k \cdot C_0 \sigma (1+\delta)\norm{\x}  \sqrt{ \frac{s \log(en/s)}m},
	\end{eqnarray*}
	where the third inequality follows from $\| \h^k_{\mcalT_{k+1}}\| + \| \h^k_{\mcalT_k\backslash \mcalT_{k+1}}\|  \le \sqrt 2  \norm{\h^k}$.  It is easy to check that when $0<\delta \le 0.01$,  there exist constants $\underline\mu, \overline\mu \in (0,1)$ such that when $\mu^k \in (\frac{\underline\mu}{\norm{\x}^2}, \frac{\overline\mu}{\norm{\x}^2})$, it holds $\rho\in (0,0.95)$. For instance, taking $\delta=0.01$, one obtains the feasible range for step size $\mu^k$ with
	\[
	\underline\mu =0.303, \quad \overline\mu=0.344.
	\]
	This completes the proof.
\end{proof}


With this in place, we are ready to prove Theorem \ref{Theorem3}.
\begin{proof}[Proof of Theorem \ref{Theorem3}]
	Due to the rotation invariance, without loss of generality we assume that $\norm{\x^0-\x} \le \norm{\x^0+\x}$. 
	Thus, the distance between the initial vector $\x^0$  and the target vector $\x$ is ${\rm dist}(\x^0,\x) = \norm{\x^0-\x}$. 
	Define $\mcalS_{k+1}=\mbox{supp}(\x^{k+1})$, $\mcalS^* = \mbox{supp}(\x)$ and $\mathcal{T}_k=\mbox{supp}(\x^k) \cup \mbox{supp}(\x)$. 
	To prove the convergence of the algorithm, observe that
	\begin{equation} \label{eq:upxkx}
		\begin{aligned}
			\norm{\x^{k+1}-\x}
			&=\left[\norm{\x^{k+1}_{\mcalS_{k+1}}-\x_{\mcalS_{k+1}}}^2+\norm{\x^{k+1}_{\mcalS^{c}_{k+1}}-\x_{\mcalS^c_{k+1}}}^2\right]^{\frac{1}{2}}\\ 
			&=\left[\norm{\x^{k+1}_{\mcalS_{k+1}}-\x_{\mcalS_{k+1}}}^2+\norm{\x_{\mcalS^{c}_{k+1}}}^2\right]^{\frac{1}{2}}.
		\end{aligned}
	\end{equation}
	For convenience, set
	\[
	\omega_1=\norm{\x^{k+1}_{\mcalS_{k+1}}-\x_{\mcalS_{k+1}}}, \qquad \omega_2=\norm{\x_{\mcalS^{c}_{k+1}}}.
	\]
	We then proceed to bound the above two terms. 
	Note that  $\textstyle\x_{\mcalS_{k+1}^{c}}$ is a subvector of $\x-\u^k$ due to the fact that $\mbox{supp}(\u^k)=\mcalS_{k+1}$. Here, $\u^k= \mathcal{H}_s(\x^k-\mu^k\nabla f(\x^k))$ is defined in Algorithm \ref{algorithm2:Iterative Algorithm}.  Under the condition of Theorem \ref{Theorem3}, it follows from Lemma \ref{lemma7} that  events \eqref{eq:concentration1} and \eqref{eq:concentration2} hold.
	Applying Lemma \ref{lemma9}, we obtain
	\begin{equation} \label{eq:ome2}
		\omega_2=\| \x_{\mcalS^{c}_{k+1}}\|  \le \norm{\x-\u^k} \le \rho \norm{\x^k-\x} + \frac{\sqrt5+1}{2} \cdot\mu^k \cdot C_0 \sigma (1+\delta)\norm{\x}  \sqrt{ \frac{s \log(en/s)}m},
	\end{equation}
	where $\rho \in (0,0.95)$. We next proceed to bound the term $\omega_1$.
	The update rule \eqref{eq:updarule} together with \eqref{eq:gradf} and \eqref{eq:defpk} gives
	\begin{eqnarray*}
		\omega_1 & = & \norm{\x^k_{\mcalS_{k+1}}-\x_{\mcalS_{k+1}}-\left[\J_{\mcalS_{k+1}}(\x^k)^{\TT}\J_{\mcalS_{k+1}}(\x^k)\right]^{-1}\left(\J_{\mcalS_{k+1}}(\x^k)^{\TT} \F(\x^k) \right.\right.\\
			&&\left.\left.
			-\J_{\mcalS_{k+1}}(\x^k)^{\TT}\J_{\mcalS_{k+1}^c}(\x^k)\x^k_{\mcalS^c_{k+1}}\right)}  \\
		&= & \norm{\left[\J_{\mcalS_{k+1}}(\x^k)^{\TT}\J_{\mcalS_{k+1}}(\x^k)\right]^{-1}\left( \J_{\mcalS_{k+1}}(\x^k)^{\TT}\J(\x^k)  \h^k - \J_{\mcalS_{k+1}}(\x^k)^{\TT} \F(\x^k) \right.\right.\\
			&& \left.\left. + \J_{\mcalS_{k+1}}(\x^k)^{\TT}\J_{\mcalS_{k+1}^c}(\x^k)\x_{\mcalS^c_{k+1}}\right) },
	\end{eqnarray*}
	where the second equality comes from the fact that 
	\[
	\J_{\mcalS_{k+1}}(\x^k)^{\TT}\J_{\mcalS_{k+1}}(\x^k) \h^k_{\mcalS_{k+1}}=\J_{\mcalS_{k+1}}(\x^k)^{\TT}\J(\x^k)  \h^k - \J_{\mcalS_{k+1}}(\x^k)^{\TT}\J_{\mcalS_{k+1}^c}(\x^k) \h^k_{\mcalS_{k+1}^c}.
	\]
	Here, $\h^k=\x^k-\x$.
	Note that $\mbox{supp}(\h^k) \subset \mathcal{T}_k$. 

	The fundamental theorem of calculus together with the fact $\F(\x)=0$ with $y_i=\x^T\A_i\x$, Newton-Leibniz formula $F(\x^k)-F(\x) = \int_0^1 \nabla F(\x(t))(\x^k-\x) dt$ and Lemma \ref{lemma8} gives
	\begin{equation}
		\begin{aligned}
			\label{eq:wme2} 
			\omega_1 &\le  \frac{1}{(2-\delta)\norm{\x^k}^2}\cdot \left\| \int_0^1 \J_{\mcalS_{k+1}}(\x^k)^{\TT} \big( \J_{\mathcal{T}_k}(\x^k) -\J_{\mathcal{T}_k}(\x(t)) \big)\h_{\mathcal{T}_k}^k dt \right.\\
			&\left.+ \J_{\mcalS_{k+1}}(\x^k)^{\TT}\J_{\mcalS_{k+1}^c}(\x^k)\x_{\mcalS^c_{k+1}}
			+\frac{\mu^k}{m}\sum\limits_{i=1}^{m}\epsilon_i[\widetilde{\A}_i]_{\mcalS_{k+1},:}\x^k \right\|\\
			&\le  \frac{1}{(2-\delta)\norm{\x^k}^2}\cdot \left( \int_0^1 \norm{\J_{\mcalS_{k+1}}(\x^k)  } \norm{\J_{\mathcal{T}_k}(\x^k) -\J_{\mathcal{T}_k}(\x(t))} \norm{\h^k} dt \right. \\
			& \left.+ \norm{\J_{\mcalS_{k+1}}(\x^k)^{\TT}\J_{\mcalS_{k+1}^c}(\x^k) }  \norm{\x_{\mcalS^c_{k+1}}  }+\norm{\frac{\mu^k}{m}\sum\limits_{i=1}^{m}\epsilon_i[\widetilde{\A}_i]_{\mcalS_{k+1},:}\x^k}\right)  \\
			&\le  \frac{1}{(2-\delta)\norm{\x^k}^2} \cdot \left( (4+\delta)\norm{\x^k} \norm{\h^k}^2 \int_0^1 (1-t)dt + (1+\delta)\norm{\x^k}^2 \norm{\x_{\mcalS^c_{k+1}} }\right.\\
			& \left.+\norm{ \frac{\mu^k}{m}\sum\limits_{i=1}^{m} \epsilon_i [\widetilde{\A}_i]_{\mcalS_{k+1},:} \x^k} \right)  \\
			&\le  \frac{4+\delta}{2(2-\delta)(1-\delta)\norm{\x}}  \norm{\x^k-\x}^2 +\frac{(1+\delta)\rho}{2-\delta} \norm{\x^k-\x}+\frac{C(\delta)\mu^k \sigma}{\norm{\x}}  \sqrt{ \frac{s \log(en/s)}m}, 
		\end{aligned}
	\end{equation}
	where we denote $\x(t)=\x+t(\x^k-\x)$. Here, the third inequality comes from Lemma \ref{lemma8},   the linearity of $\J(\x^k)$, and the fact that 
	\[
	\x^k-\x(t)=(1-t)(\x^k-\x),
	\]
	and the last inequality arises from \eqref{eq:ome2}, Lemma \ref{le:epAi} with $\mcalS:=\mathcal{S}_{k+1} \cup \mbox{supp}(\x^k)$ and the condition $\norm{\x^k-\x} \le \delta \norm{\x}$. Here, $C(\delta)>0$ is a constant depending on $\delta$.
	Putting everything together, we obtain 
	\begin{equation*}
		\norm{\x^{k+1}-\x}  \le \rho' \norm{\x^k-\x}+\frac{C \sigma}{\norm{\x}}  \sqrt{ \frac{s \log(en/s)}m},
	\end{equation*}
	where  $\rho' \in (0,1)$ by taking $\delta$ to be sufficiently small and $\mu^k \in (\frac{\underline\mu}{\norm{\x}^2}, \frac{\overline\mu}{\norm{\x}^2})$ for some universal constants $\underline\mu, \overline\mu \in (0,1)$. This completes the proof of the first part of Theorem \ref{Theorem3}.


	For the rest of Theorem \ref{Theorem3}, it is easy to see that when $\sigma = 0$, the aforementioned derivation remains valid. Note that \eqref{eq:upxkx} remains valid in noise-free case, namely, 
	\begin{equation}
		\norm{\x^{k+1}-\x}=\left[\norm{\x^{k+1}_{\mcalS_{k+1}}-\x_{\mcalS_{k+1}}}^2+\norm{\x_{\mcalS^c_{k+1}}}^2\right]^{\frac{1}{2}}.
	\end{equation}
	Similar to \eqref{eq:ome2}, the second term can be upper bounded by $\norm{\u^k-\x}$,
	\begin{equation*}
		\omega_2=\| \x_{\mcalS^{c}_{k+1}}\|  \le \norm{\x-\u^k} \le \rho \norm{\x^k-\x}.
	\end{equation*}
	For the first term, using the same approach as in \eqref{eq:wme2}, we have
	\begin{eqnarray}
		\omega_1 
		&\le  &\frac{1}{(2-\delta)\norm{\x^k}^2}\cdot \left( \int_0^1 \norm{\J_{\mcalS_{k+1}}(\x^k)  } \norm{\J_{\mathcal{T}_k}(\x^k) -\J_{\mathcal{T}_k}(\x(t))} \norm{\h^k} dt \right.\notag \\
		&& \left.+ \norm{\J_{\mcalS_{k+1}}(\x^k)^{\TT}\J_{\mcalS_{k+1}^c}(\x^k) }  \norm{\x_{\mcalS^c_{k+1}}  }\right)  \label{eq: ome_1'} \\
		&\le&  \frac{4+\delta}{2(2-\delta)(1-\delta)\norm{\x}}  \norm{\x^k-\x}^2 +\frac{(1+\delta)\rho}{2-\delta} \norm{\x^k-\x}, \notag
	\end{eqnarray}
	Putting the estimators $\omega_1$ and $\omega_2$ into \eqref{eq:upxkx}, we obtain
	\begin{equation} \label{eq:upmu}
		\norm{\x^{k+1}-\x} \le  \nu \norm{\x^k-\x}
	\end{equation}
	for some $\nu \in (\rho,1)$.
	This completes the proof of  the first half of the remaining part of Theorem \ref{Theorem3}. 

	Next, we proceed to finish the last part of the theorem's proof.
	According to \eqref{eq:upmu}, it holds
	\[
	\norm{\x^k-\x} \le \nu^k \norm{\x^0-\x} \le \nu^k \delta \norm{\x}.
	\]
	Let $k_1>0$ be the smallest integer such that it holds
	\begin{equation}
		\nu^k \delta  \norm{\x} \le x_{\min}.
		\label{eq: quadratic}
	\end{equation}
	We claim that $\mcalS^* \subseteq \mcalS_k$ for all $k\ge k_1$, where $\mcalS_k =\mbox{supp}(\x^k)$. Indeed, if there exists a $k_0>k_1$ such that $\mcalS^* \not\subseteq \mcalS_{k_0} $, then there would exist $ i \in \mcalS^*\backslash \mcalS_{k_0} \neq \emptyset$. This implies $\textstyle \norm{\x^{k_0}-\x} \ge |x_{i}| \ge x_{\min}$, which contradicts \eqref{eq: quadratic} that  $\textstyle \norm{\x^{k_0}-\x} \le \nu^{k_0}  \delta  \norm{\x} <  \nu^{k_1}  \delta  \norm{\x} \le  x_{\min}$. This gives the claim. 
	With this in place, for all $k\ge k_1$,   we have $\x_{\mcalS^c_{k+1}}=0$. It then follows from \eqref{eq:upxkx} and \eqref{eq: ome_1'} that 
	\[
	\norm{\x^{k+1}-\x}= \norm{\x^{k+1}_{\mcalS_{k+1}}-\x_{\mcalS_{k+1}}} \le  \frac{4+\delta}{2(2-\delta)(1-\delta)\norm{\x}}  \norm{\x^k-\x}^2 = \nu' \norm{\x^k-\x}^2 
	\]
	for all $k\ge k_1$, where $\nu':=\frac{4+\delta}{2(2-\delta)(1-\delta)\norm{\x}} $.
	Finally, by \eqref{eq: quadratic}, we observe 
	\[
	k_1 = \left\lfloor\frac{\log{(\delta \norm{\x}/x_{\min})}}{\log{(\nu^{-1})}} \right\rfloor + 1 \le c_1\log{( \norm{\x}/x_{\min})}+c_2,
	\]
	we complete the proof.
\end{proof}

