\subsection{Quantum Stochastic Walks Algorithm Implementation}\label{sec4.3}




\paragraph{Efficient Kraus Operator Implementation}
We implement the QSW evolution using the efficient Kraus operator formulation derived in Section \ref{sec:theory}. Traditionally, Eq. \ref{eq:qsw_master_final} is solved using the unraveling method of the master equation. However, this approach increases the matrix size from \( N \) to \( N^2 \), which leads to significant computational overhead. To accelerate the simulation, we map the Hamiltonian and Lindbladian operators \( \{H, L_{i,j}\} \) to a set of Kraus operators \( \{K_0, K_{i,j}\} \), and implement the quantum channel using the operator-sum representation:

\begin{equation}
\rho(t + 1) =  K_0 \rho(t) K_0^\dagger + \sum_{i,j} K_{i,j} \rho(t) K_{i,j}^\dagger,
\label{eq:kraus_sum}
\end{equation}
where the Kraus operators satisfy the trace-preserving condition:

\begin{equation}
K_0^\dagger K_0 + \sum_{i,j} K_{i,j}^\dagger K_{i,j} = I.
\label{eq:trace_preservation}
\end{equation}
The relation between the Lindblad equation and the Kraus operators can be derived by discretizing Eq.~(4). This yields:
\begin{align}
\rho(t + \Delta t) &= \rho(t) - i \omega [H, \rho(t)] \Delta t \nonumber \\
&\quad + \omega \sum_{i,j} c_{ij} \left( L_{i,j} \rho(t) L_{i,j}^\dagger - \frac{1}{2} \{ L_{i,j}^\dagger L_{i,j}, \rho(t) \} \right) \Delta t \nonumber \\
&= \left( I - i \omega H \Delta t - \frac{1}{2} \omega \sum_{i,j} c_{ij} L_{i,j}^\dagger L_{i,j} \Delta t \right) \rho(t) \nonumber \\
&\quad \times \left( I + i \omega H \Delta t - \frac{1}{2} \omega \sum_{i,j} c_{ij} L_{i,j}^\dagger L_{i,j} \Delta t \right) \nonumber \\
&\quad + \omega \sum_{i,j} c_{ij} L_{i,j} \rho(t) L_{i,j}^\dagger \Delta t + \mathcal{O}(\Delta t^2).
\label{eq:lindblad_discretized}
\end{align}
By comparing Eq.~\eqref{eq:lindblad_discretized} with Eq.~\eqref{eq:kraus_sum}, we approximate the Kraus operators as:

\begin{equation}
K_{i,j} = \sqrt{1 - e^{-\omega c_{ij} \Delta t}} \, L_{i,j},
\label{eq:kraus_nonunitary}
\end{equation}
and

\begin{equation}
K_0 = \sqrt{ I - \sum_{i,j} K_{i,j}^\dagger K_{i,j} } \cdot e^{-i (1 - \omega) H \Delta t}.
\label{eq:kraus_unitary}
\end{equation}

In addition, the form of the Kraus operator in our case is $\gamma_{ij} |i\rangle \langle j|$, which is a very sparse matrix. Therefore, each matrix multiplication in the second term can be rewritten as
\begin{equation}
K_{i,j} \rho K_{i,j}^\dagger = (\gamma_{ij} |i\rangle \langle j|)\, \rho \, (\gamma_{ij} |j\rangle \langle i|)
= \gamma_{ij}^2 \rho_{jj} |i\rangle \langle i|.
\label{eq:kraus_diag}
\end{equation}
This shows that the second term in Eq.~\eqref{eq:kraus_sum} only involves the diagonal elements of the density matrix. Hence, we can write
\begin{equation}
\sum_{i,j} K_{i,j} \rho K_{i,j}^\dagger = \Gamma P,
\label{eq:sum_gamma_p}
\end{equation}
where
\begin{equation}
P = \begin{pmatrix}
\rho_{11} \\
\rho_{22} \\
\vdots \\
\rho_{NN}
\end{pmatrix},
\label{eq:diag_vector}
\end{equation}
and
\begin{equation}
\Gamma = \begin{pmatrix}
\gamma_{11}^2 & \gamma_{12}^2 & \cdots & \gamma_{1N}^2 \\
\gamma_{21}^2 & \gamma_{22}^2 & \cdots & \gamma_{2N}^2 \\
\vdots & \vdots & \ddots & \vdots \\
\gamma_{N1}^2 & \gamma_{N2}^2 & \cdots & \gamma_{NN}^2
\end{pmatrix}.
\label{eq:gamma_matrix}
\end{equation}
As a result, the summation of matrix multiplications in Eq.~\eqref{eq:kraus_sum} is reduced to a single matrix-vector multiplication, and the operator-sum representation can be simplified as
\begin{equation}
\rho' = K_0 \rho K_0^\dagger + \Gamma P.
\label{eq:final_op_sum}
\end{equation}
Therefore, the procedure for the proposed \emph{Quantum PageRank-Based Portfolio Optimization} algorithm is outlined as follows:




\begin{algorithm}[H]
\caption{GPU-Accelerated Quantum PageRank for Portfolio Optimization}
\label{alg:qsw_implementation}
\begin{algorithmic}[1]
\Require Historical returns, QSW parameters $\{\omega, \alpha, \beta, \lambda\}$
\Ensure Portfolio weights $\mathbf{w}$
\State \textbf{Preprocessing:}
\State \quad Compute $\mu_i$, $\sigma_i$, $SR_i$, $\Sigma_{ij}$ from training window
\State \quad Construct weight matrix $W$ using exponential preferences
\State \quad Build Hamiltonian $H$ with normalized covariances
\State \quad Create Google matrix $G$ with damping $\alpha_{\text{damp}} = 0.9$
\State \textbf{Quantum Evolution:}
\State \quad Initialize $\rho^{(0)} = I/n$ (uniform superposition)
\State \quad Set $\Delta t = 0.1$, tolerance $\epsilon = 10^{-8}$
\While{$\|\rho^{(t+1)} - \rho^{(t)}\|_1 > \epsilon$ and $t < 5000$}
    \State Compute $K_0 = \sqrt{I - \text{Decay}} \cdot \exp(-i(1-\omega)H\Delta t)$
    \State Apply coherent evolution: $\tilde{\rho} = K_0 \rho^{(t)} K_0^{\dagger}$
    \State Extract diagonal: $\vec{p} = \text{diag}(\tilde{\rho})$
    \State Apply stochastic jumps: $\vec{p}' = \Gamma \vec{p}$
    \State Reconstruct: $\rho^{(t+1)} = \tilde{\rho} - \text{diag}(\vec{p}) + \text{diag}(\vec{p}')$
    \State Normalize: $\rho^{(t+1)} = \rho^{(t+1)}/\text{Tr}(\rho^{(t+1)})$
\EndWhile
\State \textbf{Weight Extraction:}
\State \quad $w_i = \rho_{ii}^{(\infty)}/\sum_j \rho_{jj}^{(\infty)}$ for $i = 1, \ldots, n$
\State \Return $\mathbf{w}$
\end{algorithmic}
\end{algorithm}

\paragraph{Computational Efficiency with GPU Acceleration and cuPyNumeric}

The implementation leverages \texttt{cuPyNumeric}~\cite{cupynumeric} for
GPU-accelerated linear-algebra kernels, an NVIDIA-developed library serving as a drop-in replacement for CPU-based NumPy, enabling zero-code-change adoption of numerical computations accelerated on GPUs. It speeds up all the math primitives involved in the QSW simulation, including:
\begin{itemize}
\item Highly parallelized matrix exponentials for unitary evolution: $O(n^3)$
\item Efficient element-wise operations for transition rates: $O(n^2)$
\item Diagonal extraction and reconstruction: $O(n)$ operations
\end{itemize}

Note that cuPyNumeric has built-in Application Programming Interfaces (APIs) that are capable of all the above operations for simplified coding and even provide automatic multi-GPU/multi-node GPU systems to perform computational workloads at scale for future implementation. This enables real-time portfolio optimization for universes of 100-1000 assets on modern GPUs.




