\title{Non-asymptotic confidence regions on RKHS. \ \ \ \ \  The Paley-Wiener and  standard Sobolev space cases.}

\author[1]{Fabrice Gamboa}
\author[2]{Olivier Roustant}

\affil[1]{{\small UMR CNRS 5219, Institut de Math\'ematiques de Toulouse, Universit\'e de Toulouse, France}}
\affil[2]{{\small UMR CNRS 5219, Institut de Math\'ematiques de Toulouse, INSA, Universit\'e de Toulouse, France}}



