\section{Derivative-based confidence regions in $\Hone$}
\label{sect:grad}
In this section, we assume that both function values and derivative values are observed. Notice that functions of $\Hone$ do not admit pointwise derivatives in general. Thus, we consider the subclass of functions of $\Htwo$, for which $f'$ exists pointwise (and is continuous).
Then, we can define the Monte Carlo estimator of the Sobolev norm:
\begin{equation} \label{eq:SqNormMCEwithDer}
   \HoneSqNormHat = \frac{1}{n} \sum_{i=1}^n f(X_i)^2 + \frac{1}{n} \sum_{i=1}^n f'(X_i)^2.  
\end{equation}

One may also think of modifying the definition of $\hat{f}$ such that it interpolates not only the function values but also the derivative values. However, this modification would rely on the representer theorem for derivatives, which requires a minimal regularity of the kernel $k$, typically that the cross derivative $\frac{\partial^2 K}{\partial x \partial x'}$ exists and is continuous (see e.g. \cite{Saitoh_RKHSbook}, Theorem 2.6). This is not verified for the kernel of $H^1(\mu)$  because for all $x \in \domain$ the function $y \mapsto k(x, y)$ is not differentiable  at $x$ \cite{JAT_Poincare_quadrature}.

\begin{prop}[Conformal prediction interval when derivatives are available]
\label{prop:ConfRegionWithDer}
Let $X_1, \dots, X_n$ be i.i.d. random variables with probability distribution $\mu$. Let $f \in \Htwo$ verifying $ f(X_1)^2 + f'(X_1)^2 \leq b $ almost surely. 
Then for all $\alpha \in (0, 1)$,
$$ \prob \left( \HoneNorm{f}^2\leq \HoneSqNormHat + t_{n, \alpha} \right) \geq 1 - \alpha $$
with $t_{n, \alpha} = b \sqrt{\frac{- \ln \alpha}{2n}}$. Furthermore,  
$$
\prob \left( \forall x \in \domain, \, \vert f(x) - \hat{f}(x) \vert < z_\alpha \sqrt{C(x)}  \right) \geq 1 - \alpha. 
$$
with $z_\alpha = \left(\HoneSqNormHat + t_{n, \alpha}\right)^{1/2}$.
\end{prop}

\begin{proof}
Let $Z_i = f(X_i)^2 + f'(X_i)^2$. The random variables $(Z_i)$ are i.i.d., and lie in $[0, b]$ almost surely. Furthermore, $\Esp(Z_i) = \HoneNorm{f}^2$. Then, by Hoeffding inequality, we deduce that for all $t > 0$,
$$ \prob \left( \HoneSqNormHat - \HoneNorm{f}^2 \leq - t \right) \leq e^{- \frac{2nt^2}{b^2}} $$
Choosing $t = t_{n, \alpha}$, this gives
$ \prob \left( \HoneSqNormHat + t \leq \HoneNorm{f}^2 \right) \leq \alpha $, 
which leads to the first inequality:
$$ \prob \left( \HoneNorm{f}^2\leq \HoneSqNormHat + t_{n, \alpha} \right) \geq 1 - \alpha $$
The prediction interval follows from \eqref{eq:HControlHighProba} and \eqref{eq:predictionInterval} with $G(x) = x + t_{n, \alpha}$.
%, or equivalently
%$$ \prob \left( \HoneNorm{f}^2\leq \kappa  \right) \geq 1 - \alpha $$
\end{proof}


\section{Derivative-free confidence regions in $\HoneStandard$}
\label{sect:derFreeConfReg}

In the whole section, we assume that $\mu$ is the uniform distribution on $[0, 1]$.

\subsection{First ideas of estimators}
%Lebesgue measure.
When derivatives are not observed, the simplest idea is to estimate them by finite differences. Denote by $X_{(1)}, \dots, X_{(n)}$ the sample obtained from $X_1, \dots, X_n$ by sorting in ascending order. As $X_1, \dots, X_n$ are uniformly distributed, we may replace $X_{(i)} - X_{(i-1)}$ by its expectation $\approx 1/n$. Thus, 
$$ f'(X_i) \approx \frac{f(X_{(i)})-f(X_{(i-1)})}{1/n} $$
and we obtain the finite-difference version of the estimator \eqref{eq:SqNormMCEwithDer}:
\begin{equation}
   \label{eq:SqNormMCEwithoutDer}
   T_{0, n} = \frac{1}{n} \sum_{i=1}^n f(X_i)^2 + n \sum_{i=2}^n \left[ f(X_{(i)}) - f(X_{(i-1)}) \right]^2
\end{equation}

A second idea is to use the general expression of the norm in a RKHS $\cH$ with kernel $K$. Let $x_1, \dots, x_n \in [0, 1]$, and denote by $f(\doe) = (f(x_1), \dots, f(x_n))^\top$ the observations and $K(\doe, \doe) =(K(x_i, x_j))_{1 \leq i,j \leq n}$ the Gram matrix associated to $K$. Denote by $\Pi_X(f)$ the projection of $f$ onto $\text{span}(K(x_1, .), \dots, K(x_n, .))$. Then we have (see for example \cite{paulsen2016introduction}),
% $f = \sum_{i=1}^n \alpha_i k(x_i, .)$, we have 
\begin{equation} \label{eq:SqNormGram}
	\Vert \Pi_X(f) \Vert_{\cH} ^2= f(\doe)^\top K(\doe, \doe)^{-1} f(\doe)
\end{equation}
Notice that 
$$ \Vert f \Vert_{\cH} ^2 = \Vert \Pi_X(f) \Vert_{\cH} ^2 + \Vert f-\Pi_X(f) \Vert_{\cH} ^2 $$
Thus, the supremum of $\Vert \Pi_X(f) \Vert_{\cH} ^2$ with respect to all design points $x_1, \dots, x_n$ exists and gives an approximation by below of $\Vert f \Vert_{\cH} ^2$
\begin{equation} \label{eq:SqNormGramApprox}
	\Vert f \Vert_{\cH} ^2 \underset{\geq}{\approx} \sup_{0 \leq x_1 \leq \dots \leq x_n \leq 1} \Vert \Pi_X(f) \Vert_{\cH} ^2.
\end{equation}
In the case of $\Hone$, we can go a step further by computing explicitly $\Vert \Pi_X(f) \Vert_{\cH} ^2$. Indeed, the inverse of the Gram matrix is an explicit tridiagonal matrix.
More precisely, if $0 \leq x_1 < \dots < x_n \leq 1$, it is shown in \cite{duc1973approximation} that $$ K(\doe, \doe)^{-1} = 
%\begin{pmatrix}
%	\alpha_1 & \beta_1 & 0 & \dots & \dots & 0 \\
%	\beta_1 & \alpha_2 & \beta_2 & 0 & \dots & 0 \\
%	0 & \ddots & \ddots & \ddots & \ddots & \vdots \\
%	\vdots  & \ddots & \ddots & \ddots & \ddots & 0 \\
%	0 & \dots & 0 & \beta_{n-2} & \alpha_{n-1} & \beta_{n-1} \\
%	0 & \dots & \dots & 0 & \beta_{n-1} & \alpha_n \\
%\end{pmatrix}$$
\begin{pmatrix}
	\alpha_1 & \beta_1 & &  & 0 \\
	\beta_1 & \alpha_2 & \beta_2 & \\
	 & \ddots & \ddots & \ddots & & \\
	 & & \beta_{n-2} & \alpha_{n-1} & \beta_{n-1} \\
	0 & &  & \beta_{n-1} & \alpha_n \\
\end{pmatrix}$$
where $\alpha_i, \beta_i$ are explicit expressions depending on $K$. For the uniform distribution on $[0, 1]$, we have $K(x,y) = a(\min(x,y)) b(\max(x,y))$ with $a(x) = \frac{1}{\sh(1)} \ch(x)$ and $b(x) = \ch(1-x)$. Denote $a_i = a(x_i), b_i = b(x_i)$, $\mu_{i,j} = a_i b_j - a_j b_i$. Then, we have
$$ \alpha_1 = \frac{a_2}{a_1} \frac{1}{\mu_{2,1}}, \quad 
\alpha_i = \frac{\mu_{i+1, i-1}}{\mu_{i, i-1} \mu_{i+1, i}} \quad (2 \leq i \leq n-1),
\quad
\alpha_n =  \frac{b_{n-1}}{b_n} \frac{1}{\mu_{n, n-1}}
$$ and $$
\beta_i = \frac{1}{\mu_{i+1, i}} \quad (1 \leq i \leq n-1)$$
This gives here
\begin{eqnarray*}
\alpha_1 &=& \th(x_1) + \coth(x_2 - x_1),   \\
\alpha_i &=& \coth(x_{i+1} - x_i ) + \coth(x_i - x_{i-1}), \quad (2 \leq i \leq n-1) \\
\alpha_n &=& \coth(x_n - x_{n-1}) + \th(1 - x_n) \\
\beta_i &=& - \frac{1}{\sh(x_{i+1} - x_i)}, \quad (1 \leq i \leq n-1)
\end{eqnarray*}
Define $x_0$ and $x_{n+1}$ such that $\frac{x_1 - x_0}{2} = x_1$ and $\frac{x_{n+1} - x_n}{2} = 1 - x_n$, that is $x_0 = - x_1$ and $x_{n+1} = 2 - x_n$. Then, after some algebra, we obtain, still with $x_1 < \dots < x_n $,
\begin{equation} \label{eq:SqNormGramExplicit}
\begin{split}
    \Vert \Pi_X(f) \Vert_{\cH} ^2 
=  \sum_{i=1}^{n} 
\left[ 
\th \left( \frac{x_{i+1} - x_i}{2} \right) \right.
&+ \left. \th \left( \frac{x_{i} - x_{i-1}}{2} \right)
\right] f(x_i)^2 \\
&+ \sum_{i=2}^{n} 
\frac{1}{\sh(x_i - x_{i-1})}  
\left[f(x_i) - f(x_{i-1}) \right]^2 
\end{split}
\end{equation}
