The single and two realizations approaches yield identical bounds, indicating that enforcing a common interpolating function across two noise realizations does not improve the guarantee. The bound yielded by the $2^N$-realizations exact approach, computed for $N\leq 6$ (not displayed for the sake of clarity), turns out to also be equivalent to these bounds, showing that the bound resulting from \eqref{eq:relax} is, in fact, tight up to $N=6$. Moreover, this bound outperforms \cite[Theorem 1]{moulines2011non} and \cite[Theorem 5]{taylor2019stochastic}. Although \cite[Theorem 5]{taylor2019stochastic} derives from an all-scenarios formulation, it only uses partial information on the noise distribution.  

Finally, in the strongly convex case, relying on numerical insight, we identify an analytical convergence rate that exactly matches the numerical bound from \eqref{eq:relax}.
\begin{theorem}\label{thm:absolute_noise_cst_stepsize}
  Let $N\in \N$, $0<\mu<L$, $\sigma \in \R$, $\alpha \in (0,\frac{2}{L+\mu}]$. Consider $N$ iterations of \eqref{eq:SGD} with constant stepsize $\alpha_k=\alpha$, $k=1,\ldots,N$, applied to a function $f\in \F_{\mu,L}$, under additive bounded noise $(\ve_k)_{k\in \lb N-1\rb}$ satisfying $\E[\ve_k]=0$, $\E[\ve_k]^2\leq \sigma^2$, and $\E[\langle \ve_k,\ve_l\rangle]=0$, $l\neq k$. Let $(x_k)_{k\in \NN}$ be the iterates of \eqref{eq:SGD}, and $x_\star$ denote a minimizer of $f$. Then, \begin{align}
      E[\|x_{N}-x_\star\|]^2\leq \phi^{2N}\|x_0-x_\star\|^2+\frac{1-\phi^{2N}}{1-\phi^2} \alpha^2\sigma^2,
  \end{align}  
  where $\phi=(1-\mu\alpha)$.
\end{theorem}
\begin{proof}
The first part of the proof follows exactly \cite[Section 2.8.1]{taylor2024towards}, which addresses the noise-free case. Let $S=\{(x_i,f_i,g_i)\}_{i\in\NN\cup\star}$ denote the set of iterates (and minimizer) and associated function and gradient values. We start by analyzing a single iteration of \eqref{eq:SGD}, and claim the following.
\begin{align}\label{eq:claim1}
      \|x_{k+1}-x_\star\|^2\leq \phi^{2}\|x_k-x_\star\|^2+\alpha^2 \sigma^2.
  \end{align}  
By Proposition \ref{prop:FmuL_CI} describing smooth strongly convex functions, and since $g_\star=0$, it holds
    \begin{align*}
        &f_\star\geq f_k+\langle g_k,x_\star-x_k\rangle +\frac{L}{2(L-\mu)}\bigg(\frac{\|g_k\|^2}{L}+\mu\|x_k-x_\star\|^2-\frac{2\mu}{L}\langle g_k,x_k-x_\star\rangle\bigg).\\
        &f_k\geq f_\star +\frac{L}{2(L-\mu)}\bigg(\frac{\|g_k\|^2}{L}+\mu\|x_k-x_\star\|^2-\frac{2\mu}{L}\langle g_k,x_k-x_\star\rangle\bigg).
    \end{align*}
Summing these inequalities, multiplied by $2\alpha\phi$, yields
\begin{align*}
&-\frac{2\alpha\phi(L+\mu)}{L-\mu} \langle g_k,x_k-x_\star\rangle +\frac{2\alpha\phi}{L-\mu}\|g_k\|^2+ \frac{2\alpha\phi\mu L}{L-\mu}\|x_k-x_\star\|^2\leq 0\\
   \Leftrightarrow& \|x_k-x_\star\|^2-2\alpha\langle g_k, x_k-x_\star\rangle+\alpha^2\|g_k\|^2\leq \phi^2\|x_k-x_\star\|^2-\frac{\alpha (2-\alpha(L+\mu))}{L-\mu}\|\mu (x_k-x_\star)-g_k\|^2\\
    &\hspace{6.2cm}\leq \phi^2\|x_k-x_\star\|^2,
\end{align*}
where the second inequality follows from the domain of $\alpha$. Hence,
\begin{align*}
    &\|x_k-x_\star\|^2-2\alpha\langle x_k-x_\star, g_k+\ve_k\rangle+\alpha^2\|g_k+\ve_k\|^2
    \leq \phi^2\|x_k-x_\star\|^2 -2\alpha\langle x_k-x_\star, \ve_k\rangle\\&\hspace{6cm}+\alpha^2\big(2\langle g_k,\ve_k\rangle+\|\ve_k\|^2\big)\\
    \Leftrightarrow&\|x_{k+1}-x_\star\|^2  \leq \phi^2\|x_k-x_\star\|^2 -2\alpha\langle x_k-x_\star, \ve_k\rangle+\alpha^2\big(2\langle g_k,\ve_k\rangle+\|\ve_k\|^2\big).
\end{align*}
Taking the expectation with respect to $\ve_k$ (conditioned on $x_k$) yields
\begin{align*}
    \E_{\ve_k}[\|x_{k+1}-x_\star\|^2] &\leq \phi^2\|x_k-x_\star\|^2 +\alpha^2 \E_{\ve_k}[\|\ve_k\|^2]\leq \phi^2\|x_k-x_\star\|^2 +\alpha^2 \sigma^2,
\end{align*}
by assumption on $\ve_k$. Hence, \eqref{eq:claim1} holds. By recursion, it holds
\begin{align*}
    \E[\|x_{N}-x_\star\|^2]\leq \phi^{2N}\|x_0-x_\star\|^2+\sum_{i=0}^{N-1}\phi^{2i} \alpha^2 \sigma^2.
\end{align*}
Since, for $r\neq1$, $\sum_{i=0}^{N-1} r^i=\frac{1-r^N}{1-r}$, this concludes the proof.
\end{proof}
\paragraph{Relative additive noise and the silver stepsize schedule: on the gap between \(\Gc\) and \(\Ge\).}  
Recently, \cite{altschuler2024acceleration} proposed a stepsize schedule accelerating gradient descent (\eqref{eq:SGD}, \(\ve_k=0\)) on \(\F_{0,L}\) in the deterministic setting. For \(N = 2^k - 1\), \(k \in \mathbb{N}\), the schedule is defined as  
\begin{align}\label{eq:silver}
    \alpha = \sqrt{2}, \quad \text{if } k=1, \quad \text{and} \quad \alpha = [\alpha, 1 + (1+\sqrt{2})^{j-1}, \alpha], \quad j=1,\ldots,k-1, \quad \text{otherwise}.
\end{align}
As shown in \cite{vernimmen2024convergence} via a worst-scenario PEP analysis, this schedule is highly sensitive to relative additive perturbation. Figure \ref{fig:absolute_noise_silver_stepsize} demonstrates that this sensitivity significantly diminishes when considering stochastic noise rather than deterministic perturbations.
