\section{Full SDP formulations of instances of \eqref{eq:relax} and \eqref{eq:relax_refined_sym}}\label{app:fullLMI}
This section provides the full SDP formulation for solving slightly generalized versions of \eqref{eq:PEP_SDP_ex} and \eqref{eq:PEP_SDP_ex_refined}. That is, we provide an example of SDP formulation for solving the simplest SDP relaxation \eqref{eq:relax} of \eqref{eq:PEP_untractable_gen}, and its refinement \eqref{eq:relax_refined_sym}, on the analysis of $N$ iterations of \eqref{eq:SGD}, on $\F_{0,L}$, under the additive bounded noise model. 

Consider first the general case of analyzing $N$ iterations of a method $\M$ on a class $\F$, under noise $\Omega_N$, and given an initial condition $\Ci$ satisfying Assumption \ref{assum:prob_def}. In Section \ref{sec:framework}, we defined the Gram representation of sets $S = \{(x_i, f_i, g_i)\}_{i \in \NN\cup\star}\in(\R^d\times\R\times\R^d)^{N+2}$, and $V=\{(\ve_i,\sigma_i)\}_{i \in[N-1]}\in(\R^d\times\R^d)^N$ as
\begin{align}        
    F &:=[f_\star, f_0, \ldots,\ f_N]^\top,\\
    G&:=PP^\top,\text{ where } P:=[x_\star,x_0,\ldots,x_N,g_\star,g_0,\ldots,g_N,\ve_0,\ldots,\ve_{N-1},\sigma_0,\ldots,\sigma_{N-1}]^\top,\nonumber
\end{align}
see \eqref{eq:equivFGSV}. For computational purposes, we introduce a slightly different Gram representation of $S\cup V$, that is,
\begin{align}        
    F &:=[f_0, \ldots,\ f_N]^\top,\\
    G&:=PP^\top,\text{ where } P:=[x_0,g_0,\ldots,g_N,\ve_0,\ldots,\ve_{N-1},\sigma_0,\ldots,\sigma_{N-1}]^\top,\nonumber
\end{align}
This representation allows (i) reducing the size of the variables in all SDP formulations of \eqref{eq:PEP_untractable_gen}, and (ii) encoding the optimal condition $\|g_\star\|^2=0$, and the method's dynamics directly via \emph{selection vectors}, whose purpose are to access all scalar products in $G$, including those involving $x_k$, $k\leq 1$. Specifically, we consider w.l.o.g. $x_\star$ to be the origin, and $f_\star=0$. To access elements of $G$, given $\e_i$ the $i^{\th}$-unit vector, we then define selection vectors
\begin{itemize}
    \item $\g_\star = \x_\star = \mathbf{0} \in \mathbb{R}^{3N+2}$, $\f_\star=\mathbf{0} \in \mathbb{R}^{N+1}$,
    \item For $k \in \NN$, $\g_k = \e_{k+2} \in \mathbb{R}^{3N+2}$ and $\f_k = \e_{k+1} \in \mathbb{R}^{N+1}$,
    \item For $k \in \lb N-1\rb$, $\vve_k = \e_{N+3+k} \in \mathbb{R}^{3N+2}$ and $\s_k = \e_{2N+3+k} \in \mathbb{R}^{3N+2}$,
    \item $\x_0 = \e_1 \in \mathbb{R}^{3N+2}$, and $\x_{k+1} = \x_0 + \sum_{i=0}^{k+1} \alpha_{k,i} (\g_i + \vve_i), \quad k \in \lb N-1\rb.$
\end{itemize}
These vectors allow accessing all $f_i$'s ($i\in\NN\cup\star$) in $F$, and scalar products of $x_i,g_i,\ve_j,\sigma_j$'s ($i\in\NN\cup\star$, $j\in[N-1]$) in $G$. For instance, 
\begin{align*}
    &\x_i^\top G\x_j=\langle x_i,x_j \rangle,&& \g_i^\top G\g_j=\langle g_i,g_j \rangle,     & \vve_i^\top G\vve_j =\langle \ve_i,\ve_j \rangle ,\\
    &\x_i^\top G\g_j=\langle x_i,g_j \rangle,
     && \g_i^\top G\vve_j=\langle g_i,\ve_j \rangle, & \vve_i^\top G\s_j=\langle \ve_i,\sigma_j \rangle ,\\
    &\x_i^\top G\vve_j=\langle x_i,\ve_j \rangle,&&\g_i^\top G\s_j=\langle g_i,\sigma_j \rangle,& \s_i^\top G\s_j=\langle \sigma_i,\sigma_j \rangle ,\\
      &\x_i^\top G\s_j=\langle x_i,\sigma_j \rangle,
\end{align*}
and 
\[
    F^\top (\f_i - \f_\star) = f_i - f_\star.
\]
Using these selection vectors allows formulating \eqref{eq:PEP_SDP_ex} (generalized to $N$ iterations) as follows.
    \begin{align*}
    & &&\max_{\substack{(F,G) \in \R^{N+1}\times S_+^{3N+2}}}
    F^\top(\f_N-\f_\star) \text{ s.t. }\\&\text{$\F$-interpolability:}&&
  F^\top (\f_i-\f_j)\geq \g_j^\top G(\x_i-\x_j)+\frac{1}{2L}(\g_j-\g_i)^\top G(\g_j-\g_i), \ i,j \in \NN\cup\star,\\
  &\text{$\Ci$:}&& (\x_0-\x_\star)^\top G(\x_0-\x_\star)\leq 1,\\
  &\Cind:&&\vve_k^\top G\x_j=\vve_k^\top G\g_j=\ve_k^\top G\vve_l=0, \ k,l\in[N-1],\ l\neq k,\ j\leq k, \\&\Cn:&&\vve_k^\top G \vve_k = \sigma^2, \ k\in[N-1],\end{align*}
  where satisfaction of $\M$ arises from the definition of the selection vectors, and the interpolation conditions follow from \eqref{eq:FmuL_CI}. Similarly, the symmetrized $N$ iterations version of \eqref{eq:PEP_SDP_ex_refined}, that is, \eqref{eq:relax_refined_sym} with $2$ realizations, applied to the analysis of $N$ iterations of \eqref{eq:SGD} on $\F_{0,L}$, under additive bounded noise, can be expressed as 
  \begin{align*}
    & &&\max_{\substack{(F,G)\in \R^{N+1}\times\Sym^{3N+2}, \\ G^{12}\in\Sym^{3N+2}}}
    F^\top(\f_N-\f_\star) \text{ s.t. } \\ & \begin{pmatrix}
        G & G^{12}\\
        G^{12} &G
    \end{pmatrix}\succeq 0: && G\succeq0,\ G+G^{12} \succeq0, \ G-G^{12}\succeq 0,\\&\text{$\F$-interpolability:}&&
  F^\top (\f_i-\f_j)\geq \g_j^\top G(\x_i-\x_j)+\frac{1}{2L}(\g_j-\g_i)^\top G(\g_j-\g_i), \ i,j \in \NN\cup\star, \\
  & && F^\top (\f_i-\f_j)\geq \g_j^\top G^{12}\x_i-\g_j^\top G\x_j)+\frac{1}{2L}\bigg(\g_j^\top G \g_j+\g_i^\top G\g_i-2\g_j^\top G^{12}g_j\bigg), \ i,j \in \NN\cup\star,\\
  &\text{$\Ci$:}&& \x_0^\top\x_0\leq 1,\\
  &\Cind:&&\vve_k^\top G\x_j=\vve_k^\top G\g_j=\vve_k^\top G\vve_l=0, \ k,l\in[N-1],\ l\neq k,\ j\leq k, \\&\Cn:&&\vve_k^\top G \vve_k = \sigma^2, \ k\in[N-1],\\
&\text{Covariance:} && \vve_k^\top G^{12} \vve_k=-\sigma^2, \ k\in [N-1],\end{align*}
where semi-definite positiveness constraint follow from Proposition \ref{prop:computational}.
\section{Proof of Proposition \ref{prop:relax_refined}}\label{app:relax_refined}
\begin{proof}
We prove the first inequality. Given $(F,G)\in \Ge$, let $(\ve,\sigma)\in\Omega_N$, $f \in \F$, $x_0\in\R^d$ and $x_\star\in\R^d$ be its generating random variables, function, starting point and minimizer. For any random variable $v^i$ with same distribution as $\ve$, consider $(F^i,G^i)\in\Ge$, the copy of $(F,G)$ generated by $(v^i,\sigma^i)$ and $f$, with respect to the same deterministic variables. By Proposition \ref{prop:multivar}, applied to the objective value $\Tr(A_{\text{obj}}G)+F^\top b_{\text{opt}}$ of \eqref{eq:maxGE}, which is the expectation of some function of $\ve$, it holds
\begin{align*}
    \Tr(A_{\text{obj}}G)+F^\top b_{\text{opt}}=\frac{1}{R}\sum_{i=1}^R\Tr(A_{\text{obj}}G^i)+(F^i)^\top b_{\text{opt}}.
\end{align*}

Hence, \eqref{eq:maxGE} is equivalent to \eqref{eq:PEP_SDP_ex_refined}, i.e., 
\begin{align*}
\max_{(F,G)\in\Ge}\Tr(A_{\text{obj}}G)+F^\top b_{\text{opt}}=   \max_{\substack{(F^i,G^i)\in \G_E \\\text{copies generated by same} f\in\F,\ x_0,\ x_\star\in\R^d \\\text{and same identically distributed $(\ve^i,\sigma^i)\in\Omega_N$} }} \frac 1R\sum_i \Tr(A_{\text{obj}}G^i)+(F^i)^\top b_{\text{opt}}.
\end{align*}
All feasible variables $(F^i,G^i)\in\Ge$ of this problem (i) belong to $\Gc$, by Proposition \ref{prop:def_Gc}, (ii) are interpolated by a single function $f\in \F$, hence satisfy $(\bigF,\bigG)$ as defined in \eqref{eq:relax_refined} is $\F$-interpolable, and (iii) share the same deterministic variables $\{(x_i,f_i,g_i)\}_{i=0,\star}$.

In addition, the covariance between $v^i_k$ and $v^j_k$, for $k\in \lb N-1\rb$ and $i,j\in\{1,2,\ldots,N\}$, can be chosen to be any value $C_k$ satisfying
\begin{align*}
    C_k\leq  \sqrt{\E_{v^i}[(v^i_k)^2]\E_{v^j}[(v^j_k)^2]},
\end{align*}
since by Cauchy-Schartz inequality, this quantity bounds $\E[\langle v^i_k,v^j_k\rangle]$, see, e.g., \cite[Section 4.2]{bertsekas2008introduction}.

By definition of $\Sigma_{N,R}^{ij}$, the covariance introduced in \eqref{eq:relax_refined} satisfies this assumption. Finally, $\sigma^i$, $i=1,2,\ldots,R$, can be chosen to be uncorrelated.  Hence, any feasible variable to \eqref{eq:maxGE} is also a feasible variable to \eqref{eq:relax_refined}.

We now prove the second inequality. By linearity of the objective, \eqref{eq:relax_refined} is equivalent to
\begin{align}\label{eq:interm}
    \max_{(F,G)}& \ \Tr(A_{\text{obj}}G)+(F)^\top b_{\text{opt}},\nonumber\\\text{s.t. }& \exists (F^i,G^i)\in \Gc: \ (F,G)=\frac{1}{R}\sum_{i=1}^R  (F^i,G^i), \text{ and additional constraints on $ (F^i,G^i)$ }.
\end{align}
Hence, the solution to \eqref{eq:interm} is smaller or equal to that of 
\begin{align}\label{eq:interm1}
    \max_{(F,G)}& \ \Tr(A_{\text{obj}}G)+(F)^\top b_{\text{opt}},\text{ s.t. }  \exists (F^i,G^i)\in \Gc: \ (F,G)=\frac{1}{R}\sum_{i=1}^R  (F^i,G^i).
\end{align}
By convexity of $\Gc$, any feasible variable to \eqref{eq:interm1} belongs to $\Gc$, hence is also a feasible variable of \eqref{eq:relax}, which proves the second inequality.
\end{proof}
\section{Proof of Proposition \ref{prop:relax_sym}}\label{app:relax_sym}
\begin{proof}
Clearly, any solution of \eqref{eq:relax_refined_sym} is a feasible point of \eqref{eq:relax_refined}, hence $f_{\text{obj}}^{\text{sym},\star}\leq f_{\text{obj}}^{\star}$. In addition, let $$(\bigF^*, \bigG^*) = \left(\begin{bmatrix}
        F^1\\F^2\\\vdots\\F^R
    \end{bmatrix}, \ \begin{pmatrix}
    G^1 &G^{12}&\ldots&G^{1R}\\
    G^{12} &G^2&\ldots&G^{2R}\\
    \vdots &\vdots&\ddots&\vdots\\
    G^{1R} &G^{2R}&\ldots&G^{R}
\end{pmatrix}\right)$$ be a solution to \eqref{eq:relax_refined}. \\
\textbf{Claim 1:} Given $P=[1,2,\ldots,R]$ and any permutation $\pi_p^i(P)$ as defined in Proposition \ref{prop:sym_M}, 
\begin{align*}
    (\bigF_{\pi_p^i(P)}, \bigG_{\pi_p^i(P)}),
\end{align*}
the vector and matrix obtained from $(\bigF,\bigG)$ by permuting indices of entries according to $\pi_p^i(P)$, is also a solution to \eqref{eq:relax_refined}.

Indeed, swapping the order of entries in $(\bigF,\bigG)$ leaves the objective function $\frac 1 R\sum_{i=1}^R\Tr(A_{\text{obj}}G^i)+(F^i)^\top b_{\text{opt}}$, the constraint $(F^i,G^i)\in \Gc$, and $\F$-interpolability of $(\bigF,\bigG)$ unchanged. In addition, due to the order $p$ super-symmetry of $\bSig$, and given Proposition \ref{prop:sym_M}, the covariance condition is automatically satisfied by $(\bigF_{\pi_p^i(P)}, \bigG_{\pi_p^i(P)})$ if satisfied by $(\bigF,\bigG)$.
\\
\textbf{Claim 2:} Given the $2^p$ permutations $\pi_p^i(P)$ as defined in Proposition \ref{prop:sym_M}, 
\begin{align*}
    \frac{1}{R}\sum_{i=1}^R (\bigF_{\pi_p^i(P)}, \bigG_{\pi_p^i(P)})= \left(\begin{bmatrix}
        \frac 1 R\sum_{i=1}^R F^i\\\frac 1 R\sum_{i=1}^R F^i\\\vdots\\\frac 1 R\sum_{i=1}^R F^i
    \end{bmatrix}, \ \begin{pmatrix}
    \frac 1 R\sum_{i=1}^R G^i &G^{12}&\ldots&G^{1R}\\
    G^{12} &\frac 1 R\sum_{i=1}^R G^i&\ldots&G^{1(R-1)}\\
    \vdots &\vdots&\ddots&\vdots\\
    G^{1R} &G^{1(R-1)}&\ldots&\frac 1 R\sum_{i=1}^R G^i
\end{pmatrix}\right)
\end{align*}
is also a solution to \eqref{eq:relax_refined}. Under Assumption \ref{assum:prob_def}, all constraints in \eqref{eq:relax_refined}, and its objective constraint, are linear in its variables. Hence, any convex combination of solutions of \eqref{eq:relax_refined} is also a solution to \eqref{eq:relax_refined}. In addition, the structure of $\frac{1}{R}\sum_{i=1}^R (\bigF_{\pi_p^i(P)}, \bigG_{\pi_p^i(P)})$ follows from the definition of $\pi_p^i(P)$.

Hence, to any solution to \eqref{eq:relax_refined} corresponds a feasible point of \eqref{eq:relax_refined_sym} with same objective value. Therefore, $f_{\text{obj}}^{\star}\leq f_{\text{obj}}^{\text{sym},\star}$, which concludes the proof.
\end{proof}
\section{Computational comments}\label{app:comput}
This section shows that the constraint $\bigG \succeq 0$, in \eqref{eq:relax_refined}, can be equivalently reduced to linear inequalities on $G, G^{1j}$.
\begin{proposition}\label{prop:computational}
Given $p,k\in \N$, $p\geq 1$, let  $M\in (\Sym^k)^{2^p\times 2^p}$ be a $2^p$-dimensional order $p$ super-symmetric matrix whose elements belong to $\Sym^{k}$. Then, $M\succeq0$ can be expressed via $3^p$ linear inequalities in the elements of $M$.
\end{proposition}
\begin{proof}
We proceed by induction.
\begin{itemize}
    \item If $p\geq 1$, $M\succeq 0$ if and only if $M_{1,1}\succeq 0, \ M_{1,1}-M_{1,2}\succeq 0, \ M_{1,1}+M_{1,2}\succeq 0.$
Indeed, \begin{align*}
    &\begin{pmatrix}
        M_{1,1}& M_{1,2}\\M_{1,2}  & M_{1,1}
    \end{pmatrix}\succeq 0 \Leftrightarrow [x^\top~ y^\top] \begin{pmatrix}
        M_{1,1} & M_{1,2}\\M_{1,2} & M_{1,1}
    \end{pmatrix}\begin{bmatrix}
        x \\y
    \end{bmatrix}\succeq 0, \  \forall x,y\in \R^k\\
    \Leftrightarrow \ & x ^\top M_{1,1} x+ y^\top M_{1,1} y+ 2 x^\top M_{1,2} y\geq 0, \ \forall x,y\in \R^k\\
    \Leftrightarrow\  & (x+y) ^\top(M_{1,1}+M_{1,2})(x+y)+(x-y) ^\top(M_{1,1}-M_{1,2})(x-y)\geq 0, \ \forall x,y\in \R^k.
\end{align*}
Condition $M_{1,1}\succeq 0$ follows from the case $y=0$, $M_{1,1}-M_{1,2}\succeq 0$ from the case $y=x$, and $M_{1,1}+M_{1,2}\succeq 0$ from the case $y=-x$.
    \item  Suppose the assertion is true for $p$, and consider the case $p+1$. Partition $M$ into four blocks in $(\Sym^k)^{2^{p} \times 2^{p}}$:
    \[
    M = \begin{pmatrix}
        \bar M_{1,1} & \bar M_{1,2} \\
        \bar M_{1,2} & \bar M_{1,1}
    \end{pmatrix}.
    \] Then, $M\succeq 0$ if and only if 
    $\bar M_{1,1}\succeq 0, \ \bar M_{1,1}-\bar M_{1,2}\succeq 0, \ \bar M_{1,1}+\bar M_{1,2}\succeq 0.$ By assumption, each of these $3$ positive definiteness constraints can be expressed via $3^p$ linear expressions in the elements (in $\R^k$) of $\bar M_{1,1}$, $\bar M_{1,1}-\bar M_{1,2}$, and $\bar M_{1,1}+\bar M_{1,2}$, respectively, as all are order $p$ super-symmetric. The total number of constraints is thus $3^{p+1}$.
\end{itemize}
\end{proof}  
\section{Proof of Theorem \ref{thm:exact_SDP}}\label{app:exact_SDP}
\begin{proof}
By Propositions \ref{prop:relax_refined} and \ref{prop:relax_sym}, 
\begin{align*}
                \max_{\substack{(F,G)\in \G_E}}& \Tr(A_{\text{obj}}G)+F^\top b_{\text{opt}}\leq    \max_{\substack{(F,G)\in \tilde{G}_c(\bSig)}} \Tr(A_{\text{obj}}G)+F^\top b_{\text{opt}}.
\end{align*}
We now show that any $(F,G)\in \tilde{G}_c(\bSig)$ belongs to $\Ge$.

Denote by $(F^\vii,G^\vii)$ any of the $2^N$ copies of $(F,G)$. We argue that $(F^\vii,G^\vii)$ are the realizations of a random variable, generated by realizations $(\ve^\vii,\sigma)$ of $(\ve,\sigma)\in \Omega_N$, where $\sigma$ is deterministic and $\ve$ is an equidistributed random variable in $\Omega_N$, with, at each step, $2$ possible realizations, i.e.,
\begin{align*}
    \ve_k^\vii&=\pm v_k\sqrt{A_1(f(x_k)-f_\star)+B_1\|g_k\|^2+C_1\|x_k-x_\star\|^2+D_1+E_1\sigma^2_k}\\
    \sigma_{k+1}^{2}&=A_2(f(x_k)-f_\star)+B_2\|g_k\|^2+C_2\|x_k-x_\star\|^2+D_2+(1-\rho)\sigma^2_k,
\end{align*}
where $v_k\in\R^d$ is a vector of norm $1$, which may differ from query to query. The $2^N$ realizations $\ve^\vii$ are generated by all vectors in $\{-1,1\}^N$, ordered lexicographically. Indeed, given $\bSigN^\star$, the constraints $\vve_k^\top G^{1i}\vve_k= \Sigma^{1i}_{k+1,k+1} \vve_k^\top G\vve_k$ in $\tilde{G}_c(\bSigN^\star)$, are satisfied by such realizations $\ve^\vii$.

In addition, by $\F$-interpolability of $(\bigF,\bigG)$, there exists a single function $f\in \F$ interpolating all $(F^\vi,G^\vi)$, and these are all consistent with the method $\M$, the optimality condition, and $\Ci$ by definition of $\tilde{G}_c(\bSigN^\star)$. Hence, $(F,G)=\frac{1}{2^N}\sum_i (F^\vi,G^\vi)$ belongs to $\Ge$.
\end{proof}
