\begin{definition}\label{def:condFG}
    Given $N\in \N$, consider a method $\M$, a function class $\F$, a class of noises $\Omega_N$, and an initial condition $\Ci$, satisfying Assumption \ref{assum:prob_def}. Let $(F,G)\in\R^{N+1}\times \Sym_+^{3N+2}$, and, $P\in \R^{3N+2\times 3N+2}$ satisfying $G=PP^\top$, it holds that $S=\{(P^\top\x_i,F^\top\f_i,P^\top\g_i)\}_{i\in \NN\cup\star}$
    We say a pair $(F,G)\in\R^{N+1}\times \Sym_+^{3N+2}$ \begin{itemize}
    \item is $\F$-interpolable and satisfies $\Ci$, if for any $P\in \R^{3N+2\times 3N+2}$ satisfying $G=PP^\top$, it holds that $S=\{(P^\top\x_i,F^\top\f_i,P^\top\g_i)\}_{i\in \NN\cup\star}$ is $\F$-interpolable, and satisfies $\Ci$,
    \item satisfies $\Cn$, if $\forall k \in \lb N-1\rb$, \begin{align*}
                &\vve_k^\top G\vve_k\leq A_1F^\top(\f_k-\f_\star)+B_1\g_k^\top G\g_k+C_1 \x_k^\top G\x_k+D_1+E_1\s_k^\top G\s_k, \ \forall k\in \lb N-1 \rb,\\
      & \s_{k+1}^\top G\s_{k+1}\leq A_2F^\top(\f_k-\f_\star)+B_2\g_k^\top G\g_k+C_2 \x_k^\top G\x_k+D_2+(1-\rho)\s_k^\top G\s_k.
    \end{align*}
    \item  satisfies $\Cind$, if 
    \begin{align*}
        &\vve_k^\top G\vve_l=\ \vve_k^\top G\x_i=\vve_k^\top G\g_i=\vve_k ^\top G \s_i=0, \ \forall k \in \lb N-1 \rb,  i\ < k, l\neq k,
        \\
        &\vve_k^\top G\x_k=\vve_k^\top G\g_k,  \forall k \in \lb N-1 \rb ,\text{ if } \alpha_{k-1,k}=0 \text{ in \eqref{eq:method}}.
    \end{align*}
\end{itemize}
\end{definition}
\begin{proposition}
        Given $N\in \N$, consider a method $\M$, a function class $\F$, a class of noises $\Omega_N$, and an initial condition $\Ci$, satisfying Assumption \ref{assum:prob_def}. Then, a pair $(F,G)\in\R^{N+1}\times \Sym_+^{3N+2}$ is $\F$-interpolable and satisfies $\Ci$ if and only if there exists a $\F$-interpolable set $S=\{(x_i,f_i,g_i)\}_{i\in \NN\cup\star}$ satisfying $\Ci$, and some set $V=\{(\ve_k,\sigma_k)\}_{k\in \lb N-1 \rb}$ such that $(F,G)$ satisfies \eqref{eq:FG} with respect to $S\cup V$.
\end{proposition}
\begin{proof}
    By Assumption \ref{assum:prob_def}, there exists some $b_k\in \R^{N+1}$ and $A_k \in \Sym_+^{3N+2}$ (with only elements $A_k^{ij}$, $i,j\leq N+2$ non-zeros) $k=1,2,\ldots$, such that $\F$-interpolability of, and satisfaction of $\Ci$ by, a set $S=\{(x_j,f_j,g_j)\}_{j\in \NN\cup \star}$, can be expressed as 
    \begin{align}\label{eq:interp_matrix}
        F^\top b_k+\Tr(A_k G), 
    \end{align}
    where $(F,G)$ are defined in \eqref{eq:FG} with respect to $S$ and some set $V=\{(\ve_k,\sigma_k)\}_{k\in \lb N-1 \rb}$. Hence, if $(F,G)$ satisfies \eqref{eq:FG} with respect to $S\cup V$, then $(F,G)$ satisfies \eqref{eq:interp_matrix}, and $\tilde S=\{(P^\top\x_i,F^\top\f_i,P^\top\g_i)\}_{i\in \NN\cup\star}$ is $\F$-interpolable, since, by definition of $P$, $(F,G)$ satisfies \eqref{eq:FG} with respect to $\tilde S$.

    Conversely, if $(F,G)$ is $\F$-interpolable, then it satisfies \eqref{eq:interp_matrix} by definition of $\tilde S$ with respect to some $V=\{(\ve_k,\sigma_k)\}_{k\in \lb N-1 \rb}$.
\end{proof}

