\title[Benchmarking QNNs for Wind Energy Forecasting]{Quantum Neural Networks for Wind Energy Forecasting: A Comparative Study of Performance and Scalability with Classical Models}

\author{Batuhan Hangun$^{1,*}$, Oguz Altun$^1$, Onder Eyecioglu$^{2,\dagger}$}

