\section{Gelfand-Tsetlin modules}\label{sec:GTmod}

 In this section we recall the definitions and main properties of a full subcategory of the category of $\mathfrak{gl}(n)$-modules, the so-called Gelfand-Tsetlin modules. Let us fix $n\geq 2$. In order to define Gelfand-Tsetlin modules we start constructing a maximal commutative subalgebra of $U(\mathfrak{gl}(n))$. For $m\leqslant n$, denote by $\mathfrak{gl}_m$ the Lie subalgebra
of $\mathfrak{gl}(n)$ spanned by $\{ E_{ij}\,|\, i,j=1,\ldots,m \}$, and $U_m:=U({ \mathfrak{gl}_m})$. 

\begin{definition}Set $U:=U_n$, and let $Z_{m}$ denote the center of $U_{m}$.
\begin{itemize} 
\item[(i)] The {\it standard  Gelfand-Tsetlin subalgebra} $\Gamma$ 
of $U$ is the subalgebra generated by  $
\bigcup\limits_{{i=1}}^{n}Z_i$.
\item[(ii)] A \emph{Gelfand-Tsetlin module} is a $U$-module $M$ such that $M = 
\bigoplus\limits_{\chi\in\Gamma^*} M(\chi)$, where 
$M(\chi)=\{v\in M:\forall g\in\Gamma\text{ , }\exists k\in\mathbb{N} \text{ such that } (g-\chi(g))^{k}v=0 \}.$
\end{itemize}
\end{definition}

 The realization of simple finite-dimensional $\mathfrak{gl}(n)$-modules given in \cite{GT50} is the main inspiration for the construction of relation modules. Moreover, this realization provides an eigenbasis for the action of $\Gamma$ (see \cite{Zhe73}). Let us recall the result:

\begin{definition}\label{def:GTtableau} A configuration of complex numbers 

\begin{center}
\Stone{\mbox{ \scriptsize {$l_{n1}$}}}\Stone{\mbox{ \scriptsize {$l_{n2}$}}}\hspace{1cm} $\cdots$ \hspace{1cm} \Stone{\mbox{ \scriptsize {$l_{n,n-1}$}}}\Stone{\mbox{ \scriptsize {$l_{nn}$}}}\\[0.2pt]
\Stone{\mbox{ \scriptsize {$l_{n-1,1}$}}}\hspace{1.5cm} $\cdots$ \hspace{1.5cm} \Stone{\mbox{ \tiny {$l_{n-1,n-1}$}}}\\[0.3cm]
\hspace{0.2cm}$\cdots$ \hspace{0.8cm} $\cdots$ \hspace{0.8cm} $\cdots$\\[0.3cm]
\Stone{\mbox{ \scriptsize {$l_{21}$}}}\Stone{\mbox{ \scriptsize {$l_{22}$}}}\\[0.2pt]
\Stone{\mbox{ \scriptsize {$l_{11}$}}}\\
\medskip
\end{center}is called a \emph{Gelfand-Tsetlin tableau}. A Gelfand-Tsetlin tableau is called  \emph{standard} if its entries satisfy $l_{ki}-l_{k-1,i}\in\mathbb{Z}_{\geq 0}, \text{ and }l_{k-1,i}-l_{k,i+1}\in\mathbb{Z}_{>0}$ for all possible pair of indices. 

\end{definition}

\begin{theorem}[Gelfand-Tsetlin-1950]
 Let $\lambda=(\lambda_{1},\ldots,\lambda_{n})$ be an integral dominant $\mathfrak{gl}(n)$-weight. The simple finite--dimensional  module $L(\lambda)$ has a realization of tableaux, where the vector space consist of all {standard tableaux} $T(L)$'s with top row $l_{nj}=\lambda_j+j-1$, and the $\mathfrak{gl}(n)$-module structure is given by the Gelfand-Tsetlin formulas.
 \begin{equation}\label{eq:GTformulas}
\begin{split}
E_{k,k+1}(T(L))&=-\sum_{i=1}^{k}\left(\frac{\prod_{j=1}^{k+1}(l_{ki}-l_{k+1,j})}{\prod_{j\neq i}^{k}(l_{ki}-l_{kj})}\right)T(L+\delta^{ki}),\\ E_{k+1,k}(T(L))&=\sum_{i=1}^{k}\left(\frac{\prod_{j=1}^{k-1}(l_{ki}-l_{k-1,j})}{\prod_{j\neq i}^{k}(l_{ki}-l_{kj})}\right)T(L-\delta^{ki}),\\
E_{kk}(T(L))&=\left(k-1+\sum_{i=1}^{k}l_{ki}-\sum_{i=1}^{k-1}l_{k-1,i}\right)T(L),
\end{split}
\end{equation} where  $T(L\pm\delta^{ki})$ is the tableau obtained by $T(L)$ adding $\pm 1$ to the $(k, i)$'s position of $T(L)$ (if a new tableau is not standard then the result of the action is zero). 
\end{theorem}




\section{Relation Gelfand-Tsetlin modules}\label{sec:RelGTmodules}

In \cite{FRZ19}, the class of relation Gelfand-Tsetlin modules was introduced as an attempt for unifying several known constructions of Gelfand-Tsetlin modules with diagonalizable action of $\Gamma$ (see \cite{GG65}, \cite{LP79}, \cite{Maz98}, \cite{Maz03}). This section is devoted to describe the construction and main properties of relation Gelfand-Tsetlin modules.



\subsection{Relation graphs}
Denote by $\mathfrak{V}$ the set $\{(i,j)\ |\ 1\leq j\leq i\leq n\}$ arranged in a triangular configuration with $n$ rows, where the $k$-th row is written as $((k,1),\ldots,(k,k))$, and top row given by the $n$-th row.
\begin{figure}[!htbp]
\begin{center}
\begin{tabular}{c c}
\xymatrixrowsep{0.5cm}
\xymatrixcolsep{0.1cm}\xymatrix @C=0.1em { 
 \scriptstyle{(4,1)}& &\scriptstyle{(4,2)}  & &\scriptstyle{(4,3)} &   &\scriptstyle{(4,4)} \\
  & \scriptstyle{(3,1)}   & &\scriptstyle{(3,2)}  & &\scriptstyle{(3,3)}  \\
   &     &\scriptstyle{(2,1)} & &\scriptstyle{(2,2)} & \\
 &    & &\scriptstyle{(1,1)}  & &\\
}\\
\end{tabular}
\end{center}
\caption{Configuration of the set of vertices $\mathfrak{V}$ for $n=4$}
\end{figure}


 From now on, we consider only directed graphs $G$ with set of vertices $\mathfrak{V}$.



\begin{definition}\label{def:refgraph}
For any  $1\leq i<j\leq k\leq n-1$, we call $((k,i),(k,j))$ an \emph{adjoining pair of vertices in $G$} if there is a directed path from $(k,i)$ to $(k,j)$ and  whenever $ i<t< j$, there are not directed paths from $(k,i)$ to $(k,t)$ or from $(k,t)$ to $(k,j)$. $G$ is called a \emph{relation graph} if the following conditions are satisfied:

\begin{itemize}

\item[(i)]  The only possible arrows in $G$ are the ones connecting vertices in consecutive rows or vertices in the $n$-th row.
\item[(ii)] For any $1\leq k\leq n$ and $1\leq i<j\leq k$ there are not directed paths from $(k,j)$ to $(k,i)$. 
\item[(iii)] $G$ does not contain oriented cycles or multiple arrows.

\item[(iv)] For any two vertices in the same row $k<n$ and the same connected component (of the unoriented graph associated with $G$), there exists an oriented path in $G$ from one vertex to the other.


\item[(v)] G does not contain a subgraph of the form:
\begin{center}
\begin{tabular}{c c }
\xymatrixrowsep{0.5cm}
\xymatrixcolsep{0.1cm}
\xymatrix @C=0.2em{
 \scriptstyle{(k+1,r)}\ar[rrrd] &   & &  \scriptstyle{(k+1,s)}\ar[llld] |!{[d];[lll]}\hole    & \\
 \scriptstyle{(k,i)}& &    &\scriptstyle{(k,j)}   & }
\end{tabular}
\end{center}
 with $1\leq r<s\leq k+1$, and $1\leq i< j\leq k$.

 \item[(vi)] For every adjoining pair of vertices $((k,i),(k,j))$, one of the following is a subgraph of $G$: 
\begin{center}
\begin{tabular}{c c c c}
\xymatrixrowsep{0.5cm}
\xymatrixcolsep{0.1cm}
