for some $1\leq q\leq k-1$, $1\leq p\leq k+1$, or $1\leq s<t\leq k+1.$

\end{itemize}
\end{definition}
\begin{definition}\label{def:genericgraph}
A relation graph $G$ is \emph{generic} if there are not adjoining pairs of vertices in $G$.
\end{definition}


We write vectors in $\mathbb{C}^{\frac{n(n+1)}{2}}$ as ordered tuples $L=(l_{n1},\ldots,l_{nn}|\ldots|l_{22},l_{21}|l_{11})$ indexed by elements in $\mathfrak{V}$, and by $T(L)$ we denote the Gelfand-Tsetlin tableau with $l_{ij}$ in the position of the vertex $(i,j)$ of $\mathfrak{V}$.






\begin{definition} Let $G$ be any graph, $T(L)$ any Gelfand-Tsetlin tableau, and ${\mathbb Z}_0^\frac{n(n+1)}{2}:=\{w\in {\mathbb Z}^\frac{n(n+1)}{2}\ : \ w_{n,i}=0 \text{ for any } 1\leq i\leq n\}$.


\begin{itemize}
\item[(i)] We say that \emph{$T(L)$ satisfies $G$} if
\begin{itemize}
\item[(a)] $l_{ij}-l_{rs}\in \mathbb{Z}_{\geq 0}$ whenever $(i,j)$ and $(r,s)$ are connected by a horizontal arrow  pointing right, or an arrow pointing down.
\item[(b)] $l_{ij}-l_{rs}\in \mathbb{Z}_{> 0}$ whenever $(i,j)$ and $(r,s)$ are connected by an arrow pointing up.
\end{itemize}
\item[(ii)] We say that \emph{$T(L)$ is a $G$-realization} if
\begin{itemize}
\item[(a)] $T(L)$ satisfies $G$.
\item[(b)]  For any $1\leq k\leq n-1$ we have, $l_{ki}-l_{kj}\in \mathbb{Z} $ only if $(k,i)$ and $(k,j)$ are in the same connected component of the unoriented graph associated with $G$. 
\end{itemize}

\item[(iii)] If $T(L)$ is a $G$-realization, by ${\mathcal B}_{G}(T(L))$ we denote the set of all $G$-realizations of the form $T(L+z)$, with $z\in {\mathbb Z}_0^\frac{n(n+1)}{2}$. Finally, by $V_{G}(T(L))$ we denote the complex vector space spanned by ${\mathcal B}_{G}(T(L))$.
\end{itemize}
\end{definition}
