\begin{theorem}\label{theo:graphadm}\cite[Theorem 4.33, and Theorem 5.8]{FRZ19}
For any relation graph $G$, and any $G$-realization $T(L)$, the vector space $V_{G}(T(L))$ has a structure of $\mathfrak{gl}(n)$-module, with the action of $\mathfrak{gl}(n)$ given by the Gelfand-Tsetlin formulas~\eqref{eq:GTformulas}. Moreover, $V_G(T(L))$ is a Gelfand-Tsetlin module with diagonalizable action of the generators of $\Gamma$, and $\dim(V_G(T(L))(\chi))=1$ for any  $\chi\in\Gamma^{*}$ in the support of $V_G(T(L))$.
\end{theorem}

\begin{definition}\label{def:relmod}
Modules isomorphic to $V_{G}(T(L))$ for some relation graph $G$ will be called \emph{relation modules}.
\end{definition}
