\begin{equation}\label{generictopologyweight}
Z_{\mathcal G} = \int d{\mathbf x}_0 \ldots d{\mathbf x}_{10}\,  
\left[\prod_{i=0}^{9} %W_0 
e^{-\frac{3\left({\mathbf x_{i+1}}-{\mathbf x_i}\right)^2}{2l_i\sigma}}\right]
\delta({\mathbf x}_1-{\mathbf x}_4)\,
\delta({\mathbf x}_1-{\mathbf x}_8)\,
\delta({\mathbf x}_2-{\mathbf x}_7)\,
\delta({\mathbf x}_3-{\mathbf x}_6)\,
\delta({\mathbf x}_5-{\mathbf x}_9).
\end{equation}
By applying the same methods used for the two-cluster configuration, this weight can also be written as
\begin{eqnarray}\label{generictopologyweight2}
Z_{\mathcal G} & = & Z_0 Z_9 \int d{\mathbf x}_1 d{\mathbf x}_{2} d{\mathbf x}_3 d{\mathbf x}_5\, e^{-\frac{3}{2\sigma} f({\mathbf x}_1, {\mathbf x}_2, {\mathbf x}_3, {\mathbf x}_5)}, 
\end{eqnarray}
where
\begin{eqnarray}
\label{equationf}
f({\mathbf x}_1, {\mathbf x}_2, {\mathbf x}_3, {\mathbf x}_5) & = &  
\left(\frac{1}{l_1}+\frac{1}{l_7}\right)\left({\mathbf x}_2-{\mathbf x}_1\right)^2+\left(\frac{1}{l_2}+\frac{1}{l_6}\right)\left({\mathbf x}_3-{\mathbf x}_2\right)^2+\frac{1}{l_3}\left({\mathbf x}_3-{\mathbf x}_1\right)^2 \\ \nonumber
& + & 
\frac{1}{l_5} {\left({\mathbf x}_5-{\mathbf x}_3\right)^2}+\left(\frac{1}{l_4}+\frac{1}{l_8}\right)\left({\mathbf x}_5-{\mathbf x}_1\right)^2 .
\end{eqnarray}

Similarly to the case of the monodisperse network~\cite{Bonato2024}, it is useful to introduce the following matrix, 
\begin{equation}
	A(\mathcal{G})=
	\begin{pmatrix}
		0 & \frac{1}{l_1}+\frac{1}{l_7} & \frac{1}{l_3} & \frac{1}{l_4}+\frac{1}{l_8} \\
		\frac{1}{l_1}+\frac{1}{l_7} & 0 & \frac{1}{l_2}+\frac{1}{l_6} & 0 \\
		\frac{1}{l_3} & \frac{1}{l_2}+\frac{1}{l_6} & 0 & \frac{1}{l_5} \\
        \frac{1}{l_4}+\frac{1}{l_8} & 0 & \frac{1}{l_5} & 0
	\end{pmatrix},
\end{equation}
which, if we define, in analogy with Eq.~(\ref{definitionL}), $L^{-1}_{i_1, \cdots, i_k}\equiv \sum_{j=1}^{k} \frac{1}{l_{i_j}}=\frac{k}{H_{i_1,\cdots, i_k}}$, can be written in a more compact form as 
\begin{equation}
	A(\mathcal{G})=
	\begin{pmatrix}
		0 & L^{-1}_{1, 7} & l^{-1}_{3} & L^{-1}_{4,8} \\
		L^{-1}_{1,7} & 0 & L^{-1}_{2,6} & 0 \\
		l^{-1}_{3} & L^{-1}_{2,6} & 0 & l^{-1}_{5} \\
        L^{-1}_{4,8} & 0 & l^{-1}_{5} & 0
	\end{pmatrix}.
\end{equation}
For the case where all $l_i$'s are equal, considered in~\cite{Bonato2024}, this matrix equals the adjacency 
matrix of the multigraph corresponding to $\mathcal{G}$.
Starting from $A(\mathcal{G})$, we define the related matrix
\begin{equation}
	B(\mathcal{G})=
	\begin{pmatrix}
		\Delta_1 & -L^{-1}_{1, 7} & -l^{-1}_{3} & -L^{-1}_{4,8} \\
		-L^{-1}_{1,7} & \Delta_2 & -L^{-1}_{2,6} & 0 \\
		-l^{-1}_{3} & -L^{-1}_{2,6} & \Delta_3 & -l^{-1}_{5} \\
        -L^{-1}_{4,8} & 0 & -l^{-1}_{5} & \Delta_4
	\end{pmatrix},
\end{equation}
where $\Delta_i$ equals the sum of the off-diagonal elements of the $i$-th row of the original matrix $A(\mathcal{G})$, so in our case
\begin{eqnarray}
    \Delta_1 & = & L^{-1}_{1, 7} + l^{-1}_{3} + L^{-1}_{4,8} \\ \nonumber
    \Delta_2 & = & L^{-1}_{1,7} + L^{-1}_{2,6} \\ \nonumber
    \Delta_3 & = & l^{-1}_{3} + L^{-1}_{2,6} + l^{-1}_{5} \\ \nonumber
    \Delta_4 & = & L^{-1}_{4,8} + l^{-1}_{5}.
\end{eqnarray}
This matrix can be used to write Eq.~(\ref{equationf}) as  
\begin{equation}
f({\mathbf x})={\mathbf{x}}^T B({\mathcal G}) {\mathbf{x}},
\end{equation}
where $\mathbf{x}^T=({\mathbf x}_1, {\mathbf x}_2,{\mathbf x}_3,{\mathbf x}_5)$. 

The topological weight of $\mathcal{G}$ can then be found by fixing  the position of the centre of mass of one of the clusters, and integrating over it, which gives
\begin{eqnarray}
Z_{\mathcal G} & = & Z_0 Z_9 {\bar{Z}}\,V\det(B'(\mathcal{G}))^{-3/2} 
\label{eq:ZG-det} \\ \nonumber
\bar{Z} & = & \left(\frac{2\pi \sigma}{3}\right)^{3/2 \, {\rm rk}(B'(\mathcal{G}))} 
\end{eqnarray}
where $B'(\mathcal{G})$ is any of the matrices obtained by removing the $i$-th row and column of $B(\mathcal{G})$ (this corresponds to integrating over the position of the centre of mass of the $i$-th cluster), and ${\rm rk}$ denotes the rank of a matrix (or, in this case equivalently, its dimension, which is $3$ in this example). 

We note that an alternative procedure to using the matrix $B'({\mathcal G})$ is to change variable to relative distances, by defining ${\mbox{\boldmath${\xi}$}}_i\equiv{\mathbf x}_{i+1}-{\mathbf x}_i$. In that case, instead of $B'({\mathcal G})$, the $3\times 3$ matrix of which we need to compute the determinant becomes
\begin{equation}
	\begin{pmatrix}
		L^{-1}_{1, 7}+l^{-1}_3+L^{-1}_{4,8} & l^{-1}_{3}+L^{-1}_{4,8} & L^{-1}_{4,8} \\
		l^{-1}_{3}+L^{-1}_{4,8} & L^{-1}_{2,6}+l^{-1}_3+L^{-1}_{4,8} & L^{-1}_{4,8} \\
		L^{-1}_{4,8} & L^{-1}_{4,8} & l^{-1}_5+L^{-1}_{4,8} 
	\end{pmatrix}.
\label{def_matrix_translation}
\end{equation}
It can be checked that the determinant of this matrix is the same as that of $B'({\mathcal G})$.

By applying the procedure outlined in this Section to a generic graph ${\mathcal G}$ with $n$ TUs and $k$ clusters, its topological weight can be computed, for example, by building the matrices $A({\mathcal G})$, $B({\mathcal G})$ and $B'({\mathcal G})$ as done in the example above. 

