\hline
$V_4$&$\Vp(\lambda_iT_{01}^2\wh T_0^{2m_0} - T_{11}^2\wh T_1^{2m_1}-T_{i1}\wh T_2^{l_i},2\leq i\leq k)\vphantom{\int\limits_a^b}$\\
\hline
$V_5$&$\Vp(\lambda_iT_{01}^2\wh T_0^{2m_0}+T_{11}^2\wh T_1^{2m_1}+T_{i1}^2\wh T_i^{2m_i},2\leq i\leq k)\vphantom{\int\limits_a^b}$\\
\hline
\end{tabular}
\end{center}
\label{def_V}Our main result can be formulated as follows.
\mtheo{\label{thm:flex_V}Trinomial varieties of types $V_1$\textup, $V_3$ and $V_4$ are flexible.}
