\sect{Auxiliary lemmas} \label{Proofs}

In this section, we prove three lemmas, which will be used in the next section in the proof of the main result. First, we need to define certain LNDs of the special form.

\cons{\label{rmk:lnds_X}Let
\begin{equation*}
X\colon
\begin{cases}
\lambda_2T_0^{l_0} + T_1^{l_1}-T_2^{l_2}=0,\\
\lambda_3T_0^{l_0} + T_1^{l_1}-T_3^{l_3}=0,\\
\ldots,\\
\lambda_kT_0^{l_0} + T_1^{l_1}-T_k^{l_k}=0.
\end{cases}
\end{equation*}
be a trinomial variety. Suppose that for each $i$ from $2$ to $k$ there exists a number $j_i\in\{1,\ldots,n_i\}$ such that $l_{ij_i}=1$; denote $J=\{j_2,\ldots,j_k\}$. Then for every $p \in \{0,1\}$ and $j_p \in \{1,2,\ldots,n_p\}$ we can define the LNDs $\gamma_{pj_p}^J$ by
\begin{equation*}
\begin{split}
\gamma_{pj_p}^J(T_{pj_p}) &= \prod_{i=2}^k\frac{\dd T_i^{l_i}}{\dd T_{ij_i}},~\gamma_{pj_p}^J(T_{mj_m})
= \frac{\dd T_p^{l_p}}{\dd T_{pj_p}}\prod_{i\in\{2,\ldots k\}\setminus\{m\}}\frac{\dd T_i^{l_i}}{\dd T_{ij_i}} \\
\end{split}
\end{equation*}
for $m=2,\ldots,k$, while $\gamma_{pj_p}^J(T_{ij}) = 0$ for all other pairs of indices $i,j.$ For any $s\in\Kp$, denote $\tau_{pj_p}^J(s) = \exp(s\gamma_{pj_p}^J).$
}

\lemmp{\label{lemm:move_points}Let 
\begin{equation*}
X\colon
\begin{cases}
\lambda_2T_0^{l_0} + T_1^{l_1}-T_2^{l_2}=0,\\
\lambda_3T_0^{l_0} + T_1^{l_1}-T_3^{l_3}=0,\\
\ldots,\\
\lambda_kT_0^{l_0} + T_1^{l_1}-T_k^{l_k}=0,
\end{cases}
\end{equation*}
be a trinomial variety satisfying the conditions of Remark~\textup{\ref{rmk:lnds_X}}. Pick points $P,Q \in X^\reg$. If $\gamma_{ij_i}^J(T_{pj_p})(P) \neq 0$ for some $p \in \{0,1\}$ and $j_p\in\{1,\ldots,n_p\}$ then there exists $s_{ij_i} \in \Kp$ such that $$T_{ij_i}(\tau_{ij_i}^J(s_{ij_i})(P))=T_{ij_i}(Q).$$}
{
We will prove only the case $i =p$, because other cases can be proved similarly.
Since
\begin{equation*}
\tau_{pj_p}^J(s)(T_{pj_p})= T_{pj_p} + s\prod_{i=2}^k\frac{\dd T_i^{l_i}}{\dd T_{ij_i}}\text{ and }\gamma_{pj_p}^J(T_{pj_p})(P)= \prod_{i=2}^k\frac{\dd T_i^{l_i}}{\dd T_{ij_i}} \neq 0,
\end{equation*}
we can put $$s_{pj_p} = \frac{T_{pj_p}(Q)-T_{pj_p}(P)}{\gamma_{pj_p}^J(T_{pj_p})(P)},~R =  \tau_{pj_p}^J(s_{pj_p})(P).$$ Note that, for every $j\in\{1,\ldots,n_p\}\setminus\{j_p\},$ one has $T_{pj_p}(R) = T_{pj_p}(P)$, while $T_{pj_p}(R) = T_{pj_p}(Q)$, as required.
}

\lemmp{\label{lemm:transit_X_C}
Suppose 
\begin{equation*}
X\colon
\begin{cases}
\lambda_2T_0^{l_0} + T_1^{l_1}-T_{21}\wh T_2^{l_2}=0,\\
\lambda_3T_0^{l_0} + T_1^{l_1}-T_{31}\wh T_3^{l_3}=0,\\
\ldots,\\
\lambda_kT_0^{l_0} + T_1^{l_1}-T_{k1}\wh T_k^{l_k}=0.\\
\end{cases}
\end{equation*}
Pick a set of nonzero scalars 
$$C = \{c_{ij}\in\Kp^{\times}\mid2\leq i \leq k,~2\leq j \leq n_i\}.$$ Put $$X_C = \Vp (T_{ij}-c_{ij},2\leq i \leq k,~2\leq j \leq n_i) \cap X.$$ Then $\SAut(X)$ acts on $X_C$ transitively.
}
{
Set $J=\{1,\ldots,1\}$ and recall the notion $\gamma_{pj_p}^1=\gamma_{pj_p}^J$,
Let $P,~Q \in X_C$. Note that

$$\prod_{i=2}^k\wh T_i^{l_i}(P)=\prod_{i=2}^k\wh T_i^{l_i}(Q) \neq 0.$$

By Lemma~\ref{lemm:move_points}, for each $p\in \{0,1\}$ and $j_p=1,\ldots,n_p$, there exists $s_{pj_p}$ such that 
$$T_{pj_p}(R) = T_{pj_p}(Q)\text{ for } R=\tau_{pj_p}^1(s_{pj_p})(P),$$
while if $j\in\{1,\ldots,n_p\}\setminus\{j_p\}$ then $T_{pj_p}(R) = T_{pj_p}(P)$. Starting from~$P$, for every $p \in \{0,1\}$ and $j_p \in \{1,2,\ldots,n_p\}$  we apply the automorphisms $\tau_{pj_p}^1(s_{pj_p})$ step by step to reach a point $S$ such that $T_{pj_p}(S) = T_{pj_p}(Q)$ for every $p$ and $j_p$. Hence,
$$
T_{i1}(S) = \frac{\lambda_iT_0^{l_0}(S)+T_1^{l_1}(S)}{\prod_{i=1}^k\wh T_i^{l_i}(S)} = \frac{\lambda_iT_0^{l_0}(Q)+T_1^{l_1}(Q)}{\prod_{i=1}^k\wh T_i^{l_i}(Q)} = T_{i1}(Q).
$$
Therefore, $S = Q,$ and $P,~Q$ are in the same $\SAut(X)$-orbit, as required.
}

\sect{The main result: proofs} \label{sect:flexible}
\begin{comment}
Now we can introduce some special types of trinomial varieties, which we denote $V_1,V_2,V_3.$
The definition is as follows.

\begin{equation*}
V_1\colon
