\\
T_0^{l_0} + \lambda_3T_1^{l_1}-T_3^1=0,
\\\ldots,\\
T_0^{l_0} + \lambda_kT_1^{l_1}-T_k^1=0.
\end{cases}
\end{equation*}

\begin{equation*}
V_3\colon
\begin{cases}
T_{01}\wh T_0^{l_0} + \lambda_2T_1^{l_1}-T_{21}\wh T_2^{l_2}=0,
\\
T_{01}\wh T_0^{l_0} + \lambda_3T_1^{l_1}-T_{31}\wh T_3^{l_3}=0,
\\\ldots,\\
T_{01}\wh T_0^{l_0} + \lambda_kT_1^{l_1}-T_{k1}\wh T_k^{l_k}=0.
\end{cases}
\end{equation*}
\begin{equation*}
V_4\colon
\begin{cases}
T_{01}^2\wh T_0^{2m_0} - \lambda_2T_{11}^2\wh T_1^{2m_1}-T_{21}\wh T_2^{l_2}=0,
\\
T_{01}^2\wh T_0^{2m_0} - \lambda_3T_{11}^2\wh T_1^{2m_1}-T_{31}\wh T_3^{l_3}=0,
\\\ldots,\\
T_{01}^2\wh T_0^{2m_0} - \lambda_kT_{11}^2\wh T_1^{2m_1}-T_{k1}\wh T_k^{l_k}=0,
\end{cases}
\end{equation*}
where $T_i^1=T_{i1}T_{i2}\ldots T_{in_i},\wh T_i^{2m_i}=T_{i2}^{2m_{i2}}T_{i3}^{2m_{i3}}\ldots T_{in_i}^{2m_{in_i}},\wh T_i^{l_i}=T_{i2}^{l_{i2}}T_{i3}^{l_{i3}}\ldots T_{in_i}^{l_{in_i}}.$
\end{comment}

This section is devoted to the proof of Theorem~\ref{thm:flex_V}. We will consider the types subsequently. In each type we will check, that the group $\SAut(X)$ acts transitively on regular locus $X^\reg$ of the trinomial variety $X$.

\textit{\textbf{Type}} $V_1$. Suppose $P \in X^\reg$ is such that there exist $p \in \{0,1\}$ and $j_p \in \{1,2,\ldots,n_p\}$ and $\wh J = \{j_3,\ldots,j_k\}$ for which we have 
$$
\prod_{i=3}^k\frac{\dd T_i^{1}}{\dd T_{ij_i}}(P) \neq 0, \frac{\dd T_p^{l_p}}{\dd T_{pj_p}}(P) \neq 0.
$$
Suppose also that a point $Q \in X^\reg$ satisfies $T_{ij}(Q) \neq 0$ for all $i =3,\ldots ,k$ and $j=2,\ldots,n_i.$ By Lemma~\ref{lemm:move_points} for each $m = 2,\ldots,n_2$ there exists $s_{2m}\in\Kp$ such that $\widetilde P = t_{pj_p}^J(s_{2m})(P)$ and $T_{2m}(\widetilde P)=T_{2m}(Q)$. After subsequent applications of $\tau_{pj_p}^J(s_{2m})$ we obtain a point $S$ from the $\SAut(X)$-orbit of $P$ with $T_{2m}(S) = T_{2m}(Q)\neq 0$ for each $m$ from 2 to $n_2$. Since 
$$
\frac{\dd T_2^{1}}{\dd T_{21}}(S) \neq 0,
$$
we can interchange the first and the second equations, put $j_3=1$ and  $\wh J=\{j_3,\ldots,j_k\}$ and build a similar sequence, etc. Then we obtain a point $\widetilde S$ such that $T_{ij}(\widetilde S)=T_{ij}(Q)$ for every $i=2,\ldots,k$ and $j=2,\ldots,n_i.$ By Lemma~\ref{lemm:transit_X_C}, the points $\widetilde S,~Q$ belong to the same $\SAut(X)$-orbit.

Now, pick a point $R\in X^\reg$.  If $T_{pj_p}(R)=0$ for each $p\in\{0,1\}$ and $j_p\in\{1,\ldots,n_p\}$ then there exists $J =\{j_2,\ldots,j_k\}$ such that
$$
\prod_{i=2}^k\frac{\dd T_i^{1}}{\dd T_{ij_i}}(R) \neq 0,
$$
because the point $R$ is regular. Applying, if necessary, the LND $\gamma_{pj_p}^J$ for each $p\in\{0,1\}$ and $j_p\in\{1,\ldots,n_p\}$ and Lemma~\ref{lemm:move_points}, we can assume without loss of generality that $T_{pj_p}\neq 0$ for every $p$ and $j_p$. Then we are in the case when $R,~Q$ are in the same $\SAut(X)$-orbit. 

Finally, suppose that there exist $m$, $t$ such that $T_{m}^{l_m}(R)=T_{t}^{l_t}(R)=0$. Without loss of generality we can assume that $m=2$, $t=3$. Clearly, $T_0^{l_0}(P)=T_1^{l_1}(P)=0$. Since $R\in X^\reg$, there exist $j_0\in\{1,\ldots,n_0\}$ with $l_{0j_0}=1,~j_1\in\{1,\ldots,n_1\}$ with $l_{1j_1}=1$ and $~\wh J=\{j_4,\ldots,j_k\} $ such that
$$
\frac{\dd T_0^{l_0}}{\dd T_{0j_0}}(R)\neq 0,~\frac{\dd T_1^{l_1}}{\dd T_{1j_1}}(R)\neq 0,~\frac{\dd T_i^{1}}{\dd T_{ij_i}}(R)\neq 0.
$$
For $j_3\in\{1,\ldots,n_3\}$, define the LND $\delta_{j_3}$ of $\Kp[X]$ by putting
\begin{equation*}
\begin{split}
\delta_{j_3}(T_{0l_0})&= \frac{\dd T_1^{l_1}}{\dd T_{1j_1}}\prod_{i=3}^k\frac{\dd T_i^{1}}{\dd T_{ij_i}},~
\delta_{j_3}(T_{1l_1})= -\lambda_2\frac{\dd T_0^{l_0}}{\dd T_{0j_0}}\prod_{i=3}^k\frac{\dd T_i^{1}}{\dd T_{ij_i}},\\
\delta_{j_3}(T_{mj_m})&= (\lambda_m-\lambda_2)\frac{\dd T_0^{l_0}}{\dd T_{0j_0}}\frac{\dd T_1^{l_1}}{\dd T_{1j_1}}\prod_{i\neq 2,m}\frac{\dd T_i^{1}}{\dd T_{ij_i}},
\end{split}
\end{equation*}
and $\delta_{j_3}(T_{ij})=0$ for all other pairs of indices $i,j.$ For any $s\in\Kp$ put $\psi_{j_2}(s)=\exp(s\delta_{j_3})$. Since
\begin{equation*}
\begin{split}
&\psi_{j_3}(T_{3j_3}) = T_{3j_3} + s(\lambda_3-\lambda_2)\frac{\dd T_0^{l_0}}{\dd T_{0j_0}}\frac{\dd T_1^{l_1}}{\dd T_{1j_1}}\prod_{i\neq 2,3}\frac{\dd T_i^{1}}{\dd T_{ij_i}},\\
&(\lambda_3-\lambda_2)\frac{\dd T_0^{l_0}}{\dd T_{0j_0}}\frac{\dd T_1^{l_1}}{\dd T_{1j_1}}\prod_{i\neq 2,3}\frac{\dd T_i^{1}}{\dd T_{ij_i}}(R)\neq0,
\end{split}
\end{equation*}
we can find $s_{j_3}\in\Kp$ such that $T_{3j_3}(\psi_{j_3}(R))\neq 0$. By subsequent applying of $\psi_1,\psi_2,\ldots,\psi_{n_3}$ to the point $R$ we reduce the problem to the previous cases.

\textit{\textbf{Type}} $V_3$. Suppose $P\in X^\reg$ is such that $\wh T_{0}^{l_{0}}(P) \neq 0$ and for $i=3,\ldots,k$ one has $\wh T_{i}^{l_{i}}(P)\neq 0$.
Suppose also that a point $Q \in X^\reg$ satisfies $T_{ij}(Q) \neq 0$ for all $i =3,\ldots ,k$ and $j=2,\ldots,n_i$. By Lemma~\ref{lemm:move_points} for each $m = 2,\ldots,n_2$ there exists $s_{2m}\in\Kp$ such that $\widetilde P = t_{pj_p}^J(s_{2m})(P)$ and $T_{2m}(\widetilde P)=T_{2m}(Q)$. After subsequent applications of $\tau_{pj_p}^J(s_{2m})$ we obtain a point $S$ from the $\SAut(X)$-orbit of $P$ with $T_{2m}(S) = T_{2m}(Q)\neq 0$ for each $m$ from 2 to $n_2$. Since 
$$
\frac{\dd T_2^{l_2}}{\dd T_{21}}(S) \neq 0,
$$
we can interchange the first and the second equations, put $j_3=1$ and  $\wh J=\{j_3,\ldots,j_k\}$ and build a similar sequence, etc. Then we obtain a point $\widetilde S$ such that $T_{ij}(\widetilde S)=T_{ij}(Q)$ for every $i=2,\ldots,k$ and $j=2,\ldots,n_i.$ By Lemma~\ref{lemm:transit_X_C}, the points $\widetilde S,~Q$ belong to the same $\SAut(X)$-orbit.

Now, pick a point $R\in X^\reg.$ Assume that $\wh T_{0}^{l_{0}}(R) = 0$ and for each $i=2,\ldots,k$ one has \break$\wh T_{i}^{l_{i}}(R)\neq 0$. We can use LND $\gamma_{0j_0}^1$ and Lemma~\ref{lemm:move_points} to make $\wh T_{0}^{l_{0}}(R)$ be non zero, so we are in the previous case. 
If $\wh T_{0}^{l_{0}}(R) = 0$ and there exists $i=2,\ldots,k$ such that $\wh T_{i}^{l_{i}}(R) = 0$ then either there exist $i$ and $j_i$ such that $l_{ij_i} = 1$ or there exists $j_1$ such that $l_{1j_1} = 1$. In the case $l_{ij_i} = 1$ we can interchange $T_{ij_i}$ and $T_{i0}$ and use a similar line of reasoning. For the case $l_{1j_1} = 1$, we can use $\gamma_{1j_1}^1$ and Lemma~\ref{lemm:move_points} to make $\wh T_{i}^{l_{i}}(R)$ be non zero, so we are again in the previous case.

Finally, suppose that there exist $m$, $t$ such that $T_{m}^{l_m}(R)=T_{t}^{l_t}(R)=0$. Without loss of generality we can assume that $m=2$, $t=3$. Clearly, $T_{00}T_0^{l_0}(P)=T_1^{l_1}(P)=0$. Since $R\in X^\reg$, there exist $j_0\in\{1,\ldots,n_0\}$ with $l_{0j_0}=1,~j_1\in\{1,\ldots,n_1\}$ with $l_{1j_1}=1$ and $~\wh J=\{j_4,\ldots,j_k\} $ such that
$$
\frac{\dd T_0^{l_0}}{\dd T_{0j_0}}(R)\neq 0,~\frac{\dd T_1^{l_1}}{\dd T_{1j_1}}(R)\neq 0,~\frac{\dd T_i^{l_i}}{\dd T_{ij_i}}(R)\neq 0.
$$
For $j_3\in\{1,\ldots,n_3\}$, define the LND $\delta_{j_3}$ of $\Kp[X]$ by
$$
\delta_{j_3}(T_{0l_0}) = \frac{\dd T_1^{l_1}}{\dd T_{1j_1}}\prod_{i=3}^k\frac{\dd T_i^{l_i}}{\dd T_{ij_i}},~ 
\delta_{j_3}(T_{1l_1}) = -\lambda_2\frac{\dd T_0^{l_0}}{\dd T_{0j_0}}\prod_{i=3}^k\frac{\dd T_i^{l_i}}{\dd T_{ij_i}},$$
$$
\delta_{j_3}(T_{mj_m}) = (\lambda_m-\lambda_2)\frac{\dd T_0^{l_0}}{\dd T_{0j_0}}\frac{\dd T_1^{l_1}}{\dd T_{1j_1}}\prod_{i\neq 2,m}\frac{\dd T_i^{l_i}}{\dd T_{ij_i}},$$
and $\delta_{j_3}(T_{ij})=0$ for all other pairs of indices $i,j.$ For any $s\in\Kp$ put $\psi_{j_2}(s)=\exp(s\delta_{j_3})$. Since
\begin{equation*}
\begin{split}
&\psi_{j_3}(T_{3j_3}) = T_{3j_3} + s(\lambda_3-\lambda_2)\frac{\dd T_0^{l_0}}{\dd T_{0j_0}}\frac{\dd T_1^{l_1}}{\dd T_{1j_1}}\prod_{i\neq 2,3}\frac{\dd T_i^{l_i}}{\dd T_{ij_i}},\\
&(\lambda_3-\lambda_2)\frac{\dd T_0^{l_0}}{\dd T_{0j_0}}\frac{\dd T_1^{l_1}}{\dd T_{1j_1}}\prod_{i\neq 2,3}\frac{\dd T_i^{l_i}}{\dd T_{ij_i}}(R)\neq0,
\end{split}
\end{equation*}
we can find $s_{j_3}\in\Kp$ such that $T_{3j_3}(\psi_{j_3}(R))\neq 0$. By subsequent applying of $\psi_1,\psi_2,\ldots,\psi_{n_3}$ to the point $R$ we reduce the problem to the previous cases.

\textit{\textbf{Type}} $V_4$. 
Put 
$$\sqrt{T_0^{2m_0}}=T_{01}\wh T_0^{m_0},~\sqrt{T_1^{2m_1}}=T_{11}\wh T_1^{m_1}.$$ 
Denote $\alpha_i=\sqrt{\lambda_iT_0^{2m_0}}+\sqrt{T_1^{2m_1}}$ and $\beta_i=\sqrt{\lambda_iT_0^{2m_0}}-\sqrt{T_1^{2m_1}}$.
For each vector $J =(j_2,\ldots,j_k)$, $j_i\in\{1,\ldots,n_i\},$ we denote by $\delta_{+}^J$ and $\delta_{-}^J$ two LND's of $\Kp[X]$ given by the formulas
\begin{equation*}
\begin{split}
\delta_{\pm}^J(T_{01})&= \frac{\sqrt{T_1^{2m_1}}}{T_{11}}\prod_{i=2}^k\frac{\dd T_i^{l_i}}{\dd T_{ij_i}} ,~
\delta_{\pm}^J(T_{11})= \mp\frac{\sqrt{T_0^{2m_0}}}{T_{01}}\prod_{i=2}^k\frac{\dd T_i^{l_i}}{\dd T_{ij_i}} ,\\
\delta_{\pm}^J(T_{ij_i})&= (1\pm\sqrt{\lambda_i})\frac{\sqrt{T_0^{2m_0}}}{T_{01}}\frac{\sqrt{T_1^{2m_1}}}{T_{11}}(\sqrt{T_0^{2m_0}}\pm \sqrt{\lambda_i}\sqrt{T_1^{2m_1}})\\
&\times\prod_{s\neq i}\frac{\dd T_s^{l_s}}{\dd T_{sj_s}}\text{ for all }i=2,\ldots,k,\\
\end{split}
\end{equation*}
and $\delta_+^J(T_{ij})=\delta_-^J(T_{ij})=0$ for all other $i,j.$ 

Suppose $Q\in X^\reg$ is such that, for $i=3,\ldots,k$, one has $\wh T_{i}^{l_{i}}(Q)\neq 0$ and $\alpha_i(Q)\neq 0$. Note that if there exists $i=2,\ldots,k$ for which $\alpha_i(Q)\neq0$ or $\beta_i(Q)\neq0$, then for all $i=2,\ldots,k$ we have $\alpha_i(Q)\neq0$ or $\beta_i(Q)\neq0$. Pick also a point $P\in X^\reg$ such that, for $i=2,\ldots,k$, one has $\wh T_{i}^{l_{i}}(P)\neq 0.$ Now, we can use the exponents of the LND's defined in Remark~\ref{rmk:lnds_X} to move the point $P$ to a point $\widetilde P\in X^\reg$ such that $\alpha_i(\widetilde P)=\alpha_i(Q)\neq0$ for all $i$ from 2 to $k$. Then for each $j_2=2,\ldots,n_i$, using a composition of $\exp(s_{j_2}\delta_+^J)$, where $J=(j_2,1,\ldots,1)$, we can obtain a point $R\in X^\reg$ such that $T_{2j_2}(P)=T_{2j_2}(Q)$. Those, we are in the case of Lemma~\ref{lemm:transit_X_C}, so $P$ and $Q$ are in the same $\SAut(X)$-orbit, as required.


Next, suppose that for a point $P\in X^\reg$ there exists $i=2,\ldots,k$, such that $\wh T_{i}^{l_{i}}(P)=0.$ We may assume without loss of generality that $i=2$. Then, since $P$ is a regular point of $X$, at least one of the following conditions is satisfied: there exists $j_2=1,\ldots,n_2$ such that $l_{2j_2}=1$ and $\dfrac{\dd T_2^{l_2}}{\dd T_{2j_2}}(P)\neq 0$, or $\alpha_2(P)\neq0$, or $\beta_2(P)\neq0$. In the first case we can interchange $T_{2j_2}$ and $T_{21}$. Using a reasoning same to the previous paragraph, we  obtain that the points $P$ and $Q$ are in the same $\SAut(X)$-orbit. The second and the third cases can be proved completely similarly, so we will prove only the case with $\alpha_i(P)\neq 0$. Here, for each $j_2=2,\ldots,n_i$, using a composition of $\exp(s_{j_2}\delta_+^J)$, where $J=(j_2,1,\ldots,1)$, we obtain a point $R\in X^\reg$ such that $T_{2j_2}(R)\neq0$, and thus we are in the previous case.

%\nota{Note that this theorem gives us just sufficient conditions, but not a criterion for a trinomial variety to be flexible.}

\exam{\label{ex:V1-V5}i) The variety
\begin{equation*}
X\colon
\begin{cases}
T_{01}^5T_{02}^4+T_{11}T_{12}^7-T_{21}T_{22}^8T_{23}=0,\\
2T_{01}^5T_{02}^4+T_{11}T_{12}^7-T_{31}T_{32}^2T_{33}^4=0,
\end{cases}
\end{equation*}
is flexible, because it is of type $V_3$.

ii) The variety defined by formula (\ref{formula:TV_V_4}) in Example~\ref{exam:trinomial_varieties} (iii) is flexible, because it belongs to type $V_4$.

iii) The trinomial hypersurface
$$T_{01}^3+T_{11}^5+T_{21}T_{22}T_{23}^2=0,$$
as well as the trinomial variety
\begin{equation}
X\colon
\begin{cases}
\lambda_2T_0^2+T_1^2-T_2^{l_2}=0,\\
\lambda_3T_0^2+T_1^2-T_{31}\wh T_3^{l_3}=0,\\
\ldots,\\
\lambda_kT_0^2+T_1^2-T_{k1}\wh T_k^{l_k}=0,
\end{cases}
\label{ex:unknown}
\end{equation}
where the tuple $l_2$ does not contain $1$,
do not belong to the types under consideration, and, in fact, we do not know if they are flexible or not.}

\sect{Concluding remarks} \label{sect:rigid}

It was proved in the previous section that trinomial varieties of types $V_1$, $V_3$ and $V_4$ are flexible. At the contrary, trinomial varieties of type $V_5$ are not flexible, while trinomial varieties of type $V_2$ are not flexible under some restriction, and we can not prove that they are not flexible without this restriction. To prove this, we recall the notion of rigidity: a variety is called rigid if it does not admit non-trivial $\Ga$-actions. In \cite{EvdokimovaGaifullinShafarevich23}, for a trinomial variety, a criterion to be rigid was proved.

\mtheo{\textup{\cite[Theorem 1]{EvdokimovaGaifullinShafarevich23}}
Let $X$ be a trinomial variety of Type \textup{1}. Then $X$ is not rigid if and only if one of the following holds\textup{:}
\newline\textup{1)} $m > 0$\textup;
\newline\textup{2)} there is $b \in \{1,\ldots,r\}$ such that for each $$i \in \{1,\ldots,r\}\setminus\{b\}$$ there is $j(i)\in\{1,\ldots,n_i\}$ with $l_{ij(i)} = 1.$
}
\mtheo{\label{thm:rig_t2}\textup{\cite[Theorem 3]{EvdokimovaGaifullinShafarevich23}}
Let $X$ be a trinomial variety of Type \textup2. Then $X$ is not rigid if and only if one of the following holds\textup{:}
\newline\textup{1)} $m > 0$\textup{;}
\newline\textup{2)} there are at most two numbers $a,b \in \{0,\ldots,r\}$ such that for each $$i \in \{0,\ldots,r\}\setminus\{a,b\}$$ there is $j(i)\in\{1,\ldots,n_i\}$ such that $l_{ij(i)} = 1$\textup{;}
\newline\textup{3)} there are exactly three numbers $a,b,c\in \{0,\ldots,r\}$ such that for each $i \in \{a,b\}$ there is\break $j(i)\in \{1,\ldots,n_i\}$ with $l_{ij(i)}=2$ and the numbers $l_{ik}$ are even for all $k\in\{1,\ldots,n_i\}$. Moreover\textup{,} for each $i \in \{0,\ldots,r\}\setminus\{a,b,c\}$\textup{,} there is $j(i) \in \{1,\ldots,n_i\}$ with $l_{ij(i)} = 1.$
}
