m = [2,1,1];

# defining variables and polynomial ring
r = [var('r_%d' % i) for i in (1..len(m))];
R = PolynomialRing(ZZ, names=r);
S.<x> = PolynomialRing(R);

# defining f and its tolerant
f = prod([(x-r[i])^m[i] for i in range(len(m))]);
tol_factors = [];
tol_degree = 0;
for i in range(len(m)):
    for j in range(i+1,len(m)):
        tol_factors.append((r[i]-r[j])^(2*m[i]*m[j]));
        tol_degree += 2*m[i]*m[j];
tol = prod(tol_factors);

# constructing list of possible monomials for the
# chosen partition
coef = f.list(x);
deg = [sum(m)-i for i in range(sum(m))];
weights = list(WeightedIntegerVectors(tol_degree,deg));
vec = [];
for w in weights:
    vec.append(prod([coef[i]^w[i]\
                     for i in range(len(w))]));

# constructing matrix M of integer coefficients
# of monomials in roots for each monomial in
# coefficients of f
mon_degs = list(WeightedIntegerVectors(tol_degree,\
                [1 for i in range(len(m))]));
M = [];
for i in range(len(weights)):
    v = [];
    for degs in mon_degs:
        v.append(vec[i].expand().coefficient(\
                 prod([r[j]^degs[j]\
                 for j in range(len(m))])));
    M.append(v);
M = matrix(M);

# constructing matrix B of integer coefficients
# of monomials in roots of tol(f)
B = matrix([tol.expand().coefficient(\
            prod([r[i]^degs[i]\
            for i in range(len(m))])) \
            for degs in mon_degs]);

# solve XM = B and output monomials (by their
# exponent vectors) and integer coefficients
X = M.solve_left(B);
print('exponents of [a_0,a_1,...,a_n]','coefficient')
for i in range(len(weights)):
    homogen = 2*sum(m)-2-sum(weights[i]);
    if homogen >= 0:
        w = [x for x in weights[i]];
        w.append(homogen);
