%{A'} & {B}
%\arrow["{p'}", shift left, from=1-1, to=1-2]
%\arrow["{s'}", shift left, from=1-2, to=1-1]
%\end{tikzcd}\] 
%in $\bV_1$ and an isomorphism $\sigma\colon U(A')\rightarrow A$ such that the following diagram in $\bV$ 
%\[\begin{tikzcd}
%{U(A')} & {} & A \\
%& {U(B)}
%\arrow["\sigma", from=1-1, to=1-3]
%\arrow["{U(p')}"', shift right, from=1-1, to=2-2]
%\arrow["p"', from=1-3, to=2-2]
%\arrow["{U(s')}"'{pos=0.3}, shift right, from=2-2, to=1-1]
%\arrow["s"', shift right=2, from=2-2, %to=1-3]
%\end{tikzcd}\]
%is commutative.
\end{proposition}

\begin{proof}
Let $\xi \colon U(B) \flat X \rightarrow X$ be a coherent action and let 
\begin{equation*}
\begin{tikzcd}
X \arrow [r, "k"]
& A \arrow[r, shift left, "p"] &
U(B) \ar[l, shift left, "s"]
\end{tikzcd}
\end{equation*}
be the split extension associated with $\xi$. Since $\xi$ is coherent, there exists a morphism
\[
f \colon U(\bF \ltimes X) \rightarrow A
\]
such that the following diagram in $\bV$ 
\begin{equation*}
\begin{tikzcd}
X \arrow [r, "\eta_{X}"] \ar[d, equal]
&U(\bF \ltimes X) \arrow[r, shift left, "U(\tau)"] \ar[d, dashed, "f"]&
U(\bF) \ar[l, shift left, "U(\iota)"]\ar[d, "U(\iota)"]\\
X \arrow [r, "k"]
& A \arrow[r, shift left, "p"] &
U(B) \ar[l, shift left, "s"]
\end{tikzcd}
\end{equation*}
is commutative. Protomodularity implies that $f$ is the unique arrow induced by $\id_X$ and $U(\iota)$, i.e., $f(\alpha,x)=s(\alpha 1_B) + k(x)$ for every $(\alpha,x) \in \bF \ltimes X$. 

We observe that $A$ is a unital algebra with unit $s(1_B)$. Indeed, every $a \in A$ may be written  as $s(b)+k(x)$, for some $b \in B$ and $x \in X$, and
\[
s(1_B)a=s(1_B)((s(b)+k(x))=s(1_B)s(b)+s(1_B)k(x)=s(b)+s(1_B)k(x)=a
\]
since
\[
s(1_B)k(x)=f(1,0)f(0,x)=f((1,0)\cdot(0,x))=f(0,x)=k(x).
\]
In a similar way, one may check that $as(1_B)=a$. Hence, we proved that the split epimorphism in $\bV$ associated with $\xi$
\[\begin{tikzcd}
{A} & {U(B)}
\arrow["{p}", shift left, from=1-1, to=1-2]
\arrow["{s}", shift left, from=1-2, to=1-1]
\end{tikzcd}\] 
is actually a split epimorphism in $\bV_1$, since $A$ is a unital algebra and both $p$ and $s$ preserve the units. Finally, the isomorphism $\sigma$ of \Cref{def_ideal} is the identity map~$\id_A$ and we can conclude that $\xi$ is an ideal action.
\end{proof}

This allows us to state the following.

\begin{theorem}\label{char_algebras}
Let $\bV$ be a unit-closed variety of non-associative algebras and consider the ideally exact context \eqref{eq:situation_alg}. Let
\[
\xi\colon U(B)\flat X\rightarrow X
\]
be a relative $U$-action with associated split epimorphism 
\[\begin{tikzcd}
{A} & {U(B).}
\arrow["{p}", shift left, from=1-1, to=1-2]
\arrow["{s}", shift left, from=1-2, to=1-1]
\end{tikzcd}\] 
Then $\xi$ is a coherent action if and only if $A$ is a unital algebra and $s(1_B)=1_A$.
\end{theorem}

\begin{proof}
If $\xi$ is a coherent action, then by \Cref{conv_algebras} $A$ is a unital algebra and $s(1_B)=1_A$. Conversely, if $A$ is a unital algebra and $s(1_B)=1_A$, then 
\[
p(1_A)=p(s(1_B))=(p \circ s)(1_B)=1_B
\]
and the unique morphism $f \colon U(\bF \ltimes X) \rightarrow A$ induced by $\id_X$ and $U(\iota) \colon U(\bF) \rightarrow U(B)$ makes the following a split pullback diagram:
\[\begin{tikzcd}
{U(\bF \ltimes X)} & {U(\bF)} \\
A & {U(B).}
\arrow["{UF(\tau)}", shift left, from=1-1, to=1-2]
\arrow["f"', from=1-1, to=2-1]
\arrow["{UF(\iota)}", shift left, from=1-2, to=1-1]
\arrow["{U(\iota)}", from=1-2, to=2-2]
\arrow["p", shift left, from=2-1, to=2-2]
\arrow["s", shift left, from=2-2, to=2-1]
\end{tikzcd}\]
Thus, $\xi$ is a coherent action.
\end{proof}

\begin{remark}
The condition $s(1_B)=1_A$ automatically implies that the pair $(p,s)$ is a split epimorphism in the ideally exact category $\bV_1$.
\end{remark}

