\subsection{Varieties of hoops, MV-algebras and product algebras}\label{MV}

The algebraic structure now known as a \emph{hoop} was first introduced by B.~Bosbach in~\cite{bosbach1,bosbach2}, where it appeared under the name \emph{complementary semigroups} (\emph{komplementäre Halbgruppen}). The term hoop itself was later coined in an unpublished manuscript by J.~R.~Büchi and T.~M.~Owens~\cite{BuchiOwens}, and has since become standard in the literature on substructural logics and residuated structures.  We refer the reader to \cite{hoop} for more details about the structures of hoops.

In this section, we investigate the notion of coherent actions in some varieties of hoops. We aim to prove that the variety of \emph{Wajsberg hoops} and that of \emph{product hoops} define two BAT ideally exact contexts.

\begin{definition}
A \emph{hoop} is an algebra $H=(H, \cdot, \w, 1)$ of type $(2,2,0)$ such that
\begin{enumerate}
\item[(H1)] $(H,\cdot, 1)$ is a commutative monoid;
\item[(H2)] $x \w x=1;$
\item[(H3)] $x \cdot (x \w y)=y \cdot (y \w x)$;
\item[(H4)] $(x \cdot y)\w z= x \w (y \w z)$,
\end{enumerate}
for every $x,y,z \in H$.
\end{definition}

Given two hoops $H,K$, a \emph{hoop homomorphism} is a map $f \colon H \rightarrow K$ that preserves both the binary operations $\cdot$ and $\w$, and the constant $1$.

\begin{remark}
Every hoop $H$ is endowed with a partial order $\leq$, which is defined by the following equivalent conditions: for every $x,y \in H$
\begin{enumerate}
\item $x \leq y$;
\item $x \w y=1$;
\item there exists $z$ in $H$ such that $x=z \cdot y$.
\end{enumerate}
\end{remark}

Given a homomorphism of hoop $f \colon H \rightarrow K$, its kernel $F=\ker f$ is a \textit{filter} of $H$, i.e., a subset $F\subseteq H$ such that $(F, \cdot, 1)$ is a submonoid of $(H, \cdot, 1)$ which is upward closed with respect to the natural order $\leq$ of $H$. Conversely, every filter $F$ of $H$ may be seen as the kernel of the canonical projection $\pi \colon H \rightarrow H/F$.

%The kernels of hoop homomorphisms with domain $H$ coincide with the so-called \emph{filters} of $H$, i.e., subsets $F \subseteq H$ such that $(F, \cdot, 1)$ is a submonoid of $(H, \cdot, 1)$ which is upward closed with respect to the natural order $\leq$ of $H$. In particular, kernels (and filters) are subhoops. 

\begin{remark}\cite{rel}
The variety $\Hp$ of hoops is a semi-abelian category.
\end{remark}

As mentioned above, we focus on the study of coherent actions in two relevant subvarieties of the variety $\Hp$: the variety of \emph{Wajsberg hoops} and that of \emph{product hoops}. 

%\subsubsection{Wajsberg hoops and MV-algebras}\label{MValgebras}

\begin{definition}
A \emph{bounded hoop} is a hoop $H$ with a constant $0$ such that
\begin{itemize}
\item[(B)] $0 \w x=1$,
\end{itemize}
for any $x \in H$.
\end{definition}

\begin{definition}
A \emph{Wajsberg hoop} is a hoop $H$ such that
\begin{itemize}
\item[(W)] $(x \w y)\w y=(y \w x)\w x$,
\end{itemize}
for every $x,y \in H$.
\end{definition}

It was proved in~\cite{CignoliMundici} that bounded Wajsberg hoops are term equivalent to the class of \emph{MV-algebras}~\cite{chang1, chang2}, which constitutes the equivalent algebraic semantics of \emph{Łukasiewicz logic}~\cite{Luka}.

\begin{definition}\cite{chang1}
An \emph{MV-algebra} is an algebra $A=(A, \oplus, \neg, 0)$ of type $(2,1,0)$ such that 
\begin{enumerate}
\item[(MV1)] $(A, \oplus,0)$ is a commutative monoid;
\item[(MV2)] $\neg \neg x=x$;
\item[(MV3)] $x \oplus \neg 0=\neg 0$;
\item[(MV4)] $ \neg (\neg x \oplus y)\oplus y= \neg (\neg y \oplus x)\oplus x$,
\end{enumerate}
for every $x,y \in A$.
\end{definition}

\begin{example}
The set $A=[0,1]$ endowed with the operations $x \oplus y=\min \lbrace x+y,1 \rbrace$, $\neg x=1-x$ and constant $0$ is an MV-algebra. In fuzzy logic~\cite{Fuzzy1, Fuzzy2, hajek}, this algebra is called the \emph{standard MV-algebra}, as it forms the standard real-valued semantics of Łukasiewicz logic.
\end{example}

\begin{remark}
The class of MV-algebras forms an algebraic variety which we denote by $\MV$.  Furthermore, the initial object of $\MV$ is the two-element Boolean algebra $L_2=\lbrace 0,1 \rbrace$, with $1= \neg 0$, while the terminal object is the trivial MV-algebra $\lbrace 0 \rbrace$.
\end{remark}

Every MV-algebra $A$ is endowed with a partial order $\leq$, called the \textit{natural order}, which is characterized by the following equivalent conditions: for any $x,y \in A$
\begin{enumerate}
\item $x \leq y$;
\item $x \w y=1;$
\item there exists $z \in A$ such that $x \oplus z=y.$
\end{enumerate}
Such a order determines a lattice structure, where the \emph{join} and the \emph{meet} are given by
\[
x \vee y=(x \w y)\w y \quad \text{ and } \quad x \wedge y=x \odot (x \w y).
\]

Given a homomorphism of MV-algebras $f \colon A \rightarrow B$, its kernel $\ker f$ is an \textit{ideal} of $A$, i.e., a subset $I\subseteq A$ such that $(I, \oplus, 0)$ is a submonoid of $(A, \oplus, 0)$ which is downward closed with respect to the natural order $\leq$ of $A$. Conversely, every ideal $I$ of $A$ can be seen as the kernel of the canonical projection $\pi \colon A \rightarrow A/I$.

\begin{remark}
The variety $\MV$ is not semi-abelian, since it is not pointed, but, as shown in~\cite{rel}, it is protomodular~\cite{caratt}. As a consequence, $\MV$ is ideally exact and the semi-abelian category $(\MV\downarrow L_{2})$ is equivalent to the category $\WH$ of \textit{Wajsberg hoops}.
\end{remark}

\begin{remark}\label{rem_MV}
Given an MV-algebra $A$, one may define the constant $1=\neg 0$ and two binary operations $\odot$ and $\rightarrow$ on $A$ as follows:
\[
x \odot y \coloneqq \neg (\neg x \oplus \neg y), \quad x \rightarrow y \coloneqq \neg x \oplus y
\]
for every $x,y \in A$. One may check that $(A,\odot, \rightarrow, 1)$ is a bounded Wajsberg hoop with $0$ as bottom element. Moreover, $\neg 1=0$ and $\neg x = x \rightarrow 0$.

Thus, it is defined the forgetful functor $U\colon \MV \rightarrow \WH$ that forgets the constant~$0$. The left adjoint $M\colon \WH \rightarrow \MV$ of $U$, which is called the \emph{MV-closure} in~\cite{MVclos}, maps any Wajsberg hoop $H=(H,\cdot,\w, 1)$ to the MV-algebra 
\[
M(H)=(H \times \{0,1\},\cdot, \w, 0,1),
\]
where $0 \coloneqq (1,0)$, $1 \coloneqq (1,1)$,
\[
(a,i)\cdot (b,j)=\begin{cases}
(a \cdot b,1), \quad &\text{if} \ i=j=1, \\
(a \w b,0), &\text{if} \ i=1, \ j=0,\\
(b \w a,0), & \text{if} \ i=0, \ j=1,\\
((a\w (a \cdot b))\w b,0), &\text{if} \ i=j=0.
\end{cases}
\]
and
\[
(a,i)\w (b,j)=\begin{cases}
(a \w b,1), &\text{if} \ i=j=1, \\
(a \cdot b,0), &\text{if} \ i=1, \ j=0,\\
((a\w (a \cdot b))\w b,1), & \text{if} \ i=0, \ j=1,\\
(b \w a,1), & \text{if} \ i=j=0.
\end{cases}
\]

%We observe that kernels of MV-algebras are not kernels in the underlying hoop, since they are not filters. Because of this, in the rest of the paper we consider as kernel of an MV-algebra $f \colon A \rightarrow B$ the inverse image $f^{-1}(1)$ of the constant $1$ of $B$.

One may check that the unit $\eta\colon 1_{\WH}\Rightarrow UM$ of the adjunction $M \dashv U$ is cartesian. In fact, for any Wajsberg hoop $H$, the homomorphism
\[
\eta_{H} \colon X \rightarrow UM(X) \colon x \mapsto (x,1)
\]
is the kernel of 
\begin{align*}
U(p_{H})\colon UM(W)&\rightarrow U(L_{2}) \colon (x,i)\mapsto i.
\end{align*}
Thus, by \Cref{cartesian}, we have that
\begin{equation}\label{eq:situation_MV}
\begin{tikzcd}
{\MV} & {\WH}
\arrow[""{name=0, anchor=center, inner sep=0}, "U"', from=1-1, to=1-2]
\arrow[""{name=1, anchor=center, inner sep=0}, "H"', curve={height=12pt}, from=1-2, to=1-1]
\arrow["\dashv"{anchor=center, rotate=-90}, draw=none, from=1, to=0]
\end{tikzcd}
\end{equation}
is, up to an equivalence, the adjunction associated with the unique morphism $L_2 \rightarrow \{0\}$ in $\MV$.
\end{remark}

Our aim is now to characterize coherent actions in the ideally exact context \eqref{eq:situation_MV}. We observe at first that, as for unit-closed varieties of algebras, the converse of \Cref{thmunital} actually holds also in $\WH$.

