\begin{theorem}\label{car_MV}
Consider the ideally exact context \eqref{eq:situation_MV} and let 
\[
\xi\colon U(B)\flat X\rightarrow X
\]
be a relative $U$-action in $\WH$ with associated split epimorphism 
\[\begin{tikzcd}
{A} & {U(B).}
\arrow["{p}", shift left, from=1-1, to=1-2]
\arrow["{s}", shift left, from=1-2, to=1-1]
\end{tikzcd}\] 
Then $\xi$ is a coherent action if and only if $A$ is a bounded Wajsberg hoop with bottom element $s(0_B)$.
\end{theorem}

\begin{proof}
If $\xi$ is coherent, then by \Cref{conv_MV} $A$ is a bounded Wajsberg hoop with bottom element $s(0_B)$. Conversely, if $A$ is a bounded Wajsberg hoop with bottom element $s(0_B)$, then $A \cong U(A')$ for some MV-algebra $A'$. Moreover, $p=U(p')$, $s=U(s')$ for some split epimorphism
\[\begin{tikzcd}
{A'} & {B}
\arrow["{p'}", shift left, from=1-1, to=1-2]
\arrow["{s'}", shift left, from=1-2, to=1-1]
\end{tikzcd}
\]
in $\MV$. Thus, there exists a morphism $f\colon M(X)\rightarrow A'$ in $\MV$ given by the universal property of the unit $\eta$ in the diagram below
\[
\begin{tikzcd}
X & {UM(X)} & {M(X)} \\
{U(A')} && {A'.}
\arrow["{\eta_{X}}", from=1-1, to=1-2]
\arrow["k"', from=1-1, to=2-1]
\arrow["{U(f)}", dashed, from=1-2, to=2-1]
\arrow["f", dashed, from=1-3, to=2-3]
\end{tikzcd}
\]
It follows that $f(x,1)=k(x)$, $f(1,0)=0$ and
\[
f(x,0)=f((x,1)\rightarrow (1,0))=f(x,1)\rightarrow f(1,0)=x\rightarrow 0=\neg x.
\]
Furthermore, one may check that
\[
(U(f)\circ UM(\iota)(i))=U(f)(1,i)=i=U(s')(i)=U(s')(U(\iota)(i)),
\]
\[
(U(p')\circ U(f))(x,1)=U(p')(k(x))=1=U(\iota)(1)=U(\iota)(UM(\tau)(x,1))
\]
and
\begin{align*}
(U(p')\circ U(f))(x,0)&=U(p')(\neg k(x))=\neg U(p')(k(x))=\\
&=\neg 1=0=U(\iota)(0)=U(\iota)(UM(\tau)(x,0)).
\end{align*}
We conclude that the following diagram in $\WH$
\[
\begin{tikzcd}
X & {UM(X)} & {UL_{2}} \\
X & {U(A')} & {U(B)}
\arrow["{\eta_{X}}", from=1-1, to=1-2]
\arrow[equal, from=1-1, to=2-1]
\arrow["{UM(\tau)}", shift left, from=1-2, to=1-3]
\arrow["U(f)"', dashed, from=1-2, to=2-2]
\arrow["{UM(\iota)}", shift left, from=1-3, to=1-2]
\arrow["{U(\iota)}", from=1-3, to=2-3]
\arrow["k"', from=2-1, to=2-2]
\arrow["{U(p')}", shift left, from=2-2, to=2-3]
\arrow["{U(s')}", shift left, from=2-3, to=2-2]
\end{tikzcd}
\]
is commutative and, by \Cref{unit}, the action $\xi$ is coherent.
 \end{proof}

