%\subsubsection{Product hoops and product algebras}\label{prodalgebras}
Similar results of those of \Cref{conv_MV}, \Cref{car_MV} and \Cref{BAT_MV} can be obtained for \emph{product hoops} and \emph{product algebras}. We start by recalling the following definitions.

\begin{definition}\cite{basichoop}
A \emph{basic hoop} is a hoop $H$ such that
\[
((x \rightarrow y)\rightarrow z)\rightarrow ((y \rightarrow x)\rightarrow z)\rightarrow z)=1,
\]
for any $x,y,z \in H$.
\end{definition}

\begin{definition}\cite{prodred}
A \textit{product hoop} is a basic hoop $H$ satisfying the identity
\[
(y \rightarrow z)\vee ((y\rightarrow (x \cdot y))\rightarrow x)=1,
\]
for any $x,y,z \in H$
\end{definition}

We denote by $\PH$ the variety of product hoops. Similarly to the case of Wajsberg hoops, it was proved in~\cite{prodred} that bounded product hoops are term equivalent to the class of \emph{product algebras}, which were introduced in~\cite{godo} and constitutes the equivalent algebraic semantics of \emph{product logic}~\cite{prodred, CignoliTorrens1}. 

\begin{definition}\cite{hajek}
A \emph{BL-algebra} is an algebra $A=(A, \vee, \wedge, \cdot, \rightarrow, 0,1)$ such that
\begin{itemize}
\item[(i)] $(A,\vee,\wedge, \cdot, \rightarrow, 0, 1)$ is a bounded residuated lattice~\cite{res_lattices};
\item[(ii)] $x \wedge y=x \cdot (x \rightarrow y)$;
\item[(iii)] $(x \rightarrow y)\vee (y \rightarrow x)=1$,
\end{itemize}
for any $x,y \in A$.
\end{definition}

\begin{definition}\cite{godo}
A \emph{product algebra} is a BL-algebra $A$ satisfying the identity
\[
\neg x \vee ((x \rightarrow x \cdot y) \rightarrow y)=1,
\]
for any $x,y \in A$, where $\neg x \coloneqq x \rightarrow 0.$
\end{definition}

We denote by $\PA$ the variety of product algebras. Since $\PA$ is protomodular, it is an ideally exact category and it has as initial object the two-element Boolean algebra $L_2$.

\begin{example}
An example of product algebra is given by the set $A=[0,1]$ endowed with the operations $x \cdot_{\prod} y=xy$ and
%(the multiplication between real numbers) and 
\[
x \rightarrow_{\prod} y=\begin{cases} 1, \ \ &\text{if} \ x \leq y, \\
\frac{y}{x}, &\text{otherwise.} \end{cases}
\]
%We denote this algebra by $[0,1]_{\prod}$.
In fuzzy logic, this is called the \emph{standard product algebra}, as it forms the standard real-valued semantics of \emph{product logic}.
\end{example}

\begin{remark}\label{rem_prod}
Given a product algebra $A=(A, \vee, \wedge, \cdot, \rightarrow, 0,1)$, one may check that $(A,\cdot,\rightarrow,1)$ is a bounded product hoop. Thus, it is defined a forgetful functor $U\colon \PA \rightarrow \PH$. In~\cite{prod} the authors provide a description of the left adjoint of such $U$. We now recall the construction provided that freely adds the constant $0$ to a product hoop. 

Let $H$ be a product hoop. It can be shown that every element $x \in H$ can be decomposed in a boolean and a cancellative component given by the following terms:
\[
b(x)=(x \rightarrow x^{2})\rightarrow x, \quad c(x)=x \rightarrow x^{2}.
\]
%Indeed, $b(x)$ is a boolean element, $c(x)$ is a cancellative element and $x=b(x)\wedge c(x)$.
Moreover, the set $G(H)=\lbrace b(x) \; | \; x \in H\rbrace $ is a \emph{generalized Boolean algebra}~\cite{gen_bool}, $C(H)=\lbrace c(x) \; | \; x \in H \rbrace$ is a \emph{cancellative hoop}~\cite{hoop} and the MV-closure $B(H)=M(G(H))$ of $G(H)$ is a Boolean algebra. 

Now, let $H^{\bullet} \coloneqq \lbrace x^{\bullet} \; | \; x \in H\rbrace$ and let $\sim$ be the equivalence relation on $H \cup H^{\bullet}$ defined by
\[
x \sim x' \quad \text{if and only if} \quad b(x)=b(x') \ \text{and} \ \neg b(x)\vee_{H}c(x)=\neg b(x)\vee_{H} c(x),
\]
where $\vee_{H} \colon B(H)\times C(H)\rightarrow C(H)$ is defined by
\[
b \vee_{H} c=\begin{cases}
b \vee c, \ & \text{if} \ b \in G(H), \\
\neg b \rightarrow c, & \text{otherwise.}
\end{cases}
\]
One may check that the set $H \cup H^{\bullet}/\sim$ endowed with the operations
\begin{align*}
&xy^{\bullet}=((b\rightarrow b')\wedge cc')^{\bullet},\\
&x^{\bullet}y^{\bullet}=((b \vee b')\wedge cc')^{\bullet},\\
&x^{\bullet}\rightarrow y^{\bullet}=(b'\rightarrow b)\wedge(b \vee(c\rightarrow c')),\\
&x^{\bullet}\rightarrow y=(b \vee b')\wedge(b \vee(c \rightarrow c'))\\
&x \rightarrow y^{\bullet}=(b \wedge b'\wedge (bc\rightarrow c'))^{\bullet},\end{align*}
where $b = b(x)$, $c = c(x)$, $b'=b(x')$ and $c'=c(x')$, is a product algebra. Moreover, the free functor $K\colon \PH\rightarrow \PA$, which sends a product hoop $H$ to the product algebra $K(H)=H\cup H^{\bullet}/\sim$, is the left adjoint of the forgetful functor $U\colon \PA \rightarrow \PH$.

Finally, the unit $\eta \colon 1_{\PH}\Rightarrow HK$ of the adjunction $K\dashv U$ is cartesian. Indeed, for any product hoop $H$, the morphism $\eta_{H}\colon H \rightarrow UK(H) \colon x \mapsto x$ is the kernel of
\begin{align*}
U(p_{H})\colon UK(H)&\rightarrow U(L_{2})\\
x& \mapsto \begin{cases}
1, \ & \text{if} \ x \in H,\\
0, & \text{otherwise.}
\end{cases}
\end{align*}
%since $K(U(p_{H}))=\{x \in UK(H) \; | \; U(p_{H})=1\}=\{x \in UK(H) \; | \; x \in H\}.$
Thus, by \Cref{cartesian}, we have that
\begin{equation}\label{eq:situation_PR}
\begin{tikzcd}
{\PA} & {\PH}
\arrow[""{name=0, anchor=center, inner sep=0}, "U"', from=1-1, to=1-2]
\arrow[""{name=1, anchor=center, inner sep=0}, "K"', curve={height=12pt}, from=1-2, to=1-1]
\arrow["\dashv"{anchor=center, rotate=-90}, draw=none, from=1, to=0]
\end{tikzcd}
\end{equation}
is, up to an equivalence, the adjunction associated with the unique morphism $L_2 \rightarrow \lbrace 0 \rbrace$ in $\PA$.
\end{remark}

We are now ready to show that the converse of \Cref{thmunital} holds for the ideally exact context \eqref{eq:situation_PR}.

\begin{proposition}\label{conv_prod}
Consider the ideally exact context \eqref{eq:situation_PR} and let 
\[
\xi\colon U(B)\flat X\rightarrow X
\]
be a relative $U$-action in $\PH$. If $\xi$ is coherent, then $\xi$ is an ideal action.
%with associated split epimorphism
%\begin{equation}
%\begin{tikzcd}\label{ideal_split_pr}
%{A} & {U(B).}
%\arrow["{p}", shift left, from=1-1, to=1-2]
%\arrow["{s}", shift left, from=1-2, to=1-1]
%\end{tikzcd}
%\end{equation}

%then there exists a split epimorphism 
%\[
%\begin{tikzcd}
%{A'} & {B}
%\arrow["{p'}", shift left, from=1-1, to=1-2]
%\arrow["{s'}", shift left, from=1-2, to=1-1]
%\end{tikzcd}
%\] 
%in $\PA$ and an isomorphism $\sigma \colon U(A') \rightarrow A$ such that the following diagram in $\PH$
%\[\begin{tikzcd}
%{U(A')} & {} & A \\
%& {U(B)}
%\arrow["\sigma", from=1-1, to=1-3]
%\arrow["{U(p')}"', shift right, from=1-1, to=2-2]
%\arrow["p"', from=1-3, to=2-2]
%\arrow["{U(s')}"'{pos=0.3}, shift right, from=2-2, to=1-1]
%\arrow["s"', shift right=2, from=2-2, to=1-3]
%\end{tikzcd}\]
%is commutative.
\end{proposition}

\begin{proof}
Let $\xi\colon U(B)\flat X\rightarrow X$ be a coherent action in $\PH$ with associated split epimorphism
\begin{equation*}
\begin{tikzcd}\label{ideal_split_pr}
{A} & {U(B).}
\arrow["{p}", shift left, from=1-1, to=1-2]
\arrow["{s}", shift left, from=1-2, to=1-1]
\end{tikzcd}
\end{equation*}
By \Cref{unit}, there exists a morphism $f\colon UK(X)\rightarrow A$ in $\PH$ such that the following diagram
\[\begin{tikzcd}
X & {UK(X)} & {UK(0)} \\
X & A & {U(B)}
\arrow["{\eta_{X}}", from=1-1, to=1-2]
\arrow[equal, from=1-1, to=2-1]
\arrow["{UK(\tau)}", shift left, from=1-2, to=1-3]
\arrow["f"', dashed, from=1-2, to=2-2]
\arrow["{UK(\iota)}", shift left, from=1-3, to=1-2]
\arrow["{U(\iota)}", from=1-3, to=2-3]
\arrow["k"', from=2-1, to=2-2]
\arrow["p", shift left, from=2-2, to=2-3]
\arrow["s", shift left, from=2-3, to=2-2]
\end{tikzcd}\]
commutes. As in the case of Wajsberg hoops, it is sufficient to prove that $A$ is a bounded product hoop with bottom element $s(0_B)$, i.e., $s(0_{B})\rightarrow a=1$ for any $a \in A$.

For any $a \in A$, we have
\[
p(s(0_{B})\rightarrow a)=ps(0_{B})\rightarrow p(a)=0_{B}\rightarrow p(a)=1.
\]
Thus, $s(0_{B})\rightarrow a \in X$ and
\begin{align*}
f(1^{\bullet}\rightarrow (s(0_{B})\rightarrow a))&=f(1)=1.
\end{align*}
Moreover
\begin{align*}
f(1^{\bullet})\rightarrow f(s(0_{B})\rightarrow a)&=s(0_{B})\rightarrow (s(0_{B})\rightarrow a)\\
&=s(0_{B})\cdot s(0_{B})\rightarrow a\\
&=s(0_{B})\rightarrow a,
\end{align*}
i.e., $s(0_{B})\rightarrow a=1$. Hence, the internal action $\xi$ is ideal.
\end{proof}

This allow us to state the following characterization for coherent/ideal actions in the ideally exact context \eqref{eq:situation_PR}.

\begin{theorem}\label{car_PR}
Consider the ideally exact context \eqref{eq:situation_PR} and let 
\[
\xi\colon U(B)\flat X\rightarrow X
\]
be a relative $U$-action in $\PH$ with associated split epimorphism
\[
\begin{tikzcd}
{A} & {U(B).}
\arrow["{p}", shift left, from=1-1, to=1-2]
\arrow["{s}", shift left, from=1-2, to=1-1]
\end{tikzcd}
\]
Then $\xi$ is a coherent action if and only if $A$ is a bounded product hoop with bottom element~$s(0_B)$. \noproof
\end{theorem}

Again, as a direct consequence of the previous characterization, we get the following result, whose proof is analogous to the one of \Cref{BAT_MV}.

\begin{theorem}
The ideally exact context
\[
\begin{tikzcd}
{\PA} & {\PH}
\arrow[""{name=0, anchor=center, inner sep=0}, "U"', from=1-1, to=1-2]
\arrow[""{name=1, anchor=center, inner sep=0}, "K"', curve={height=12pt}, from=1-2, to=1-1]
\arrow["\dashv"{anchor=center, rotate=-90}, draw=none, from=1, to=0]
\end{tikzcd}
\]
is BAT. \noproof
\end{theorem}

We end this section by presenting a class of examples of coherent/ideal actions in the variety of product hoops.

\begin{example}\cite{strongsect, Montagna}
Let $A$ be a product algebra. Let 
\[
\operatorname{B}(A)=\{x \in A \; | \; \neg \neg x=x\}
\]
be the set of \emph{regular elements} of $A$ and let
\[
\operatorname{D}(A)=\{x \in A \; | \; \neg \neg x=1\}
\]
be the set of \emph{dense elements} of $A$. Then $\operatorname{B}(A)$ is the greatest Boolean subalgebra of $A$, $\operatorname{D}(A)$ is a filter of $A$ and one may consider the split extension
\[\begin{tikzcd}
\operatorname{D}(A) & A & {\operatorname{B}(A)}
\arrow["k", from=1-1, to=1-2]
\arrow["p", shift left, from=1-2, to=1-3]
\arrow["s", shift left, from=1-3, to=1-2]
\end{tikzcd}\]
where $p(a)= \neg \neg a$ (see~\cite[Theorem~1.2, Lemma~1.4]{CignoliTorrens1} where it is proved that $p$ is a homomorphism), for every $a \in A$, $k$ and $s$ are the canonical inclusions. Then, by \Cref{car_PR} the action associated with the split extension above is coherent since $s(0_A)=0_A$. Notice that this split extension has \emph{strong section} (see~\cite{strongsect, Rump1, Rump2}).
\end{example}

\subsection{A non-varietal example}\label{sec_set}

We conclude the manuscript by presenting an example that illustrates how the converse of \Cref{thmunital} holds true beyond the framework of varieties. To achieve this, we consider the ideally exact category $\Set^{\op}$ (see~\cite[Example 3.7]{IdeallyExact}).

In this case, the monadic adjunction with cartesian unit of \Cref{cartesian} may be described  by
\begin{equation}\label{eq:situation_set}
\begin{tikzcd}
{\Set^{\op}} & {(\Set_*)^{\op},}
\arrow[""{name=0, anchor=center, inner sep=0}, "U"', from=1-1, to=1-2]
\arrow[""{name=1, anchor=center, inner sep=0}, "F"', curve={height=15pt}, from=1-2, to=1-1]
\arrow["\dashv"{anchor=center, rotate=-90}, draw=none, from=1, to=0]
\end{tikzcd}
\end{equation}
where $(\Set_*)^{\op}$ is the dual of the category of pointed sets, $U$ maps any set $A$ to the pointed set $(1+A,1)$, where $+$ denotes the disjoint union between sets, and $F(X,*)=X$ for any pointed set $(X,*)$. We observe that the unit and the counit of the adjunction
\[
\eta_{(X,*)} \colon UF(X,*)=(1+X,1) \rightarrow (X,*),
\]
\[
\varepsilon_{A} \colon A \rightarrow FU(A)=1+A
\]
are defined by
\[
\eta_{(X,*)}(x)=x, \quad \eta_{(X,*)}(1)=*, \quad \varepsilon_{A}(a)=a.
\]
We aim to show that the ideally exact context \eqref{eq:situation_rng} is BAT.

\begin{remark}
Let us observe that the adjunction we just described is nothing but the dual of the one giving rise to the so-called \emph{maybe monad}, widely used in computer science, see~\cite{maybe_mon}.
\end{remark} 

\begin{remark}
One may check that, as in the previous varietal cases, the functor $U$ of diagram \eqref{eq:situation_set} is full on isomorphisms. In fact, an isomorphism $\alpha \colon (1+A,1) \to (1+B,1)$ in $(\Set_*)^{\op}$ is nothing but a bijection between $1+A$ and $1+B$ such that $\alpha(1)=1$. Hence, the restriction $\beta=\alpha_{\downharpoonright_{A}}$ is a bijection between $A$ and $B$ such that $U(\beta)=\alpha$.
\end{remark}

Now, let $(B,*_B)$ and $(X,*_X)$ be pointed sets. A split extension of $(B,*_B)$ by $(X,*_X)$ in the semi-abelian category $(\Set_*)^{\op}$ may be described as a diagram in $\Set_*$
\[\begin{tikzcd}
{(B,*_B)} & {(A,*_{A})} & {(X,*_{X})}
\arrow["p", shift left, from=1-1, to=1-2]
\arrow["s", shift left, from=1-2, to=1-1]
\arrow["k", from=1-2, to=1-3]
\end{tikzcd}\]
where $p$ is a split monomorphism, $s$ is a split epimorphism, $s \circ p=\id_B$, and there is a canonical isomorphism $(X,*_X) \cong (A/p(B), [*_A])$.

\begin{remark}
As shown in~\cite{Deval}, since $k$ is a normal epimorphism, there exists a unique splitting 
\[\delta \colon X \rightarrow A\]
defined by 
\[
\delta([a])=
\begin{cases}
a, \quad &\text{if }[a] \neq [*_A],\\
*_A, \quad &\text{if }[a]=[*_A].
\end{cases}
\]  
%$\delta([a])=a$ if $a \not\in[*_A]$, and $\delta([*_A])=*_A.$
\end{remark}

We aim to prove now that, as in the previous examples, the converse of \Cref{thmunital} actually holds also in the ideally exact context \eqref{eq:situation_set}.
%From now on, when we say that a split monomoprhism in $(\Set_{*})^{\op}$ in ideal, we mean the the corresponding split epimorphism in $\Set_*$ is ideal.

\begin{proposition}\label{conv_set}
Consider the ideally exact context \eqref{eq:situation_set} and let
\[\xi \colon U(B)\flat (X,*_{X}) \rightarrow (X,*_{X})\] be a relative $U$-action in $(\Set_{*})^{\op}$. If $\xi$ is coherent, then $\xi$ is an ideal action.
