\begin{remark}
Let
\[\begin{tikzcd}
{(1+B, 1)} & {(A,p(1)).}
\arrow["p", shift left, from=1-1, to=1-2]
\arrow["s", shift left, from=1-2, to=1-1]
\end{tikzcd}\]
be a split monomorphism in $\Set_{*}$. Since $(A,p(1))$ is isomorphic to $(1 + A', 1)$, where $A'=A \setminus \lbrace p(1) \rbrace$, and $s_{\downharpoonright_{A'}}$ can be defined if and only if $s^{-1}(1)=\lbrace *_A \rbrace$, we may state the following characterization of coherent/ideal actions in the category $(\Set_*)^{\op}$.
%the unique element of $A$ which is mapped to $1$ by $s$ is $*_A$
\end{remark}

\begin{theorem}\label{char_set}
Consider the ideally exact context \eqref{eq:situation_set} and let
\[\xi \colon U(B)\flat (X,*_{X}) \rightarrow (X,*_{X})\] be a relative $U$-action in $(\Set_{*})^{\op}$ with associated split monomorphism in $\Set_{*}$
\[\begin{tikzcd}
{(1+B, 1)} & {(A,*_{A}).}
\arrow["p", shift left, from=1-1, to=1-2]
\arrow["s", shift left, from=1-2, to=1-1]
\end{tikzcd}\]
Then $\xi$ is a coherent action if and only if $s^{-1}(1)= \lbrace *_A \rbrace$. \noproof
\end{theorem}

%\smallskip
The next example shows that the notion of coherent/ideal action does not trivialize in~$(\Set_*)^{\op}$.

\begin{example}
Consider the pointed sets $(A,*)$ and $(B, *)$, where $A=\lbrace a, * \rbrace$ and $B=\lbrace * \rbrace$. Let $p \colon B \hookrightarrow A$ be the inclusion and consider its retraction $s \colon A \rightarrow B$ defined by $s(a)=s(*)=*$. The associated action is not coherent since there exists no function $s' \colon \lbrace * \rbrace \rightarrow \emptyset$.
\end{example}

To conclude the manuscript, we aim to prove that the ideally exact context \eqref{eq:situation_set} has a good theory of actions.

\begin{theorem}
The ideally exact context
\[
\begin{tikzcd}
{\Set^{\op}} & {(\Set_*)^{\op},}
\arrow[""{name=0, anchor=center, inner sep=0}, "U"', from=1-1, to=1-2]
\arrow[""{name=1, anchor=center, inner sep=0}, "F"', curve={height=15pt}, from=1-2, to=1-1]
\arrow["\dashv"{anchor=center, rotate=-90}, draw=none, from=1, to=0]
\end{tikzcd}
\]
is BAT.
\end{theorem}

\begin{proof}
From \Cref{conv_set}, we know that every coherent relative $U$-action is ideal. It remains to show that every morphism between ideal split monomorphisms in $\Set_*$ is ideal.

Let $B$ be a set and consider a morphism
\[
\begin{tikzcd}
{(A_2,*_2)} & {} & {(A_1,*_1)} \\
& {(1+B,1)}
\arrow["h", from=1-1, to=1-3]
\arrow["{s_2}"', shift right, from=1-1, to=2-2]
\arrow["s_1"', from=1-3, to=2-2]
\arrow["{p_2}"'{pos=0.3}, shift right, from=2-2, to=1-1]
\arrow["p_1"', shift right=2, from=2-2, to=1-3]
\end{tikzcd}
\]
%\[
%h \colon ((A_2,*_2),p_2,s_2) \to ((A_1,*_1),p_1,s_1)
%\]
between ideal split monomorphisms over $(1+B,1)$. %In other words, we have that $h \colon A_2 \to A_1$ is a map such that $h(*_2)=*_1$, $h \circ p_2=p_1$ and $s_1 \circ h=s_2$. 

It follows from \Cref{char_set} that $s_i^{-1}(1)=*_i$, for $i=1,2$. In addition, if $p_i(b)=*_i$, then $b=s_i(p_i(b)))=s_i(*_i)=1$. This means that $p_i^{-1}(*_i)=1$, for any $i=1,2$. 

Thus, if $A_i'=A_i \setminus \lbrace *_i \rbrace$, we have that $p_i'=p_i{_{\downharpoonright_{B}}}$ and $s_i'=s_i{_{\downharpoonright_{A_i'}}}$ define two split monomorphisms in $\Set$
\[
\begin{tikzcd}
{B} & {A_i',}
\arrow["p_i'", shift left, from=1-1, to=1-2]
\arrow["s_i'", shift left, from=1-2, to=1-1]
\end{tikzcd} \quad i=1,2
\]
and it is immediate to check that 
\[
\begin{tikzcd}
{A_2} & {} & {A_1} \\
& {B}
\arrow["h'=h_{\downharpoonright_{A_i'}}", from=1-1, to=1-3]
\arrow["{s_2'}"', shift right, from=1-1, to=2-2]
\arrow["s_1'"', from=1-3, to=2-2]
\arrow["{p_2'}"'{pos=0.3}, shift right, from=2-2, to=1-1]
\arrow["p_1'"', shift right=2, from=2-2, to=1-3]
\end{tikzcd}
\]
%\[
%h'=h_{\downharpoonright_{A_i'}} \colon (A_2',p_2',s_2') \rightarrow (A_1',p_1',s_1')
%\]
is a morphism of split monomorphisms over $B$ such that $U(h')=h$. In fact, one has that $h(a)=*_1$ if and only if $s_2(a)=s_1(h(a))=s_1(*_1)=1$. Hence, from \Cref{char_set} we get that $a=*_2$, i.e., $h^{-1}(*_1)=*_2$.
\end{proof}

