\section{$K$-Theory Generators in Higher Dimensions} \label{Section:S^n unitaries}

It is clear that there is a limit to how much progress can be made with this approach of finding unitary generators for $K$-theory for each $\fS^d$ separately as in the previous section. In this section, we describe a more general approach to finding a representative of the key generator of $\widetilde{KO}_{d+2}(\fS^d)$.

For each $d$ there is an element $g_d \in \widetilde{KO}_{d+2}(\fS^d) = \Z$ that generates $\widetilde{KO}_*(\fS^d)$ as a free $KO_*(\R)$-module. In this section, for each $d$ we will describe how to construct a unitary defined on the sphere, with the proper symmetry, that represents $g_d$. We will not explicitly describe how to obtain unitary generators for the other non-trivial groups of $\widetilde{KO}_*(\fS^d)$. We suffice it to say that these generators can all be obtained from the key generator in $\widetilde{KO}_{d+2}(\fS^d)$ using the natural transformations. Specifically, if $g_d$ is a generator of $\widetilde{KO}_{d+2}(\fS^d)$, 
then $\eta(g)$ is a generator of $\widetilde{KO}_{d+3}(\fS^d) = \Z_2$,
 $\eta^2(g)$ is a generator of $\widetilde{KO}_{d+4}(\fS^d) = \Z_2$,
 and $\xi(g)$ is a generator of $\widetilde{KO}_{d+6}(\fS^d) = \Z$. 
 Hence, when we have a unitary representing $g$, we can obtain a formula for the unitaries representing $\eta(g)$, $\eta^2(g)$, and $\xi(g)$ using the formulas for $\eta$ and $\xi$ found in \cite{Boer2020}.

Our main result is Theorem~\ref{main-thm} which is connected to Constructions~\ref{construction1} and \ref{construction} below. Construction~\ref{construction} is presented as an algorithm to produce unitaries 
and Theorem~\ref{main-thm} states that the unitaries from this construction actually represent generators of the correct $K$-theory groups. This algorithm builds on the construction for complex $K$-theory (from \cite{SBS}), which is re-stated as Part (0) of Construction~\ref{construction}. The real $K$-theory elements are given in Parts (1)-(4).

\begin{defn}
Let $k$ be a positive odd integer and let  $n = 2^{(k-1)/2}$. A list of self-adjoint matrices $a_1, \dots, a_k \in M_n(\C)$ is called a list of ``complex $k$-Clifford generators" if they satisfy 
$$a_i a_j + a_j a_i = 2 \delta_{i,j} \; $$
for all $i,j$. These elements form an irreducible representation of the the Clifford algebra $\C_k$.
\end{defn}

\begin{const}  \label{construction1}
Following Section 2 of \cite{SBS}, for $k$ odd
the following is the ``standard" list of complex self-adjoint complex $k$-Clifford generators in $M_n(\C)$ constructed inductively:
\begin{itemize} 
\item For $k = 1$, we have $\Gamma_{1,1} = 1$.
\item For $k = 3$, we have 
$$\Gamma_{1,3} = \begin{bmatrix} 0 & 1 \\ 1 & 0 \end{bmatrix} \; , \quad
\Gamma_{2,3} =  \begin{bmatrix} 0 & i \\ -i & 0 \end{bmatrix} \; , \quad
\Gamma_{3,3} =  \begin{bmatrix} 1 & 0 \\ 0 & -1 \end{bmatrix} \; .$$
\item For $k \geq 3$, let $\Gamma_{1,k}, \dots, \Gamma_{k,k}$ be the standard list of complex self-adjoint $k$-Clifford generators in $M_n(\C)$, and then define $\Gamma_{1,k+2}, \dots, \Gamma_{k+2,k+2} \in M_{2n}(\C)$ by
\begin{align*}
\Gamma_{i, k+2} &= \begin{bmatrix} 0 & \Gamma_{i, k} \\ \Gamma_{i,k} & 0 \end{bmatrix} && i = 1, \dots, k, \\
\Gamma_{k+1,k+2} &=  \begin{bmatrix} 0 & i I_{n} \\ -i I_{n} & 0 \end{bmatrix} \\
\Gamma_{k+2, k+2} &=  \begin{bmatrix} I_{n} & 0 \\ 0 & -I_{n}  \end{bmatrix} \\
\end{align*}
\end{itemize}
\end{const}

\begin{const} ~ \label{construction}

\begin{enumerate}
\item[(0)] Let $k \equiv 1 \pmod 2$ and let $n = 2^{(k-1)/2}$.
\begin{itemize}
\item Write down the standard complex Clifford generators $\Gamma_{1,k}, \dots, \Gamma_{k,k} \in M_n(\C)$.
\item Let $Q_{k-1}(x) = \sum_{i = 1}^k x_i \Gamma_{i,k}$ and $U_k(x) = \sum_{i = 1}^k x_i \Gamma_{i,k} + x_{k+1} i I_n$.
%\item Then $[Q_{k-1}] \in K_{0}(C(S^{k-1}), \C)$ and $[U_k] \in K_{1}(C(S^k), \C)$.
\end{itemize}

\vspace{.5cm}

\item[(1)] Let $k \equiv -1 \pmod 8$ and let $n = 2^{(k-1)/2}$.
\begin{itemize}
\item Write down the standard complex Clifford generators $\Gamma_{1,k}, \dots, \Gamma_{k,k} \in M_n(\C)$.
\item Let $$  S=  \{j \in  \{1, \dots, k\} \mid \text{$j$ is odd} \} $$
and define $\Up_{1,k}, \dots, \Up_{k,k} \in M_n(\C)$ by
$$\Up_{i,k} =
	\begin{cases} 
			 \prod_{ j \in S \backslash \{i\}} i \Gamma_{j,k} & i \in S \\ \hspace{.5cm} \Gamma_{i,k} & i \notin S 
	\end{cases} $$
\item Let $Q\pr_{k-1}(x) = \sum_{i = 1}^k x_i \Up_{i,k}$ and $U\pr_k(x) = \sum_{i = 1}^k x_i \Up_{i,k} + x_{k+1} i I_n$.
%\item Then $[Q\pr_{k-1}] \in KO_{0}(\fS^{k-1})$ and $[U\pr_k] \in KO_{1}(\fS^{k})$.
\end{itemize}

\vspace{.5cm}

\item[(2)] Let $k \equiv 1 \pmod 8$ and let $n = 2^{(k-1)/2}$.
\begin{itemize}
\item Write down the standard complex Clifford generators $\Gamma_{1,k}, \dots, \Gamma_{k,k} \in M_n(\C)$.
\item Let $$  S=  \{j \in  \{1, \dots, k\} \mid \text{$j$ is even} \} $$
and define $\Up_{1,k}, \dots, \Up_{k,k} \in M_n(\C)$ by
$$\Up_{i,k} =
	\begin{cases} 
			 \prod_{ j \in S \backslash \{i\}} i  \Gamma_{j,k} & i \in S \\ \hspace{.5cm} \Gamma_{i,k} & i \notin S 
	\end{cases} $$
\item Let $Q\pr_{k-1}(x) = \sum_{i = 1}^k x_i \Up_{i,k}$ and $U\pr_k(x) = \sum_{i = 1}^k x_i \Up_{i,k} + x_{k+1} i I_n$.
%\item Then $[Q\pr_{k-1}] \in KO_{2}(\fS^{k-1})$ and $[U\pr_k] \in KO_{3}(\fS^{k})$.
\end{itemize}

\vspace{.5cm}

\item[(3)] Let $k \equiv 3 \pmod 8$ and let $n = 2^{(k-1)/2}$.
\begin{itemize}
\item Write down the standard complex Clifford generators $\Gamma_{1,k}, \dots, \Gamma_{k,k} \in M_n(\C)$.
\item Let $$  S=  \{j \in  \{1, \dots, k\} \mid \text{$j$ is odd and $j \geq 5$} \} $$
 and define $\Up_{1,k}, \dots, \Up_{k,k} \in M_n(\C)$ by
$$\Up_{i,k} =
	\begin{cases} 
			 \prod_{ j \in S \backslash \{i\}} i \Gamma_{j,k} & i \in S \\ \hspace{.5cm} \Gamma_{i,k} & i \notin S 
	\end{cases} $$
\item Let $Q\pr_{k-1}(x) = \sum_{i = 1}^k x_i \Up_{i,k}$ and $U\pr_k(x) = \sum_{i = 1}^k x_i \Up_{i,k} + x_{k+1} i I_n$.
%\item Then $[Q\pr_{k-1}] \in KO_{4}(\fS^{k-1})$ and $[U\pr_k] \in KO_{5}(\fS^{k})$.
\end{itemize}

\vspace{.5cm}

\item[(4)] Let $k \equiv 5 \pmod 8$ and let $n = 2^{(k-1)/2}$.
\begin{itemize}
\item Write down the standard complex Clifford generators $\Gamma_{1,k}, \dots, \Gamma_{k,k} \in M_n(\C)$.
\item Let $$  S=  \{j \in  \{1, \dots, k\} \mid \text{$j$ is even or $j \leq 3$} \} $$
and define $\Up_{1,k}, \dots, \Up_{k,k} \in M_n(\C)$ by
$$\Up_{i,k} =
	\begin{cases} 
			 \prod_{ j \in S \backslash \{i\}} i\Gamma_{j,k} & i \in S \\ \hspace{.5cm} \Gamma_{i,k} & i \notin S 
	\end{cases} $$
\item Let $Q\pr_{k-1}(x) = \sum_{i = 1}^k x_i \Up_{i,k}$ and $U\pr_d(x) = \sum_{i = 1}^k x_i \Up_{i,k} + x_{k+1} i I_n$.
%\item Then $[Q\pr_{k-1}] \in KO_{6}(\fS^{k-1})$ and $[U\pr_k] \in KO_{7}(\fS^{k})$.
\end{itemize}
\vspace{.5cm}
\end{enumerate}

We note that in the products that define $\Up_{i,k}$ for $i \in S$ in Parts (1)-(4) above, the order of the factors 
matters since the Clifford generators do not commute. The proper order is always taken to correspond to the natural order of increasing integer indices $j \in S \backslash \{ i \}$ from left to right.
\end{const}

In the complex case, we know that the elements $[Q_{k-1}]$ and $[U_k]$ from Part (0) of Construction~\ref{construction} represent generators of $K_{0}(C(S^{k-1}), \C) = \Z$ and $K_{1}(C(S^k), \C) = \Z$ respectively from Proposition~1 in \cite{SBS}. Our goal in this section is to prove the following Theorem which addresses the real case. 

\begin{thm} \label{main-thm}
In the real case, $[Q\pr_{k-1}]$ and $[U\pr_k]$ from Parts (1)-(4) of Construction~\ref{construction} represent generators of $KO_{k+1}(\fS^{k-1}) = \Z$ and $KO_{k+2}(\fS^k) = \Z$ respectively, for odd $k$. In other words,
$$g_{k-1} = [Q\pr_{k-1}] \qquad \text{and} \qquad g_k = [U\pr_k] \; .$$
\end{thm}

\begin{lemma}
For positive odd integers $k$, the standard list of complex self-adjoint $k$-Clifford generators satisfies
$$
(\Gamma_{i,k})\T = (-1)^{i+1} \Gamma_{i,k} 
\quad \text{and} \quad
(\Gamma_{i,k})\sT = 
\begin{cases} 
-\Gamma_{i,k} & i \leq 3 \\
(-1)^{i+1} \Gamma_{i,k} & \rm{otherwise.}
\end{cases} $$
\end{lemma}

\begin{proof}
Check this directly for $k = 3$ and then proceed by induction.
\end{proof}

\begin{lemma} \label{transpose}
Let $a_1, \dots, a_k, b_1, \dots, b_\ell$ be a list of complex self-adjoint $(k + \ell)$-Clifford generators satisfying
$$(a_i)\T = a_i \quad \text{and} \quad (b_i)\T = -b_i \; .$$
Define 
$$\widetilde a_i = i (a_1 a_2 \dots \widehat a _i \dots a_k) \text{~for $1 \leq i \leq k$} 
\quad \text{and} \quad \widetilde b _i = i (b_1 b_2 \dots \widehat{b_i} \dots b_\ell) \text{~for $1 \leq i \leq \ell$} \; .
$$
Then
\begin{enumerate}
\item If $\ell \equiv 0 \pmod 4$, then
$a_1, \dots, a_k, \widetilde b_1, \dots, \widetilde b_\ell$ is a list of complex self-adjoint $(k + \ell)$-Clifford generators 
and $(\widetilde{b}_i)\T = \widetilde{b}_i$
\item If $k \equiv 0 \pmod 4$, then
$\widetilde{a}_1, \dots, \widetilde{a}_k, b_1, \dots, b_\ell$ is a list of complex self-adjoint $(k + \ell)$-Clifford generators 
and $(\widetilde{a}_i)\T = -\widetilde{a}_i$
\end{enumerate}
\end{lemma}

\begin{lemma} \label{sharp}
The same statements in Lemma~\ref{transpose} hold if we replace $x\T$ with $x\sT$ throughout.
\end{lemma}

For any positive integer $k$, let $\Delta(k) =\tfrac{k(k+1)}{2}$ be the $k$th triangular number. Note that $\Delta(k-1)$ is the number of pair-wise adjacent transpositions involved to transform a product $x_1 \dots x_k $ into $ x_k \dots x_1$ and that $\Delta(k)$ is even if and only if $k \equiv 3$ or $k \equiv 4 \pmod 4$.

\begin{proof}[Proof of Lemmas~\ref{transpose} and \ref{sharp}.]
For part (1), check first that
\begin{align*}
(\widetilde b_i)^* &= -i (b_1 b_2 \dots \widehat{b_i} \dots b_\ell)^* \\
	&= -i (b_\ell \dots \widehat{b_i} \dots b_2 b_1) \\
	&= -i (-1)^{\Delta(\ell-2)} (b_1 b_2 \dots \widehat{b_i} \dots b_\ell) \\
	&= \widetilde b_i 
\end{align*}
since $\ell-2 \equiv 2 \pmod 4$. From this it follows that $\widetilde b_i$ are self-adjoint unitaries. In particular $(\widetilde b_i)^2 = 1$.

Similarly we have
\begin{align*}
(\widetilde b_i)\T &=  i (b_1 b_2 \dots \widehat{b_i} \dots b_\ell)\T \\
	& = i (-1)^{\Delta(\ell-2)} (b_1\T b_2\T \dots \widehat{b_i} \dots b_\ell\T) \\
	&= i (-1)^{\Delta(\ell-2)} (-1)^{\ell-1} (b_1 b_2 \dots \widehat{b_i} \dots b_\ell) \\
	&= \widetilde b_i
\end{align*}
We also compute, for all $1 \leq i \leq k, 1 \leq j \leq \ell$
\begin{align*}
a_i \widetilde b_j &= i a_i (b_1 \dots \widehat{b}_j \dots b_\ell) \\
	&= i (-1)^{\ell-1} (b_1 \dots \widehat{b}_j \dots b_\ell) a_i \\
	&= - \widetilde b_j a_i
\end{align*}
and, for all $1 \leq i < j \leq \ell$
\begin{align*}
\widetilde b_i \widetilde b_j 
	&= i^2 (b_1 \dots \widehat{b}_i \dots b_\ell)(b_1 \dots \widehat{b}_j \dots b_\ell) \\
	&= i^2 (-1)^{\ell-1} (-1)^{\ell-2} (b_1 \dots \widehat{b}_j \dots b_\ell)(b_1 \dots \widehat{b}_i \dots b_\ell) \\
	&= - \widetilde b_j \widetilde b_i \; .
\end{align*}
This proves Part (1).

For Part (2) we set $\widetilde a_i = i (a_1 a_2 \dots \widehat a _i \dots a_k)$. 
Then we have 
\begin{align*}
(\widetilde a_i)\T &=  i (a_1 a_2 \dots \widehat{a_i} \dots a_k)\T \\
	& = i (-1)^{\Delta(k-2)} (a_1\T a_2\T \dots \widehat{a_i} \dots a_k\T) \\
	&= i (-1)^{\Delta(k-2)}  (a_1 a_2 \dots \widehat{a_i} \dots a_k) \\
	&= - \widetilde a_i
\end{align*}
The proof is otherwise the same  as for Part (1). 

The proof of Lemma~\ref{sharp} is identical to that of Lemma~\ref{transpose}, since both involutions ${\rm Tr}$ and $\sharp \otimes {\rm Tr}$ have the same formal properties -- they are linear and antimultiplicative.
\end{proof}

Starting with the standard list of Clifford generators, we can use Lemmas~\ref{transpose} and \ref{sharp} to modify, and obtain lists of Clifford generators satisfying the desired symmetries as specified in the the following Proposition.

\begin{lemma} \label{lemma:sigma-generators}
Suppose that $k$ is odd. In each of the four cases of Construction~\ref{construction}, the constructed list $\Up_{1,k}, \dots, \Up_{k,k}$ consists of Clifford generators that satisfy,
\begin{enumerate}
\item for $k \equiv -1 \pmod 8$, we have $\Up_{i,k}\T = -\Up_{i,k}$.
\item for $k \equiv 1 \pmod 8$, we have $\Up_{i,k}\T = \Up_{i,k}$.
\item for $k \equiv 3 \pmod 8$, we have $\Up_{i,k}\sT = -\Up_{i,k}$.
\item for $k \equiv 5 \pmod 8$, we have $\Up_{i,k}\sT = \Up_{i,k}$.
\end{enumerate}
\end{lemma}

\begin{proof}
First suppose that $k \equiv -1 \pmod 8$. Let $\Gamma_{1,k}, \dots, \Gamma_{k,k}$ be the standard list of self-adjoint complex $k$-Clifford generators. Then we have $\Gamma_{i,k}$ is symmetric (that is $\Gamma_{i,k}\T = \Gamma_{i,k}$) for all odd $i$, and is otherwise antisymmetric. The number of such odd integers is congruent to $0 \pmod 4$. These generators play the role of the $b_i$'s in Part (1) of Lemma~\ref{transpose}. So we can replace $\Gamma_{i,k}$ for odd $i$ with $\widetilde{\Gamma}_{i,k}$ which are skew-symmetric. This produces the set of $k$-Clifford generators $\Up_{1,k}, \dots, \Up_{k,k}$ as displayed in Construction~\ref{construction}, and they are all skew-symmetric by construction.

Now if $k \equiv 1 \pmod 8$, then the set of standard Clifford generators that are skew-symmetric is those with even index, and this number is congruent to $0 \pmod 4$. Using Part (2) of Lemma~\ref{transpose} this time, those can be replaced with symmetric Clifford generators, to form a full list $\Up_{1,k}, \dots, \Up_{k,k}$ of self-adjoint complex Clifford generators that are symmetric.

Let $k \equiv 3 \pmod 8$ and $\Gamma_{1,k}, \dots, \Gamma_{k,k}$ be the standard list of self-adjoint complex $k$-Clifford generators. 
Then we have
$\Gamma_{i,k}\sT = \Gamma_{i,k}$ for $i$ that happen to be both odd and $i \geq 5$. The number of such indices is a multiple of 4, so using Lemma~\ref{sharp} we can replace these to obtain a full list of self-adjoint complex $k$-Clifford generators that satisfy
$\Up_{i,k}\sT = -\Up_{i,k}$.

Finally, if $k \equiv 5 \pmod 8$ then the standard list of self-adjoint complex $k$-Clifford generators can be modified, again using Lemma~\ref{sharp}, so that they all satisfy
$\Up_{i,k}\sT = \Up_{i,k}$, as desired. In this case, the Clifford generators that are modified are the ones with with $i$ even, as well as $i = 1,3$. The number of such generators is a multiple of 4 in this case.
\end{proof}

\begin{thm} \label{thm:KO}
Suppose that $k$ is odd. 
In each of the four real cases, the unitaries defined in Construction~\ref{construction} satisfiy the right symmetries so that  $[Q\pr_{k-1}] \in KO_{k+1}(\fS^{k-1}) = \Z$ and $[U\pr_k] \in KO_{k+2}(\fS^k) = \Z$. 
\end{thm}


\begin{proof}
First, it is easy to check that $Q\pr_{k-1}$ is a self-adjoint unitary and that $U\pr_k$ is a unitary in each case, from the fact that
$\Up_{i,k}$ are self-adjoint unitaries.

In the case $k \equiv -1 \pmod 8$, the Clifford generators $\Up_{1, k}, \dots, \Up_{k,k}$ are anti-symmetric. Hence
\begin{align*}
	(Q\pr_{k-1}) \Ttau(x)   
		&= \left( \sum_{i = 1}^k x_i \Up_{i,k} \right) \Ttau \\
		&= \sum_{i = 1}^{k} (-x_i) \Up_{i,k}\T\\
		&= \sum_{i = 1}^{k} (-x_i) ( - \Up_{i,k}) \\
		&= Q\pr_{k-1} (x) \;  \\
\text{and} \quad 
	(U\pr_k)\Ttau(x)   
		&= \left( \,  \sum_{i = 1}^{k} x_i \Up_{i,k}  + x_{k+1} i \, I_n \right) \Ttau \\
		&= \left( \,  \sum_{i = 1}^{k} (-x_i) (-\Up_{i,k})  + (-x_{k+1}) i \, I_n \right)  \\
		&= \left( \,  \sum_{i = 1}^{k} x_i \Up_{i,k} - x_{k+1} i \, I_n \right)  \\
		&= (U\pr_k)^*(x) \; .
\end{align*}
Therefore $[Q\pr_{k-1}] \in KO_0(\fS^{k-1})$ and $[U\pr_{k}] \in KO_1(\fS^{k})$.

Now, assume that $k \equiv 1 \pmod 8$. Then the Clifford generators $\Up_{1, k}, \dots, \Up_{k,k}$ are symmetric, so we have
\begin{align*}
	(Q\pr_{k-1})\Ttau(x)   
		&= \left( \sum_{i = 1}^k x_i \Up_{i,k} \right) \Ttau \\
		%&= \sum_{i = 1}^{k} (-x_i) \Up_{i,k}\T\\
		&= \sum_{i = 1}^{k} (-x_i) (  \Up_{i,k}) \\
		&= -Q\pr_{k-1} (x) \;  \\
\text{and} \quad 
	(U\pr_k)\Ttau(x)   
		&= \left( \,  \sum_{i = 1}^{k} x_i \Up_{i,k}  + x_{k+1} i \, I_n \right) \Ttau \\
		&= \left( \,  \sum_{i = 1}^{k} (-x_i) (\Up_{i,k})  + (-x_{k+1}) i \, I_n \right)  \\
		%&= \left( \, -  \sum_{i = 1}^{k} x_i \Up_{i,k} - x_{k+1} i \, I_n \right)  \\
		&= -U\pr_k(x) \; .
\end{align*}
It follows that $[Q\pr_{k-1}] \in KO_2(\fS^{k-1})$ and $[U\pr_{k}] \in KO_3(\fS^{k})$ (and note that here we are using the new alternate formulation of $KO_3(-)$ in terms of unitaries).

In the third case, $k \equiv 3 \pmod 8$, the elements $\Up_{1, k}, \dots, \Up_{k,k}$ satisfy $\Up_{i,k}\sT = - \Up_{i,k}$. Thus
\begin{align*}
	(Q\pr_{k-1}) \sTtau(x)   
		&= \left( \sum_{i = 1}^k x_i \Up_{i,k} \right) \sTtau \\
		&= \sum_{i = 1}^{k} (-x_i) \Up_{i,k}\sT\\
		&= \sum_{i = 1}^{k} (-x_i) ( - \Up_{i,k}) \\
		&= Q\pr_{k-1} (x) \;  \\
\text{and} \quad 
	(U\pr_k)\sTtau(x)   
		&= \left( \,  \sum_{i = 1}^{k} x_i \Up_{i,k}  + x_{k+1} i \, I_n \right) \sTtau \\
		%&= \left( \,  \sum_{i = 1}^{k} (-x_i) (-\Up_{i,k})  + (-x_{k+1}) i \, I_n \right)  \\
		&= \left( \,   \sum_{i = 1}^{k} x_i \Up_{i,k} - x_{k+1} i \, I_n \right)  \\
		&= (U_k\pr)^*(x) \; .
\end{align*}
Thus $[Q\pr_{k-1}] \in KO_4(\fS^{k-1})$ and $[U\pr_{k}] \in KO_5(\fS^{k})$.

Finally, if $k \equiv 5 \pmod 8$ we have $\Up_{i,k}\sT = \Up_{i,k}$ for all $i$ so
\begin{align*}
	(Q\pr_{k-1}) \sTtau(x)   
		&= \left( \sum_{i = 1}^k x_i \Up_{i,k} \right) \sTtau \\
		%&= \sum_{i = 1}^{k} (-x_i) \Up_{i,k}\sT\\
		&= \sum_{i = 1}^{k} (-x_i) (  \Up_{i,k}) \\
		&= -Q\pr_{k-1} (x) \;  \\
\text{and} \quad 
	(U\pr_k)\sTtau(x)   
		&= \left( \,  \sum_{i = 1}^{k} x_i \Up_{i,k}  + x_{k+1} i \, I_n \right) \Ttau \\
		&= \left( \,  \sum_{i = 1}^{k} (-x_i) (\Up_{i,k})  + (-x_{k+1}) i \, I_n \right)  \\
		&= -U\pr_k(x) \; .
\end{align*}
It follows that $[Q\pr_{k-1}] \in KO_6(\fS^{k-1})$ and $[U\pr_{k}] \in KO_{-1}(\fS^{k})$ (and note that here we are again using the new alternate formulation of $KO_{-1}(-)$ in terms of unitaries).
\end{proof}

\begin{proof}[Proof of Theorem~\ref{main-thm}]
Recall that the complexification map 
$$c_{k+1} \colon \widetilde{KO}_{k+1}(\fS^{k-1}) \rightarrow \widetilde{KU}_{k+1}(\fS^{k-1})$$ is defined by forgetting the extra symmetry that a self-adjoint unitary representing real $K$-theory must satisfy. In this case at hand, $c_{k+1}$ is known to be an isomorphism, because of the structure of the free $\mathcal{CR}$-module, namely that
$\widetilde{K}_*\crr(\fS^{k-1})$ is a free $\mathcal{CR}$-module with generator in $\widetilde{KO}_{k+1}(\fS^{k-1})$.
From Proposition~1 of \cite{SBS} we know that $[Q_{k-1}]$ represents a generator of 
$\widetilde{KU}_{k+2}(\fS^{d}) = \Z$. It follows that
$[Q\pr_{k-1}]$ must be a generator of $\widetilde{KO}_{k+1}(\fS^{k-1})$. A similar argument shows that
$[U\pr_k]$ is a generator of $\widetilde{KO}_{k+2}(\fS^{k})$.
\end{proof}

\section{Appendix: An alternative unitary picture for $KO_{-1}$ and $KO_3$.} \label{newunitaries}

In Table~\ref{unitaryTable} describing the unitary picture of $KO_i(A, \tau)$, there are alternative symmetry relations given for $KO_{-1}(A, \tau)$ and for $KO_{3}(A, \tau)$, which are different than those developed in \cite{BL}. In this section we will prove that the two unitary pictures of $KO$-theory in these cases are equivalent.

\begin{lemma}
Let $w = \left( \begin{smallmatrix} 0 & -1 \\ 1 & 0 \end{smallmatrix} \right)$. Then for any $x \in M_2(\C)$ we have 
\begin{enumerate}
\item $x^\sharp = w^* x^{\rm{Tr}} w$ 
\item $x^{\rm{Tr}} = w x^{\sharp} w^*$
\item $x^\sharp = w x^{\rm{Tr}} w^*$ 
\item $x^{\rm{Tr}} = w^* x^{\sharp} w$
\end{enumerate} \end{lemma}

\begin{proof}
The first statement follows from direct computation on $x = \left( \begin{smallmatrix} a & b \\ c & d \end{smallmatrix} \right)$. Statement (3) follows from Statement (1) and the fact that $w^2 = -1_2$, which is in the center of $M_2(\C)$, by
\begin{align*}
x^\sharp &= w^2 x^\sharp (w^*)^2 \\
	&= w^2 (w^* x^{\rm{Tr}} w) (w^*)^2 \\
	&= w x^{\rm{Tr}} w^*  \; .
\end{align*}
Statements (2) and (4) follow immediate from Statements (1) and (3) by conjugation.
\end{proof}

\begin{lemma} \label{lemma-sharp/trace}
Let $(A, \tau)$ be a $C \sp *$-algebra with antimultiplicative involution. Let $w = \left( \begin{smallmatrix} 0 & 1 \\ -1 & 0 \end{smallmatrix} \right)$.
Then a unitary $u \in M_2(A)$ satisfies
$u\Ttau =  u$ if and only if $v = u w$ satisfies $v\stau = - v$.
Furthermore, a unitary $u \in M_2(A)$ satisfies
$u\Ttau =  -u$ if and only if $v = u w$ satisfies $v\stau =  v$.
\end{lemma}

We also note that the same statements of Lemma~\ref{lemma-sharp/trace} remain true if we instead use $w = \left( \begin{smallmatrix} 0 & -1 \\ 1 & 0 \end{smallmatrix} \right)$.

\begin{proof}
Suppose that $u$ satisfies $u\Ttau = u$. Then
\begin{align*}
v\stau &= (uw)\stau \\
	&= w^\sharp u\stau \\
	&= -w (w^* u\Ttau w) \\	
	&= -u\Ttau w \\
	&= -v \;.
\end{align*}
This proves the forward implication of the first statement. The other statements are proven by similarly.
\end{proof}

\begin{prop} \label{prop-K(-1)}
Let $A$ be a real unital $C \sp *$-algebra. Then $KO_{-1}(A)$ is isomorphic to the group of homotopy classes of unitaries in 
$\cup_{n \in \N} M_{2n}(A_\C)$ that satisfy $v\stau = -v$, subject to the relation
$$[v] = \left[ \diag\left(v,\sm{0}{\1}{-\1}{0} \right) \right] \; .$$
\end{prop}

\begin{proof}
Let $A$ be given. Then we know from \cite{BL} (as indicated in Table~\ref{unitaryTable}) that $KO_{-1}(A)$ is isomorphic to the group of homotopy classes of unitaries $u$ in 
$\cup_{n \in \N} M_{2n}(A_\C)$ that satisfy $u\Ttau = u$, subject to the relation
$$[u] = \left[ \diag\left(u, 1_2\right) \right] \; .$$
Now if $u$ is such a unitary, then $v = uw$ satisfies $v\stau = -v$ by Lemma~\ref{lemma-sharp/trace}. Furthermore, if $u = 1_2$, then we have $v = 1_2 \cdot w = \sm{0}{\1}{-\1}{0}$. Hence the $[u] \mapsto [uw]$ is a well-defined map from $KO_{-1}(A)$ to the group described in the Proposition.

Conversely, if $v$ is a unitary that satisfies $v\stau = -v$, then $u = v(-w)$ satisfies $u \Ttau = u$, again by Lemma~\ref{lemma-sharp/trace}. So $[v] \mapsto [-vw]$ is a map from the group described in the Proposition to $KO_{-1}(A)$.

Now $w(-w) = 1_2$, so it follows that these two group homomorphisms are mutual inverses.
\end{proof}

\begin{prop} \label{prop-K(3)}
Let $A$ be a real unital $C \sp *$-algebra. Then $KO_{3}(A)$ is isomorphic to the group of homotopy classes of unitaries in 
$\cup_{n \in \N} M_{2n}(A_\C)$ that satisfy $u\Ttau = -u$, subject to the relation
$$[u] = \left[ \diag\left(u,\sm{0}{\1}{-\1}{0} \right) \right] \; .$$
\end{prop}

\begin{proof}
The map $[u] \mapsto [uw]$ provides an isomorphism from the previous picture $KO_3(A)$ from \cite{BL} to the picture described in the Proposition. The proof is similar to the proof of Proposition~\ref{prop-K(-1)}, relying on Lemma~\ref{lemma-sharp/trace}.
\end{proof}

