    \caption{Example of output generated by \Cref{alg:alg} for a single iteration of the main loop.}
    \label{fig:dominance}
\end{figure}

\begin{lemma}\label{lem:alg}
    Let $(V^\star_1,V^\star_2,\dots,V^\star_b)$ be any $b$-tuple of disjoint subsets of $[n]$. The output $(V_1,V_2,\dots,V_b)$ of \Cref{alg:alg} when given $|V^\star_i|\geq 1/\eps$ for $i \in [b]$, and $m(V^\star_i,j)$ for $i \in [b]$ and $j \in [1/\eps-1]$ satisfies \[
    \bigcup_{i'=1}^i V_{i'} \succeq \bigcup_{i' =1}^i V^\star_{i'} 
    \]
    and $|V_i| \leq (1+2\eps)|V^\star_i|$ for all $i \in [b]$.
\end{lemma}

\begin{proof} 
    We start by observing that $|V_i| \leq (1+2\eps)|V_i^\star|$ holds for all $i \in [b]$ as at most \[
    \eps|V_i^\star| + \left(\frac{1}{\eps}-1\right)\eps|V_i^\star| + \lceil\eps|V_i^\star|\rceil \leq (1+\eps)|V_i^\star| + 1 \leq (1+2\eps)|V_i^\star|
    \]
    elements are added to $V_i$, where the last inequality holds as $|V_i| \geq 1/\eps$.

    We now show that $\bigcup_{i'=1}^i V_{i'} \succeq \bigcup_{i' =1}^i V^\star_{i'}$ by induction on $i$. Denote $V_0 = V^\star_0 = \emptyset$ such that the base case $V_0 \succeq V^\star_0$ is trivial. Let $i \geq 1$ and suppose that $\bigcup_{i'=0}^{i-1} V_{i'} \succeq
    \bigcup_{i'=0}^{i-1} V^\star_{i'}$. Let $V = \bigcup_{i'=0}^{i} V_{i'}$ and let $V^\star =
    \bigcup_{i'=0}^{i} V^\star_i$. We must show that $V \succeq V^\star$. We claim the following.

    \bigskip

    \begin{claim}\label{claim:alg}
        For any $h \in [n] \setminus V$, we have 
        \begin{itemize}
        \item[(i)]$|V_i \cap [k]| \geq |V_i^\star \cap [h]|$ and 
        \item[(ii)] $|V_i \cap \{n,n-1,\dots,h\}]| \geq |V_i^\star \cap \{n,n-1,\dots,h\}|$
        \end{itemize}
    \end{claim}
    \begin{proof}[Proof of \Cref{claim:alg}]

    Consider any $h \in [n] \setminus V$. Let \[
    M = |\{j \in [1/\eps-1] \mid m(V_i^\star,j) < h\}|
    \]
    be the number of milestones smaller than $h$. Note that $h$ itself cannot be a milestone as any milestone is added to $V_i$ on line~\ref{line:loop1-add} after $c$ is incremented by at least $1$ on line~\ref{line:loop1-inc}.

    We start by observing that \begin{equation}
    \label{eq:capbound}
       \lfloor M\eps|V_i^\star|\rfloor \leq |V_i^\star \cap [h-1]| \leq |V_i^\star \cap [h]| \leq \lfloor(M+1)\eps|V_i^\star|\rfloor,
    \end{equation}
    which follows directly from the definition of milestones and the fact that $h$ is not a milestone. See \Cref{fig:claima}.

    \begin{figure}
        \centering
        \input{lemma11fig}
        \caption{Illustration of the setup in the proof of \Cref{claim:alg}. Shaded boxes indicate elements in the corresponding set.}
        \label{fig:claima}
    \end{figure}

    To show (i), consider the iteration of the forward loop where $f = h$. As $h \notin V$, $h$ was not added to $V_i$ on line~\ref{line:loop1-add}, implying that $c < 1$ on line~\ref{line:loop1-check}. As $c$ is initially $\eps|V_i^\star|$ and was incremented by $M\eps|V_i^\star|$ before this iteration, we must have \[
    |V_i \cap [h]| = \lfloor (M+1)\eps|V_i^\star|\rfloor \geq |V_i^\star \cap [h]|,
    \]
    where the last inequality follows from \Cref{eq:capbound}.

    Define $h' = n-h+1$ such that $[-h'] = \{n,n-1,\dots,h\}$.
    To show (ii), consider the iteration of the backward loop where $f=h$. As $h \notin V$, $h$ was not added to $V_i$ on line~\ref{line:loop2-add}, implying that $c < 1$ in this iteration. In fact, we must have $c=0$ as the fractional increments of $c$ sum to $\eps|V_i^\star| + (1/\eps-1)\eps|V_i^\star| = |V_i^\star|$ and $c$ is only ever decremented by $1$. Since $c$ was incremented by $(1/\eps-1-M)\eps|V_i^\star|+\lceil\eps|V_i^\star|\rceil$ between the iteration of the forward loop where $f=h$ and the iteration of the backward loop where $f=h$, we must have \[
    |V_i \cap [-h']| \geq (1/\eps-1-M)\eps|V_i^\star| + \lceil\eps|V_i^\star|\rceil
    \]
    We see that also
    \begin{equation*}
    |V_i^\star \cap [-h']| = |V_i^\star| - |V_i^\star \cap [h-1]| \leq |V_i^\star| - \lfloor M\eps|V_i^\star|\rfloor
    \end{equation*}
    where we use \Cref{eq:capbound} in the second inequality. Subtracting the above two inequalities we get
    \begin{align*}
    |V_i^\star \cap [-h']|-|V_i \cap [-h']| &\leq  |V_i^\star| - \lfloor M\eps|V_i^\star|\rfloor - (1/\eps-1-M)\eps|V_i^\star| - \lceil\eps|V_i^\star|\rceil \\
    &= (M+1)\eps|V_i^\star| - \lceil\eps|V_i^\star|\rceil - \lfloor M\eps|V_i^\star|\rfloor \\
    &< 1,
    \end{align*}
    from which it follows that $|V_i^\star \cap [-h']|-|V_i \cap [-h']| \leq 0$ as both terms are integers.
    \renewcommand{\qedsymbol}{$\diamond$}
    \end{proof}

    We return to the proof of the lemma. 
    Suppose that $|V \cap [h]| < |V^* \cap [h]|$ for some $h \in [n]$ and let $h$ be minimal with this property. By the minimality of $h$, we must have $h \notin V\supseteq V_i$. By the induction hypothesis and \Cref{claim:alg}, \begin{align*}
    |V \cap [k]| &= |(V \setminus V_i) \cap [h]| + |V_i \cap [h]| \\
                     &\geq |(V^\star \setminus V^\star_i) \cap [h]| + |V^\star_i \cap [h]| \\
                     &= |V^\star \cap [h]|,
    \end{align*}
    which is a contradiction.

    Suppose that $|V \cap [-h']| < |V^* \cap [-h']|$ for some $h' \in [n]$ and let $h'$ be minimal with this property. Let $k=n-h'+1$. Then $h \notin V$. By the induction hypothesis and \Cref{claim:alg}, \begin{align*}
    |V \cap [-h']| &= |(V \setminus V_i) \cap [-h']| + |V_i \cap [-h']| \\
                     &\geq |(V^\star \setminus V^\star_i) \cap [-h']| + |V^\star_i \cap [-h']| \\
                     &= |V^\star \cap [-h']|,
    \end{align*}
    which is again a contradiction.
\end{proof}

\Cref{lem:pq} now follows relatively directly by combining the last two lemmas with full enumeration.

\begin{proof}[Proof of~\Cref{lem:pq}] We need to distinguish a few cases, to cover cases in which we cannot apply \Cref{lem:alg} and \Cref{lem:ann}:
    \begin{itemize}[leftmargin=2cm]
        \item[Case 1:] $a<4(1+\eps)/\eps^2+1$. In this case we can in time $n^{O_\eps(a'/a)}$ fully enumerate all partial policies of length $a'$, showing the claim, even without the $1+\eps$ factor.
        \item[Case 2:] $a\geq 4(1+\eps)/\eps^2+1$. This implies that $a\geq 2(1+\eps)^{2}/\eps$ (using $1/\eps\in\mathbb{N}$), which is needed to apply \Cref{lem:ann}. The same assumption allows us to define $|V_1^\star|=\lfloor (a-1)/(1+2\eps)\rfloor$ and get that $\eps|V_1^\star|\geq 2/\eps$.

        \begin{itemize}
            \item[Case 2a:] $a'-\lfloor (a-1)/(1+2\eps)\rfloor<2/\eps$. We will run into trouble defining bucket sizes so as to apply \Cref{lem:alg}. Since $a$ may be too large, we cannot simply enumerate all partial policies of length $a'$. We define $b=2$ and $|V_2^\star|=a'-|V_1^\star|$. We apply full enumeration to obtain $m(V^\star_1,j)$ for all $j \in [1/\eps-1]$. We obtain $V_1$ by \Cref{alg:alg} and $V_2$ by full enumeration, in total time $n^{O_\eps(1)}$. Then, for the correct elements from the enumerations, \Cref{lem:alg} guarantees that also the dominance condition needed to apply \Cref{lem:ann} is fulfilled.
            \item[Case 2b:] $a'-\lfloor (a-1)/(1+2\eps)\rfloor\geq 2/\eps$. We define $|V_2^\star|,\dots,|V_b^\star|$ in the following way: Start with a counter with value equal to the total size of $|V_2^\star|,\dots,|V_b^\star|$, which, by definition of $|V^\star_1|$, is $a'-\lfloor (a-1)/(1+2\eps)\rfloor\geq 2/\eps$. Open a new bucket of size $1/\eps$ and decrease the counter by $1/\eps$ until the value of the counter drops to $2/\eps$ or less. Define the final ($b$-th) bucket to have size of the current value of the counter. This way, $1/\eps\leq |V_i^\star|\leq 2/\eps\leq \eps|V_1|$ for all $i\in[b]$, and $b\in O_\eps(a'/a)$. We may thus enumerate $m(V^\star_i,j)$ for all $i\in[b]$ and $j \in [1/\eps-1]$, in time $n^{O_\eps(a'/a)}$, and apply \Cref{lem:alg} to each element in the enumeration. For the correct element from the enumeration, we may then also apply \Cref{lem:ann}.
        \end{itemize}
    \end{itemize}
    Note that, in Cases 2a and 2b, we need to scale down $\eps$ by a constant to obtain the necessary guarantee from the application of \Cref{lem:ann}.
\end{proof}

\section{Conclusion}

First, it remains as an open question whether there also exists a PTAS for the arbitrary-cost case. 
It seems plausible that one can use standard techniques to get the number of relevant cost classes per bucket down to a logarithmic number and to then use a similar approach as described in \Cref{subsec:bounded} for each cost class, which would result in a QPTAS. It is unclear to us whether this approach can be modified to obtain a PTAS. 

Second, recall that it is not known whether computing the optimal non-adaptive policy for SBFE of $k$-of-$n$ functions is NP-hard, even in the arbitrary-cost case. Although there are many problems in stochastic combinatorial optimization with this status, and it is common to develop approximation algorithms for them, that fact may be particularly intriguing for this fundamental problem.


