\lemratio*

\begin{proof}
    Recall that there are $n = 2m+2t$ variables in the instance $L_{m,t,\eps}$ and the function value is determined when we find at least $k = m+t$ $1$s or at least $n-k+1$ $0$s.
    Let $F$ be the event that $X-m \in [-t,t-1]$.
    By the law of total expectation
    \begin{equation}\label{eq:cost}
        \frac{\E[\cost(\pi)]}{\E[\cost(\pi')]} =
        \frac{\E[\cost(\pi) \mid
            \overline{F}]\Pr[\overline{F}]+\E[\cost(\pi)
            \mid F]\Pr[F]}{\E[\cost(\pi') \mid
            \overline{F}]\Pr[\overline{F}]+\E[\cost(\pi')\mid F]\Pr[F]}.
    \end{equation}
    Suppose $\overline{F}$ occurs. Then either $X \geq m+t$ or $X \leq m-t-1$. In the first case, the number of $1$s in $x$ is at least $X \geq m+t=k$. In the latter case, the number of $0$s in $x$ is at least $2m-X \geq 2m-(m-t-1) = (2m+t)-m+1 = n-m-t+1 = n-k+1$. In both cases, the function value is determined by any economical policy at cost $0$. Thus, $\E[\cost(\pi)
    \mid \overline{F}] = \E[\cost(\pi') \mid \overline{F}] = 0$ and
    therefore \Cref{eq:cost} simplifies to
    \[
        \frac{\E[\cost(\pi)]}{\E[\cost(\pi')]} =
        \frac{\E[\cost(\pi) \mid F]}{\E[\cost(\pi') \mid
            F]},
    \]
    as desired.
\end{proof}

\lembinomial*

\begin{proof}
    Fix an integer $c$ and $i \in [-c,c-1]$. Now, for any positive integer
    $a \geq c$
    \begin{align}\label{eq:recip} 
        \nonumber\Pr[X_{2a}-a = i \mid X_{2a}-a \in [-c,c-1]] &= \frac{\Pr[X_{2a}-a
        = i]}{\Pr[X_{2a}-a \in [-c,c-1]]} \\
                     &= \frac{\binom{2a}{a+i}}{\sum_{j=-c}^{c-1} \binom{2a}{a+j}}.
    \end{align}
    We show that the reciprocal of \Cref{eq:recip} converges to $2c$
    as $a \rightarrow \infty$ and the lemma follows by the quotient law for limits. We see that
    \begin{equation}
        \label{eq:sum}
        \frac{\sum_{j=-c}^{c-1} \binom{2a}{a+j}}{\binom{2a}{a+i}} =
        \sum_{j=-c}^{c-1} \frac{\binom{2a}{a+j}}{\binom{2a}{a+i}} =
        \sum_{j=-c}^{c-1} \frac{(a+i)!(a-i)!}{(a+j)!(a-j)!}.
    \end{equation}

    Now, we show that every term in \Cref{eq:sum} converges to $1$ as $n
    \rightarrow \infty$ and the lemma follows from the sum law for limits.
    Consider a fixed integer $j \in [-c,c-1]$. We see that 
    \begin{equation}
        \label{eq:frac}
        \frac{(a+i)!(a-i)!}{(a+j)!(a-j)!} 
    \end{equation}
    equals $1$ when $j=i$ and can otherwise be expressed as the product of
    $|i-j|$ fractions of the form $(a+c_1)/(a+c_2)$ where $c_1,c_2 \in
    [-c,c-1]$. Using this observation and the product law for limits, we see that \Cref{eq:frac} converges to $1$ as $a
    \rightarrow \infty$ for any fixed $j \in [-c,c-1]$. This completes the
    proof of the lemma.
\end{proof}

