Note that we have worked on biquandle colorings of prime virtual knotoids in our examples so far. Given any two knotoid diagrams $K_1$, $K_2$, and two $X$-colorings of $K_1$ and $K_2$, respectively. It is clear that the $X$-colorings of $K_1$ and $K_2$ can be extended to a unique $X$-coloring of the product $K_1K_2$ if the head semi-arc of $K_1$ has the same color as the tail semi-arc of $K_2$. The following corollaries follow easily from this observation.

\begin{corollary}
  Let $X=\{x_1,...,x_n\}$ be a biquandle, and $K_1$ and $K_2$ be two virtual knotoid diagrams. We have, 
    \[ \Phi_{X_{ik}}^{\mathbb{Z}}(K_1K_2)=\Phi_{X_{ij}}^{\mathbb{Z}}(K_1) \Phi_{X_{jk}}^{\mathbb{Z}}(K_2),\]
    for all $i,j,k\in \{1,...,n\}.$
\end{corollary}

    \begin{corollary}

     (Proven in \cite{gugumcu2021biquandle} for classical knotoids.)
        Let $K_1$ and $K_2$ be two virtual knotoid diagrams. Then for any finite biquandle $X$, the biquandle counting matrix of $K_1K_2$ is the matrix product of the biquandle counting matrices of $K_1$ and $K_2$, i.e.
        \[\mathcal{M}_X(K_1K_2)=\mathcal{M}_X(K_1)\mathcal{M}_X(K_2).\]
    \end{corollary}

    \section{Biquandle Virtual Brackets and Virtual Knotoids}
    \label{bvbs}moo

    Biquandle virtual brackets were introduced by Nelson in \cite{nelson2019biquandle} as a generalization of biquandle brackets in \cite{nelson2017quantum} to oriented virtual knots and links.


    A biquandle virtual bracket is defined as follows. 

\begin{definition}\label{defn:biquandlebracket}
		Let $X$ be a biquandle and $R$ be a commutative, unitary ring. A \textit{biquandle} \textit{X-virtual bracket}, denoted by $\beta$, consists of maps $A,B,V,C,D,U:X\text{ x }X\rightarrow R$ and two elements $\delta\in R$, $\omega\in R^{\text{x}}$ such that for all $x,y,z\in X$ the following equations $(1)-(23)$ hold, where for all $x,y\in X$ and $F\in\{A,B,V,C,D,U\}$,  $F(x,y)$ is denoted by $F_{x,y}$, and for convenience, $x\un y$ and $x\ovr y$ are denoted by $x^y$ and $x_y$, respectively. We name the maps $A,B,V,C,D,U$ as \textit{coefficient maps}.
		\begin{align}
			\omega&=&&\hspace{-4.2cm}\delta A_{x,x}+B_{x,x}+V_{x,x},\\
			\omega^{-1}&=&&\hspace{-4.2cm}\delta C_{x,x}+D_{x,x}+U_{x,x},\\
			1&=&& \hspace{-4.2cm}A_{x,y}C_{x,y}+V_{x,y}U_{x,y},\\
			1&=&& \hspace{-4.2cm}B_{x,y}D_{x,y}+V_{x,y}U_{x,y},\\
			0&=&& \hspace{-4.2cm}A_{x,y}U_{x,y}+V_{x,y}C_{x,y},\\
			0&=&& \hspace{-4.2cm}B_{x,y}U_{x,y}+V_{x,y}D_{x,y},\\
			0&=&&\hspace{-4.2cm}\delta B_{x,y}D_{x,y}+A_{x,y}D_{x,y}+B_{x,y}C_{x,y},\\
			0&=&&\hspace{-4.2cm}\delta A_{x,y}C_{x,y}+A_{x,y}D_{x,y}+B_{x,y}C_{x,y},
        \end{align}
        \begin{align}
			A_{x,y} A_{x^y,z_y} A_{y,z}+V_{x,y} A_{x^y,z_y} V_{y,z}&=&&\hspace{-1.4cm}A_{y_x,z_x} A_{x,z} A_{x^z,y^z}+V_{y_x,z_x} A_{x,y} V_{x^z,y^z}\\
			A_{x,y} A_{x^y,z_y} B_{y,z}+B_{x,y} A_{x^y,z_y} A_{y,z}&&&\notag\\
			+\delta B_{x,y} A_{x^y,z_y} B_{y,z}+B_{x,y} A_{x^y,z_y} V_{y,z}&&&\notag\\
			+B_{x,y} B_{x^y,z_y} B_{y,z}+A_{x,y} V_{x^y,z_y} B_{y,z}&&&\notag\\
			+V_{x,y} A_{x^y,z_y} B_{y,z}&=&&\hspace{-1.4cm}A_{y _x,z_x} B_{x,z} B_{x^z,y^z}\\
			A_{x,y} B_{x^y,z_y} B_{y,z}&=&&\hspace{-1.4cm}A_{y_x,z_x} A_{x,z} B_{x^z,y^z}+B_{y_x,z_x} A_{x,z} A_{x^z,y^z}\notag\\
			&&&\hspace{-1.4cm}+\delta B_{y_x,z_x} A_{x,z} B_{x^z,y^z}+B_{y_x,z_x} A_{x,z} V_{x^z,y^z}\notag\\
			&&&\hspace{-1.4cm}+B_{y_x,z_x} B_{x,z} B_{x^z,y^z}+B_{y_x,z_x} V_{x,z} B_{x^z,y^z}\\
			%&&&\hspace{-1.4cm}+V_{y_x,z_x} A_{x,z} B_{x^z,y^z}\\
			A_{x,y} V_{x^y,z_y} A_{y,z}&=&&\hspace{-1.4cm}A_{y_x,z_x} A_{x,z} V_{x^z,y^z}+V_{y_x,z_x} A_{x,z} A_{x^z,y^z}\\
			A_{x,y} A_{x^y,z_y} V_{y,z}+V_{x,y} A_{x^y,z_y} A_{y,z}&=&&\hspace{-1.4cm}A_{y_x,z_x} V_{x,z} A_{x^z,y^z}\\
			B_{x,y} B_{x^y,z_y} A_{y,z}+B_{x,y} V_{x^y,z_y} V_{y,z}&=&&\hspace{-1.4cm}A_{y_x,z_x} B_{x,z} B_{x^z,y^z}+V_{y_x,z_x} V_{x,z} B_{x^z,y^z}\\
			A_{x,y} B_{x^y,z_y} B_{y,z}+V_{x,y} V_{x^y,z_y} B_{y,z}&=&&\hspace{-1.4cm}B_{y_x,z_x} B_{x,z} A_{x^z,y^z}+B_{y_x,z_x} V_{x,z} V_{x^z,y^z}\\
			B_{x,y} B_{x^y,z_y} V_{y,z}+B_{x,y} V_{x^y,z_y} A_{y,z}&=&&\hspace{-1.4cm}A_{y_x,z_x} B_{x,z} V_{x^z,y^z}\\
			A_{x,y} B_{x^y,z_y} V_{y,z}&=&&\hspace{-1.4cm}B_{y_x,z_x} B_{x,z} V_{x^z,y^z}+B_{y_x,z_x} V_{x,z} A_{x^z,y^z}\\
		V_{x,y} B_{x^y,z_y} A_{y,z}&=&&\hspace{-1.4cm} A_{y_x,z_x} V_{x,z} B_{x^z,y^z}+V_{y_x,z_x} B_{x,z} B_{x^z,y^z}\\
			A_{x,y} V_{x^y,z_y} B_{y,z}+V_{x,y} B_{x^y,z_y} B_{y,z}&=&&\hspace{-1.4cm}V_{y_x,z_x} B_{x,z} A_{x^z,y^z}\\
			V_{x,y} V_{x^y,z_y} A_{y,z}&=&&\hspace{-1.4cm}A_{y_x,z_x} V_{x,z} V_{x^z,y^z}\\
			A_{x,y} V_{x^y,z_y} V_{y,z}&=&&\hspace{-1.4cm}V_{y_x,z_x} V_{x,z} A_{x^z,y^z}\\
			V_{x,y} B_{x^y,z_y} V_{y,z}&=&&\hspace{-1.4cm}V_{y_x,z_x} B_{x,z} V_{x^z,y^z}\\
			V_{x,y} V_{x^y,z_y} V_{y,z}&=&&\hspace{-1.4cm}V_{y_x,z_x} V_{x,z} V_{x^z,y^z}
		\end{align}
	\end{definition} 

   A biquandle virtual bracket invariant of biquandle colored virtual knots is defined in analogy with the Kauffman bracket by Nelson in $\cite{nelson2019biquandle}$. We utilize/mimic this idea to construct biquandle virtual bracket invariant of virtual knotoids as follows.

    Let $X$ be a biquandle, $R$ be a commutative ring with unit element, and $K_f$ be an oriented virtual knotoid diagram with $n$ crossings that is endowed with an $X$-coloring $f$. By first ignoring the orientation on $K_f$, each classical crossing of $K_f$ is replaced by either vertical or horizontal strands as in the Kauffman bracket, or by a virtual crossing as shown in Figure \ref{smooth}. Each of these replacements is called a \textit{smoothing} of the crossing. We specifically call the virtual crossing replacement a \textit{virtual smoothing}. 

