\section*{Appendix}
\subsection*{Kernel gradient correction for axisymmetric CSPH method}\label{A}
Let us analyze the approximation errors of the contact axisymmetric SPH method in the same way as it was done in~\cite{Rublev2024} for the Cartesian case. For this purpose, a Taylor series expansion of the expressions whose derivatives are evaluated using SPH sums is performed in the neighborhood of the point $\mathbf{r}_a$. The contact values are considered in the acoustic approximation (\ref{RazpadP}-\ref{RazpadU}).

After Taylor series expansion, the following expressions are obtained:
\begin{equation}\label{axisymmetric-csph-Teylor-continuity}
	\frac{d\varepsilon_a}{dt} = 
	\left(\boldsymbol{\nabla}\otimes\mathbf{U}_a\right) : \mathbf{L}_a  + \frac{U^r_a}{r_a} - \frac{1}{Z_a}\boldsymbol{\nabla} P_a \cdot \sum\limits_b v_br_{ab}\boldsymbol{\nabla}_aW_{ab} + O(h),
\end{equation}

\begin{multline}\label{axisymmetric-csph-Teylor-momentum}
	\frac{d\mathbf{U}_a}{dt} = 
	-\frac{2P_a}{\rho_a}\sum\limits_bv_b\boldsymbol{\nabla}_aW_{ab} - \frac{1}{\rho_a}\mathbf{L}_a\cdot\left(\boldsymbol{\nabla} P_a + \frac{P_a}{r_a}\mathbf{e}^r\right)  + \frac{P_a}{\rho_ar_a}\mathbf{e}^r + 
	\\
	\frac{Z_a}{\rho_a} \sum\limits_bv_b \left[\left(\boldsymbol{\nabla}\otimes\mathbf{U}_a\right):\left( \mathbf{e}^R_{ba}\otimes (\mathbf{r}_b - \mathbf{r}_a)\right)\right]\boldsymbol{\nabla}_a W_{ab} + O(h),
\end{multline}

\begin{multline}\label{axisymmetric-csph-Teylor-energy}
	\frac{dE_a}{dt} =
	-\frac{2P_a}{\rho_a}\mathbf{U}_a\cdot\sum\limits_bv_b\boldsymbol{\nabla}_aW_{ab}  + \frac{P_a}{\rho_aZ_a}\boldsymbol{\nabla} P_a\cdot\sum\limits_bv_br_{ab}\boldsymbol{\nabla}_aW_{ab}  -
	\\
	\frac{1}{\rho_a}\boldsymbol{\nabla} P_a\cdot\left(\mathbf{L}_a\mathbf{U}_a\right) - \frac{P_a}{\rho_a}\mathbf{L}_a:(\boldsymbol{\nabla}\otimes\mathbf{U}_a) - \frac{P_a}{\rho_ar_a}\mathbf{U}_a\cdot\left(\mathbf{L}_a\cdot\mathbf{e}^r\right) + 
	\\
	\frac{Z_a}{\rho_a}\sum\limits_bv_bU_a^R\left(\boldsymbol{\nabla}_a W_{ab}\otimes(\mathbf{r}_b - \mathbf{r}_a)\right):(\boldsymbol{\nabla}\otimes\mathbf{U}_a) + O(h),
\end{multline}
where $v_b = \frac{m_b}{2\pi\rho_br_b}$,
$$\mathbf{L}_a = \sum\limits_b v_b\boldsymbol{\nabla}_aW_{ab}\otimes (\mathbf{r}_b - \mathbf{r}_a).$$

Following the approach outlined in~\cite{Rublev2024} to introduce the kernel gradient correction into the equations of the CSPH method (Total Kernel Correction, TKC), one can write down the corrected equations of the ``harmonic mean'' scheme:
\begin{equation}\label{csph-normalized-continuity-axisymmetric}
	\frac{d\varepsilon_a}{dt} = -\sum\limits_{b}\frac{m_b}{2\pi\rho_b}\frac{r_a+r_b}{r_ar_b}(\overline{U}_{ab}^{*R} - \overline{U}_a^{R})\frac{W'_{ab}}{h_{ab}} + \frac{U^r_a}{ r_a},
\end{equation}
\begin{equation}\label{csph-normalized-motion-axisymmetric}
	\frac{d\mathbf{U}_a}{dt} = -\sum\limits_{b}\frac{m_b}{2\pi \rho_b\rho_a}\frac{r_a+r_b}{r_ar_b}\tilde{P}_{ab}^*\mathbf{L}_{ab}^{-1}\cdot\boldsymbol{\nabla}_aW_{ab} + \frac{P_a}{\rho_a r_a}\mathbf{e}^r.
\end{equation}
\begin{equation}\label{csph-normalized-energy-axisymmetric}
	\frac{dE_a}{dt} =
	\sum\limits_{b}\frac{m_b}{2\pi\rho_a\rho_b}\frac{r_a+r_b}{r_ar_b}\tilde{P}_{ab}^*\tilde{U}_{ab}^{*R} W'_{ab}.
\end{equation}
where $\overline{U}_a^{R} = \mathbf{U}_a\cdot \left(\mathbf{L}_{a}^{-1} \cdot\mathbf{e}^R_{ba}\right)$, $\tilde{U}_a^{R} = \mathbf{U}_a\cdot \left(\mathbf{L}_{ab}^{-1}\cdot \mathbf{e}^R_{ba}\right)$, $\mathbf{L}_{ab}^{-1} = \frac{1}{2}(\mathbf{L}_{a}^{-1} + \mathbf{L}_{b}^{-1})$.
$\overline{U}_{ab}^{*R}$, $\tilde{P}_{ab}^{*}$ and $\tilde{U}_{ab}^{*R}$ is calculated as
\begin{equation*}
	\overline{U}^{*R}_{ab} = \frac{\overline{U}_l^{R}Z_l + \overline{U}_r^{R}Z_r + (P_l - P_r)}{Z_l  + Z_r},
\end{equation*} 
\begin{equation*}
	\tilde{U}^{*R}_{ab} = \frac{\tilde{U}_l^{R}Z_l + \tilde{U}_r^{R}Z_r - P_r + P_l}{Z_l  + Z_r},
\end{equation*}
\begin{equation*}
	\tilde{P}^{*}_{ab} = \frac{P_rZ_l + P_lZ_r - Z_lZ_r\left( \tilde{U}_{r}^R - \tilde{U}_{l}^R \right)}{Z_l  + Z_r}.
\end{equation*}




