\section*{Introduction}

A discussion in \cite[paragraph preceding Proposition 2.5]{zbMATH03654393} asks whether connected Lie groups $\bG$ with dense subgroups $\Gamma\le \bG$ consisting of elements which each generate relatively-compact subgroups are necessarily compact. Motivated by this, \cite[Theorem 2]{zbMATH03975248} (also \cite[Theorem 1.6]{MR3578406}) classifies those connected Lie groups
\begin{itemize}[wide]
\item which have dense subgroups $\Gamma\le \bG$ as above;
\item are \emph{topologically perfect} in the sense of having dense derived subgroups;
\item and have no non-trivial central compact subgroups:
\end{itemize}
they are precisely the semidirect products $\bL\rtimes \bK$ with connected, simply-connected, nilpotent $\bL$ and compact, semisimple $\bK$ so that the center $Z(\bK)$ acts on $\bL$ with no non-trivial fixed point. This note extends that characterization (providing a few other equivalent ones) to arbitrary connected locally compact groups. 

For subsets $A,B\subseteq \bG$ of a group we write
\begin{equation*}
  [A,B]:=\left\{[a,b]:=aba^{-1}b^{-1}\ |\ a\in A,\ b\in B\right\}
\end{equation*}
for the set of \emph{commutators} of elements in $A$ and $B$ respectively.

We will refer freely to the notion of a \emph{(pro-)Lie algebra} $Lie(\bG)$ \cite[Definitions 2.6 and 3.10 and Theorem 3.12]{hm_pro-lie-bk} of a connected locally compact group $\bG$, for which theory we refer the reader to \cite{hm_pro-lie-bk} with more specific references where appropriate. The notation will be consistent: $\fg:=Lie(\bG)$, $\fh:=Lie(\bK)$, $\fl:=Lie(\bL)$, etc. A few more vocabulary items will help unwind the result paraphrased in abbreviated form in the abstract.

\begin{itemize}[wide]
\item A \emph{weight} of a compact group $\bK$ with respect to a complex finite-dimensional representation $\bK\xrightarrow{\rho} \mathrm{GL}(V)$ is a 1-dimensional sub-representation of the restriction $\rho|_{\bT}$ for a maximal \emph{pro-torus} (i.e. \cite[Definitions 9.30]{hm5} compact connected abelian subgroup) $\bT\le \bK_0$ of the identity component of $\bK$.

  The term applies to real representations as well, after complexification. 

\item Subsets of (always Hausdorff) topological groups are \emph{elliptic} when contained in compact subgroups, and \emph{pointwise-elliptic} when they consist of elliptic elements. 
\end{itemize}

\begin{theoremN}\label{thn:dns.ell.sbgp}
  The following conditions on a locally compact connected group $\bG$ are equivalent.

  \begin{enumerate}[(1),wide=0pt]
  \item\label{item:thn:dns.ell.sbgp:pt.ell.sbg} $\bG$ has a dense pointwise-elliptic subgroup.

  \item\label{item:thn:dns.ell.sbgp:pt.ell.sbs} $\bG$ has a dense pointwise-elliptic subset $\Gamma$ with $[\Gamma,\Gamma]$ pointwise-elliptic.

  \item\label{item:thn:dns.ell.sbgp:char} The conjunction of

    \begin{enumerate}[(a),wide]
    \item\label{item:thn:dns.ell.sbgp:cpct.ss} the quotient $\bG/\bG_{sol}$ by the \emph{(solvable) radical} \cite[Definition 10.23]{hm_pro-lie-bk} $\bG_{sol}\le \bG$ is compact, and

    \item\label{item:thn:dns.ell.sbgp:0wt} for every (equivalently, any one) maximal compact subgroup $\bK\le \bG$ the adjoint action of the derived subgroup $\bK'\le \bK$ on the quotient space $\fg/\fk$ has no trivial weights.     
    \end{enumerate}
  \item\label{item:thn:dns.ell.sbgp:alm.semidir} $\bG$ is expressible as an extension
    \begin{equation}\label{eq:lk.by.m}
      \{1\}\to
      \left(\bM\text{ compact}\right)
      \lhook\joinrel\xrightarrow{\quad}
      \bG
      \xrightarrowdbl{\quad}
      \bL\rtimes \bK
      \to \{1\}
    \end{equation}
    with $\bL$ Lie, connected, simply-connected and nilpotent, and $\bK'$ acting on $\fl:=Lie(\bL)$ trivial-weight-freely.

    Equivalently, maximal tori $\bT\le \bK'$ act on $\bL$ with no non-trivial fixed points. 
  \end{enumerate}
\end{theoremN}

The fact that ``many'' free tuples generating pointwise-elliptic groups exist when $\bG$ is Lie will be a byproduct. Recall \cite[pre Theorem 9.2]{oxt_meas-cat_2e_1980} that a \emph{residual} subset of a locally compact Hausdorff topological space is one which contains a countable intersection of dense opens. 

\begin{corollaryN}\label{corn:when.lie}
  Let $\bG$ be a non-solvable connected Lie group satisfying the equivalent conditions of \Cref{thn:dns.ell.sbgp}.

  For sufficiently large positive integers $d$ there are $d$-tuples in $\bG$ generating dense free pointwise-elliptic subgroups of $\bG$, and the set of such tuples is residual.  \qedhere
\end{corollaryN}

