\section{Dense subgroups consisting of elliptic elements}\label{se:lg.pt.ell}

We follow \cite[Definitions 10.1 and 10.8]{hm_pro-lie-bk} in denoting by
\begin{equation}\label{eq:der.ser}
  \bG=:\bG^{(0)}\ge \bG^{(1)}\ge \cdots
  \quad\text{and}\quad
  \bG=:\bG^{((0))}\ge \bG^{((1))}\ge \cdots
\end{equation}
the \emph{derives} and \emph{closed derived series} of a topological group respectively. 

\pf{thn:dns.ell.sbgp}
\begin{thn:dns.ell.sbgp}
  The mutual conjugacy \cite[\S 4.13, Theorem, pp.188-189]{mz} of the maximal compact subgroups shows that indeed the quantifier in condition \Cref{item:thn:dns.ell.sbgp:0wt} does not matter. Moreover, expressing $\bG$ as
  \begin{equation*}
    \bG
    \cong
    \varprojlim_{\substack{\bL\trianglelefteq \bG\\\bL\text{ compact}\\\bG/\bL\text{ Lie}}}
    \bG/\bL
    \quad
    \left(\text{\cite[\S 4.6, Theorem]{mz}}\right),
  \end{equation*}
  we can assume $\bG$ lie upon observing that an element is elliptic if and only if its image through a quotient by a compact normal subgroup is, so that the pointwise ellipticity of a subset $\Gamma\le \bG$ is equivalent to that of
  \begin{equation*}
    \bL\cdot\Gamma\le \bG
    \quad\text{and hence}\quad
    \pi(\Gamma)\cong \bL\cdot\Gamma/\bL
    ,\quad
    \bG\xrightarrow{\quad\pi\quad}\bG/\bL
  \end{equation*}
  for any (equivalently, all) compact normal $\bL\trianglelefteq \bG$.

  As one last preliminary simplification, note that \Cref{item:thn:dns.ell.sbgp:cpct.ss} and the weaker version of \Cref{item:thn:dns.ell.sbgp:0wt} requiring that $\bK$ itself (rather than $\bK'$) act trivial-weight-freely are jointly equivalent \cite[Theorem B]{2506.09642v1} to $\bG$ containing a dense pointwise-elliptic sub\emph{set}, so we can assume that conjunction to hold throughout the present proof. 

  \begin{enumerate}[label={},wide]

  \item\textbf{\Cref{item:thn:dns.ell.sbgp:pt.ell.sbg} $\Rightarrow$ \Cref{item:thn:dns.ell.sbgp:pt.ell.sbs}} requires no argument. 

  \item\textbf{\Cref{item:thn:dns.ell.sbgp:pt.ell.sbs} $\Rightarrow$ \Cref{item:thn:dns.ell.sbgp:char}:} The unique \cite[\S 1.8]{ragh} maximal compact subgroup of the \emph{nil-radical} (\cite[Definition 10.40]{hm_pro-lie-bk}, \cite[Theorem 3.18.13]{var_lie}) $\bG_{nil}\le \bG$ is normal in $\bG$, so can be ignored by the proof's prefatory remarks. We can thus assume $\bG_{nil}$ simply-connected (and hence \cite[Theorem 3.6.2]{var_lie} analytically isomorphic to its Lie algebra via the exponential map). Thus:
    \begin{equation}\label{eq:gp.chn}
      \begin{tikzpicture}[>=stealth,auto,baseline=(current  bounding  box.center)]
        \path[anchor=base] 
        (0,0) node (g) {$\bG$}
        +(0,-1) node (gsol) {$\bG_{sol}$}
        +(0,-2) node (gnil) {$\bG_{nil}$}
        +(0,-3) node (1) {$\{1\}$}
        ;
        \draw[-] (g) to[bend left=0] node[pos=.5,auto] {$\scriptstyle $} (gsol);
        \draw[-] (gsol) to[bend left=0] node[pos=.5,auto] {$\scriptstyle $} (gnil);
        \draw[-] (gnil) to[bend left=0] node[pos=.5,auto] {$\scriptstyle $} (1);        
        \draw[decorate,decoration = {brace},thick] (1,0) to[bend left=0] node[pos=.5,auto] {$\scriptstyle\quad \bG/\bG_{sol}\cong \bK'/\left(\text{finite}\right)$} (1,-.8);
        \draw[decorate,decoration = {brace},thick] (1,-1) to[bend left=0] node[pos=.5,auto] {$\scriptstyle\quad \bG_{sol}/\bG_{nil}\cong \bR^d\times \bT^e$} (1,-1.8);
        \draw[decorate,decoration = {brace},thick] (1,-2) to[bend left=0] node[pos=.5,auto] {$\scriptstyle\quad \bG_{nil}\text{ nilpotent simply-connected}$} (1,-2.8);
        \draw[decorate,decoration = {brace},thick] (-1,-1.8) to[bend left=0] node[pos=.5,auto] {$\scriptstyle\quad \text{\parbox{3.5cm}{$\bG/\bG_{nil}$ contains (the image of) $\bK$ as a maximal compact subgroup}}$} (-1,0);
      \end{tikzpicture}
    \end{equation}
    where the abelianness of $\bG_{sol}/\bG_{nil}$ follows from \cite[Theorem 3.8.3(iii)]{var_lie}.

    % % As the hypothesis transports over to quotients, induction on the length of the \emph{closed derived series} \cite[Definition 10.8]{hm_pro-lie-bk}
    % % \begin{equation*}
    % %   \bG=:\bG_{sol}^{((0))}
    % %   \ge
    % %   \bG_{sol}^{((1))}
    % %   \ge
    % %   \cdots
    % %   \ge
    % %   \bG_{sol}^{((\mathrm{max}))}
    % %   \gneq
    % %   \{1\}
    % % \end{equation*}
    % % (with the base case of the induction handled by \cite[Theorem 1.3]{2506.09642v1}) further reduces the problem to showing that the action of $\bK'$ on the center $\bA:=Z(\bG_{nil})$ (a vector group) has no trivial weights.
    % % 

    As indicated in \Cref{eq:gp.chn}, we identify $\bK$ with its image through
    \begin{equation*}
      \bG
      \xrightarrowdbl{\quad\pi\quad}
      \overline{\bG}:=\bG/\bG_{nil}. 
    \end{equation*}
    Observe next that
    \begin{itemize}[wide]
    \item the commutator subgroup $\overline{\bG}^{((1))}\le \overline{\bG}$ is contained in $\bR^d\cdot \bK'$;

    \item and the elements of $\bK'$ are \emph{precisely} \cite[Theorem 9.2]{hm5} the commutators $[s,t]:=sts^{-1}t^{-1}$, $s,t\in \bK$.
    \end{itemize}
    $\Gamma$ being dense with pointwise-elliptic commutator set $[\Gamma,\Gamma]$, it follows that arbitrary elements
    \begin{equation*}
      (v,s)\in \bG_{nil}\cdot \bK'\cong \bG_{nil}\rtimes \bK'
    \end{equation*}
    are arbitrarily approximable by elliptic $t\in [\Gamma,\Gamma]$ with
    \begin{equation*}
      \pi(t)\in \bR^d\cdot \bK'\le \overline{\bG}=\bG/\bG_{nil}.
    \end{equation*}
    The maximal compact subgroups of $\bR^d\cdot \bK'$ are conjugate to $\bK'$, so we may assume all such $\pi(t)$ contained in $\bK'$ by \cite[Theorem 1.12]{2506.09642v1}. We can thus decompose
    \begin{equation}\label{eq:tvs}
      t=(v_t,s_t)\in \bG_{nil}\cdot \bK'\cong \bG_{nil}\rtimes \bK'
      ,\quad
      v_t\in \left\{w^{-1}\cdot \Ad_{s_t}w\ :\ w\in \bG_{nil}\right\}      
    \end{equation}
    (the latter inclusion claim following from the assumed ellipticity of $t$ and \cite[Lemma 1.7(1)]{2506.09642v1}).

    Choose $s\in \bK'$ so as to minimize $\dim\ker\left(1-\Ad_s|_{\fg_{nil}}\right)$. For sufficiently $s'$ ranging over a sufficiently small neighborhood $U\ni s\in \bK'$ the decompositions
    \begin{equation*}
      \fg_{nil}
      =
      \ker\left(1-\Ad_{s'}\right)
      \oplus
      \im\left(1-\Ad_{s'}\right)
    \end{equation*}
    glue into a decomposition $U\times \fg_{nil}\cong \cE_{\ker}\oplus \cE_{\im}$ as a sum of trivial bundles, which the analytic isomorphism $\fg_{nil}\cong \bG_{nil}$ induced by the exponential map then turns into a decomposition
    \begin{equation*}
      U\times \bG_{nil}
      \cong
      \cF_{\ker}\times_{U}\cF_{\im}
    \end{equation*}
    as a \emph{Whitney product} \cite[\S 4]{zbMATH03056184} of trivial fiber bundles, with respective fibers
    \begin{equation*}
      \begin{aligned}
        \cF_{\ker,s'}
        &=\left\{g\in \bG_{nil}\ :\ \Ad_{s'}g=g \right\}\\
        \cF_{\im,s'}
        &=\left\{h^{-1}\cdot \Ad_{s'}h\ :\ h\in \bG_{nil} \right\}.
      \end{aligned}      
    \end{equation*}
    It follows that if $\dim\ker\left(1-\Ad_s|_{\fg_{nil}}\right)$ is minimal for $s\in \bK'$, then the $(v_t,s_t)$ of \Cref{eq:tvs} cannot approach $(v,s)\in \bG_{nil}\cdot \bK'$, $\Ad_s v=v$ unless $v$ is trivial.

    In summary: $\bK'$ must act on $\fg_{nil}$ trivial-weight-freely. This suffices, given that the action on the $\bR^d\le \fg_{sol}/\fg_{nil}$ of \Cref{eq:gp.chn} has no trivial weights by \cite[Theorem 1.3]{2506.09642v1}. 

  \item\textbf{\Cref{item:thn:dns.ell.sbgp:char} $\Rightarrow$ \Cref{item:thn:dns.ell.sbgp:pt.ell.sbg}:} We retain the standing assumption that $\bG$ is Lie. A further bit of simplification will be to substitute for $\bG$ the middle term of the top row in
    \begin{equation*}
      \begin{tikzpicture}[>=stealth,auto,baseline=(current  bounding  box.center)]
        \path[anchor=base] 
        (0,0) node (l) {$\bG_{sol}$}
        (-1.5,0) node (ll) {$\{1\}$}
        +(2.8,.5) node (um) {$\bullet$}
        +(2.8,-.5) node (dm) {$\bG$}
        +(4.5,.5) node (ur) {$\bK'$}
        +(4.5,-.5) node (dr) {$\bG/\bG_{sol}$}
        +(6.5,0) node (rr) {$\{1\}$}
        ;
        \draw[->] (ll) to[bend left=0] node[pos=.5,auto] {$\scriptstyle $} (l);
        \draw[right hook->] (l) to[bend left=6] node[pos=.5,auto] {$\scriptstyle $} (um);
        \draw[right hook->] (l) to[bend right=6] node[pos=.5,auto] {$\scriptstyle $} (dm);
        \draw[->] (um) to[bend left=6] node[pos=.5,auto] {$\scriptstyle $} (ur);
        \draw[->] (dm) to[bend right=6] node[pos=.5,auto] {$\scriptstyle $} (dr);
        \draw[->] (ur) to[bend left=6] node[pos=.5,auto,swap] {$\scriptstyle $} (rr);
        \draw[->] (ur) to[bend left=6] node[pos=.5,auto,swap] {$\scriptstyle $} (rr);
        \draw[->] (dr) to[bend right=6] node[pos=.5,auto,swap] {$\scriptstyle $} (rr);
        \draw[->>] (um) to[bend left=0] node[pos=.5,auto,swap] {$\scriptstyle $} (dm);
        \draw[->>] (ur) to[bend left=0] node[pos=.5,auto,swap] {$\scriptstyle $} (dr);
      \end{tikzpicture}
    \end{equation*}
    thus ensuring the splitting $\bG\cong \bG_{sol}\rtimes \bK'$.

    % % OLD: ALTERED SO AS TO MINIMIZE RELIANCE ON \cite[Theorem 1.3]{zbMATH01903603}. 
