To put the following statement in perspective, recall \cite[Proposition 1.18]{2506.09642v1} that compact groups acting on connected locally compact groups always leave (some) maximal compact subgroups thereof invariant. 

\begin{lemma}\label{le:im.ndg}
  Let $\bK$ be a compact group acting on a solvable connected Lie group $\bL$, and $\bT\le \bL$ a $\bK$-invariant maximal torus. Every element of $\bL\rtimes \bK$ whose $\bK$-component has no 1-eigenvectors in
  \begin{equation*}
    \fl/\ft
    ,\quad
    \fl:=Lie(\bL)
    ,\quad
    \ft:=Lie(\bT)
  \end{equation*}
  is elliptic. 
\end{lemma}
\begin{proof}
  \cite[Lemma 1.7]{2506.09642v1} settles the abelian-$\bL$ case so we can assume, inductively on the length of $\left(\bL^{((n))}\right)_n$, that an element
  \begin{equation*}
    t
    =
    (v,s)\in \bG:=\bL\rtimes \bK
    ,\quad
    1-\Ad_s\text{ invertible on }\fl/\ft
  \end{equation*}
  has elliptic image in the quotient $\bL/\bL^{((\mathrm{max}))}$ by the bottom (abelian) layer of the derived series. Additionally, since quotienting out compact normal subgroups is harmless (as observed in the introductory remarks to the proof of \Cref{thn:dns.ell.sbgp}), we can assume there is no torus component to $\bL^{((\mathrm{max}))}\cong \bR^d$. 

  The image of $t$ in $\bG/\bL^{((\mathrm{max}))}$ belongs to some maximal compact subgroup thereof, which surjects onto $\bK$ and hence splits as
  \begin{equation*}
    \bM\rtimes \bK
    ,\quad
    \bM\le \bL/\bL^{((\mathrm{max}))}\text{ maximal compact}.
  \end{equation*}
  We can thus substitute for $\bG$ the (automatically split \cite[\S VII.3.2, Proposition 3]{bourb_int_7-9_en}) extension
  \begin{equation*}
    \{1\}
    \to
    \bL^{((\mathrm{max}))}
    \lhook\joinrel\xrightarrow{\quad}
    \bL^{((\mathrm{max}))}\rtimes \left(\bM\rtimes \bK\right)
    \xrightarrowdbl{\quad}
    \bM\rtimes \bK
    \to \{1\},
  \end{equation*}
  again falling back on the abelian-$\bL$ case to conclude.
\end{proof}

