\title[A generating set for the Johnson kernel]{A generating set for the Johnson kernel}

\author{Marco Boggi}
\address{UFF - Instituto de Matem\'atica e Estat\'{\i}stica -
Niter\'oi - RJ 24210-200; Brazil}
\email{marco.boggi@gmail.com}

\begin{abstract}For a connected orientable hyperbolic surface $S$ without boundary and of finite topological type, the Johnson kernel $\cK(S)$ 
is the subgroup of the mapping class group of $S$ generated by Dehn twists about separating simple closed curves on $S$. 
We prove that $\cK(S)$ is generated by the Dehn twists about separating simple closed curves on $S$ bounding either: 
a closed subsurface of genus $1$ or $2$; a closed subsurface of genus $1$ minus one point; a closed disc minus two points.
%For $S$ a surface with at most one puncture and genus $\geq 3$, by a result of Johnson, the Dehn twists about separating simple 
%closed curves on $S$ bounding a closed subsurface of genus $1$ minus one point can be removed from the list and the resulting normal
%generating set is minimal.
\vskip 0.2cm
\noindent AMS Mathematics Subject Classification: 57K20; 57K31; 57M07.
\end{abstract}

\maketitle



\section{Introduction}
Let $S=S_{g,n}$ be a closed orientable differentiable surface of genus $g(S)=g$ from which $n(S)=n$ points have been removed. 
We assume that the Euler characteristic $\chi(S)=2-2g-n$ of $S$ is negative. We let $S_g:=S_{g,0}$.
Let then $\G(S)$ and $\PG(S)$ be respectively the mapping class group and the pure mapping class group of the surface $S$.
We will sometimes use the notation $\G_{g,[n]}:=\G(S_{g,n})$ and $\G_{g,n}:=\PG(S_{g,n})$.
The \emph{Johnson kernel} (or \emph{Johnson subgroup}) $\cK(S)$ is the subgroup of $\G(S)$ (and $\PG(S)$) generated by
Dehn twists about separating simple closed curves on $S$. We also let $\cK_{g,n}:=\cK(S_{g,n})$.

Classically (cf.\ \cite{J1}), for a closed surface $S$ or a $1$-pointed surface $(S,P)$ of genus $\geq 2$, the Johnson kernel 
is defined to be the kernel (whence the name) of the natural representation $\G(S)\to\Out(\pi_1(S,P)/\pi_1(S,P)^{[3]})$
(resp.\ $\G(S,P)\to\Aut(\pi_1(S,P)/\pi_1(S,P)^{[3]})$), where, for a group $G$, we denote by $G^{[k]}$ the $k$-th term 
of the lower central series of $G$, i.e.\ $G^{[1]}:=G$ and $G^{[k+1]}:=[G^{[k]},G]$, for all $k\in\N^+$. In \cite[Theorems~5 and 6]{J3}, Johnson
then showed that these kernels coincide with $\cK(S)$ and $\cK(S\ssm P)$, respectively. 

More generally (cf.\ \cite[Theorem~3.13]{mod}), 
$\cK(S)$ is the kernel of the natural representation $\G(S)\to\Out(\pi_1(S,P)/W^3\pi_1(S,P))$, where $W^3\pi_1(S,P)$ is the third term of the
\emph{weight filtration} on the fundamental group of the (punctured) surface $S$ which is defined as follows (cf.\ \cite[Section~2]{mod}).
Let $N$ be the kernel of the natural epimorphism $\pi_1(S,P)\to\pi_1(\ol{S},P)$, where $\ol{S}$ is the closed surface obtained from $S$
filling in the punctures. Then, we define $W^1\pi_1(S,P):=\pi_1(S,P)$; $W^2\pi_1(S,P):=N\cdot[\pi_1(S,P),\pi_1(S,P)]$ and:
\[W^{k+1}\pi_1(S,P):=[W^k\pi_1(S,P),\pi_1(S,P)]\cdot[W^{k-1}\pi_1(S,P), N].\]

The \emph{Torelli group} $\cI(S)$ is the kernel of the natural representation $\G(S)\to\Sp(H_1(\ol{S};\Z))$, where
$\ol{S}$ is the closed surface obtained from $S$ filling in all the punctures. There is an inclusion $\cK(S)\subseteq\cI(S)$.
A deep result by Johnson (cf.\ \cite{J4}) then states that, for $n(S)\leq 1$, the commutator subgroup $[\cI(S),\cI(S)]$ is contained
in $\cK(S)$ as a finite index subgroup and that the (abelian) quotients $\cI(S)/\cK(S)$ and $\cK(S)/[\cI(S),\cI(S)]$ are, respectively, 
a finitely generated free $\Z$-module and a finite $\Z/2$-module.
This description also holds for the case $n(S)> 1$ (cf.\ \cite[Theorem~3.18 and Theorem~3.21]{mod}).

After being an open question for a long time, it is now settled that the Johnson kernel is finitely generated for $n(S)\leq 1$ and $g(S)\geq 4$
(cf.\ \cite[Theorem~1.1]{EH}, \cite[Theorem~A]{CEP}). In \cite[Theorem~1.3]{EF}, a finite (albeit complicated) generating set consisting 
of Dehn twists is given. In this paper, we address a related but different question, namely what topological types of Dehn twists are 
sufficient and necessary in a generating set for the Johnson kernel. 

This problem is motivated by \cite[Theorem~2]{J}, which states that, 
for $g(S)\geq 3$ and $n(S)\leq 1$, the Torelli group $\cI(S)$ is normally generated by a genus $1$ bounding pair map 
(cf.\ \cite[Section~1]{J} for the definition of such mapping class) and by a similar result for the Johnson kernel (cf.\ \cite[Theorem~1]{J}), 
which states that, for $g(S)\geq 2$ and $n(S)\leq 1$, the Johnson kernel $\cK(S)$ is generated by the Dehn twists about separating 
simple closed curves on $S$ bounding either a closed subsurface of genus $1$ or $2$. Here, we prove a more general version of Johnson's result:

\begin{customtheorem}{A}The Johnson kernel $\cK(S)$ is generated by the Dehn twists about separating simple closed curves on $S$
bounding either: a closed subsurface of genus $1$ or $2$; a closed subsurface of genus $1$ minus one point; a closed disc minus two points.
\end{customtheorem}

\begin{remark}The proof of Theorem~A, which we will give in the following section, does not make use of \cite[Theorem~1]{J}
and provides, in particular, a new proof of the closed surface case of this theorem.
\end{remark}

For  $g(S)\geq 2$ and $n(S)\leq 1$, we then show that the set of generators for $\cK(S)$ given by Johnson (cf.\  \cite[Theorem~1]{J}) is optimal 
in the following sense. Given a group $G$ and a normal subgroup $N$ of $G$, we say that a subset $X$ of $G$ is a \emph{normal generating set} 
for $N$ if the set $X$ is closed under conjugation by elements of $G$ and generates the subgroup $N$. We have:

\begin{customtheorem}{B}For $g(S)\geq 2$ and $n(S)\leq 1$, the normal generating set for the Johnson kernel $\cK(S)$ given by the 
Dehn twists about separating simple closed curves on $S$ bounding either a closed subsurface of genus $1$ or $2$ is minimal.
\end{customtheorem}
