\subsection*{\Cref{ex:Y-D-dependent-zero-sens}}\label{proof-Ex}

For completeness we derive the cdf and quantile function of $Y$. Using the definition of $Y$, and independence of $(D, X_1, X_2)$ in the second equation, we obtain
    \begin{align*}
        F_Y(y) 
        &= 
        \P(Y \le y | X_1 = 0)(1-p) + \P(Y \le y | X_1 = 1)\,p
        \\
        &= 
        \P(D \le y)(1-p) + \P(X_2 \le y )\,p
        \\
        &=
        \Id_{\{y \le C\}} \,(1-p)F_D(y) + \Id_{\{y > C\}} \,\big(1-p + pF_{X_2}(y)\big)\,.
    \end{align*}
Next, the quantile function of $Y$ is
\begin{align*}
    \Finv_Y(u)
    &= 
    \inf\{ y \in \R \, |\, F_Y(y) \ge u\}
    \\
    &= 
    \inf\{ y \in \R \, |\, \Id_{\{y \le C\}} \,(1-p)F_D(y) + \Id_{\{y > C\}} \,\big(1-p + pF_{X_2}(y)\big) \ge u\}
    \\
    &= \begin{cases}
        \Finv_D\big(\frac{u}{1-p}\big) \qquad  & u \le 1-p
        \\[1em]
        \Finv_{X_2}\big(\frac{u - 1 + p}{p}\big) & u > 1-p\,.
    \end{cases}
\end{align*}
To see the last equality, note that if $(1-p)F_D(C) \ge u$ (which is equivalent to $1-p \ge u$), then the infimum simplifies to $\inf\{ y \in \R \, |\, (1-p)F_D(y) \ge u\} = \Finv_D(\frac{u}{1-p})$. The case when $(1-p)F_D(C) > u$ follows similarly.


\subsection*{\Cref{mortgage-cascade}}
The distribution of $F_{X|D}(x|t)$ is given by 
\begin{align*}
    F_{X|D}(x\, |\, t)
    &= 
    \P(X \le x | D = t)
    \\
    &=
    \P(X \le x | D = 0)\Id_{\{t = 0\}} + \P(X \le x | D = 1)\Id_{\{t = 1\}}
    \\
    &=
    \Phi\left(\tfrac{\log(x) - \mu}{\sigma}\right)\Id_{\{t = 0\}}
    + \Phi\left(\tfrac{\log(x) - 2\mu}{\sigma}\right)\Id_{\{t = 1\}}\,.
\end{align*}
Moreover, the conditional quantile function of $F_{X|D}(x\, |\, t)$ (the inverse in $x$ with $t$ fixed) is
\begin{align*}
    \Finv_{X|D}(u\, |\, t)
    &=
    \exp\left\{ \Phi^{-1}(u)\sigma  + \mu \right\}\Id_{\{t = 0\}}
    +
    \exp\left\{ \Phi^{-1}(u)\sigma  + 2 \mu \right\}\Id_{\{t = 1\}}\,.
\end{align*}
Next, the perturbation on $X$ induced by $D_\delta$ is 
\begin{align*}
    X_\delta
    :&= 
    \Finv_{X|D}(V\, |\, t)\big|_{t = D_\delta}
    =
    \exp\left\{ \Phi^{-1}(V)\sigma  + \mu \right\}\Id_{\{D_\delta = 0\}}
    +
    \exp\left\{ \Phi^{-1}(V)\sigma  + 2 \mu \right\}\Id_{\{D_\delta = 1\}}\,,
\end{align*}
where $V\sim U(0,1)$ and the cdf of $X_\delta$ is 
\begin{equation*}
    F_{X_\delta}(x)
    =
    \Phi\left(\tfrac{\log(x) - \mu}{\sigma}\right)(1-p_\delta)
    + \Phi\left(\tfrac{\log(x) - 2\mu}{\sigma}\right)p_\delta,.
\end{equation*}



\section{Auxiliary results}\label{app:aux-results}

The next results are generalizations of lemma 1 in \cite{Pesenti2024EJOR-non-diff}.

\begin{lemma}\label{lemma:delta-function-general}
Let $\kappa_\delta(z)$, $\delta \ge 0, z \in\R$ be a function that is differentiable in both $z$ and $\delta$ and satisfies $\kappa_0(z) = z$ for all $z \in \R$. For fixed $p \in \R$ and $\delta > 0$, define the family of functions
    \begin{equation}
    \label{eq:h-delta}
        h_\delta(z) := \frac{1}{\delta} \, \big(\Id_{\{\kappa_\delta(z) \le p\}} - \Id_{\{z \le p\}} \big)\,, \quad z\in \R\,.
    \end{equation}
Then, for any measurable function $H \colon \R^k \to \R$ and rv $Z$ and random vector $\W$, such that $  \E[H(\W) \, |\, \X ]< +\infty$, it holds
 \begin{equation*}
     \lim_{\delta \downarrow 0} \E[h_\delta(Z) H(\W) \, |\, \X ]
     =
     \E[\frac{\partial}{\partial_\delta} \kappa_\delta^{-1}(Z)\big|_{\delta = 0} H(\W) \Id_{\{Z = p\}}\, |\, \X ]\,,
 \end{equation*}
 where $\kappa_\delta^{-1}(z)$ denotes the inverse of $\kappa_\delta(z)$ with respect to $z$. 
\end{lemma}
\begin{proof}
Let $\xi$ be an infinitely often differentiable function. Using the change of variable $y = \kappa_\delta(z)$   
\begin{align*}
        \int_\R\xi(z) h_\delta(z) \diff z
        &= 
        \frac1\delta \int_\R\xi(z) \big(\Id_{\{\kappa_\delta(z)\le p \}} - \Id_{\{z \le p\}} \big) \diff z
        \\
        &= 
        \frac1\delta \int_\R \frac{\xi(z)}{\frac{\partial}{\partial z'} \kappa_\delta(z')} \Big|_{z' =z= \kappa_\delta^{-1}(y)} \Id_{\{y \le p \}}  \diff y
        -
        \frac1\delta \int_{-\infty}^{p}\xi(z) \diff z\,.
    \end{align*}
Letting $\Xi$ be the primitive of $\xi$ vanishing at $-\infty$, we obtain
\begin{align*}
        \int_\R\xi(z) h_\delta(z) \diff z
        &= 
        \frac1\delta \int_{-\infty}^{p}
        \frac{d}{dz} \Xi \big(\kappa_\delta^{-1}(z)\big) \diff z
        -
        \frac1\delta\, \Xi(p)
        = 
        \frac1\delta\, \big( \Xi(\kappa_\delta^{-1}(p)
         -
        \Xi(p)\big)\,.
\end{align*}
Taking the limit (note that $\kappa_0(x) = x$)
\begin{equation*}
    \lim_{\delta \to 0} \int_\R\xi(z) h_\delta(z) \diff z
    =
    \xi(p) \frac{\partial}{\partial \delta}\kappa_\delta^{-1}(p)\Big|_{\delta = 0}\,.
\end{equation*}

For the second statement, we have
\begin{align*}
    \lim_{\delta \downarrow 0} \E[h_\delta(Z) H(\W) \, |\, \X ]
     =
     \frac{\partial}{\partial \delta}\kappa_\delta^{-1}(p)\big|_{\delta = 0}\; \E[ H(\W) \Id_{\{Z = p\}}\, |\, \X ]\,.
\end{align*}
\end{proof}

\begin{lemma}\label{lemma:delta-function-very-general}
Let $\kappa_\delta(z)$, $\delta \ge 0, z \in\R$ be a function that is differentiable in both $z$ and $\delta$, invertible in $z$, and satisfies $\kappa_0(z) = z$ and $\kappa_0^{-1}(z) = z$ for all $z \in \R$. Further let $\ell\colon \R^{m+1} \to \R$ be differentiable and invertible in its first component. Then, for fixed $p \in \R$ and $\delta > 0$, define the family of functions
    \begin{equation*}
        h_\delta(z;\v, p) := \frac{1}{\delta} \, \big(\Id_{\{\ell(\kappa_\delta(z); \v ) \le p\}} - \Id_{\{\ell(z; \v) \le p\}} \big)\,, \quad z\in \R, \v \in \R^m\,.
    \end{equation*}
Then, for any text function $\xi\colon \R\to \R$, it holds that 
 \begin{equation*}
    \lim_{\delta \to 0} \int_\R\xi(z) h_\delta(z;\v, p) \diff z
    =
    \xi\big(\ell^{-1}(p;\v)\big) \tfrac{\partial}{\partial \delta}\kappa_\delta^{-1}\big(\ell^{-1}(p;\v)\big)\Big|_{\delta = 0}\,.
 \end{equation*}
\end{lemma}
\begin{proof}
Fix $\v \in \R^m$ and let $\xi$ be an infinitely often differentiable function. Using in the first integral the change of variable $y = \ell(\kappa_\delta(z); \v)$, and in the second integral the change of variable $y' = \ell(z; \v)$, where we omit the dependence on $\v$. Then we obtain
\begin{align*}
        \int_\R\xi(z) h_\delta(z; \v, p) \diff z
        &= 
        \frac1\delta \int_\R\xi(z) \Id_{\{\ell(\kappa_\delta(z); \v)\le p \}} \diff z
        -
        \frac1\delta \int_\R\xi(z) \Id_{\{\ell(z; \v) \le p\}} \diff z
        \\
        &= 
        \frac1\delta \int_{-\infty}^p \frac{\xi(z)}{\frac{\partial}{\partial z'}\big( \ell(\kappa_\delta(z'), \v)\big)} \Big|_{z' = z= \kappa_\delta^{-1}(\ell^{-1}(y; \v))} \diff y
        \\
        & \quad
        -
        \frac1\delta \int_{-\infty}^{p}\frac{\xi(z)}{\frac{\partial}{\partial z}\ell(z; \v)}\Big|_{z = \ell^{-1}(y'; \v)} \diff y'\,.
    \end{align*}
Letting $\Xi$ be the primitive of $\xi$ vanishing at $-\infty$, it holds 
\begin{align*}
        \int_\R\xi(z) h_\delta(z; \v, p) \diff z
        &= 
        \frac1\delta \int_{-\infty}^{p}
        \frac{d}{dz} \Xi \big(\kappa_\delta^{-1}(\ell^{-1}(z; \v))\big) \diff z
        -
        \frac1\delta \int_{-\infty}^{p}
        \frac{d}{dz} \Xi \big(\ell^{-1}(z; \v)\big) \diff z
        \\
        &= 
        \frac1\delta\, \Big[ \, \Xi\big(\kappa_\delta^{-1}\big(\ell^{-1}(p; \v)\big)\big)
         -
        \Xi\big(\ell^{-1}(p;\v)\big)\Big]\,.
\end{align*}
Taking the limit (recall that $\kappa^{-1}_0(x) = x$)
\begin{equation}\label{eq:delta-limit-general}
    \lim_{\delta \to 0} \int_\R\xi(z) h_\delta(z;\v, p) \diff z
    =
    \xi\big(\ell^{-1}(p;\v)\big) \tfrac{\partial}{\partial \delta}\kappa_\delta^{-1}\big(\ell^{-1}(p;\v)\big)\Big|_{\delta = 0}\,.
\end{equation}
\end{proof}


\begin{lemma}\label{lemma:derivative-kappa}
Define the function $\kappa_\delta(u): = \Phi(\Phi^{-1}(u)(1 + \delta)\big)$, for $\delta \ge 0$ and $u \in (0,1)$. Then, 
 \begin{equation*}
     \frac{\partial}{\partial \delta} \kappa_\delta^{-1}(u)\Big|_{\delta = 0}
     =
     - \Phi^{-1}(p) \,\phi\big(\Phi^{-1}(p)\big)\,.
 \end{equation*}
\end{lemma}
\begin{proof}
Note that $\kappa_\delta^{-1}(u) = \Phi\big(\tfrac{1}{1 + \delta}\, \Phi^{-1}(u)\big)$. We calculate, by making the change of variable $y:= \Phi^{-1}(u)$,
\begin{align*}
\lim_{\delta \to 0} \tfrac{1}{\delta} \big(\kappa_\delta^{-1}(u)  - \kappa_0^{-1}(u) \big)
    &=
    \lim_{\delta \to 0} \tfrac1\delta \Big\{\Phi\big(\tfrac{1}{1 + \delta}\, \Phi^{-1}(u)\big) - \Phi \big(\Phi^{-1}(u)\big)\Big\}
    \\
&= 
\lim_{\delta \to 0} \tfrac1\delta \Big\{\Phi\big(\tfrac{1}{1 + \delta}\, y\big) - \Phi (y)\Big\}
\\
&=
\lim_{\delta \to 0} \tfrac1\delta \Big\{\Phi\Big( y (1 - \delta) + o(\delta) \Big) - \Phi (y)\Big\}
\\
&=
\lim_{\delta \to 0} \tfrac1\delta \big\{\Phi(y)  - \delta y\, \phi(y)  - \Phi (y) +  o(\delta)\big\}
\\
&= 
- y \phi(y)
\\
&=
- \Phi^{-1}(u) \,\phi\big(\Phi^{-1}(u)\big)\,,
\end{align*}
where we used in the third equality the Taylor approximation of $\frac{1}{1 + \delta}$ and in the forth the Taylor approximation of $\Phi(\cdot)$ around $y$. 
\end{proof}






\section{Proofs}\label{app:proofs}

\begin{proof}[Proof of \Cref{prop:marginal-sensitivity}]\label{proof-sensitivity-rep}
This proof follows by a generalization of Prop. 11 in \cite{pesenti2024risk}, which only holds for linear prediction function $\mfg$. We also refer to \cite{Tsanakas2016RA} for an alternative proof for the sensitivity measure of unconditional distortion risk measures. 

To simplify notation, we write the distorted output $Y_\delta:=\mfg\big( \D_{i,\delta} , \X\big) $, where $\D_{i,\delta}:= (D_1, \ldots, D_{i-1}, D_i(1 + \delta), D_{i+1}, \ldots, D_m)$, the conditional cdfs $F(y):= \P(Y \le y |\X = \x, \D_{-i} = \d_{-i})$, and $F(y, \delta):= \P(Y_\delta \le y |\X = \x, \D_{-i} = \d_{-i})$. Then we have that 
\begin{equation*}
\rho_\gamma\big(Y_\delta\,|\,\X = \x\big) = \E\Big[\E[F^{-1}(U, \delta) \gamma(U) | \X = \x, \D_{-i} = \d_{-i}]\, \Big| \, \X = x\Big]\,    
\end{equation*}
for a, conditional on $(\X = \x, \D_{-i} = d_{-i})$, uniform rv $U$. Moreover, using the mean value theorem together with Lebesgue dominated convergence we interchange expectation and limit to 
\begin{align}
\lim_{\delta \to 0}\frac{
    \rho_\gamma\big(Y_\delta\,|\,\X = \x\big) - \rho_\gamma\big( Y\,|\,\X=\x\big)}{\delta}
    \nonumber
    \\
    &\hspace*{-6em}=
    \E\Big[\E[\partial_\delta F^{-1}(U, \delta) \big|_{\delta = 0}\gamma(U) | \X = \x, \D_{-i} = \d_{-i}]\, \Big| \, \X = \x\Big]
    \nonumber
    \\
    &\hspace*{-6em}=
    \E\Big[\E[\partial_\delta F^{-1}(F(Y), \delta) \big|_{\delta = 0}\gamma(F(Y)) | \X = \x, \D_{-i} = \d_{-i}]\, \Big| \, \X = \x\Big]
    \nonumber
    \\
    &\hspace*{-6em}=
    \E\Big[\int_\R \partial_\delta F^{-1}(F(y), \delta) \big|_{\delta = 0}\gamma(F(y)) f(y)\diff y \Big| \, \X = \x\Big]
    \,,
    \label{eq:derivative-rho-proof}
\end{align}
where $\partial_\delta := \tfrac{\partial}{\partial_\delta} $ denotes the partial derivative with respect to $\delta$, $f$ the density of $Y_\delta$ given $(\X, \D_{-i})$, and where we used that $\P$-a.s. $U = F(Y)$, given $(\X, \D_{-i})$.  
By taking derivative of the equation $F(F^{-1}(U, \delta), \delta) = u$, we obtain for all $u \in (0,1)$ that
\begin{equation*}
    \tfrac{\partial}{\partial_\delta} F^{-1}(u, \delta)\Big|_{\delta = 0}
    =
    -\frac{\partial_\delta F(y, \delta)}{f(y)}\Big|_{y = F^{-1}(u)}
\end{equation*}
Inserting the representation of $\partial_\delta F(y, \delta)$ into \eqref{eq:derivative-rho-proof}, the integral becomes
\begin{align*}
    \int_\R \partial_\delta F^{-1}(F(y), \delta) \big|_{\delta = 0} \gamma(F(y)) f(y)\diff y
    &=
     \int_\R -\frac{\partial_\delta F(y, \delta)}{f(y)}\gamma(F(y)) f(y)\diff y
     \\
     &=
     \int_\R -\partial_\delta F(y, \delta)\gamma(F(y))\diff y
     \,. 
\end{align*}
Next, we applied \Cref{lemma:delta-function-very-general} with $p = y$, $\ell = \mfg$, and $\kappa_\delta(x) = x(1 + \delta)$ to 
\begin{align*}
    \partial_\delta F(y, \delta)
    &=
    \lim_{\delta \to 0}\, \tfrac1\delta\, \E[\Id_{\{\mfg( \D_{i,\delta} , \X)  \le y\}} - \Id_{\{\mfg( \D , \X)  \le y\}} |\X = \x, \D_{-i} = \d_{-i}]
    \\
    &= \tfrac{\partial}{\partial \delta } \kappa_\delta^{-1}\big(\mfg^{-1}(y, \d_{-i}, \x)\big)\big|_{\delta = 0}\; f_{D_i | \X, \D_{-i}}\big(\mfg^{-1}(y, \d_{-i}, \x)\big),
\end{align*}
where $\mfg^{-1}$ denotes the inverse in its $i$-th component, and we use the notation $\mfg^{-1}(y, \d_{-i}, \x): = \mfg^{-1}(d_1, \ldots, d_{i-1}, y, d_{i+1}, \ldots, d_m, \x)$.  
Noting that $\partial_\delta \kappa^{-1}_\delta(x)|_{\delta = 0} = - x$, and then making a change of variable $t = \mfg^{-1}(y, \d_{-i}, \x)$, which implies that $\partial_i \mfg(t, \d_{-i}, \x) \diff t= \diff y$
\begin{align*}
    \int_\R \partial_\delta F^{-1}(F(y), \delta) \big|_{\delta = 0}& \gamma(F(y)) f(y)\diff y
    \\
    &=
    \int_\R \mfg^{-1}(y, \d_{-i}, \x)\; f_{D_i | \X, \D_{-i}}\big(\mfg^{-1}(y, \d_{-i}, \x)\big)\gamma(F(y))\diff y
    \\
    &=
    \int_\R t\;\partial_i \mfg(t, \d_{-i}, \x) \;  \gamma\big(F(\mfg(t, \d_{-i}, \x))\big)\, f_{D_i | \X, \D_{-i}}(t)\, \diff t
    \\
    &= 
    \E\big[D_i\;\partial_i \mfg(\D, \X) \; \gamma\big(F(\mfg(\D, \X))\big)\, |\, \X = \x, \D_{-i} = \d_{-i}\big]
    \\
    &= 
    \E\big[D_i\;\partial_i \mfg(\D, \X) \; \gamma(F(Y))\, |\, \X = \x, \D_{-i} = \d_{-i}\big].
\end{align*}
Collecting, we obtain 
\begin{align*}
    \lim_{\delta \to 0}\frac{
    \rho_\gamma\big(Y_\delta\,|\,\X = \x\big) - \rho_\gamma\big( Y\,|\,\X=\x\big)}{\delta}
    =
     \E\big[D_i\;\partial_i \mfg(\D, \X) \, \gamma(F(Y))\, |\, \X = \x\, \big]\,.
\end{align*}
\end{proof}


\begin{proof}[Proof of \Cref{thm:individual}]
For simplicity, we omit the superscripts of $\ell^{\t, \x}\in \Gamma^{\t, \x}$ and simply write $\ell$. Next for any uniform rv $U\sim U(0,1)$, the objective function in \eqref{opt:main} is
\begin{align*}
    \int_0^1 \big(\gamma(u) - \ell(u)\big)^2\, du
    &= \E\big[\, (\gamma(U) - \ell(U)\big)^2 \, \big]
    \\
     &= \E\big[\, \E\big[\big(\gamma(U_{Y|\X}) - \ell(U_{Y|\X})\big)^2 \,| \X\big]\, \big]
     \\
     &= 
     \int_{\R^n}\int_{\R^{m}} \big(\gamma(U_{\mfg(\t, \x)|\X}) - \ell(U_{\mfg(\t, \x)|\X})\big)^2\,\diff F_{\D|\X}(\t|\x)\  \,  \diff F_\X(\x)\,,
\end{align*}
where the second equation follows by choosing the uniform rv to be $U_{Y|\X}$ and where for $(\x, \t) \in \R^{n+m}$, we define $U_{\mfg(\t, \x)|\X}:= F_{\mfg(\D, \X)|\X}\big(\mfg(\t, \x) | \x\big)$.

Using \Cref{prop:marginal-sensitivity}, we define the Lagrangian, pointwise in $\x$, of optimisation problem \eqref{opt:main} with Lagrange multipliers $\eta(\x) \in \R $ by
\begin{align*}
    L(\ell, \x)
    :&=
    \int_{\R^{m}}\Big\{ \Big(\ell(U_{\mfg(\t, \x)|\X}) - \gamma(U_{\mfg(\t, \x)|\X})\Big)^2
    + 2\eta(\x)\,  t_i \, \partial_{i} \mfg(\t, \x) \ell(U_{\mfg(\t, \x)|\X}) 
      \Big\}\,\diff F_{\D|\X}(\t|\x)\  \, 
    \\
    &= 
    \int_{\R^{m}}\Big\{ \Big( \ell(U_{\mfg(\t, \x)|\X})- \Big[\gamma(U_{\mfg(\t, \x)|\X}) - \eta(\x)\,  t_i \, \partial_{i} \mfg(\t, \x) 
   \Big]\Big)^2 
    \\
    & \qquad \qquad
    - \Big[\gamma(U_{\mfg(\t, \x)|\X}) - \eta(\x)\,  t_i \, \partial_{i} \mfg(\t, \x) \Big]^2
    +
    \gamma(U_{\mfg(\t, \x)})^2
    \Big\}\,\diff F_{\D|\X}(\t|\x)\, .
\end{align*}
Using pointwise optimisation, a solution has to satisfy for all $(\t, \x) \in \supp(\D, \X)$ 
\begin{equation} \label{eq:h-opt}
    \ell^*_{\eta(\x)}(U_{\mfg(\t, \x)|\X})=
    \gamma(U_{\mfg(\t, \x)|\X}) - \eta(\x)\,  t_i \, \partial_{i} \mfg(\t, \x)\,.
\end{equation}
Next, we calculate the Lagrange multiplier. For this we enforce for each $\x$ the constraint
\begin{subequations}\label{eqs:Lagrange-multiplier}
    \begin{align}
    0 &=\partial_{D_i}\;  \rho_{\ell^*_{\eta(\x)}}(\, Y\,|\,\X = \x\,)
        \\
        &=
        \E\big[\,D_i \,\partial_{i} \mfg(\D, \X) \ell^*_{\eta(\x)}\big(U_{Y|\X}\big)  \,|\, \X = \x\,\big]
        \\
        &=
        \partial_{D_i}\;  \rho_{\gamma}(\, Y\,|\,\X = \x\,)
        -
         \eta(\x)\,\E\big[\,\big(D_i \,\partial_{i} \mfg(\D, \X) \big)^2  \,|\, \X = \x\,\big]\,.
    \end{align}
\end{subequations}

Thus, the optimal Lagrange multiplier is
\begin{equation*}
    \eta^*(\x)  =  \frac{\partial_{D_i}\;  \rho_{\gamma}(\, Y\,|\,\X = \x\,)}{\E\big[\,\big(D_i \,\partial_{i} \mfg(\D, \X) \big)^2  \,|\, \X = \x\,\big]}\,.
\end{equation*}
\Cref{eq:optimal-h} holds by replacing $\eta(\x)$ in \eqref{eq:h-opt} by the optimal Lagrange multiplier $\eta^*(\x)$, yielding $\ell^*_{\eta^*(\x)}$. By \Cref{asm-integrability}, $\ell^*_{\eta^*(\x)}$ is square integrable in $(\t, \x)$ and hence belongs to $\Gamma^{\t,\x}$.

The marginally fair premium follows by explicitly calculating
\begin{align*}
    \rho_{\ell^*_{\eta^*(\x)}}(Y \,|\,\X) 
       &=
       \E\big[Y \ell^*_{\eta^*(\x)} (U_{Y|\X})\, |\X\big]
       \\
    &=
    \rho_\gamma(Y \,|\,\X) -
    \frac{ \partial_{D_i}\;  \rho_\gamma(\, Y\,|\,\X\,)}{\E\big[\,\big(D_i \partial_{i} \mfg(\D, \X) \big)^2 \big|\,\X\big]}\; 
    \E[Y \, D_i \, \partial_{i} \mfg(\D, \X)\, |\,\X ]    \,.
\end{align*}
Uniqueness follows since the optimization problem is strictly convex in $\ell$ and the constraint is linear in $\ell$. Existence follows by existence of the Lagrange multiplier. Setting the notation $\gamma^*:= \ell^*_{\eta^*(\x)}$ concludes the proof.
\end{proof}



\begin{proof}[Proof of \Cref{prop:mutli-marginal}]
    We proceed similarly to the proof of \Cref{thm:individual} in that we consider the
Lagrangian, pointwise in $\x$, of the optimization problem \eqref{opt:main} with constraints $ \partial_{D_i}\;  \rho_\ell(\, Y\,|\,\X\,)= 0$, $i = 1\ldots, m$. Indeed the Lagrangian is
\begin{align*}
    L(\ell, \x)
    :&=
    \int_{\R^{m}}\Big\{ \Big(\ell(U_{\mfg(\t, \x)|\X}) - \gamma(U_{\mfg(\t, \x)|\X})\Big)^2
    \\
    &\qquad + \sum_{k = 1}^m \, 2\;\eta_k(\x)\,  t_k \, \partial_{k} \mfg(\t, \x) \ell(U_{\mfg(\t, \x)|\X}) 
      \Big\}\diff F_{\D|\X}(\t|\x)\  
      \\
      &= 
     \int_{\R^{m}}\Big\{ \Big(\ell(U_{\mfg(\t, \x)|\X}) - 
     \big[\gamma(U_{\mfg(\t, \x)|\X})
      - \sum_{k = 1}^m \;\eta_k(\x)\,  t_k \, \partial_{k} \mfg(\t, \x)\big]\Big)^2
      \Big\} \diff F_{\D|\X}(\t|\x) + c\,,
\end{align*}
where $c$ contains terms independent of $\ell$. Thus, the optimal $\ell^*$ satisfies for all $(\t, \x) \in \supp(\D, \X)$
\begin{equation*}
 \ell^*
      :=    \gamma(U_{\mfg(\t, \x)|\X})
      - \sum_{k = 1}^m \;\eta_k^*(\x)\,  t_k \, \partial_{k} \mfg(\t, \x)\,,
\end{equation*}
where the Lagrange multipliers are such that the constraints are fulfilled.
Finally, we calculate 
\begin{align*}
    \rho_{\ell^*}(Y \,|\,\X) 
       &=
      \rho_{\gamma}(Y \,|\,\X) 
           - 
           \sum_{k = 1}^m \;\eta_k^*(\X)
       \;\E[Y \, D_i \, \partial_{i} \mfg(\D, \X)\, |\,\X ]\,,
\end{align*}
which concludes the representation of the multi-marginal fair decision rule. Uniqueness, if the multi-marginal fair decision rule exists, follows by strict convexity of the objective function and linearity of the constraints.
\end{proof}


\begin{proof}[Proof of \Cref{prop:marginal-compact}]
    This follows similarly to the proof of \Cref{prop:marginal-sensitivity} using the chain rule and noting that $\P$-a.s.
    \begin{equation*}
        \lim_{\delta\to 0}\frac{F_{D_i}^{-1} \big(\Phi \big(\Phi^{-1}(U) (1  + \delta)\big) \big) - D_i}{\delta}
        = 
        \frac{\phi\big(\Phi^{-1}(U)\big)}{f_{D_i}\big(F_{D_i}^{-1} (U ) \big)}
        =
        \frac{\phi\big(\Phi^{-1}(F_{D_i}(D_i))\big)}{f_{D_i} (D_i )}\,,
    \end{equation*}
    which concludes the proof.
\end{proof}

\begin{proof}[Proof of \Cref{cor:marginal-compact}]
    The proof follows along the lines of the proofs of \Cref{thm:individual} and \Cref{prop:mutli-marginal} and is omitted.
\end{proof}


\begin{proof}[Proof of \Cref{prop:sens-discrete-mean}]
We apply in the third equation \Cref{lemma:delta-function-general,lemma:derivative-kappa}, 
\begin{align*}
    \partial_{D_i} \, \E[Y|\X]
    &=
    \lim_{\delta \to 0} \frac1\delta \, \E[Y_\delta - Y \, |\,\X  ]
    \\
    &= 
    \lim_{\delta \to 0} \frac1\delta \sum_{k = 1}^{K-1}\E\big[ \Delta_k \mfg\, \big(\Id_{\{ \Phi\left(\Phi^{-1}(\tilde{U}) (1+ \delta)\right)\le p_k\}} - \Id_{\{ \tilde{U} \le p_k\}}\big)  \, |\,\X \big]
    \\
    &= 
    \sum_{k = 1}^{K-1} v_k \, \E \big[\Delta_k \mfg \Id_{\{\tilde{U} = p_k\}} \, |\,\X \big]
    \\
    &=
    \sum_{k = 1}^{K-1} v_k \, \E \big[\Delta_k \mfg \Id_{\{D_i = t_k\}} \, |\,\X \big]\,,
\end{align*}
where the last equation follows by definition of $\tilde{U}$.
\end{proof}


\begin{proof}[Proof of \Cref{thm:sens-discrete}]
Similar to the proof of \Cref{prop:marginal-sensitivity}, we denote the distorted output by $Y_\delta:=\mfg\big( \D_{i,\delta} , \X\big) $, with perturbation given in \eqref{eq:D-discrete-pert}, and the conditional cdfs by $F(y):= \P(Y \le y |\X = \x, \D_{-i} = \d_{-i})$ and by $F(y, \delta):= \P(Y_\delta \le y |\X = \x, \D_{-i} = \d_{-i})$. For simplicity we write $U:= U_{Y|\X, \D_{-i}}$, then as $F^{-1}(U, \delta) $ and $Y_\delta$ have the same distribution, for all $\delta\ge 0$, we have
\begin{align*}
    \lim_{\delta \to 0}\tfrac{1}{\delta}\big(\rho_\gamma(Y_\delta  | \X) &- \rho_\gamma(Y | \X)\big)
    \\
    &=
    \E\Big[ \E\big[ \lim_{\delta \to 0}\tfrac{1}{\delta}(F^{-1}(U, \delta) - F^{-1}(U)) \gamma(U)\, \big|\, \X = \x, \D_{-i} = \d_{-i}\big] \, \big|\, \X = \x \Big]\,.
\end{align*}
Using the representation of $Y_\delta$ and $Y$ in \eqref{eq:Y-discrete-pert}, and denoting $\kappa_\delta(x):= \Phi\left(\Phi^{-1}(x) (1+ \delta)\right)$, the inner expectation becomes, 
\begin{align*}
    \E\big[\lim_{\delta \to 0}\tfrac{1}{\delta} (F^{-1}(U, \delta)& - F^{-1}(U)) \gamma(U)\, \big|\, \X = \x, \D_{-i} = \d_{-i}\big]
    \\
    &= 
    \sum_{k = 1}^{K-1}\Delta_k \mfg \, \E\big[ \lim_{\delta \to 0}\tfrac{1}{\delta}\big(\Id_{\{ \kappa_\delta(\tilde{U}) \le p_k\}}  - \Id_{\{ \tilde{U}\le p_k\}} \big) \gamma(U)\, \big|\, \X = \x, \D_{-i} = \d_{-i}\big] 
    \\
    &= 
     \sum_{k = 1}^{K-1}v_k\, \Delta_k \mfg \, \E[  \Id_{\{D_i = t_k\}} \,\gamma(U)\, | \X = \x, \D_{-i} = \d_{-i}]
    \end{align*}
where in the last equation we applied \Cref{lemma:delta-function-general,lemma:derivative-kappa}. Collecting, we obtain
    \begin{align*}
     \lim_{\delta \to 0}\tfrac{1}{\delta}\big(\rho_\gamma(Y_\delta  | \X) - \rho_\gamma(Y | \X)\big)
    =
    \sum_{k = 1}^{K-1}v_k\,  \E[\Delta_k \mfg \, \Id_{\{D_i = t_k\}} \,  \gamma(U_{Y|\X})\,| \X = \x]
\end{align*}
which concludes the proof.
\end{proof}

\begin{proof}[Proof of \Cref{cor:marginal-discrete}]
    The proof follows along the lines of \Cref{cor:marginal-compact} and is omitted.
\end{proof}

\begin{proof}[Proof of \Cref{thm:casaade-sensitivity}]
