\begin{proof}[Proof of \Cref{prop:cascade-compact}]
    This follows from \Cref{prop:marginal-compact}.
\end{proof}


\begin{proof}[Proof of \Cref{prop:cascade-discrete}]
    First we note that
\begin{equation*}
    \partial_{D_i}^c\;  \rho_\gamma(\, Y\,|\,\X\,)
    =
    \sum_{l = 1}^{n+m} \lim_{\delta \to 0}\tfrac{1}{\delta}\Big(\rho_\gamma\big(\mfg\big((\D, \X)_{-l}, \Psi^{(l)}(D_{i, \delta}, \V)\big)\big) - \rho_\gamma(Y)\Big)\,,
\end{equation*}
where we use the notation that $(\D, \X)_{-l}$ is the vector $(\D, \X)$ deprived of the $l^\text{th}$ component, $l \in \{1, \ldots, m+n\}$. Then for each $l\in \{1, \ldots, m+n\}$, the perturbed output is
\begin{align*}
    \mfg\big((\D, \X)_{-l}, \Psi^{(l)}(D_{i, \delta}, \V)\big)
    =
    \sum_{k = 1}^K \Delta_{k,l} \tilde{\mfg}\, \Id_{\{ \Phi\left(\Phi^{-1}(\tilde{U}) (1+ \delta)\right)\le p_k\}}  + \tilde{\mfg}_{K,l}
        \,,
\end{align*}
where $ \Delta_{k,l} \tilde{\mfg}: =
\mfg\big((\D, \X)_{-l}, \Psi^{(l)}(t_k, \V)\big) - \mfg\big((\D, \X)_{-l}, \Psi^{(l)}(t_{k+1}, \V)\big)$, $k = 1, \ldots, K -1$, and $ \tilde{\mfg}_{K,l} := \mfg\big((\D, \X)_{-l}, \Psi^{(l)}(t_K, \V)\big)$. With this representation, we use for each $l \in \{1, \ldots, m+n\}$ similar steps as in the proof of \Cref{thm:sens-discrete} and obtain that
\begin{equation*}
    \partial_{D_i}^c\;  \rho_\gamma(\, Y\,|\,\X\,)
    =
    \sum_{l = 1}^{n+m}\, 
    \sum_{k = 1}^{K-1}
    \E[\Delta_{k,l} \tilde{\mfg} \, \Id_{\{D_i = t_k\}} \,  \gamma(U_{Y|\X})\,| \X = \x]\,.
\end{equation*}
Finally, noting that by the standard construction we can choose $\Psi^{(l)}(t_k, \V) = F_{D_l}^{-1}(V| D_i = t_k)$, for $l = 1, \ldots, m$, and $\Psi^{(l)}(t_k, \V) = F_{X_l}^{-1}(V| D_i = t_k)$, for $l = m+1, \ldots, m+n$, for a uniform rv $V$ independent of $D_i$, concludes the proof.
\end{proof}

