	\begin{notations}\label{notation-rKalpha}{\rm With the above notations, we set:
			\begin{itemize}
				\item $r(K,\alpha):=\sup\left\{r\in [0,1):\,r^{\sigma}\left(1+r\right)^{\tau}<M_K^{-\tau}\right\}$;
				%\item $\widetilde{r_1}(K,\zeta,\alpha):=\sup\left\{r\in [0,\mu_KM_K^{-1/\alpha}]:\,\frac{M_K|\zeta|}{\mu_K^{\alpha}}\left(\frac{r}{|\zeta|}\right)^{\alpha}\left(1+\frac{r}{|\zeta|}\right)<1\right\}$;
