			\end{itemize}
		}
	\end{notations}

	\noindent{}Observe that $r(K ,\tau)>0$ and that, if $K$ contains $1$ in its interior, then $K(\alpha)$ contains some non-empty open disc centered at $1$.
	%\begin{remark}{\rm It is worth noticing that the larger $\alpha$ is, the larger $r(K,\alpha)$ is, while the smaller (in terms of inclusion) the set $\EE(K,\alpha)$ is.}
	%\end{remark}

	Given $C>0$, $\sigma,\tau\in \N\setminus \{0\}$, and $n\in \N$, let us now define the polynomial $\Pi_{n,C}^{\sigma,\tau}$ by
	\begin{equation}\label{def-Pi-n}
		\Pi_{n,C}^{\sigma,\tau}(z)=C^nz^{\sigma n}\left(1-z\right)^{\tau n}.
	\end{equation}
	\noindent{}The introduction of these polynomials for our purpose, and the following fact, are inspired by the proof of Proposition 2.2 in \cite{Mouze2020}:
	\begin{fact}\label{fact-Pin}With the above notations,
		\begin{enumerate}[(a)]
			\item one can write $\Pi_{n,C}^{\sigma,\tau}(z)=\sum_{k=\sigma n}^{(\sigma +\tau)n}b_kz^k$ with $|b_k|\geq C^n$, $\sigma n\leq k \leq (\sigma +\tau)n$;
			\item $\Pi_{n,C}^{\sigma,\tau}(1)=0$ and, for any $\sigma n\leq j\leq (\sigma + \tau)n -1$, $|S_j(\Pi_{n,C}^{\sigma,\tau})(1)|=|\Re \left(S_j(\Pi_{n,C}^{\sigma,\tau})(1)\right)|\geq C^n$.
		\end{enumerate}
	\end{fact}

	\begin{proof}(a) By definition, a direct computation yields
		\[
		\Pi_{n,C}^{\sigma,\tau}(z) = C^n \sum_{k=\sigma n}^{(\sigma + \tau)n}\binom{\tau n}{k-\sigma n}(-1)^{k-\sigma n}z^k.
		\]
		Setting $b_k=C^n\binom{\tau n}{k-\sigma n}(-1)^{k-\sigma n}$, we get the second part of (a).

		(b) The first assertion is obvious. For the second, let $\sigma n\leq j\leq (\sigma + \tau)n -1$. The previous expression leads to
		\begin{eqnarray*}
			S_j(\Pi_{n,C}^{\sigma,\tau})(1) & = & \Re\left(S_j(\Pi_{n,C}^{\sigma,\tau})(1)\right)\\
			& = & C^n\sum_{k=0}^{j-\sigma n}\binom{\tau n}{k}(-1)^k\\
			& = & C^n (-1)^{j-\sigma n}\binom{\tau n-1}{j-\sigma n},
		\end{eqnarray*}
		where the last equality, which is rather standard, can be checked by induction.
	\end{proof}
