	%This theorem will be a crucial tool in proving the next lemma.

	We are ready to state and prove our lemma. 	From now on, if $P(z)=\sum_{k=0}^{n}a_kz^k$ is a non-zero polynomial then we denote by $\text{deg}(P)$ its degree and by $\text{val}(P)$ its valuation, that is $\text{val}(P):=\min\{k\in\N:a_k\neq0\}$.  We recall that, by Proposition \ref{prop-alphaK}, for any compact set $K\subset \C\setminus (-\infty,0]$ and any $\alpha \in (0,\alpha_K)$, there exists a simply connected bounded domain $G\subset \C\setminus (-\infty,0]$ containing $K$, such that $(G,z^{\alpha})$ is a pair of approximation.

	\begin{lemma}\label{lemma-approx-PV-control-partial-sums}Let $K\subset \C\setminus \D$ be a compact set, with connected complement. We assume that $1 \in K$ and that $K\cap (-\infty,0]=\emptyset$. Then, for any  $\alpha \in (0,\alpha_K)$, $\varepsilon>0$, $\vp \in A(K)$, $N\in \N$, $B\geq 0$, $r\in(0,r(K,\alpha))$ and any compact set $L\subset K(\alpha)$, there exists a polynomial $P=\sum_{k=v}^da_kz^k$ with $d>v\geq N$ such that:
		\begin{enumerate}
			\item $\sup_{z\in L}|P(z)-\vp(z)|< \varepsilon$;
			\item $\sup_{z\in \overline{D(0,r)}}|P(z)|<\varepsilon$;
			\item $\left|\Re(\sum_{k=N}^ja_k)\right|\geq B$, for any $v\leq j\leq d-1$;
			\item $\left|a_k\right|\geq B$, for any $v\leq k\leq d$;
		\end{enumerate}
	\end{lemma}

	\begin{proof}The idea is to construct $P$ as a sum of two polynomials: the first one, given by Theorem \ref{thm-PV}, will guarantee the desired simultaneous approximation (items (1) and (2)); The second one will suitably perturbate the first one in order to get (3) and (4).

		Let $\alpha$, $K$, $\vp$, and $\varepsilon>0$ be fixed as in the statement. Let $G$ be a simply connected bounded domain in $\C\setminus (-\infty,0]$, containing $K$, such that $(G,z^{\alpha})$ is a pair of approximation (Proposition \ref{prop-alphaK}). Upon adding a small segment to $K$, we may and shall assume that $K$ is non-polar. By Mergelyan's theorem, we may and shall assume that $\vp$ is a polynomial. Let us write $\alpha=\sigma/\tau$, with $\sigma$ and $\tau$ positive integers, and let us fix $r\in(0,r(K,\alpha))$ and a compact set $L\subset K(\alpha)$. By the definitions of $r(K,\alpha)$ and $K(\alpha)$, there exists $C>M_K^{\tau}$ such that
		\begin{equation}\label{choice-of-C}
			Cr^{\sigma}\left(1+r\right)^{\tau}<1 \quad \text{and} \quad \sup_{z\in L}C\left\vert z\right\vert^{\sigma}\left\vert1-z\right\vert^{\tau}<1.
		\end{equation}

		By Theorem \ref{thm-PV}, there exists a sequence $(Q_n)$ of polynomials, with $\text{deg}(Q_n)\leq n$, such that $\|z^{n\alpha}Q_n - \vp\|_{K}$ goes to $0$ as $n\to \infty$. Using $\alpha=\sigma/\tau$,  we get that the sequence $(z^{n\sigma}Q_{n\tau})_n$ is also convergent to $\vp$ uniformly on $K$. Let us fix $n_0\in \N$ such that
		\begin{equation}\label{ineq-first-Merg-on-K}
			\|z^{n\sigma}Q_{n\tau}-\vp\|_K < \varepsilon/2,\quad n\geq n_0.
		\end{equation}
		Fix any $n\geq n_0$. Since $K$ is non-polar, Bernstein's inequality (see \cite[Theorem 	5.5.7]{Ransford1995}) and the fact that $K\subset\C\setminus \D$ yield
		\[
		|Q_{n\tau}(z)| \leq \|Q_{n\tau}\|_Ke^{n\tau g_{\overline{\C}\setminus K}(z,\infty)}\leq \|z^{n\sigma}Q_{n\tau}\|_KM_K^{n\tau},\quad z\in \overline{\D}.
		\]
		Thus
		\begin{equation}\label{ineq-Qnl-Bernstein}
			|z^{n\sigma}Q_{n\tau}(z)| \leq \left(|z|^{\sigma}M_K^{\tau}\right)^{n}\|z^{n\sigma}Q_{n\tau}\|_K,\quad z\in \overline{\D}.
		\end{equation}
		Note that the first inequality of \eqref{choice-of-C} implies $r^{\sigma}M_K^{\tau}<1$, hence $\left(|z|^{\sigma}M_K^{\tau}\right)^{n} \to 0$ as $n\to \infty$, uniformly for $z\in \overline{D(0,r)}$. Since  the sequence $(\|z^{n\sigma}Q_{n\tau}\|_K)_{n\geq n_0}$ is bounded (by \eqref{ineq-first-Merg-on-K}), there exists $n_1\geq n_0$, such that for any $n\geq n_1$,
		\begin{equation}\label{ineq-Qnl}
			\|z^{n\sigma}Q_{n\tau}-\vp\|_K < \varepsilon/2\quad \text{and}\quad \|z^{n\sigma}Q_{n\tau}\|_{\overline{D(0,r)}}<\varepsilon/2.
		\end{equation}

		We shall now perturbate the polynomial $z^{n\sigma}Q_{n\tau}$. For $n\geq n_1$ and $C$ as above, let us set
		\[
		P_n(z)=z^{n\sigma}Q_{n\tau}+\Pi_{n,C}^{\sigma,\tau}(z);
		\]
		see \eqref{def-Pi-n} for the definition of $\Pi_{n,C}^{\sigma,\tau}$. By the definitions of $r(K,\alpha)$ and $K(\alpha)$, and the choice of $C$, it is clear that there exists $n_2\geq n_1$ such that for any $n\geq n_2$,
		\[
		\|P_n(z)-\vp\|_L < \varepsilon/2\quad \text{and}\quad \|P_n\|_{\overline{D(0,r)}}<\varepsilon/2,
		\]
		that is, $P_n$ satisfies (1) and (2) for any $n\geq n_2$.

		It remains to check that $P_n$ satisfies (3) and (4). To do so, let us estimate the coefficients of $z^{n\sigma}Q_{n\tau}$, and its partial sums at $1$, for $n\geq n_2$.  Let us write $z^{n\sigma}Q_{n\tau}=\sum_{k=n\sigma}^{n(\sigma+\tau)}c_kz^k$ with $c_k$ in $\C$.  Using that $K\subset \C\setminus \D$ together with \eqref{ineq-first-Merg-on-K} and \eqref{ineq-Qnl-Bernstein}, Cauchy's inequalities yield, for any $n\sigma\leq k\leq n(\sigma+\tau)$,
		\begin{equation}\label{eq-est-coef-ck}
			|c_k|\leq  M_K^{\tau n}\left(\|\vp\|_K+\varepsilon/2\right),
		\end{equation}
		and, for any $n\sigma\leq j<n(\sigma+\tau)$,
		\begin{equation}\label{ineq-partial-sum-znsQnl}
			|S_j(z^{n\tau}Q_{n\sigma})(1)|\leq n\tau M_K^{\tau n}\left(\|\vp\|_K+\varepsilon/2\right).
		\end{equation}
		Let us denote by $a_{k,n}$ the $k$th Taylor coefficient of $P_n$. By construction, Fact \eqref{fact-Pin} and the inequalities \eqref{eq-est-coef-ck} and \eqref{ineq-partial-sum-znsQnl}, we get for any $n\sigma \leq k\leq n(\sigma +\tau)$,
		\[
		|a_{k,n}|\geq C^n - M_K^{\tau n}\left(\|\vp\|_K+\varepsilon/2\right),
		\]
		and for any $n\sigma \leq j< n(\sigma +\tau)$,
		\[
		|S_j(P_n)(1)|\geq C^n - n\tau M_K^{\tau n}\left(\|\vp\|_K+\varepsilon/2\right).
		\]
		Finally, using $C>M_K^{\tau}$ , there exists $n\geq n_2$ such that $P:=P_n$ has all the desired properties.
	\end{proof}

	\medskip

	We shall now derive from this lemma answers to the motivational problems mentioned in the introduction. First of all, we will use it to construct a function in $H(\D)$ whose partial sums are dense in a half-space of $A(K)$, but not in the whole space $A(K)$. Given a real number $s$, we shall denote by $\C_{s}^+$ the half-space $\{z\in \C:\,\Re(z)\geq s\}$ and by $\C_{s}^-$ the half-space $\{z\in \C:\,\Re(z)\leq s\}$. We keep on using Notations \ref{notation-rKalpha}.

	\begin{theorem}\label{thm-Cos-Peris-restricted}Let $K\subset \C\setminus \D$ be a compact set, with connected complement and let $\alpha \in (0,\alpha_K)$. We assume that $1 \in K$ and that $K\cap (-\infty,0]=\emptyset$. Then there exists a function $f\in H(D(0,r(K,\alpha)))$ such that the following properties hold true:
		\begin{enumerate}
			\item \label{item-1-thm-CP}for any $\vp \in A(K)$ with $\vp(1)\in\C_{0}^+$ and any compact subset $L$ of $K(\alpha)$ with connected complement, there exists a sequence $(\lambda_n)_n$ of integers such that
			\[
			S_{\lambda_n}(f) \to \vp \quad \text{uniformly on }L\text{ as }n\to \infty;
			\]
			\item \label{item-2-thm-CP}for any $n\in \N$, $S_n(f)(1)\in \C_{-1}^-\cup \C_{0}^+$.
		\end{enumerate}
	\end{theorem}

	\begin{proof}Let $\alpha$ and $K$ be fixed as in the statement. Let $(\vp_n)_n$ be a sequence contained and dense in the half-space $\{\vp \in A(K):\,\vp(1)\in \C_0^+\}$ of $A(K)$. Without loss of generality, we may and shall also assume that $\Re{(\vp_n(1))}>0$. Let us also fix two sequences of positive real numbers $(\varepsilon_n)_n$ and $(s_n)_n$ such that $(\varepsilon_n)_n$ decreases to $0$ and satisfies $0<\varepsilon_n < \Re(\vp_n(1))$, and $(s_n)_n$ increases to $r(K,\alpha)$. Let also $(L_n)_n$ be an increasing exhaustion of $K(\alpha)$ by compact sets, such that
		\[
		\sup_{z\in L_n}\left\vert z\right\vert^{\sigma}\left\vert1-z\right\vert^{\tau}<\left(1-\frac{1}{n}\right)M_K^{-\tau},\, n\in \N.
		\]

		Let us now build by induction polynomials $P_n$, $n\in \N$, with the help of Lemma \ref{lemma-approx-PV-control-partial-sums}. We set $P_0=0$ and suppose that $P_1,\ldots P_{n-1}$ have been built. We apply Lemma \ref{lemma-approx-PV-control-partial-sums}, with $\vp=\vp_n-\sum_{k=0}^{n-1}P_k$, $\varepsilon=\varepsilon_n$, $N=\text{deg}(P_{n-1})+1$, $r=s_n$, $L=L_n$ and $B=|\Re(\sum_{k=0}^{n-1}P_k(1))|+1$. It directly follows that, for any $n\geq 1$,
