		\begin{align*}
			\begin{autobreak}
				\MoveEqLeft[0]
				(1+\alpha)P(\phi(\infty),\phi(\zeta))-\alpha P(\phi(0),\phi(\zeta))
				=\frac{1}{2\pi}\left((1+\alpha)-\alpha\frac{1-\left(\frac{\tilde{\phi}^{-1}(0)}{1-\varepsilon}\right)^2}{\left|\phi(\zeta)-\left(\frac{\tilde{\phi}^{-1}(0)}{1-\varepsilon}\right)\right|^2}\right)
				\geq\frac{1}{2\pi}\left((1+\alpha)-\alpha\frac{1-\left(\frac{\tilde{\phi}^{-1}(0)}{1-\varepsilon}\right)^2}{\left(1+\left(\frac{\tilde{\phi}^{-1}(0)}{1-\varepsilon}\right)\right)^2}\right)
				=\frac{1}{2\pi}\left((1+\alpha)-\alpha\frac{1-\frac{\tilde{\phi}^{-1}(0)}{1-\varepsilon}}{1+\frac{\tilde{\phi}^{-1}(0)}{1-\varepsilon}}\right)
			\end{autobreak}
		\end{align*}
		where the inequality comes from the fact that
		\[
		\frac{\tilde{\phi}^{-1}(0)}{1-\varepsilon}=\frac{\sqrt{\left(\frac{x_0+1}{x_0-1}\right)^2-1}-\frac{x_0+1}{x_0-1}}{1-\varepsilon}\in(-1,0),
		\]
		and, thus, that
		\[
		\min\left\{\left|\phi(\zeta)-\left(\frac{\tilde{\phi}^{-1}(0)}{1-\varepsilon}\right)\right|:\zeta\in\partial G_\varepsilon\right\}=1+\frac{\tilde{\phi}^{-1}(0)}{1-\varepsilon}.
		\]
		A straightforward computation shows that
		\[
		(1+\alpha)-\alpha\frac{1-\frac{\tilde{\phi}^{-1}(0)}{1-\varepsilon}}{1+\frac{\tilde{\phi}^{-1}(0)}{1-\varepsilon}}\geq 0
		\]
		if and only if $\tilde{\phi}^{-1}(0)\geq-\frac{1-\varepsilon}{1+2\alpha}$.
		\begin{comment}
			\begin{align*}
				\begin{autobreak}
					\MoveEqLeft[0]
					(1+\alpha)-\alpha\frac{1-\frac{\tilde{\phi}^{-1}(0)}{1-\varepsilon}}{1+\frac{\tilde{\phi}^{-1}(0)}{1-\varepsilon}}\geq0
					\iff(1+\alpha)\left(1+\frac{\tilde{\phi}^{-1}(0)}{1-\varepsilon}\right)\geq\alpha+\alpha\left(1-\frac{\tilde{\phi}^{-1}(0)}{1-\varepsilon}\right)
					\iff(1+2\alpha)\frac{\tilde{\phi}^{-1}(0)}{1-\varepsilon}\geq-1
					\iff\tilde{\phi}^{-1}(0)\geq-\frac{1-\varepsilon}{1+2\alpha}.
				\end{autobreak}
			\end{align*}
		\end{comment}
		Without loss of generality, we assume that $\varepsilon$ is small enough so that $\frac{1-\varepsilon}{1+2\alpha}<1$. Composing the previous inequality by $\tilde{\phi}$, that is decreasing on $(-1,0)$ (since $\psi$ is), one easily checks that $\tilde{\phi}^{-1}(0)\geq-\frac{1-\varepsilon}{1+2\alpha}$ holds if and only if
		\[
		x_0\leq \left(\frac{(1+2\alpha)+(1-\varepsilon)}{(1+2\alpha)-(1-\varepsilon)}\right)^2.
		\]
		\begin{comment}We can easily check that $\psi$ (and so also $\tilde{\phi}$) is decreasing on $(-1,0)$ and so
			\begin{align*}
				\begin{autobreak}
					\MoveEqLeft[0]
					\tilde{\phi}^{-1}(0)\geq-\frac{1-\varepsilon}{1+2\alpha}
					\iff\tilde{\phi}\left(-\frac{1-\varepsilon}{1+2\alpha}\right)\geq0
					\iff-\frac{x_0-1}{4}\left(\frac{1-\varepsilon}{1+2\alpha}+\frac{1+2\alpha}{1-\varepsilon}\right)+\frac{x_0+1}{2}\geq0
					\iff x_0\left(\frac{1-\varepsilon}{1+2\alpha}+\frac{1+2\alpha}{1-\varepsilon}-2\right)\leq\left(\frac{1-\varepsilon}{1+2\alpha}+\frac{1+2\alpha}{1-\varepsilon}+2\right)
					\iff x_0\leq\frac{(1-\varepsilon)^2+(1+2\alpha)^2+2(1-\varepsilon)(1+2\alpha)}{(1-\varepsilon)^2+(1+2\alpha)^2-2(1-\varepsilon)(1+2\alpha)}
					\iff x_0\leq\left(\frac{(1+2\alpha)+(1-\varepsilon)}{(1+2\alpha)-(1-\varepsilon)}\right)^2
					\iff x_0\leq g(1-\varepsilon)
				\end{autobreak}
			\end{align*}
			where $g:[0,1]\to\R$ is the function $g(y)=\left(\frac{(1+2\alpha)+y}{(1+2\alpha)-y}\right)^2$ for $y\in[0,1]$.
		\end{comment}
		Since the right-hand side of the last inequality is a continuous decreasing function of $\varepsilon$ on $(0,1)$, that takes the value $\left(\frac{1+\alpha}{\alpha}\right)^2$ at $0$, we deduce frome the above that, if $x_0<\left(\frac{1+\alpha}{\alpha}\right)^2$, or equivalently if $\alpha<\frac{1}{\sqrt{x_0}-1}$, then $(G_{\varepsilon},z^{\alpha})$ is a pair of approximation for every $\varepsilon$ small enough, by Corollary \ref{poisson}. Conversely, if $\alpha\geq \frac{1}{\sqrt{x_0}-1}$, the same argument shows that $(G_\varepsilon,z^{\alpha})$ is a pair of approximation for no $\varepsilon>0$. To finish, if $G$ is a simply connected bounded domain in $\C\setminus(-\infty,0]$ that contains $K$, then $G\supseteq G_{\varepsilon}$ for some $\varepsilon>0$, hence $(G,z^{\alpha})$ cannot be a pair of approximation. This completes the proof.
