	Using Theorem \ref{Solynin} (taking into account its last part), we immediately get
	\begin{equation*}
		M_K
		=\exp\left(\Phi\left(\frac{\textup{dist}(-1,K)}{\textup{diam}(K)}\right)\right)
		=\exp\left(\Phi\left(\frac{2}{x_0-1}\right)\right)
		\left(\sqrt{\frac{2}{x_0-1}+1}+\sqrt{\frac{2}{x_0-1}}\right)^2.
	\end{equation*}

	\subsection{When $K$ is a subarc of the unit circle}
	Let $\theta_0\in(0,2\pi)$ and $K=\left\{e^{i\theta}:\theta\in\left[\frac{-\theta_0}{2},\frac{\theta_0}{2}\right]\right\}$. Let $\psi:\overline{\C}\setminus K\to\overline{\C}\setminus\overline{D\left(0,\sin\left(\frac{\theta_0}{4}\right)\right)}$ be the function defined by
	\[
	\psi(z)=\frac{1}{2}\left(z-1+\sqrt{\left(z-e^{i\frac{\theta_0}{2}}\right)\left(z-e^{-i\frac{\theta_0}{2}}\right)}\right),
	\]
	where the square root is chosen so that $\psi(z)=z+O(1)$ as $z\to\infty$. Then $\psi$ is a conformal mapping onto $\overline{\C}\setminus\overline{D\left(0,\sin\left(\frac{\theta_0}{4}\right)\right)}$ (see Exercise 4 on page 137 in \cite{Ransford1995}).

	Now, let $0<\varepsilon<1-\sin\left(\frac{\theta_0}{4}\right)$. Then $\psi^{-1}\left(\partial D\left(0,\sin\left(\frac{\theta_0}{4}\right)+\varepsilon\right)\right)$ is a Jordan curve whose ``interior'' contains $K$. Denoting by $G_\varepsilon$ this domain, it is clear that $G_\varepsilon\subseteq\C\setminus(-\infty,0]$. The following proposition provides us with the exact value of $\alpha_K$ in this setting.
	\begin{prop}
		For $K$ as above, the following holds:
		\[
		\alpha_K=\frac{1-\sin\left(\frac{\theta_0}{4}\right)}{2\sin\left(\frac{\theta_0}{4}\right)}.
		\]
	\end{prop}
	\begin{proof}
		Since $\psi$ maps $\overline{\C}\setminus \overline{G_{\varepsilon}}$ conformally onto $\overline{\C}\setminus\overline{D\left(0,\sin\left(\frac{\theta_0}{4}\right)+\varepsilon\right)}$, the function
		\[
		\phi:\left\{\begin{array}{ccc}
			\overline{\C}\setminus \overline{G_{\varepsilon}} & \to & \D\\
			z & \mapsto & \frac{\sin\left(\frac{\theta_0}{4}\right)+\varepsilon}{\psi(z)}
		\end{array}
		\right.
		\]
		is conformal onto $\D$. Taking into account that $\psi(\infty)=\infty$ and $\psi(0)=-1$ we have, for $\zeta\in\partial G_{\varepsilon}$,
		\begin{align*}
			\begin{autobreak}
				\MoveEqLeft[0]
				(1+\alpha)P(\phi(\infty),\phi(\zeta))-\alpha P(\phi(0),\phi(\zeta))
				=\frac{1}{2\pi}\left((1+\alpha)-\alpha\frac{1-\left(\sin\left(\frac{\theta_0}{4}\right)+\varepsilon\right)^2}{\left|\phi(\zeta)-\left(\sin\left(\frac{\theta_0}{4}\right)+\varepsilon\right)\right|^2}\right)
				\geq\frac{1}{2\pi}\left((1+\alpha)-\alpha\frac{1-\left(\sin\left(\frac{\theta_0}{4}\right)+\varepsilon\right)^2}{\left(1-\left(\sin\left(\frac{\theta_0}{4}\right)+\varepsilon\right)\right)^2}\right)
				=\frac{1}{2\pi}\left((1+\alpha)-\alpha\frac{1+\sin\left(\frac{\theta_0}{4}\right)+\varepsilon}{1-\left(\sin\left(\frac{\theta_0}{4}\right)+\varepsilon\right)}\right)
			\end{autobreak}
		\end{align*}
		where we used the fact that $\min\left\{\left|\phi(\zeta)-\left(\sin\left(\frac{\theta_0}{4}\right)+\varepsilon\right)\right|:\zeta\in\partial G_\varepsilon\right\}=1-\left(\sin\left(\frac{\theta_0}{4}\right)+\varepsilon\right)$ for the inequality above. Now, a direct computation shows that the inequality
		\[
		(1+\alpha)-\alpha\frac{1+\sin\left(\frac{\theta_0}{4}\right)+\varepsilon}{1-\sin\left(\frac{\theta_0}{4}\right)+\varepsilon}\geq0
		\]
		is equivalent to
		\[
		\sin\left(\frac{\theta_0}{4}\right)+\varepsilon\leq\frac{1}{1+2\alpha}.
		\]
		Thus, by Corollary \ref{poisson}, if $\sin\left(\frac{\theta_0}{4}\right)<\frac{1}{1+2\alpha}$, or equivalently if $\alpha<\frac{1-\sin\left(\frac{\theta_0}{4}\right)}{2\sin\left(\frac{\theta_0}{4}\right)}$, then $(G_\varepsilon,z^{\alpha})$ is a pair of approximation for every $\varepsilon$ small enough. Conversely, if $\alpha\geq \frac{1-\sin\left(\frac{\theta_0}{4}\right)}{2\sin\left(\frac{\theta_0}{4}\right)}$, then $(G_\varepsilon,z^{\alpha})$ is a pair of approximation for no $\varepsilon>0$. We conclude as at the end of the proof of Proposition \ref{compu-alphaK-interval}.
	\end{proof}
	Let us now estimate $M_K$. By Theorem \ref{Solynin},
	\[
	M_K\leq\sup\left\{\Phi\left(\frac{\textup{dist}(z,K)}{\textup{diam}(K)}\right):\, z\in\D\right\}=\Phi\left(\frac{\sup\left\{\textup{dist}(z,K):\, z\in\D\right\}}{\textup{diam}(K)}\right).
	\]
	Now, we easily see that
	\[ 
	\textup{diam}(K)= \left\{
	\begin{array}{ll}
		2\sin\left(\frac{\theta_0}{2}\right) & \text{ if } \theta_0\in(0,\pi] \\
		2 & \text{ else },
	\end{array} 
	\right. 
	\]
	and that $\sup\left\{\textup{dist}(z,K):\, z\in\D\right\}=\textup{dist}(-1,K)=\sqrt{1+2\cos\left(\frac{\theta_0}{2}\right)}$. Finally, we get
	\[ 
	M_K\leq \left\{
	\begin{array}{ll}
		\exp\left(\Phi\left(\frac{\sqrt{1+2\cos\left(\frac{\theta_0}{2}\right)}}{2\sin\left(\frac{\theta_0}{2}\right)}\right)\right) & \text{ if } \theta_0\in(0,\pi] \\
		\exp\left(\Phi\left(\frac{\sqrt{1+2\cos\left(\frac{\theta_0}{2}\right)}}{2}\right)\right) & \text{ else }.
	\end{array} 
	\right. 
	\]


