The work-statistics for a single-mode bead-spring-dashpot subjected to constant velocity pulling was derived in ref.~\citenum{Kailasham2020}, in which the stiffness of the steering spring was taken to be $c_2$. Setting $N=1$ and $c=c_2$, we obtain, 
\begin{equation}\label{eq:n1_sim}
\begin{split}
\left[\bm{A}\right]_{NN}&=(c_2+1)\\
\left[\bm{L}\right]_{NN}&=1\\
\left[\bm{D}\right]_{NN}&=\left[1+\left(\dfrac{K}{\zeta}\right)\right]^{-1}=\left[\dfrac{\zeta}{\zeta+K}\right]
\end{split}
\end{equation}
and the dimensionless work
\begin{align*}
&\left<{W}_{\text{dis}}\right>_{N=1}=\dfrac{\left(\zeta+K\right)}{\zeta}\left(\dfrac{c_2}{c_2+1}\right)^2vd\nonumber\\
&+\dfrac{c_2^2}{\left(c_2+1\right)^3}\left(\dfrac{\zeta+K}{\zeta}\right)^2\left[\exp\left(-\dfrac{\zeta\left(c_2+1\right)\tau_{\text{m}}}{\left(\zeta+K\right)}\right)-1\right]v^2
\end{align*}
Denoting the dimensional variables with an asterisk, we have $d=d^{*}\sqrt{H/k_BT}$, $\tau_{\text{m}}=Ht^{*}_{\text{m}}/\zeta$ and $v=v^{*}\zeta/\sqrt{k_BTH}$, we obtain
\begin{align}
&\left<{W}^{*}_{\text{dis}}\right>_{N=1}=\left(\dfrac{c_2}{c_2+1}\right)^2\left(\zeta+K\right)v^{*}d^{*}\\\nonumber
&+\dfrac{c^2_2}{\left(c_2+1\right)^3}\dfrac{\left(\zeta+K\right)^2v^{*2}}{H}\left[\exp\left(-\dfrac{H\left(c_2+1\right)d^{*}}{\left(\zeta+K\right)v^{*}}\right)-1\right],
\end{align}
which agrees identically with eq.~(16) in ref.~\citenum{Kailasham2020}. We report the value of the dimensionless dissipation for a dumbbell in the limit of large trap stiffness here: 
\begin{align}\label{eq:vel_N1}
\lim_{c\to\infty}\left<{W}_{\text{dis}}\right>_{N=1}=\left(1+\varphi\right)vd
\end{align}
as it will be useful for later discussion in the manuscript.

\vspace{-10pt}

~\citet{Speck2005} have studied Rouse chains (without internal friction) subjected to constant velocity pulling and oscillatory driving. In their paper, the last bead of the Rouse chain is directly manipulated to move at a prescribed velocity (or frequency) and is not attached to a steering spring. Their results may be extended to describe the case of a chain being pulled by a steering spring with a different stiffness, but the paper~\cite{Speck2005} only reports results for the case where all the springs are of the same stiffness. To compare our results with theirs, we set $c=1$, and note for a Rouse chain that 
\begin{align}
\begin{split}
\bm{D}&=\bm{D}^{-1}=\boldsymbol{\delta}\\[5pt]
\boldsymbol{\Phi}&=\left[\omega^2\boldsymbol{\delta}+\bm{A}^{2}\right]^{-1}
\end{split}
\end{align}
resulting in the following expression for the dissipation
\begin{equation}\label{eq:wdis_rouse_oscil}
\begin{split}
&\left<W_{\text{dis}}\right>_{\text{Rouse}}=\dfrac{d^2\omega^2}{4}\left[1-\cos(2\omega\tau_{\text{m}})\right]\left[\boldsymbol{\Phi}\cdot\bm{A}^{-1}\right]_{NN}\\[5pt]
&+\dfrac{d^2\omega}{4}\left[2\omega\tau_{\text{m}}+\sin(2\omega\tau_{\text{m}})\right]\left[\boldsymbol{\Phi}\right]_{NN}\\[5pt]
&-d^2\omega^3\left[\sin(\omega\tau_{\text{m}})\boldsymbol{\Phi}^2\cdot\bm{G}(\tau_{\text{m}})\right]_{NN}\\[5pt]
&+d^2\omega^2\left[\cos(\omega\tau_{\text{m}})\boldsymbol{\Phi}^2\cdot\bm{A}\cdot\bm{G}(\tau_{\text{m}})\right]_{NN}-d^2\omega^2\left[\boldsymbol{\Phi}^2\cdot\bm{A}\right]_{NN}
\end{split}
\end{equation} 

We next seek to obtain an expression for the dissipation in the limit of slow driving $(\omega\ll1)$. In the absence of an analytical expression for $\boldsymbol{\Phi}$, we numerically evaluate the $(NN)^{\text{th}}$ element of this matrix and plots its dependence on frequency and chain length in Fig.~\ref{fig:phi_var}. 

We observe that $\boldsymbol{\Phi}_{NN}$ has a low frequency plateau whose value varies linearly with the chain length. In the slow driving regime, therefore, we may only retain terms from eq.~(\ref{eq:wdis_rouse_oscil}) that are linear in $\omega$, and reject the higher-order terms, to give
\begin{align}\label{eq:ps_slow_oscil}
&\lim_{\omega\ll1}\left<W_{\text{dis}}\right>_{\text{Rouse}}\approx\dfrac{d^2\omega}{4}\left[2\omega\tau_{\text{m}}+\sin(2\omega\tau_{\text{m}})\right]\left[\boldsymbol{\Phi}\right]_{NN}\nonumber\\[5pt]
&=\dfrac{N}{3}\dfrac{d^2\omega}{4}\left[2\omega\tau_{\text{m}}+\sin(2\omega\tau_{\text{m}})\right]
\end{align}
where the equality in the second line follows from Fig.~\ref{fig:phi_var}~(b), by replacing the $(NN)^{\text{th}}$ element of $\boldsymbol{\Phi}$ with $(N/3)$ in the limit of slow driving. 
Using $d=d^{*}\sqrt{H/k_BT}$, $\tau_{\text{m}}=Ht^{*}_{\text{m}}/\zeta$ and $\omega=\omega^{*}\zeta/H$ to cast eq.~(\ref{eq:ps_slow_oscil}) in its dimensional form, 
\begin{align}\label{eq:ps_slow_dim}
&\left<W^{*}_{\text{dis}}\right>_{\text{Rouse}}=\dfrac{N\zeta}{3}\dfrac{d^{2*}\omega^{*}}{4}\left[2\omega^*\tau^*_{\text{m}}+\sin(2\omega^*\tau^*_{\text{m}})\right]
\end{align}
We reproduce below eq.~(66) exactly as it appears in the paper by~\citet{Speck2005}, which is an analytical expression for the average dimensional dissipation in the slow driving regime:
\begin{align}\label{eq:slow_66}
\overline{W_{\text{d}}}=\dfrac{N\gamma}{3}\dfrac{L^2\omega}{4}\left[2\omega t_{\text{s}}+\sin(2\omega t_{\text{s}})\right]
\end{align}
where $\gamma$ is the friction coefficient, which is denoted by $\zeta$ in this manuscript. The term $L$ represents the distance over which the last bead is moved over a time interval $t_{\text{s}}$, whose equivalents are $d^{*}$ and $\tau^{*}_{\text{m}}$ in the present work.
The excellent agreement between eqs.~(\ref{eq:ps_slow_dim}) and ~(\ref{eq:slow_66}) provide a validation of the work expression derived in this manuscript.

It is also instructive to write the expression for dissipation incurred in subjecting a single-mode spring-dashpot ($N=1$) to oscillatory driving, as this result will be discussed later in the manuscript. For $N=1$, eq.~(\ref{eq:n1_sim}) applies, along with
\begin{widetext}
\begin{equation}\label{eq:n1_phi}
\begin{split}
\left[\boldsymbol{\Phi}\right]_{NN}&=\dfrac{\left(1+\varphi\right)^2}{\omega^2\left(1+\varphi\right)^2+(c+1)^2}\\[5pt]
\left[\boldsymbol{\Phi}\cdot\bm{A}^{-1}\right]_{NN}&=\left(\dfrac{1}{c+1}\right)\left[\dfrac{\left(1+\varphi\right)^2}{\omega^2\left(1+\varphi\right)^2+(c+1)^2}\right]\\[5pt]
\left[\boldsymbol{\Phi}\cdot\bm{D}\right]_{NN}&=\left[\dfrac{\left(1+\varphi\right)}{\omega^2\left(1+\varphi\right)^2+(c+1)^2}\right]\\[5pt]
\left[\boldsymbol{\Phi}^2\cdot\bm{G}(\tau_{\text{m}})\cdot\bm{D}\right]_{NN}&=\dfrac{\left(1+\varphi\right)^3}{\left[\omega^2\left(1+\varphi\right)^2+(c+1)^2\right]^2}\exp\left[-\dfrac{c+1}{1+\varphi}\tau_{\text{m}}\right]\\[5pt]
\left[\boldsymbol{\Phi}^2\cdot\left(\bm{D}\cdot\bm{A}\right)\cdot\bm{G}(\tau_{\text{m}})\cdot\bm{D}\right]_{NN}&=\dfrac{\left(1+\varphi\right)^2(c+1)}{\left[\omega^2\left(1+\varphi\right)^2+(c+1)^2\right]^2}\exp\left[-\dfrac{c+1}{1+\varphi}\tau_{\text{m}}\right]\\[5pt]
\left[\boldsymbol{\Phi}\cdot\bm{D}\cdot\bm{A}\cdot\bm{D}\right]_{NN}&=\dfrac{\left(1+\varphi\right)^2(c+1)}{\left[\omega^2\left(1+\varphi\right)^2+(c+1)^2\right]^2}
\end{split}
\end{equation}
%\end{widetext}
Substituting eq.~(\ref{eq:n1_phi}) into eq.~(\ref{eq:wdis_o_num}) and simplifying,
\begin{equation}\label{eq:n1_wdis_os}
\begin{split}
&\left<W_{\text{dis}}\right>_{N=1}=\dfrac{c^2d^2\omega^2}{2}\left(\dfrac{1}{c+1}\right)\left[\dfrac{\left(1+\varphi\right)^2}{\omega^2\left(1+\varphi\right)^2+(c+1)^2}\right]+\dfrac{\pi c^2d^2\omega}{4}\left[\dfrac{\left(1+\varphi\right)}{\omega^2\left(1+\varphi\right)^2+(c+1)^2}\right]\\[5pt]
&-\dfrac{c^2d^2\omega^3\left(1+\varphi\right)^3}{\left[\omega^2\left(1+\varphi\right)^2+(c+1)^2\right]^2}\exp\left[-\dfrac{c+1}{1+\varphi}\tau_{\text{m}}\right]-\dfrac{c^2d^2\omega^2\left(1+\varphi\right)^2(c+1)}{\left[\omega^2\left(1+\varphi\right)^2+(c+1)^2\right]^2}
\end{split}
\end{equation}

%\begin{equation}\label{eq:n1_wdis_os}
%\begin{split}
%&\left<W_{\text{dis}}\right>_{N=1}=\dfrac{c^2d^2\omega^2}{2}\left(\dfrac{1}{c+1}\right)\left[\dfrac{\left(1+\varphi\right)^2}{\omega^2\left(1+\varphi\right)^2+(c+1)^2}\right]\\[5pt]
%&+\dfrac{\pi c^2d^2\omega}{4}\left[\dfrac{\left(1+\varphi\right)}{\omega^2\left(1+\varphi\right)^2+(c+1)^2}\right]\\[5pt]
%&-\dfrac{c^2d^2\omega^3\left(1+\varphi\right)^3}{\left[\omega^2\left(1+\varphi\right)^2+(c+1)^2\right]^2}\exp\left[-\dfrac{c+1}{1+\varphi}\tau_{\text{m}}\right]\\[5pt]
%&-\dfrac{c^2d^2\omega^2\left(1+\varphi\right)^2(c+1)}{\left[\omega^2\left(1+\varphi\right)^2+(c+1)^2\right]^2}
%\end{split}
%\end{equation}

\end{widetext}
In the limit of large steering spring stiffness ($c\to\infty$), we recognize that eq.~(\ref{eq:n1_wdis_os}) becomes
\begin{align}\label{eq:oscil_large_c}
\lim_{c\to\infty}\left<W_{\text{dis}}\right>_{N=1}=\dfrac{\pi d^2\omega}{4}(1+\varphi)
\end{align} 
while taking the limit of a large driving frequency ($\omega\to\infty$) in eq.~(\ref{eq:n1_wdis_os}) results in
\begin{align}
\lim_{\omega\to\infty}\left<W_{\text{dis}}\right>_{N=1}&=\dfrac{d^2}{2}\dfrac{c^2}{c+1}+\dfrac{c^2d^2\pi}{4(1+\varphi)}
\end{align}

