\section{\label{sec:app_a} Simplifications used in the derivation of work expression}
This section contains the detailed steps pertaining to the simplification of equations that appear in the derivation of the work expression.
\subsection{\label{sec:i_derv} Simplifying the second term on the RHS of eq.~(\ref{eq:mean_work_step2})}
Defining 
\begin{equation}\label{eq:def_i}
I=\int_{0}^{\tau_{\text{m}}}d\tau\dot{\bm{h}}(\tau)\cdot\int_{0}^{\tau}d\tau'\bm{G}(\tau-\tau')\cdot\bm{D}\cdot\boldsymbol{h}(\tau')
\end{equation}
we start by simplifying the term within the square braces on the RHS of eq.~(\ref{eq:def_i}). Noting that
\begin{equation}\label{eq:intermed_1}
\dfrac{d}{d\tau'}\left\{\bm{G}(\tau-\tau')\right\}\cdot\bm{A}^{-1}=\bm{G}(\tau-\tau')\cdot\bm{D},
\end{equation}
and integrating the inner integral in eq.~(\ref{eq:def_i}) by parts, we may write
\begin{align}\label{eq:inner_integ}
&\int_{0}^{\tau}d\tau'\bm{G}(\tau-\tau')\cdot\bm{D}\cdot\boldsymbol{h}(\tau')=\bm{A}^{-1}\cdot\bm{h}(\tau)-\bm{G}(\tau)\cdot\bm{A}^{-1}\cdot\bm{h}(0)-\int_{0}^{\tau}d\tau'\bm{G}(\tau-\tau')\cdot\bm{A}^{-1}\cdot\dot{\bm{h}}(\tau')
\end{align}
Substituting eq.~(\ref{eq:inner_integ}) into eq.~(\ref{eq:def_i}), we obtain
\begin{align}\label{eq:i_final}
I&=\int_{0}^{\tau_{\text{m}}}d\tau\dot{\bm{h}}(\tau)\cdot\bm{A}^{-1}\cdot\bm{h}(\tau)-\int_{0}^{\tau_{\text{m}}}d\tau\dot{\bm{h}}(\tau)\cdot\bm{G}(\tau)\cdot\bm{A}^{-1}\cdot\bm{h}(0)-\int_{0}^{\tau_{\text{m}}}d\tau\int_{0}^{\tau}d\tau'\dot{\bm{h}}(\tau)\cdot\bm{G}(\tau-\tau')\cdot\bm{A}^{-1}\cdot\dot{\bm{h}}(\tau')
\end{align}
\end{widetext}
which, upon substitution into eq.~(\ref{eq:mean_work_step2}), yields eq.~(\ref{eq:av_work_intermed}).

\subsection{\label{sec:j_derv} Simplifying the second term on the RHS of eq.~(\ref{eq:av_work_intermed})}
Defining
\begin{equation}\label{eq:def_j}
J=\int_{0}^{\tau_{\text{m}}}d\tau{\dot{\bm{h}}(\tau)}\cdot\bm{A}^{-1}\cdot\bm{h}(\tau)
\end{equation}
and integrating by parts, we get
\begin{align}\label{eq:j_eval_1}
J&=\bm{h}(\tau)\cdot\bm{A}^{-1}\cdot\bm{h}(\tau)\bigg\rvert_{0}^{\tau_{\text{m}}}-\int_{0}^{\tau_{\text{m}}}d\tau\dot{\bm{h}}(\tau)\cdot\bm{A}^{-1}\cdot\bm{h}(\tau)\nonumber\\[5pt]
&=\bm{h}(\tau_{\text{m}})\cdot\bm{A}^{-1}\cdot\bm{h}(\tau_{\text{m}})-\bm{h}(0)\cdot\bm{A}^{-1}\cdot\bm{h}(0)-J
\end{align}
and finally, 
\begin{equation}\label{eq:j_ans}
J=\dfrac{1}{2}\left[\bm{h}(\tau_{\text{m}})\cdot\bm{A}^{-1}\cdot\bm{h}(\tau_{\text{m}})-\bm{h}(0)\cdot\bm{A}^{-1}\cdot\bm{h}(0)\right]
\end{equation}
Substituting eq.~(\ref{eq:j_ans}) into eq.~(\ref{eq:av_work_intermed}) and simplifying results in eq.~(\ref{eq:w_av_simp2}).

\subsection{\label{sec:id_derv}Simplifying the second term on the RHS of eq.~(\ref{eq:sigma_intermed_3})}

Noting that 
\begin{align}\label{eq:aside_int1}
&\bm{G}(\tau_1-\tau'_2)\cdot\bm{G}(\tau_2-\tau'_2)\nonumber\\[5pt]
&=\exp[-\bm{D}\cdot\bm{A}\left(\tau_{1}-\tau'_{2}\right)]\exp[-\bm{D}\cdot\bm{A}\left(\tau_{2}-\tau'_{2}\right)]\nonumber\\[10pt]
&=\exp[-\bm{D}\cdot\bm{A}\left(\tau_{1}+\tau_{2}\right)]\exp[2\bm{D}\cdot\bm{A}\tau'_2],
\end{align}
we may write
\begin{align}\label{eq:aside_int2}
&\int_{0}^{\tau_2}d\tau'_{2}\exp[2\bm{D}\cdot\bm{A}\tau'_2]=\dfrac{1}{2}\bm{D}^{-1}\cdot\bm{A}^{-1}\exp[2\bm{D}\cdot\bm{A}\tau'_2]\bigg\rvert_{0}^{\tau_2}\nonumber\\[10pt]
&=\dfrac{1}{2}\bm{D}^{-1}\cdot\bm{A}^{-1}\exp[2\bm{D}\cdot\bm{A}\tau_2]-\dfrac{1}{2}\bm{D}^{-1}\cdot\bm{A}^{-1},
\end{align}
we obtain the identity given in eq.~(\ref{eq:aside_int3}).Using the identity to simplify the second term on the RHS of eq.~(\ref{eq:sigma_intermed_3}) results in eq.~(\ref{eq:variance_relation}).

