\subsection{Clipping Distortion}
Let $I_{\text{min}}$ and $I_{\text{max}}$ be the lower and upper limits of the dynamic linear range of the optical transmitter. Also, denote $I_{\text{DC}}$ as the DC bias. Note that the clipping of $x[n]$ is performed before DC biasing; thus, it is expressed by
\begin{align}
    \tilde{x}[n] = \begin{cases}
    I_{\text{min}} - I_{\text{DC}}, & \text{if $x[n] < I_{\text{min}}$},\\
    x[n] - I_{\text{DC}}, & \text{if $I_{\text{min}} \leq x[n] \leq I_{\text{max}}$}, \\
    I_{\text{max}} - I_{\text{DC}}, & \text{if $x[n] > I_{\text{max}}$}.
  \end{cases}
\end{align}
Let $X_0$, $X_1$, $\dots$, $X_{M-1}$ be the $M$ symbols of the QAM constellation where the occurrence probability of $m$-th symbol $X_m$ is $p_m$ (i.e., $\text{Pr}(X = X_m) = p_m$). Assuming a sufficiently large number of subcarriers (i.e., $N \geq 64$), due to the central limit theorem (CLT), $x[n]$ can be well approximated by a zero-mean Gaussian distribution. The average electrical signal power is thus
\begin{align}
    \sigma^2_x = \left(1 - \frac{2}{N}\right)\sum_{m = 0}^{M-1}p_m\big|X_m\big|^2.
    \label{signal-variance}
\end{align}
According to the Bussgang theorem, the clipped signal $\tilde{x}$ can be written as
\begin{align}
    \tilde{x}[n] = Rx[n] + z_{\text{clip}}[n],
\end{align}
where $R$ is the attenuation factor and $z_{\text{clip}}[n]$ is the additive clipping noise. If we denote $\alpha = \frac{I_{\text{min}} - I_{\text{DC}}}{\sigma_x}$ and $\beta = \frac{I_{\text{max}} - I_{\text{DC}}}{\sigma_x}$, the attenuation factor is given by $R = \mathcal{Q}(\alpha) - \mathcal{Q}(\beta)$ \cite{Dimitrov2012}, where $\mathcal{Q}(x) = \frac{1}{\sqrt{2\pi}}\int_x^{\infty}\exp\left(\frac{-t^2}{2}\right)dt$ is the Q-function. 

Let $\eta$, $\gamma$, and $h$ be the electrical-to-optical conversion factor of the optical transmitter, the responsivity of the PD, and the optical channel gain, respectively. The received time-domain electrical signal is thus given by
\begin{align}
    y[n] = \eta \gamma h(Rx[n] + z_{\text{clip}}[n] + I_{\text{DC}}) + z[n], 
\end{align}
where $I_{\text{DC}}$ is the DC-bias and $z[n]$ denotes the receiver noise, which is modeled as a zero-mean Gaussian distribution with variance $\sigma^2_z = BN_0$. Here, $B$ is the modulation bandwidth and $N_0$ is the noise power spectral density. After the A/D conversion, CP removal, and S/P processing, the time-domain signal $y[n]$ is transformed into its frequency domain through an FFT. Note that the DC-bias term is filtered out since it does not carry information. 
The frequency-domain signal is thus given by
\begin{align}
    Y[k] = \eta\gamma h \big(RX[k] + Z_{\text{clip}}[k]\big) + Z[k],
    \label{sub-channel}
\end{align}
where $Z_{\text{clip}}[k] = \text{FFT}\{z_{\text{clip}}[n]\} \sim \mathcal{CN}(0, \sigma_{\text{clip}}^2)$  and $Z[k] = \text{FFT}\{z[n]\} \sim \mathcal{CN}(0, \sigma^2_z)$. Given a sufficiently large number of subcarriers, $Z_c[k]$ can be approximated as a zero-mean Gaussian random variable according to the CLT. The variance of $Z_c[k]$ is given by \cite{Dimitrov2012}
\begin{align}
    \sigma^2_{\text{clip}} = \sigma^2_x   &\Big(R+\alpha\phi(\alpha)-\beta\phi(\beta)  +\alpha^2(1-\mathcal{Q}(\alpha))+\beta^2\mathcal{Q}(\beta) \big. \nonumber \\ & \left. -\big(\phi(\alpha) - \phi(\beta) + (1-\mathcal{Q}(\alpha))\alpha + \mathcal{Q}(\beta)\beta\big)^2 \right. \!\!\! -  R^2\Big),
    \label{clipping-noise-variance}
\end{align}
where $\phi(t) = \frac{1}{2\pi}\exp\left(\frac{-t^2}{2}\right)$.
\section{Constellation Optimization}
For conciseness, denote $\rho = \eta\gamma h$. The channel capacity of the $k$-th subcarrier given in \eqref{sub-channel} as a function of the symbol distribution $\mathbf{p} = \begin{bmatrix}
    p_0 & p_1 & \cdots \ & p_{M-1}
\end{bmatrix}^T$ is given by
\begin{align}
    C(\mathbf{p}) & = I(X; Y) = h(Y) - h(Y|X) \\
    & = -\int_{\mathbb{C}}p(Y)\log p(Y)dY - h(\rho Z_{\text{clip}} + Z),
    \label{channel-capacity-complex}
\end{align}
where $p(Y)$ denotes the probability density function (PDF) of the complex variable $Y$. Since $Z_{\text{clip}} \sim \mathcal{CN}(0, \sigma^2_{\text{clip}})$, one has $h(\rho Z_{\text{clip}} + Z) = \log\left(\pi e\left(\rho^2\sigma^2_{\text{clip}} + \sigma^2_z\right)\right)$. The PDF $p(Y)$ can be written as
\begin{align}
    p(Y) &= \sum_{m=0}^{M-1}p(Y|X = X_m)\text{Pr}(X = X_m) \nonumber \\
    & = \sum_{m=0}^{M-1}p_m\frac{1}{\pi\left(\rho^2\sigma^2_{\text{clip}} + \sigma^2_z\right)}\exp\left(-\frac{\left| Y - \rho RX_m\right|^2}{\rho^2\sigma^2_{\text{clip}} + \sigma^2_z}\right).
\end{align}
By rewriting  $p(Y)$ as in \eqref{probablity-real-domain}, which is on top of this page, where $Y_r = \mathfrak{R}(Y)$, $Y_i = \mathfrak{I}(Y_i)$ are the real and imaginary parts of $Y_i$ and  $X_{m, r} = \mathfrak{R}(X_m)$, $X_{m, i} = \mathfrak{I}(X_m)$ are the real and imaginary parts of $X_m$, one can transform the complex integration \eqref{channel-capacity-complex} into an integration over the real domain as follows
\begin{figure*}
\begin{align}
p(Y) & = p\left(Y_r + iY_i\right)  = \sum_{m = 1}^M p_m\frac{1}{\pi\left(\rho^2\sigma^2_{\text{clip}} + \sigma^2_z\right)}\exp\left(-\frac{\left(Y_r - RX_{m, r}\right)^2 + \left(Y_i - RX_{m, i}\right)^2}{\rho^2\sigma^2_{\text{clip}} + \sigma^2_z}\right).
\label{probablity-real-domain}
\end{align}
%\vspace{-0.3cm}
\rule{\linewidth}{0.4pt}
\vspace{-0.9cm}
\end{figure*}
\begin{align}
    C(\mathbf{p})  = & -\!\!\iint_{\mathbb{R}^2}p\left(Y_r \! + \! iY_i\right)\log p\left(Y_r + iY_i\right)dY_rdY_i \nonumber \\
    & - \log\left(\pi e \left(\rho^2\sigma^2_{\text{clip}} + \sigma^2_z\right)\right).
\end{align}
Given an average symbol power limit $P$, we are interested in maximizing the capacity $C(\mathbf{p})$, which is thus formulated as 
\begin{subequations}
\label{OptProb1}
    \begin{alignat}{2}
        &\underset{\mathbf{p}}{\text{maximize}} & \hspace{2mm} & C(\mathbf{p}) \label{obj1}\\
        &\text{subject to }  
        & & \mathbf{a}^T\mathbf{p} \leq P, \label{constraint11}  \\ 
        & & & \mathbf{1}^T_M \mathbf{p} = 1, 
        \label{constraint12} \\
        & & & 0 \leq \mathbf{p} \leq 1, \label{constraint13}
    \end{alignat}
\end{subequations}
where $\mathbf{a} = \begin{bmatrix}\left|X_0\right|^2 & \left|X_1\right|^2 & \cdots & \left|X_{M-1}\right|^2\end{bmatrix}$, $\mathbf{1}_M$ denotes the all-one column vector of size $M$ and $(\cdot)^T$ is the transpose operation. 
Optimally solving \eqref{OptProb1} can be challenging and computationally expensive due to the complex nonlinear nonconvex terms $R$ and $\sigma^2_{\text{clip}}$ that make the objective in \eqref{obj1} a nonconvex function of $\mathbf{p}$. 
In wireless environments where the channel condition often changes quickly, obtaining a PCS (not necessarily optimal) solution within a reasonable amount of time is crucial to enabling real-time transmission. This is especially important in the case of high-order QAM (i.e., larger size of the optimization variable $\mathbf{p}$).
To strive for a balance between quality and complexity, we resort to the simple PGD method for solving \eqref{OptProb1} \cite{boyd2004convex}. The adoption of PGD is also motivated by the fact that the feasible set of \eqref{OptProb1} is convex, which enables efficient handling of the projection step.  The algorithm is outlined as in \textbf{Algorithm 1}.
\vspace{-0.5cm}
\begin{figure}[ht]
\centering
\resizebox{0.48\textwidth}{!}{  % Adjust width scale here
\begin{minipage}{.55\textwidth}
\begin{algorithm}[H]
\caption{PGD method for solving \eqref{OptProb1}}
\begin{algorithmic}[1]
\State Choose a starting point $\mathbf{p}^{(0)}$, a maximum number of iterations $L_{\text{max}}$, a step size $\tau$, and an error tolerance $\varepsilon$.
\For{$k$ = 1 to $L_{\text{max}}$}
    \State Compute the gradient of $C(\mathbf{p})$ at 
    $\mathbf{p}^{(k)}$, denoted as 
    \Statex ~~~~$\nabla C\left(\mathbf{p}^{(k)}\right)$.
    \State Update $\mathbf{q}^{(k+1)} \leftarrow \mathbf{p}^{(k)} - \tau \nabla C\left(\mathbf{p}^{(k)}\right)$. 
    \State Project $\mathbf{q}^{(k+1)}$ onto the feasible set $\mathcal{S}$ of $\eqref{OptProb1}$, i.e., 
    \Statex ~~~~$\mathbf{p}^{(k+1)} = \text{arg}~\underset{\mathbf{p} \in \mathcal{S}}{\text{min}} \left\lVert \mathbf{p} - \mathbf{q}^{(k+1)} \right\rVert$.
    \If{$\frac{\left\lVert\mathbf{p}^{(k+1)} - \mathbf{p}^{(k)}\right\rVert}{\left\lVert\mathbf{p}^{(k)}\right\rVert} \leq \varepsilon$}
        \State \Return $\mathbf{p}^{(k+1)}$
    \EndIf
\EndFor
\end{algorithmic}
\end{algorithm}
\end{minipage}
}
\end{figure}

Note that due to the complexity of the objective function \eqref{obj1}, there is no simple analytical expression for the gradient of $C(\mathbf{p})$. The computation of $\nabla C\left(\mathbf{p}^{(k)}\right)$ is, therefore, performed numerically. The projection of $\mathbf{q}^{(k+1)}$ onto the feasible set of \eqref{OptProb1} can be formulated as the following  problem 
\begin{subequations}
\label{OptProb2}
    \begin{alignat}{2}
        &\underset{\mathbf{p}}{\text{minimize}} & \hspace{2mm} & \frac{1}{2}\left\lVert\mathbf{p} - \mathbf{q}^{(k+1)}\right\rVert \label{obj2}\\
        &\text{subject to } 
        & & \eqref{constraint11},~\eqref{constraint12}, ~\eqref{constraint13} \nonumber.
    \end{alignat}
\end{subequations}
Although several generic solvers (e.g., SDPT3 and SeDuMi) can be used to solve \eqref{OptProb2}, they are designed for tackling general optimization problems, and thus might not be efficient for our specific problem. In the following, we present a nested bisection method to efficiently solve \eqref{OptProb2}.

The Lagrangian of \eqref{OptProb2} is given by
$
  \mathcal{L}(\mathbf{p}, \lambda, \nu) = \frac{1}{2} \left\|\mathbf{p} - \mathbf{q}^{(k+1)}\right\|^2 \! + \! \lambda \left(\mathbf{a}^T \mathbf{p} - P \right) \! + \! \nu\left(\mathbf{1}^T_M\mathbf{p} - 1 \right),  
$
where $\lambda \geq 0$ and $\nu$ are dual variables associated with the constraints \eqref{constraint11} and \eqref{constraint12}, respectively. 
Taking the derivative of the Lagrangian with respect to $\mathbf{p}$  and setting it to zero yields 
%\frac{\partial \mathcal{L}}{\partial p_i} = p_i - q_i + \lambda a_i + \nu = 0 \quad \Rightarrow \quad 
$\mathbf{p} = \mathbf{q}^{(k+1)} - \lambda \mathbf{a} - \nu$.
To satisfy the box constraint in \eqref{constraint13}, $\mathbf{p}$ is projected onto the interval $[0,1]$, resulting in $\mathbf{p} = \min\left(1, \max\left(0, \mathbf{q}^{(k+1)} - \lambda \mathbf{a} - \nu \right)\right).$ Then we employ a nested bisection algorithm to find $\lambda$ and $\nu$ given constraints \eqref{constraint11} and \eqref{constraint12}. Specifically, the outer loop adjusts $\nu$ to enforce $\mathbf{1}_M^T\mathbf{p} = 1$ while the inner loop solves for $\lambda$ such that $\mathbf{a}^T \mathbf{p} \leq P$. The algorithm is described in \textbf{Algorithm~\ref{alg:proj}}.
\vspace{-0.2cm}
\begin{figure}[ht]
\centering
\resizebox{0.48\textwidth}{!}{  % Half-width scaling
\begin{minipage}{.55\textwidth}
\begin{algorithm}[H]
\caption{Nested bisection method for solving \eqref{OptProb2}}
\label{alg:proj}
\begin{algorithmic}[1]
\State Choose an error tolerance $\varepsilon$, a max iterations $L_{\text{max}}$, and a sufficiently large $W$.
\State Define function \texttt{SolveLambda}($\nu$):
\State Initialize $\lambda_{\text{low}} \gets 0$, $\lambda_{\text{high}} \gets W$
\For{$l_1 = 1$ to $L_{\text{max}}$}
    \State $\lambda \gets (\lambda_{\text{low}} + \lambda_{\text{high}}) / 2$
    \State $\mathbf{p} \gets \min\left(1, \max\left(0, \mathbf{q}^{(k+1)} - \lambda \mathbf{a} - \nu \right)\right)$
    \If{$\mathbf{a}^T\mathbf{p} - P \leq \varepsilon$ \textbf{or} $\lambda_{\text{high}} - \lambda_{\text{low}} \leq \varepsilon$}
        \State \Return $\mathbf{p}$
    \ElsIf{$\mathbf{a}^T\mathbf{p} > P$}
        \State $\lambda_{\text{low}} \gets \lambda$
    \Else
        \State $\lambda_{\text{high}} \gets \lambda$
    \EndIf
\EndFor

\State Initialize $\nu_{\text{low}} \gets -W$, $\nu_{\text{high}} \gets W$
\For{$l_2 = 1$ to $L_{\text{max}}$}
    \State $\nu \gets (\nu_{\text{low}} + \nu_{\text{high}})/2$
    \State $\mathbf{p} \gets \texttt{SolveLambda}(\nu)$
    \If{$|\mathbf{1}^T_M\mathbf{p} - 1| \leq \varepsilon$ \textbf{or} $\nu_{\text{high}} - \nu_{\text{low}} \leq \varepsilon$}
        \State \Return $\mathbf{p}$
    \ElsIf{$\mathbf{1}^T_M\mathbf{p} > 1$}
        \State $\nu_{\text{low}} \gets \nu$
    \Else
        \State $\nu_{\text{high}} \gets \nu$
    \EndIf
\EndFor
\end{algorithmic}
\end{algorithm}
\end{minipage}
}
\end{figure}
