	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

	By  conservation of total euchromatin material in the nucleus, we have  
	\begin{equation}
		\label{eqn:kinem-E}
		\frac{\partial\rho_E}{\partial t}+\boldsymbol{\nabla}\cdot(\rho_E\,\boldsymbol{u}_E) = d_c\,\Delta\rho_E,
	\end{equation} where $\boldsymbol{u}_E(\boldsymbol{r},t)$ is the local euchromatin velocity. Similarly, the conservation of heterochromatin gives 
	\begin{equation}
		\label{eqn:kinem-H}
		\frac{\partial\rho_H}{\partial t}+\boldsymbol{\nabla}\cdot(\rho_H\,\boldsymbol{u}_H) = d_c\,\Delta\rho_H,
	\end{equation} where $\boldsymbol{u}_H(\boldsymbol{r},t)$ is the local velocity of heterochromatin. Here, the density of chromatin components evolves not only through diffusion but also through advection by their respective velocity fields. For simplicity, we assume that the diffusivity of both euchromatic and heterochromatic elements is governed by the same diffusion constant, $d_c$. Given initial data for the densities $\rho_E$ and $\rho_H$, their evolution can be readily obtained once the velocities $\boldsymbol{u}_E$ and $\boldsymbol{u}_H$ are known. The latter are determined by the momentum equations associated with euchromatin and heterochromatin, respectively, which themselves depend explicitly on the chromatin densities. 

	The momentum equations are given by the balance of internal forces and friction with the surrounding solvent (nucleoplasm). Here, we neglect the inertial terms, assuming that their dynamics is dominated by the frictional forces with the solvent. The momentum conservation equation for the euchromatin is given by
	\begin{equation}
		\label{eqn:stress-E-balance}
		\boldsymbol{\nabla}\cdot\boldsymbol{\sigma}_E = \Gamma_0\hspace{1pt}\rho_E\left(\boldsymbol{u}_E-\boldsymbol{u}_S\right)\!,
	\end{equation} where $\Gamma_0$ is a friction coefficient, $\boldsymbol{u}_S(\boldsymbol{r},t)$ is the solvent velocity, and $\boldsymbol{\sigma}_E$ is the euchromatin stress tensor, which is given by the following constitutive relation \cite{Kirkwood1958, Snell1967, Onuki1992,Doi2013}:
	\begin{equation}
		\label{eqn:euch-stress}
		\boldsymbol{\sigma}_E = {-p_E\hspace{1pt}\boldsymbol{I} + 2\eta_c\rho_E\boldsymbol{E}_E}
	\end{equation} where {$\eta_c\rho_E$} is the density-dependent viscosity of euchromatin, with $\eta_c$ a viscosity coefficient, $\boldsymbol{E}_E$ is the rate-of-strain tensor of the euchromatin material, that is,  
	\begin{equation}
		\boldsymbol{E}_E =\frac{1}{2} [\boldsymbol{\nabla}\boldsymbol{u}_E+(\boldsymbol{\nabla}\boldsymbol{u}_E)^{\!\mathsf{T}}],
	\end{equation} and the euchromatic pressure is given by
	\begin{equation}
		\label{eqn:pressure-E}
		{p_E = \frac{1}{2}B\rho_E(\rho_E+\rho_H)},
	\end{equation} where $B$ captures the strength of steric interactions between euchromatin and total chromatin. {Note that we do not subtract the trace of the strain tensor, and thus include both shear and volumetric contributions. This corresponds to a two-constant approximation, using a single coefficient for both shear and dilatational viscosity.}  
	\\
	%
	\indent
	Similarly, we write the force balance equation for the heterochromatin to be
	\begin{equation}
		\label{eqn:stress-H-balance}
		\boldsymbol{\nabla}\cdot\boldsymbol{\sigma}_H =\Gamma_0\hspace{1pt}\rho_H(\boldsymbol{u}_H-\boldsymbol{u}_S),
	\end{equation} where the heterochromatin stress $\boldsymbol{\sigma}_H$ is given by
	\begin{equation}
		\label{eqn:hetero-stress}
		\boldsymbol{\sigma}_H = {-p_H\boldsymbol{I}+2\eta_c\rho_H\boldsymbol{E}_H},	
	\end{equation} with {$\eta_c\rho_H$} as the heterochromatin density-dependent viscosity, and the rate-of-strain tensor 
	\begin{equation}
		\boldsymbol{E}_H =\frac{1}{2} [\boldsymbol{\nabla}\boldsymbol{u}_H+(\boldsymbol{\nabla}\boldsymbol{u}_H)^{\!\mathsf{T}}].
	\end{equation} The heterochromatic pressure $p_H$ is given by the following relation~\cite{Foster2015, Toner2005}:
	\begin{equation}
		\label{eqn:pressure-H}
		{p_H = \frac{1}{2}B\rho_H(\rho_E+\rho_H) - B {\rho}_C\rho_H},
	\end{equation} where $B$ is the same as in Eq.~(\ref{eqn:pressure-E}), {and ${\rho}_C$ is a parameter that accounts for the effects of chromatin-condensing factors such as HP1 cross-linking. This active term represents an isotropic contractile stress in heterochromatin, counteracting steric repulsion and driving local condensation.} Physically, $\rho_C$ sets the density threshold at which contractile forces due to molecular cross-linking exceed the repulsive steric interactions~\cite{Foster2015}.
