	%%  Appendix A %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
	\section{Dimensionless parameters}	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

	By rescaling time and space using a characteristic time scale $T$ and a length scale $L$, respectively, the continuity equations can be rescaled, yielding a single dimensionless parameter: $d_c T/L^2$. Thus, by choosing that 
	\begin{equation}
		\label{eqn:time-scale}
		T = L^2/d_c
	\end{equation} the dimensionless continuity equations can be rewritten as in Table I. Note that we also rescaled the local densities by a characteristic density-scale $\rho_0$.

	Moreover, rescaling each of the momentum equations by {a force-density scale $f_0$}, we find the following dimensionless friction coefficient 
	\begin{equation}
		{\Gamma = \frac{\Gamma_0\rho_0 L}{f_0 T}}.
	\end{equation} From the momentum equation of the solvent, we get two additional dimensionless parameters: a rescaled activity 
	\begin{equation}
		{\alpha = \frac{\alpha_0\rho_0}{f_0 L}},
	\end{equation} and a rescaled solvent viscosity {$\eta_s/(f_0 L T)$}. Setting the latter to unity, we find the following {force-density scale}
	\begin{equation}
		\label{eqn:stress-scale}
		{f_0 = \frac{\eta_s}{L T} = \frac{\eta_s d_c}{L^3}},
	\end{equation} where the last equality follows from Eq.~(\ref{eqn:time-scale}). Also, from the momentum equations of euchromatin and heterochromatin, we find the following dimensionless parameters: first, a rescaled compressibility {$B\rho_0^2/(f_0 L)$}, which is set to unity and gives the following characteristic density 
	\begin{equation}
		\label{eqn:density-scale}
		{\rho_0 = \sqrt{\frac{f_0 L}{B}}= \frac{\sqrt{\eta_s d_c}}{L\sqrt{B}}};
	\end{equation} second, a rescaled chromatin viscosity coefficient
	\begin{equation}
		{\eta = \frac{\rho_0\eta_c}{f_0 L T} = \frac{\eta_c \sqrt{d_c}}{L\sqrt{\eta_s B}}},
	\end{equation} where the last equality follows from Eq.~(\ref{eqn:stress-scale}) and (\ref{eqn:density-scale}); and lastly a dimensionless cross-linking density
	\begin{equation}
		{\bar{\rho}_C = \frac{B{\rho}_C\rho_0}{f_0 L} =\frac{\rho_C}{\rho_0}= \frac{\rho_C L\sqrt{B}}{\sqrt{\eta_s d_c}}},
	\end{equation} where last two equalities follow from Eq.~(\ref{eqn:stress-scale}) and (\ref{eqn:density-scale}). The solvent pressure is rescaled as: {$p = L^2 p_S/(\eta_s d_c)$}.   

	Thus, by means of Eqs.~(\ref{eqn:time-scale}), (\ref{eqn:stress-scale}) and (\ref{eqn:density-scale}), the dimensionless friction coefficient $\Gamma$ can be written as
	\begin{equation}
		\label{eqn:Gamma-def}
		{\Gamma = \frac{\Gamma_0 L\sqrt{d_c}}{\sqrt{\eta_s B}}},
	\end{equation} whereas the dimensionless activity strength $\alpha$ reads
	\begin{equation}
		\label{eqn:Alpha-def}
		{\alpha = \frac{\alpha_0 L}{\sqrt{\eta_s d_c B}}}.
	\end{equation} Note that a natural length-scale $L$ could be defined by setting either {$\Gamma$, $\alpha$ or $\bar{\rho}_C$ to one}; however, {here we choose $L$ to be given by the radius of the cell nucleus $R$}. Table I shows the continuity and momentum equations, and the dynamical equation of the nematic order parameter $\boldsymbol{Q}$, rescaled by their characteristic scales ($T$, $L$, and $\rho_0$), in terms of the dimensionless parameters $\alpha$, $\eta$, $\bar{\rho}_c$ and $\Gamma$.

	%%  Appendix B %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
	\section{Linear stability analysis}	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

	The homogeneous and stationary state of the governing equations in Table I is given by the constant densities $\bar{\rho}_E$  and $\bar{\rho}_H$, together with vanishing velocities: $\bar{\boldsymbol{u}}_S= \boldsymbol{0}$, $\bar{\boldsymbol{u}}_E = \boldsymbol{0}$, and $\bar{\boldsymbol{u}}_H = \boldsymbol{0}$. We perturb the chromatin densities about their homogeneous states:
	\begin{equation}
		\label{eqn:density-perturb}
		\rho_{E} = 	\bar{\rho}_{E} + \varepsilon\,\delta\rho_E,\quad\text{and}\quad\rho_{E} = 	\bar{\rho}_{H} + \varepsilon\,\delta\rho_H,
	\end{equation} where $\delta\rho_E$ and $\delta\rho_H$ are the linear perturbations in the euchromatin and heterochromatin densities, respectively, while $\varepsilon$ is a small perturbation parameter, which is immaterial purely keeping track of the perturbation order. Similarly, we perturb the velocities about their stationary state, namely
	\begin{equation}
		\label{eqn:velocity-perturb}
		\boldsymbol{u}_{S} = \varepsilon\,\delta\boldsymbol{u}_S,\;\;\,
		\boldsymbol{u}_{E} = \varepsilon\,\delta\boldsymbol{u}_E,\;\;\,\text{and}\;\;\,\boldsymbol{u}_{H} = \varepsilon\,\delta\boldsymbol{u}_H.
	\end{equation}

	%%  Appendix B.1 %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
	\subsection{Linearized chromatin density equations}
	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

	To first order in $\varepsilon$, the continuity equations for the chromatin components can be written as follows:
	\begin{align}
		\label{eqn:lin-den-E}
		\frac{\partial}{\partial t}(\delta\rho_E) + \bar{\rho}_E\, \boldsymbol{\nabla}\cdot\delta\boldsymbol{u}_E &= \Delta(\delta\rho_E),\\[6pt]
		\label{eqn:lin-den-H}
		\frac{\partial}{\partial t}(\delta\rho_H) + \bar{\rho}_H\, \boldsymbol{\nabla}\cdot\delta\boldsymbol{u}_H &= \Delta(\delta\rho_H),
	\end{align} while the solvent incompressibility condition becomes
	\begin{equation}
		\label{eqn:lin-incomp-cond}
		\boldsymbol{\nabla}\cdot\delta\boldsymbol{u}_S = 0.
	\end{equation}

	Similarly, by expanding to first order in $\varepsilon$ the momentum equations of euchromatin and heterochromatin components, we find
	\begin{align}
		\label{eqn:lin-mom-uE}
		&\eta{\bar{\rho}_E}\big[\Delta\delta\boldsymbol{u}_E + \boldsymbol{\nabla}(\boldsymbol{\nabla}\!\cdot\delta\boldsymbol{u}_E)\big]\! + \Gamma\bar{\rho}_E(\delta\boldsymbol{u}_S-\delta\boldsymbol{u}_E) \notag\\[6pt]
		&\quad-\boldsymbol{\nabla}\Big[\frac{\bar{\rho}_E}{2}\delta\rho_H + \Big(\bar{\rho}_E + \frac{\bar{\rho}_H}{2}\Big)\delta{\rho}_E\Big]\! =  0,\\[14pt]
		\label{eqn:lin-mom-uH}
		&\eta{\bar{\rho}_H}\big[\Delta\delta\boldsymbol{u}_H + \boldsymbol{\nabla}(\boldsymbol{\nabla}\!\cdot\delta\boldsymbol{u}_H)\big]\! + \Gamma\bar{\rho}_H(\delta\boldsymbol{u}_S-\delta\boldsymbol{u}_H) \; \notag\\[6pt]
		&\quad-\boldsymbol{\nabla}\Big[\frac{\bar{\rho}_H}{2}\delta\rho_E
		+ \Big(\bar{\rho}_H-\bar{\rho}_C + \frac{\bar{\rho}_E}{2}\Big)\delta{\rho}_H\Big]\! =  0,
	\end{align}  respectively. By applying the divergence operator onto Eq.~(\ref{eqn:lin-mom-uE}) and (\ref{eqn:lin-mom-uH}), we obtain the following equations:   
	\begin{align}
		\label{eqn:lin-mom-E}
		2\eta{\bar{\rho}_E}\Delta( \boldsymbol{\nabla}\cdot\delta\boldsymbol{u}_E) 
		&= \Gamma \bar{\rho}_E(\boldsymbol{\nabla}\cdot\delta\boldsymbol{u}_E) + \frac{\bar{\rho}_E}{2}\Delta(\delta\rho_H) \notag\\[5pt] 
		& \quad+\left[\bar{\rho}_E+\frac{\bar{\rho}_H}{2}\right]\!\Delta(\delta\rho_E) ,\\[12pt]
		\label{eqn:lin-mom-H}
		2\eta{\bar{\rho}_H}\Delta( \boldsymbol{\nabla}\cdot\delta\boldsymbol{u}_H) 
		&= \Gamma \bar{\rho}_H(\boldsymbol{\nabla}\cdot\delta\boldsymbol{u}_H) + \frac{\bar{\rho}_H}{2}\Delta(\delta\rho_E)\notag\\[5pt] 
		& \quad+\left[\bar{\rho}_H - \bar{\rho}_C + \frac{\bar{\rho}_E}{2}\right]\Delta(\delta\rho_H).
	\end{align} Therefore, the divergence terms $\boldsymbol{\nabla}\cdot\delta\boldsymbol{u}_E$ and $\boldsymbol{\nabla}\cdot\delta\boldsymbol{u}_H$ can be expressed solely in terms of density fields by means of Eq.~(\ref{eqn:lin-den-E}) and (\ref{eqn:lin-den-H}), respectively, which by substitution into Eq.~(\ref{eqn:lin-mom-E}) and (\ref{eqn:lin-mom-H}) leads to
	\begin{align}
		\label{eqn:lin-rel-E}
		\!\!\frac{\partial}{\partial t}{\left(\Gamma\!- {2\eta}\Delta\right)} \delta\rho_E &= \left[\Gamma+\bar{\rho}_E+\frac{\bar{\rho}_H}{2}\right]\!\Delta(\delta\rho_E) \notag \\[5pt]
		&\;+\frac{\bar{\rho}_E}{2}\Delta(\delta\rho_H)-{2\eta}\Delta^2(\delta\rho_E),\\[10pt]
		\label{eqn:lin-rel-H}
		\frac{\partial}{\partial t}{\left(\Gamma\! - {2\eta}\Delta\right)} \delta\rho_H &= \left[\Gamma+\bar{\rho}_H - \bar{\rho}_C+\frac{\bar{\rho}_E}{2}\right]\!\Delta(\delta\rho_H) \notag \\[5pt]
		&\;+\frac{\bar{\rho}_H}{2}\Delta(\delta\rho_E)-{2\eta}\Delta^2(\delta\rho_H),
	\end{align} where $\Delta^2$ is the biharmonic operator.

	By expressing the linearized densities $\delta\rho_E$ and $\delta\rho_H$ in Fourier series, namely
	\begin{align}
		\delta\rho_E(\boldsymbol{r},t) = \sum_{\boldsymbol{k}}\,e^{i\boldsymbol{k}\cdot\boldsymbol{r}}\,\delta\hat{\rho}_E^{\,\boldsymbol{k}}(t),\\[8pt]
		\delta\rho_H(\boldsymbol{r},t) = \sum_{\boldsymbol{k}}\,e^{i\boldsymbol{k}\cdot\boldsymbol{r}}\,\delta\hat{\rho}_H^{\,\boldsymbol{k}}(t),
	\end{align} where $\boldsymbol{k}$ is the Fourier wave-vector and $\delta\hat{\rho}_{E,H}^{\,\boldsymbol{k}}$ are the corresponding Fourier amplitudes of $\delta\rho_{E,H}$, we can rewrite   Eq.~(\ref{eqn:lin-rel-E}) and (\ref{eqn:lin-rel-H}) solely in terms of $\delta\hat{\rho}_{E}^{\,\boldsymbol{k}}$ and $\delta\hat{\rho}_{H}^{\,\boldsymbol{k}}$. This can written in the following matrix form:
	\begin{equation}
		\frac{\partial}{\partial t}\!\begin{bmatrix}
			\delta\hat{\rho}_{E}^{\,\boldsymbol{k}} \\[3pt]
			\delta\hat{\rho}_{H}^{\,\boldsymbol{k}} 
		\end{bmatrix} =	 \,\boldsymbol{\mathcal{S}}_{\hspace{-0.5pt}{k}}\!\begin{bmatrix}\delta\hat{\rho}_{E}^{\,\boldsymbol{k}} \\[3pt]
			\delta\hat{\rho}_{H}^{\,\boldsymbol{k}} 
		\end{bmatrix}\!,
	\end{equation} where the matrix $\boldsymbol{\mathcal{S}}_{\hspace{-0.5pt}{k}}$ is shown in Eq.~(\ref{eqn:stability-matrix}), and $k$ is the magnitude of $\boldsymbol{k}$. The eigenvalues of $\boldsymbol{\mathcal{S}}_{\hspace{-0.5pt}{k}}$ are the growth rates of the Fourier amplitudes of density perturbations. These eigenvalues are found to be
	\begin{equation}
		\label{eqn:density-eigenvalues}
		\lambda_\pm(k) = -\frac{\,k^2}{2}\!\left[a_k+b_k\pm\sqrt{c_k + (a_k-b_k)^2}\,\right]
	\end{equation} where $a_k$ and $b_k$ are diagonal components of the matrix in Eq.~(\ref{eqn:stability-matrix}), that is, $a_k = k^{-2}[\boldsymbol{\mathcal{S}}_{\hspace{-0.5pt}{k}}]_{1,1}$ and $b_k = k^{-2}[\boldsymbol{\mathcal{S}}_{\hspace{-0.5pt}{k}}]_{2,2}$, whilst $c_k = 4k^{-4}[\boldsymbol{\mathcal{S}}_{\hspace{-0.5pt}{k}}]_{1,2}[\boldsymbol{\mathcal{S}}_{\hspace{-0.5pt}{k}}]_{2,1}$. The solution $\lambda_+$ is always negative, while the other could become positive, displaying a band of linearly unstable modes. We denote the latter by $\lambda_C$. The instability condition is determined by the sign of the growth rate $\lambda_C(k)$ near $k=0$; namely,
	\begin{equation*}
		\lambda_C \simeq \frac{\frac{2\bar{\rho}_C-4\Gamma}{\bar{\rho}_E+\bar{\rho}_H}\!- 3 +\! \sqrt{1\!+\!\frac{4\bar{\rho}_C^2+4\bar{\rho}_C(\bar{\rho}_E-\bar{\rho}_H)}{(\bar{\rho}_E+\bar{\rho}_H)^2}}}{\frac{4\Gamma}{\bar{\rho}_E+\bar{\rho}_H}}\,k^2 +\mathcal{O}[k^3].
	\end{equation*} We find that the system remains stable to linear density perturbations whenever
	\begin{equation}
		\bar{\rho}_C\le\bar{\rho}^{\,\star}_C = \frac{(\Gamma + \bar{\rho}_E+\bar{\rho}_H)(2\Gamma + \bar{\rho}_E+\bar{\rho}_H)}{2(\Gamma+\rho_E)+\bar{\rho}_H},
	\end{equation} with the equality corresponding to the onset of instability. The system is linearly unstable if $\bar{\rho}_C>\bar{\rho}^{\,\star}_C$, which is shown in Fig.~\ref{fig:figure_2}(b). Note that this criterion is independent of the viscosity ratio $\eta$. However the fastest growing mode $k_{0}$ satisfies $\lambda_C'(k_{0})=0$ and depends on viscosity as
	\begin{equation}
		k_{0}\propto{\eta^{-1/2}}.
	\end{equation} This scaling is readily obtain by noting that $\lambda_C'(k)=0$ can be rewritten as a polynomial in terms of $k\sqrt{\eta}$. 

	Also, note that this instability is completely independent of the activity parameter $\alpha$, as the extensile active stresses act only on the solvent (nucleoplasm), which is treated here as an incompressible fluid.

	%%  Appendix B.2 %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
	\subsection{Linearized solvent equations}
	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

	Lastly, we also expand to linear order in $\varepsilon$ the momentum equation of the solvent, using Eq.~(\ref{eqn:density-perturb}) and (\ref{eqn:velocity-perturb}), and a perturbation in the nematic order parameter,
	\begin{equation}
		\label{eqn:Q-perturb}
		\boldsymbol{Q} = 	\bar{\boldsymbol{Q}} + \varepsilon\,\delta\boldsymbol{Q}(\boldsymbol{r},t),
	\end{equation}  about a homogeneous state $\bar{\boldsymbol{Q}}$, where $\delta\boldsymbol{Q}$ are the corresponding linear perturbations. This leads to the following expansion to first order in $\varepsilon$:
	\begin{align}
		\label{eqn:lin-mom-S}
		\Delta(\delta\boldsymbol{u}_S)-\!\boldsymbol{\nabla} \delta p = &\,\Gamma\bar{\rho}_H(\delta\boldsymbol{u}_S-\delta\boldsymbol{u}_H)+\Gamma\bar{\rho}_E(\delta\boldsymbol{u}_S-\delta\boldsymbol{u}_E)\notag\\[5pt]
		&+\boldsymbol{\nabla}\!\cdot\!(\alpha\bar{\rho}_E\delta\boldsymbol{Q}) + \alpha\,\bar{\boldsymbol{Q}}\cdot\boldsymbol{\nabla}\delta\rho_E,
	\end{align} where the solvent pressure $p = \bar{p} + \varepsilon\,\delta p(\boldsymbol{r},t)$. To zeroth order in $\varepsilon$, any constant and symmetric tensor $\bar{\boldsymbol{Q}}$ satisfies Eq.~(\ref{eqn:Q-dyanmics}). To first order in $\varepsilon$, the rescaled nematic order equation (see Table I) becomes
	\begin{align}
		\label{eqn:lin-Q-dyn}
		\frac{\partial}{\partial t}(\delta\boldsymbol{Q})&=\bar{\boldsymbol{Q}}\cdot(\boldsymbol{\nabla}\delta\boldsymbol{u}_S)+(\boldsymbol{\nabla}\delta\boldsymbol{u}_S)^{\mathsf{T}}\cdot\bar{\boldsymbol{Q}} \notag\\[2pt] 
		&\quad + \Delta(\delta\boldsymbol{Q})-2\hspace{1pt}\bar{\boldsymbol{Q}}\,\bar{\boldsymbol{Q}}:\boldsymbol{\nabla}\delta\boldsymbol{u}_S.
	\end{align} 

	By Fourier transforming the linearized solvent momentum equation in (\ref{eqn:lin-mom-S}), we find 
	\begin{align}
		\label{eqn:lin-mom-S-Fourier}
		\!\!i\boldsymbol{k}\delta \hat{p}_{\boldsymbol{k}} +  k^2\delta\hat{\boldsymbol{u}}^{\boldsymbol{k}}_S  = &\;\Gamma\bar{\rho}_H(\delta\hat{\boldsymbol{u}}^{\boldsymbol{k}}_H-\delta\hat{\boldsymbol{u}}^{\boldsymbol{k}}_S)+\Gamma\bar{\rho}_E(\delta\hat{\boldsymbol{u}}^{\boldsymbol{k}}_E-\delta\hat{\boldsymbol{u}}^{\boldsymbol{k}}_S)\notag\\[5pt]
		&\!-i\boldsymbol{k}\!\cdot\!(\alpha\bar{\rho}_E\delta\hat{\boldsymbol{Q}}_{\boldsymbol{k}}) - \alpha\,\bar{\boldsymbol{Q}}\cdot (i{\boldsymbol{k}}\delta\hat{\rho}^{\boldsymbol{k}}_E),
	\end{align} while the incompressibility condition in Eq.~(\ref{eqn:lin-incomp-cond}) becomes
	\begin{equation}
		\label{eqn:lin-incomp-cond-k}
		\boldsymbol{k}\cdot\delta\hat{\boldsymbol{u}}^{\boldsymbol{k}}_S = 0.
	\end{equation}

	Similarly, linearized dynamics of the nematic order parameter in Eq.~(\ref{eqn:lin-Q-dyn}) can be written in Fourier space as:
	\begin{align}
		\label{eqn:lin-Q-dyn-Fourier}
		\frac{\partial}{\partial t}(\delta\hat{\boldsymbol{Q}}_{\boldsymbol{k}})&=\bar{\boldsymbol{Q}}\cdot(i\boldsymbol{k}\,\delta\hat{\boldsymbol{u}}^{\boldsymbol{k}}_S)+(i\boldsymbol{k}\,\delta\hat{\boldsymbol{u}}^{\boldsymbol{k}}_S)^{\mathsf{T}}\cdot\bar{\boldsymbol{Q}} \notag\\[2pt] 
		&\quad - k^2(\delta\hat{\boldsymbol{Q}}_{\boldsymbol{k}})-2\hspace{1pt}\bar{\boldsymbol{Q}}\,\bar{\boldsymbol{Q}}:(i\boldsymbol{k}\,\delta\hat{\boldsymbol{u}}^{\boldsymbol{k}}_S),
	\end{align} where $\delta \hat{p}_{\boldsymbol{k}}(t)$ and $\delta \hat{\boldsymbol{Q}}_{\boldsymbol{k}}(t)$ are Fourier amplitudes of the linearized pressure $\delta p$ and linearized nematic order parameter $\delta\boldsymbol{Q}$, respectively. Similarly,  $\delta\hat{\boldsymbol{u}}^{\boldsymbol{k}}_S(t)$, $\delta\hat{\boldsymbol{u}}^{\boldsymbol{k}}_E(t)$, and $\delta\hat{\boldsymbol{u}}^{\boldsymbol{k}}_H(t)$ are Fourier amplitudes of the linearized velocity fields of solvent, euchromatin and heterochromatin, respectively. The latter two velocity amplitudes, $\delta\hat{\boldsymbol{u}}^{\boldsymbol{k}}_E$ and $\delta\hat{\boldsymbol{u}}^{\boldsymbol{k}}_H$, are determined from the Fourier transform of momentum equations in (\ref{eqn:lin-mom-uE}) and (\ref{eqn:lin-mom-uH}), namely 
	\begin{align}
		\label{eqn:lin-mom-uE-k}
		\!\eta{\bar{\rho}_E}\big[&k^2\delta\hat{\boldsymbol{u}}^{\boldsymbol{k}}_E + \boldsymbol{k}(\boldsymbol{k}\cdot\delta\hat{\boldsymbol{u}}^{\boldsymbol{k}}_E)\big]\! + \Gamma\bar{\rho}_E(\delta\hat{\boldsymbol{u}}^{\boldsymbol{k}}_E-\delta\hat{\boldsymbol{u}}^{\boldsymbol{k}}_S)\;
		\notag\\[6pt]
		&+i\boldsymbol{k}\Big[\frac{\bar{\rho}_E}{2}\delta\hat{\rho}^{\,\boldsymbol{k}}_H + \!\Big(\bar{\rho}_E + \frac{\bar{\rho}_H}{2}\Big)\delta{\hat{\rho}}^{\,\boldsymbol{k}}_E\Big]\! =  0,\\[12pt]
		\label{eqn:lin-mom-uH-k}
		\!\eta{\bar{\rho}_H}\big[&k^2\delta\hat{\boldsymbol{u}}^{\boldsymbol{k}}_H + \boldsymbol{k}(\boldsymbol{k}\cdot\delta\hat{\boldsymbol{u}}^{\boldsymbol{k}}_H)\big]\! + \Gamma\bar{\rho}_H(\delta\hat{\boldsymbol{u}}^{\boldsymbol{k}}_H-\delta\hat{\boldsymbol{u}}^{\boldsymbol{k}}_S)\;
		\notag\\[6pt]
		&+i\boldsymbol{k}\Big[\frac{\bar{\rho}_H}{2}\delta\hat{\rho}^{\,\boldsymbol{k}}_E + \!\Big(\bar{\rho}_H -\bar{\rho}_{C} + \frac{\bar{\rho}_E}{2}\Big)\delta{\hat{\rho}}^{\,\boldsymbol{k}}_H\Big]\! =  0.
	\end{align}

	%%%%%%%%%%%%%%%%%%%% Figure 7 %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
	\begin{figure*}[t]\includegraphics[width=\textwidth]{figure_7.pdf}
		\caption{\label{fig:figure_7} Diagrams showing instability regions in two dimensions as a function of components of the Fourier  vector $\boldsymbol{k}=[k_x,\,k_y]$, where the color shows only the positive values of the growth rates associated with linear perturbations in the nematic order parameter $\boldsymbol{Q}$ about: (a) an isotropic state for extensile active stresses with {$\alpha=5$}; (b) an aligned state along the $y$-direction, for extensile active stresses with {$\alpha=5$}; (c) an aligned state along the $y$-direction, for contractile active stresses with {$\alpha=-50$}. Here, we  choose {$\eta=0.01$ and $\Gamma=25$}, while the homogeneous densities {$\bar{\rho}_E = 10$ and  $\bar{\rho}_H=40$}. 
	}\end{figure*} 
	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

	From equations (\ref{eqn:lin-mom-S-Fourier}), (\ref{eqn:lin-incomp-cond-k}), (\ref{eqn:lin-mom-uE-k}), and (\ref{eqn:lin-mom-uH-k}), we can analytically determine the pressure $\delta \hat{p}_{\boldsymbol{k}}$ and the solvent velocity $\delta\hat{\boldsymbol{u}}^{\boldsymbol{k}}_S$, as well as the euchromatin velocity $\delta\hat{\boldsymbol{u}}^{\boldsymbol{k}}_E$ and the heterochromatin velocity $\delta\hat{\boldsymbol{u}}^{\boldsymbol{k}}_H$, purely in terms of the  densities $\delta\hat{\rho}_E^{\,\boldsymbol{k}}$ and $\delta\hat{\rho}_H^{\,\boldsymbol{k}}$. Thus, the linearized dynamics of the order parameter in Eq.~(\ref{eqn:lin-Q-dyn-Fourier}), together with continuity equations in Fourier space, that is,
	\begin{align}
		\label{eqn:lin-den-E-k}
		\frac{\partial}{\partial t}(\delta\hat{\rho}^{\,\boldsymbol{k}}_E) + \bar{\rho}_E (\boldsymbol{k}\cdot\delta\hat{\boldsymbol{u}}^{\boldsymbol{k}}_E) &= -k^2\delta\hat{\rho}^{\,\boldsymbol{k}}_E,\\[6pt]
		\label{eqn:lin-den-H-k}
		\frac{\partial}{\partial t}(\delta\hat{\rho}^{\,\boldsymbol{k}}_H) + \bar{\rho}_H (\boldsymbol{k}\cdot\delta\hat{\boldsymbol{u}}^{\boldsymbol{k}}_H) &= -k^2\delta\hat{\rho}^{\,\boldsymbol{k}}_H,
	\end{align} forms a closed set of linear differential equations in $\delta\hat{\rho}_E^{\,\boldsymbol{k}}$, $\delta\hat{\rho}_H^{\,\boldsymbol{k}}$ and the independent components of $\delta\hat{\boldsymbol{Q}}_{\boldsymbol{k}}$ (specifically, 3 in two dimensions, and 6 in three dimensions).

	%%  Appendix B.3 %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
	\subsection{Nematic order parameter}
	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

	The base state of $\boldsymbol{Q}$ is a symmetric, constant tensor, but its components are not entirely unconstrained, as 
	\begin{equation}
		\label{eqn:Q-def}
		{\boldsymbol{Q}} = \frac{\int\boldsymbol{p}\boldsymbol{p}\,{\Psi}(\boldsymbol{p})\;\mathrm{d}^d\boldsymbol{p}}{\int{\Psi}(\boldsymbol{p})\;\mathrm{d}^d\boldsymbol{p}},
	\end{equation} where $\boldsymbol{p}$ is a unit vector in dimension $d$, ${\Psi}$ is an orientational distribution, and the integration is performed  over the $d$-dimensional unit sphere~\cite{DoiBook1986, Saintillan2008, Saintillan2013, Gao2017[Rev]}. The definition in Eq.~(\ref{eqn:Q-def}) implies that the trace of $\boldsymbol{Q}$ is unity, 
	$\mathrm{tr}(\boldsymbol{Q}) = 1$. We denote the distribution at zeroth order in the perturbation as $\bar{\Psi}$, which can described by either a constant,
	\begin{equation}
		\bar{\Psi}(\boldsymbol{p}) = \Psi_0\quad\text{(isotropic state)},
	\end{equation} or a fixed orientation $\bar{\boldsymbol{n}}$, that is,
	\begin{equation}
		\bar{\Psi}(\boldsymbol{p}) = \delta(\boldsymbol{p} - \bar{\boldsymbol{n}}),\quad\text{(aligned state)}
	\end{equation}  with $\delta$ as the Dirac--delta function. Specifically, we find 
	\begin{equation}
		\bar{\boldsymbol{Q}}_I\! = {d}^{-1}\boldsymbol{I}~\,\text{(isotropic)},\;\text{and}\;\, \bar{\boldsymbol{Q}}_A\! = \bar{\boldsymbol{n}}\bar{\boldsymbol{n}}~\,\text{(aligned)},
	\end{equation} where $\boldsymbol{I}$ is the identity tensor. In two dimensions,
	\begin{equation}
		\label{eqn:base-state-2D}
		\bar{\boldsymbol{Q}}_I = {\footnotesize\begin{bmatrix}
				\frac{1}{2} & 0\\
				0 & \frac{1}{2}\end{bmatrix}}, \quad\text{and}\quad\bar{\boldsymbol{Q}}_A = {\footnotesize\begin{bmatrix}
				0 & 0\\
				0 & 1
		\end{bmatrix}},
	\end{equation} where we choose $\bar{\boldsymbol{n}}$ to be aligned with the $y$-axis, without any loss of generality. Similarly, in three dimensions,
	\begin{equation}
		\label{eqn:base-state-3D}
		\bar{\boldsymbol{Q}}_I = {\footnotesize\begin{bmatrix}
				\frac{1}{3} & 0 & 0\\
				0 & \frac{1}{3} & 0\\
				0 & 0 & \frac{1}{3}\\
		\end{bmatrix}},\quad\text{and}\quad\bar{\boldsymbol{Q}}_A = {\footnotesize\begin{bmatrix}
				0 & 0 & 0\\
				0 & 0 & 0\\
				0 & 0 & 1\\
		\end{bmatrix}},
	\end{equation} where in the latter we choose $\bar{\boldsymbol{n}}$ to be along the $z$-axis.

	In two dimensions, the first-order perturbation in nematic order parameter $\delta\boldsymbol{Q}$ and its corresponding Fourier transform can be written as
	\begin{equation*}
		\delta{\boldsymbol{Q}} = {\footnotesize\begin{bmatrix}
				\delta q_1 & \delta q_3\\
				\delta q_3 & -\delta q_1
		\end{bmatrix}},\quad
		\delta{\hat{\boldsymbol{Q}}_{\boldsymbol{k}}} = {\footnotesize\begin{bmatrix}
				\delta\hat{q}^{\boldsymbol{k}}_1 & \delta\hat{q}^{\boldsymbol{k}}_3\\
				\delta\hat{q}^{\boldsymbol{k}}_3 & -\delta\hat{q}^{\boldsymbol{k}}_1
		\end{bmatrix}},
	\end{equation*} where $\delta q_j(\boldsymbol{r},t)$ and $\delta \hat{q}^{\hspace{1pt}\boldsymbol{k}}_j(t)$ are their respective independent components. Note that the trace of $\delta{\boldsymbol{Q}}$ must be zero such that we maintain $\mathrm{tr}(\boldsymbol{Q})=1$. Thus, the linear system associated with perturbations about the two-dimensional isotropic state $\bar{\boldsymbol{Q}}_I$ in Eq.~(\ref{eqn:base-state-2D}) is given by
	\begin{equation}
		\frac{\partial}{\partial t}\!{\footnotesize\begin{bmatrix}
				\delta\hat{q}^{\boldsymbol{k}}_1\\[1pt]
				\delta\hat{q}^{\boldsymbol{k}}_2\\[1pt]
				\delta \hat{\rho}^{\,\boldsymbol{k}}_E\\[1pt]
				\,\delta \hat{\rho}^{\,\boldsymbol{k}}_H\,
		\end{bmatrix}}\!= {\begin{bmatrix}
				\boldsymbol{\mathcal{H}}_I^{\boldsymbol{k}} & \boldsymbol{O}_{2\times2}\\[1pt]
				\,\boldsymbol{O}_{2\times2} & \boldsymbol{\mathcal{S}}_k
		\end{bmatrix}}{\footnotesize\begin{bmatrix}
				\delta\hat{q}^{\boldsymbol{k}}_1\\[1pt]
				\delta\hat{q}^{\boldsymbol{k}}_2\\[1pt]
				\delta \hat{\rho}^{\,\boldsymbol{k}}_E\\[1pt]
				\,\delta \hat{\rho}^{\,\boldsymbol{k}}_H\,
		\end{bmatrix}},
	\end{equation} where $\boldsymbol{\mathcal{S}}_k$ is the matrix from Eq.~(\ref{eqn:stability-matrix}), $\boldsymbol{O}_{a\times b}$ is a zero matrix of $a$ rows and $b$ columns, and $\boldsymbol{\mathcal{H}}_I^{\boldsymbol{k}}$ is found to be
	\begin{equation}
		\boldsymbol{\mathcal{H}}_I^{\boldsymbol{k}} = -k^2 \boldsymbol{I}_{2\times2} + \frac{1}{2}\Lambda(k) \,\boldsymbol{\mathcal{R}}_I^{\boldsymbol{k}},
	\end{equation}  where $\boldsymbol{I}_{2\times2}$ is the identity matrix, the function  
	\begin{equation}
		\label{eqn:Lambda-def}
		{\Lambda(k) = \frac{\alpha\bar{\rho}_E}{\displaystyle 1+\frac{\eta\,\Gamma\left(\bar{\rho}_E+\bar{\rho}_H\right)}{\Gamma+\eta\,k^2}}},
	\end{equation} and the matrix 
	\begin{equation}
		\boldsymbol{\mathcal{R}}_I^{\boldsymbol{k}} =\!{\footnotesize\begin{bmatrix}
				\sin ^2(2 \varphi ) & -\frac{1}{2} \sin (4 \varphi ) \\
				-\frac{1}{2} \sin (4 \varphi ) & \cos ^2(2 \varphi ) \\
		\end{bmatrix}}\!,
	\end{equation} with polar angle $\varphi$ defining the components $k_x = k\cos\varphi$ and $k_y = k\sin\varphi$ of the wavevector $\boldsymbol{k} = [k_x,\,k_y]$. One of the eigenvalues of $\boldsymbol{\mathcal{H}}_I^{\boldsymbol{k}}$ is given by $-k^2$, while the other is
	\begin{equation}
		\lambda_I(k) = -k^2+\Lambda(k)/2,
	\end{equation} which shows that the isotropic state is always stable for the contractile case ($\alpha<0$), whereas for the extensile case ($\alpha>0$) it is always unstable; see Fig.~\ref{fig:figure_7}(a).

	%%%%%%%%%%%%%%%%%%%% Figure 8 %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
	\begin{figure*}[t!]\includegraphics[width=\textwidth]{figure_8.pdf}
		\caption{\label{fig:figure_8} Diagrams of instability regions in three dimensions as a function of components of the Fourier vector $\boldsymbol{k}=[k_x,\,k_y,\,k_z]$, showing cross-sectional cuts at $k_y=0$. The regions are rotationally symmetric around the $k_z$--axis. Here, the color shows only the positive values of the growth rates associated with linear perturbations in the nematic order parameter $\boldsymbol{Q}$. (a) The unstable growth rate $\lambda_I$ about an isotropic state for extensile active stresses with {$\alpha=5$}. (b) and (c) shows unstable growth rates $\lambda_A^1$ and $\lambda_A^2$, respectively, about an aligned state along the $z$-direction, for extensile active stresses with {$\alpha=5$}. (d) The unstable growth rate $\lambda_A^2$ for perturbations about an aligned state along the $z$-direction, for contractile active stresses with {$\alpha=-50$} (note that $\lambda_A^1<0$ for $\alpha<0$). Here, we  choose {$\eta=0.01$ and $\Gamma=25$}, while the homogeneous chromatin densities {$\bar{\rho}_E = 10$ and  $\bar{\rho}_H=40$}. 
	}\end{figure*} 
	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

	Similarly, the linear system associated with perturbations about an aligned state $\bar{\boldsymbol{Q}}_A$  is given by
	\begin{equation}
		\label{eqn:stability-matrix-A}
		\frac{\partial}{\partial t}\!{\footnotesize\begin{bmatrix}
				\delta\hat{q}^{\boldsymbol{k}}_1\\[1pt]
				\delta\hat{q}^{\boldsymbol{k}}_2\\[1pt]
				\delta \hat{\rho}^{\,\boldsymbol{k}}_E\\[1pt]
				\,\delta \hat{\rho}^{\,\boldsymbol{k}}_H\,
		\end{bmatrix}}\!= {\begin{bmatrix}\boldsymbol{\mathcal{H}}_A^{\boldsymbol{k}} & \boldsymbol{\mathcal{C}}_{\boldsymbol{k}}\\[1pt]
				\,\boldsymbol{O}_{2\times2} & \boldsymbol{\mathcal{S}}_k\end{bmatrix}}{\footnotesize\begin{bmatrix}
				\delta\hat{q}^{\boldsymbol{k}}_1\\[1pt]
				\delta\hat{q}^{\boldsymbol{k}}_2\\[1pt]
				\delta \hat{\rho}^{\,\boldsymbol{k}}_E\\[1pt]
				\,\delta \hat{\rho}^{\,\boldsymbol{k}}_H\,
		\end{bmatrix}},
	\end{equation} where $\boldsymbol{\mathcal{H}}_A^{\boldsymbol{k}}$ is given by
	\begin{equation}
		\boldsymbol{\mathcal{H}}_A^{\boldsymbol{k}} = -k^2 \boldsymbol{I}_{2\times2}+\Lambda(k)\boldsymbol{\mathcal{R}}_A^{\boldsymbol{k}},
	\end{equation} with matrices
	\begin{align}
		\boldsymbol{\mathcal{R}}_A^{\boldsymbol{k}} &=\sin ^2(\varphi ){\footnotesize\begin{bmatrix}
				0 & 0 \\
				\sin (2\varphi ) & -\cos (2 \varphi ) \\
		\end{bmatrix}}\!,\\[8pt]
		\boldsymbol{\mathcal{C}}_{\boldsymbol{k}} &=-\frac{\Lambda(k)\cos (\varphi)\sin^3(\varphi )}{\bar{\rho}_E} {\footnotesize\begin{bmatrix}
				0 & 0 \\
				1 & 0 \\
		\end{bmatrix}}.
	\end{align} 

	In addition to the eigenvalues associated with density perturbations, as derived in Eq.~(\ref{eqn:density-eigenvalues}), the remaining eigenvalues of the stability matrix in Eq.~(\ref{eqn:stability-matrix-A}) are given by a purely diffusive eigenvalue, $-k^2$, and 
	\begin{equation}
		\lambda_A(k) = -k^2-\Lambda(k)\sin^2(\varphi)\cos(2\varphi).
	\end{equation} 

	The region of instability is given by $\lambda_A>0$, and shown in Fig.~\ref{fig:figure_7}(b) and (c) for the extensile ($\alpha>0$) and contractile ($\alpha<0$) stresses, respectively. It can be shown that the fastest growing mode in the the contractile case is found when the angle $\varphi = \frac{\pi}{6}$, $\frac{5\pi}{6}$, $\frac{7\pi}{6}$, and  $\frac{11\pi}{6}$, while $k$ satisfies the equation $\Lambda'(k)\!+16k = 0$. In the case of extensile stresses, the fastest growing mode is given by angle $\varphi = \frac{\pi}{2}$ and $\frac{3\pi}{2}$, with $k$ satisfying  $\Lambda'(k)-2k=0$.

	In three dimensions, the first-order perturbation in nematic order parameter $\delta\boldsymbol{Q}$ and its corresponding Fourier transform can be written as
	\begin{equation*}
		\delta{\boldsymbol{Q}} =\! {\footnotesize\begin{bmatrix}
				\delta q_1 & \delta q_3 & \delta q_4 \\
				\delta q_3 & \delta q_2 & \delta q_5 \\
				\delta q_4 & \delta q_5 & \!\!-\delta q_1\! - \delta q_2\!
		\end{bmatrix}}\!,\;
		\delta{\hat{\boldsymbol{Q}}_{\boldsymbol{k}}} = \!{\footnotesize\begin{bmatrix}
				\delta\hat{q}^{\boldsymbol{k}}_1 & \delta\hat{q}^{\boldsymbol{k}}_3 & \delta\hat{q}^{\boldsymbol{k}}_4\\
				\delta\hat{q}^{\boldsymbol{k}}_3 & \delta\hat{q}^{\boldsymbol{k}}_2 & \delta\hat{q}^{\boldsymbol{k}}_5 \\
				\delta\hat{q}^{\boldsymbol{k}}_4 & \delta\hat{q}^{\boldsymbol{k}}_5 & \!\!-\delta\hat{q}^{\boldsymbol{k}}_1-\delta\hat{q}^{\boldsymbol{k}}_2\! \\
		\end{bmatrix}}\!,
	\end{equation*} where $\delta q_j(\boldsymbol{r},t)$ and $\delta \hat{q}^{\hspace{1pt}\boldsymbol{k}}_j(t)$ are their respective independent components. This representation ensures that the trace of $\boldsymbol{Q}$ is unity. The linear system associated with perturbations about the three-dimensional isotropic state $\bar{\boldsymbol{Q}}_I$ in Eq.~(\ref{eqn:base-state-3D}) can be written as 
	\begin{equation}
		\frac{\partial}{\partial t}\!{\footnotesize\begin{bmatrix}
				\delta\hat{q}^{\boldsymbol{k}}_1\\
				\vdots\\
				\delta\hat{q}^{\boldsymbol{k}}_5\\[1pt]
				\delta \hat{\rho}^{\,\boldsymbol{k}}_E\\[1pt]
				\,\delta \hat{\rho}^{\,\boldsymbol{k}}_H\,
		\end{bmatrix}}\!= {\begin{bmatrix}
				\boldsymbol{\mathcal{M}}_I^{\boldsymbol{k}} & \boldsymbol{O}_{5\times2}\\[1pt]
				\,\boldsymbol{O}_{2\times5} & \boldsymbol{\mathcal{S}}_k
		\end{bmatrix}}{\footnotesize\begin{bmatrix}
				\delta\hat{q}^{\boldsymbol{k}}_1\\
				\vdots\\
				\delta\hat{q}^{\boldsymbol{k}}_5\\[1pt]
				\delta \hat{\rho}^{\,\boldsymbol{k}}_E\\[1pt]
				\,\delta \hat{\rho}^{\,\boldsymbol{k}}_H\,
		\end{bmatrix}},
	\end{equation} where 
	\begin{equation}
		\boldsymbol{\mathcal{M}}_I^{\boldsymbol{k}} = -k^2 \boldsymbol{I}_{5\times5} + \frac{1}{3}\Lambda(k) \,\boldsymbol{\mathcal{U}}_I^{\boldsymbol{k}},
	\end{equation}  where $\boldsymbol{I}_{5\times5}$ is the five-dimensional identity matrix, $\Lambda(k)$ is defined in Eq.~(\ref{eqn:Lambda-def}), and  matrix $\boldsymbol{\mathcal{U}}_I^{\boldsymbol{k}}$ is given solely in terms of the angles $\varphi\in[0,2\pi]$ and $\vartheta\in[0,\pi]$ by expressing the components of $\boldsymbol{k} = [k_x,\,k_y,\,k_z]$ in spherical coordinates: $k_x = k\sin(\vartheta)\cos(\varphi)$, $k_y = k\sin(\vartheta)\sin(\varphi)$, and $k_z = k\cos(\vartheta)$. The expression of $\boldsymbol{\mathcal{U}}_I^{\boldsymbol{k}}$ is cumbersome and will not be shown here. Three of the eigenvalues of $\boldsymbol{\mathcal{M}}_I^{\boldsymbol{k}}$ are $-k^2$ and the other two are both given by
	\begin{equation}
		\lambda_I(k) = -k^2+\Lambda(k)/3.
	\end{equation} Again, as in two dimensions, we find the isotropic state to be always unstable (stable) for extensile (contractile) active stresses, see Fig.~\ref{fig:figure_8}(a). 

	The linear system associated with perturbations about the aligned state $\bar{\boldsymbol{Q}}_A$ in Eq.~(\ref{eqn:base-state-3D}) reads as follows:
	\begin{equation}
		\frac{\partial}{\partial t}\!{\footnotesize\begin{bmatrix}
				\delta\hat{q}^{\boldsymbol{k}}_1\\
				\vdots\\
				\delta\hat{q}^{\boldsymbol{k}}_5\\[1pt]
				\delta \hat{\rho}^{\,\boldsymbol{k}}_E\\[1pt]
				\,\delta \hat{\rho}^{\,\boldsymbol{k}}_H\,
		\end{bmatrix}}\!= {\begin{bmatrix}
				\boldsymbol{\mathcal{M}}_A^{\boldsymbol{k}} & \boldsymbol{\mathcal{B}}_{\boldsymbol{k}}\\[1pt]
				\,\boldsymbol{O}_{2\times5} & \boldsymbol{\mathcal{S}}_k
		\end{bmatrix}}{\footnotesize\begin{bmatrix}
				\delta\hat{q}^{\boldsymbol{k}}_1\\
				\vdots\\
				\delta\hat{q}^{\boldsymbol{k}}_5\\[1pt]
				\delta \hat{\rho}^{\,\boldsymbol{k}}_E\\[1pt]
				\,\delta \hat{\rho}^{\,\boldsymbol{k}}_H\,
		\end{bmatrix}},
	\end{equation} where the block matrix
	\begin{equation}
		\boldsymbol{\mathcal{M}}_A^{\boldsymbol{k}} = -k^2 \boldsymbol{I}_{5\times5}+\Lambda(k)\,\boldsymbol{\mathcal{U}}_A^{\boldsymbol{k}},
	\end{equation} with matrix $\boldsymbol{\mathcal{U}}_A^{\boldsymbol{k}}$ defined solely in terms of the angles $\vartheta$ and $\varphi$ (not shown), while the matrix $\boldsymbol{\mathcal{B}}_{\boldsymbol{k}}$ is given by
	\begin{equation}
		\boldsymbol{\mathcal{B}}_{\boldsymbol{k}} =-\frac{\Lambda(k)\cos^3(\vartheta)\sin(\vartheta )}{\bar{\rho}_E} {\footnotesize\begin{bmatrix}
				0 & 0\;\, \\
				0 & 0\;\, \\
				0 & 0\;\, \\
				\,\cos\varphi & 0\;\, \\
				\,\sin\varphi & 0\;\, \\
		\end{bmatrix}}.
	\end{equation} 

	We find that three eigenvalues of the matrix $\boldsymbol{\mathcal{M}}_A^{\boldsymbol{k}}$ are $-k^2$, whereas the remaining two are given by
	\begin{align}
		\label{eqn:lambdaA_1}
		\lambda^{\mathsf{(1)}}_A(k) &= -k^2+\Lambda(k)\cos^2(\vartheta),\\[10pt]
		\label{eqn:lambdaA_2}
		\lambda^{\mathsf{(2)}}_A(k) &= -k^2+\Lambda(k)\cos^2(\vartheta)\cos(2\vartheta).
	\end{align} As a result, if $\alpha>0$ (extensile case), then both eigenvalues $\lambda^{\mathsf{(1)}}_A$ and $\lambda^{\mathsf{(2)}}_A$ are strictly positive within the same range of $k_z$ modes, see Fig.~\ref{fig:figure_8}(b) and (c). However, if $\alpha<0$ (contractile case), then $\lambda^{\mathsf{(1)}}_A<0$ for any $\boldsymbol{k}$ vector, and only the eigenvalue $\lambda^2_A$ can become strictly positive, resulting in a linear instability, as shown in Fig.~\ref{fig:figure_8}(d). 

	The fastest growing mode for $\alpha>0$ is found when the angle $\vartheta=0$ and $\pi$, and $k$ satisfies $\Lambda'(k)-2k=0$ (as found in two dimensions).  Likewise, the fastest growing mode for the contractile case ($\alpha<0$) is found at the angle $\vartheta=\frac{\pi}{3}$, $\frac{2\pi}{3}$, $\frac{4\pi}{3}$, and  $\frac{5\pi}{3}$, where $k$ satisfies $\Lambda'(k)+16k=0$ (also as in two dimensions). Note that the eigenvectors associated with $\lambda^{\mathsf{(1)}}_A$ and $\lambda^{\mathsf{(2)}}_A$ in Eqs.~(\ref{eqn:lambdaA_1}) and (\ref{eqn:lambdaA_2}) are found to be 
	\begin{align}
		\boldsymbol{e}^{\mathsf{(1)}}_A &= [0,0,0,-\sin\varphi,\hspace{1pt}\cos\varphi,0,0]^{\mathsf{T}},\\[5pt]
		\boldsymbol{e}^{\mathsf{(2)}}_A &= [0,0,0,\cos\varphi,\hspace{1pt}\sin\varphi,0,0]^{\mathsf{T}},
	\end{align} respectively.

