\title{\AS{A Study of Non-linear Flows and Shear Banding in Wormlike Micelles Under Varying Elasticity, Flow Curvature, and Surfactant Chemistry}}

%\title{Influence of Surfactant Chemistry and Flow Geometry on Non-linear Flows of Shear Banding Wormlike Micelles}
\author{Alfredo Scigliani}
\author{Hadi Mohammadigoushki}
\email[Corresponding Author: ]{hadi.moham@eng.famu.fsu.edu}
\affiliation{Department of Chemical and Biomedical Engineering, FAMU-FSU College of Engineering, Tallahassee, FL 32310, USA.}
