\caption{The FedPhD Algorithm for HFL of DMs}
\label{alg:fedphd}
\begin{algorithmic}[1]
\STATE \textbf{Input:} Initial global model $\boldsymbol{\theta}^{(0)}$; global and sparse training rounds $R$, $R_{s}$; edge and global update frequency, $r_e$, $r_g$; number of edge servers and clients $N_e$, $N$; SH score parameters $a$ and $b$; target distribution $q_u(y)$; pruning ratio $s_{p}$
