\section{Diffusion Models Training}
\begin{algorithm}[H]
\caption{FL-based DM training on client $n$ at round $r$}
\label{alg:client_training_dm}
\begin{algorithmic}[1]
\STATE \textbf{Input:} Global model $\boldsymbol{\theta}^{(r)}$, local dataset $\mathcal{D}_n$, local epochs $E$, batch size $B$, learning rate $\eta$
\STATE \textbf{Output:} Updated local model $\boldsymbol{\theta}^{(r+1)}_n$

\STATE Initialize local model: $\boldsymbol{\theta}_n \leftarrow \boldsymbol{\theta}^{(r)}$
\FOR{epoch $e = 0, \dots, E-1$}
    \FOR{batch $\mathcal{B} \in \mathcal{D}_n$}
        \FOR{each $\mathbf{x}_0 \in \mathcal{B}$ in parallel}
            \STATE Sample $t \sim \text{Uniform}(\{1, 2, \dots, T\})$
            \STATE Compute $\bar{\alpha}_t = \prod_{s=1}^{t} \alpha_s$
            \STATE Sample noise $\boldsymbol{\epsilon} \sim \mathcal{N}(0, \mathbf{I})$
            \STATE Compute noised data $\mathbf{x}_t = \sqrt{\bar{\alpha}_t} \mathbf{x}_0 + \sqrt{1 - \bar{\alpha}_t} \boldsymbol{\epsilon}$
            \STATE Compute $\mathcal{L}(\boldsymbol{\theta}_n)$ using \eqref{eq:noise_predict} %$\mathcal{L}(\boldsymbol{\theta}_n) = \mathbb{E}_{t,\mathbf{x}_0,\boldsymbol{\epsilon}} \left[ \lVert \boldsymbol{\epsilon} - \boldsymbol{\epsilon}_{\theta}(\sqrt{\bar{\alpha}_t} \mathbf{x}_0 + \sqrt{1 - \bar{\alpha}_t} \boldsymbol{\epsilon}, t) \rVert^2 \right]$
        \ENDFOR
        \STATE Calculate $F_{n}(\boldsymbol{\theta}_n) = \frac{1}{|\mathcal{B}|} \sum_{\mathbf{x}_0 \in \mathcal{B}} \mathcal{L}(\boldsymbol{\theta}_n)$
        \STATE Update local model: $\boldsymbol{\theta}_n \leftarrow \boldsymbol{\theta}_n - \eta \nabla F_{n}(\boldsymbol{\theta}_n)$
    \ENDFOR
\ENDFOR
\STATE Set $\boldsymbol{\theta}^{(r+1)}_n \leftarrow \boldsymbol{\theta}_n$
\STATE \textbf{return} Updated local model parameters $\boldsymbol{\theta}^{(r+1)}_n$
\end{algorithmic}
\end{algorithm}
