	\begin{abstract}
	For every unitary irreducible representation of a nilpotent Lie group we prove that the representation Hilbert space is the only nonzero invariant Hilbert space of distribution vectors. 
	\end{abstract}




	\maketitle





	\section{Introduction}

	Hilbert subspaces of topological vector spaces in the sense of Laurent Schwartz \cite{Sch64} provide an abstract version of reproducing kernels of function spaces and they thus play an important role in many areas of analysis and representation theory of Lie groups,  
	as shown for instance in \cite{Ne00}. 
	There has been a recent interest in uniqueness of Hilbert subspaces of spaces of tempered distributions that are invariant to modulations and translations, partly motivated by problems related to time-frequency analysis and modulation spaces, see \cite{ToGuMaRa21}, \cite{BaMoPi24}, \cite{RaToVi25}. 


	In this paper we prove an abstract uniqueness theorem for Lie group representations, which recovers some of the preceding results in the special case  of  Schr\"odinger representations of the Heisenberg groups. 
	Specifically, we show that if $\pi\colon G\to\Bc(\Hc)$ is an irreducible unitary  representation of a connected and simply connected nilpotent Lie group $G$, 
	then $\Hc$ is the only continuously embedded Hilbert space into the space of 
	distribution vectors $\Hc_{-\infty}$ which is nonzero and is invariant to the action of $G$ 
	(Theorem~\ref{unique}). 

	 Our approach is completely different from the methods from the earlier papers, 
	 inasmuch as we rely on some basic results in representation theory of nilpotent Lie groups. 
	 Thus, in Corollary~\ref{RaToVi25_Thm0.3}, we provide a new perspective on  \cite[Thm. 0.3]{RaToVi25}. 


	\section{Preliminaries}


	The framework of the present paper is provided by the notions of smooth vectors and distribution vectors with respect to unitary representations of Lie groups. 
	Details of this theory can be found in \cite{Ne10}, \cite{BeBe10}, \cite{BeBe11}, \cite{BeBeGa18}, 
	and the references therein. 

		For every locally convex, topological $\CC$-vector space $\Yc$, we denote by $\Lc(\Yc)$ the associative algebra of continuous linear operators on $\Yc$. 
		and by $\Yc'$ the space of continuous antilinear functionals on $\Yc$ endowed with its $w^*$-topology, i.e., the topology of pointwise convergence. 
		If $\langle\cdot,\cdot\rangle\colon\Yc'\times\Yc\to\CC$ is the corresponding sesquilinear duality pairing (antilinear in its second variable), 
		then for every $T\in\Lc(\Yc)$ there is a unique operator $T'\in\Lc(\Yc')$ satisfying 
		$\langle T'\eta,y\rangle=\langle \eta,Ty\rangle$ for all $\eta\in\Yc'$ and $y\in\Yc$. 
		If $\Xc$ is a Banach space, since the continuous linear operators on $\Xc$  are precisely the bounded operators, we denote $\Bc(\Xc):=\Lc(\Xc)$.


Here is our main setting: 
	\begin{itemize}
		\item $G$ is a connected, simply connected nilpotent Lie group
		\item $\pi\colon G\to \Bc(\Hc)$ is an irreducible (continuous) unitary representation; 
		\item $\Hc_\infty:=\{v\in \Hc\mid \pi(\cdot)v\in\Ci(G,\Hc)\}$ is the Fr\'echet space of smooth vectors; 
		\item $\Hc_{-\infty}$ is the space of distribution vectors, 
		i.e., the space of continuous antilinear functionals on $\Hc_\infty$, endowed with the $w^*$-topology;
		\item $\langle\cdot,\cdot\rangle\colon\Hc_{-\infty}\times\Hc_\infty\to\CC$ 
		is the corresponding sesquilinear duality pairing, antilinear in its second variable, 
		which agrees with the scalar product of the Hilbert space $\Hc$;  
		\item we have the group representations 
		$$\pi_\infty\colon G\to\Lc(\Hc_\infty)\text{ and }
		\pi_{-\infty}\colon G\to\Lc(\Hc_{-\infty})$$ 
		satisfying $\pi_\infty(g)=\pi(g)\vert_{\Hc_\infty}$ and $\pi_{-\infty}(g):=(\pi_\infty(g^{-1}))'$ for every $g\in G$;
		\item $\Sc(G)$ is the associative Fr\'echet algebra of Schwartz functions on $G$ with the convolution product.
	\end{itemize}



\begin{remark}
\label{triple}
\normalfont 
In the setting above,  the natural continuous injective linear maps 
\begin{equation}
	\label{triple_eq1}
	\Hc_\infty\hookrightarrow \Hc\hookrightarrow \Hc_{-\infty}
\end{equation}
intertwine the group representations $\pi_\infty$, $\pi$, and $\pi_{-\infty}$. 

Using integration with respect to the Haar measure of $G$, 
the unitary representation $\pi$ gives rise to a Banach $*$-algebra representation 
$\pi\colon L^1(G)\to\Bc(\Hc)$. 
Moreover,  we have 
$\pi(\Sc(G))\Hc_\infty\subseteq\Hc_\infty$, 
and this gives rise to the algebra representation 
$$\pi_\infty\colon \Sc(G)\to\Lc(\Hc_\infty).$$
Also, the map 
$$\pi_{-\infty}\colon \Sc(G)\to\Lc(\Hc_{-\infty}),\quad 
\pi_{-\infty}(\varphi):=(\pi(\varphi^*))'
$$
is an algebra representation.  
%It is easily checked that 

The maps in \eqref{triple_eq1} 
intertwine the representations $\pi_\infty$, $\pi\vert_{\Sc(G)}$, $\pi_{-\infty}$ of the associative algebra $\Sc(G)$ 
and we have 
\begin{equation}
\label{triple_eq2}
\pi_{-\infty}(\Sc(G))\Hc_{-\infty}\subseteq\Hc_\infty. 
\end{equation}
\end{remark}

\begin{lemma}
\label{alg_irred}
If $\Vc\subseteq\Hc_\infty$ is a $\CC$-linear subspace satisfying $\pi_\infty(\Sc(G))\Vc\subseteq\Vc$ then  either $\Vc=\{0\}$ or $\Vc=\Hc_\infty$, that is, the representation 
$\pi_\infty\colon \Sc(G)\to\Lc(\Hc_\infty)$ is algebraically irreducible.
\end{lemma}

\begin{proof}
See \cite[Cor. 3.4.1]{Ho77}, 
and also \cite[Cor. 3.4]{dC87} 
and \cite[Thm. 2.9]{BeBeGa18}.
\end{proof}

Our main result Theorem~\ref{unique} can be regarded as a sharpening of the condition of absence of nontrivial closed invariant subspaces for irreducible unitary representations of nilpotent Lie groups. 
Before continuing our preparations for its proof, we derive the following simple result that has a similar flavour and may hold an independent interest. 


\begin{proposition}
	\label{w_irred}
	If $\Yc\subseteq \Hc_{-\infty}$ is a $w^*$-closed linear subspace with  $\pi_{-\infty}(\Sc(G))\Yc\subseteq\Yc$, then we have either $\Yc=\{0\}$ or $\Yc=\Hc_{-\infty}$. 
\end{proposition}

\begin{proof}
	Let $\Yc^\perp:=\{v\in\Hc_\infty\mid\langle\Yc,v\rangle=\{0\}\}$, 
	which is a closed linear subspace of $\Hc_\infty$. 
	Since $\Yc\subseteq \Hc_{-\infty}$ is a $w^*$-closed linear subspace, we obtain 
	a topological linear isomorphism  
	\begin{equation}
		\label{w_irred_proof_eq1}
		\Yc\simeq(\Hc_\infty/\Yc^\perp)'. 
	\end{equation}
	On the other hand, the hypothesis $\pi_{-\infty}(\Sc(G))\Yc\subseteq\Yc$ implies 
	$\pi_\infty(\Sc(G))\Yc^\perp\subseteq\Yc^\perp$ 
	hence, by Lemma~\ref{alg_irred}, we have either $\Yc^\perp=\{0\}$ or $\Yc^\perp=\Hc_\infty$. 
	Now the assertion follows by \eqref{w_irred_proof_eq1}. 
\end{proof}

The next lemma is a more precise form of \cite[Cor.~3.4.2]{Ho77}. 
We give below its short proof.

\begin{lemma}\label{isometry}
Let $\pi$ be as above and $\sigma\colon G\to \Bc(\Xc)$ be another unitary representation of $G$.
Assume that the linear map $T\colon \Hc_\infty\to \Xc$ satisfies
$$ T\pi(\varphi) = \sigma (\varphi) T \quad \text{for all } \varphi \in \Sc(G).$$
Then $T$ extends to a bounded operator on $\Hc$ that is  a scalar multiple of an isometry. 
\end{lemma}

\begin{proof}
Let $v_1, v_2\in \Hc_\infty\setminus \{0\}$ be such that 
$\dual{v_1}{v_2}=0$.
The orthogonal projection $P:=\dual{\cdot}{v_1}{v_1}$ belongs to $\Bc(\Hc)_\infty$ by \cite[Ex. 3.1]{BeBe10}. 
By \cite[Thm.~3.4]{Ho77}, there is $\varphi\in \Sc(G)$ with 
$P= \pi(\varphi)$, hence $P=P^*=P^2 = \pi(\psi)$ where $\psi:=\varphi^*\ast \varphi$. 
Then, by hypothesis,  $\sigma(\psi)T=TP=\dual{\cdot}{v_1}Tv_1$, hence
$$ \sigma(\psi) T v_1= Tv_1 \; \; \text{and}\; \; \sigma (\psi) Tv_2=0.$$
It follows that $Tv_1$, respectively $Tv_2$, are eigenvectors for the eigenvalues $1$, respectively $0$, of the self-adjoint operator $\sigma(\psi)$, and thus they are orthogonal. 

Therefore we have obtained that for $v_1, v_2\in \Hc_\infty$, 
\begin{equation}\label{isom1}
 \dual{v_1}{v_2}=0 \; \Longrightarrow  \; \dual{Tv_1}{T v_2}=0.
\end{equation}
Let now $v, w\in \Hc_\infty$ be arbitrary with $\Vert v\Vert =\Vert w\Vert=1$. 
Set 
$ v_2 = w- \dual{w}{v} v$.
Then $\dual{v}{v_2}=0$  hence, by \eqref{isom1}, $\dual{Tv}{Tv_2}=0$ , that is, 
 \begin{equation}\label{isom2}
\dual{Tv}{Tw}= \dual{v}{w}\Vert Tv\Vert^2.
\end{equation} 
Interchanging the roles of $w$ and $v$ we have obtained that 
$\dual{v}{w}\Vert Tv\Vert^2= \dual{v}{w}\Vert Tw\Vert^2$.
It follows that 
$$ \Vert Tv\Vert= \Vert Tw\Vert  \quad\text{if  }\dual{v}{w}\ne 0.$$
If $\dual{v}{w}= 0$ and we put
$w_\epsilon=(w+\epsilon v)/\Vert w+\epsilon v\Vert$ for every $\epsilon>0$, then 
$\dual{v}{w_\epsilon}\ne 0$. Using the above equality we get that 
$$ \Vert Tv\Vert =\Vert w+\epsilon v\Vert^{-1}\Vert T(w+\epsilon v)\Vert =\Vert w+\epsilon v\Vert^{-1}  \Vert Tw+\epsilon Tv\Vert.$$
Letting $\epsilon\to 0$, we get that 
$$ \Vert Tv\Vert= \Vert Tw\Vert  \quad\text{for every} \quad v, w\in \Hc_\infty, \; \Vert v\Vert =\Vert w\Vert =1.$$
Thus $\lambda_0:=\Vert Tv\Vert$ is independent on $v\in\Hc_\infty$ with $\Vert v\Vert=1$. 
Then by \eqref{isom2}
we get 
\begin{equation}\label{isom3}
\dual{T v}{T w }= \lambda_0^2 \dual{v}{w}
 \end{equation} 
for every $v, w\in \Hc_\infty$.
Since $\Hc_\infty$ is dense in $\Hc$, \eqref{isom3} shows that $T$ extends 
as a bounded operator on $\Hc$, $\eqref{isom3}$ holds for $v, w\in \Hc$, hence the extension of $T$ is a scalar multiple of an isometry.  
\end{proof}



\section{The main result} 



\begin{theorem}
\label{unique}
Let $\pi\colon G\to\Bc(\Hc)$ be an irreducible unitary representation of a connected, simply connected nilpotent Lie group $G$. 
Let $\Xc\subseteq\Hc_{-\infty}$ be a $\CC$-linear subspace endowed with the structure of a complex Hilbert space satisfying the following hypotheses: 
\begin{enumerate}%[{\rm(H1)}]
[start=1,label={\rm(H\arabic*)}]
	\item\label{unique_item1} 
	the inclusion map $\Xc\hookrightarrow\Hc_{-\infty}$ is continuous; 
	\item\label{unique_item2}
	 $\pi_{-\infty}(G)\Xc\subseteq\Xc$; 
	\item\label{unique_item3} 
	for every $g\in G$ the operator $\pi_\Xc(g):=\pi_{-\infty}(g)\vert_\Xc\colon\Xc\to\Xc$ is an isometry.
\end{enumerate}
Then either $\Xc=\{0\}$ or $\Xc=\Hc$. 
\end{theorem}

For the proof of the above theorem we still need the following lemma.

\begin{lemma}
	\label{cont}
	Let $\Gamma$ be a topological group, 
	$\Xc$ a complex Hilbert space, $\rho\colon \Gamma\to \Bc(\Xc)$ a mapping, 
	and for every $x\in\Xc$ denote 
	$\rho^x\colon \Gamma\to\Xc$, $\rho^x(g):=\rho(g)x$. 
	Assume that the following conditions are satisfied: 
	\begin{enumerate}[{\rm(a)}]
		\item For every $g,h\in \Gamma$ we have $\rho(gh)=\rho(g)\rho(h)$ and moreover $\rho(\1)=\id_\Xc$. 
		\item For every $g\in \Gamma$ the operator $\rho(g)\colon \Xc\to\Xc$ is an isometry. 
		\item There exists a subset $A\subseteq\Xc$ that spans a dense linear subspace of $\Xc$ and $\rho^x\colon \Gamma\to \Xc$ is continuous for every $x\in A$. 
	\end{enumerate}
	Then $\rho$ is a continuous unitary representation  of the topological group $\Gamma$. 
\end{lemma}

\begin{proof}
	For every $g\in \Gamma$ we have $\id_\Xc=\rho(\1)=\rho(g)\rho(g^{-1})$, 
	hence $\rho(g)\in\Bc(\Xc)$ is a surjective isometry.
	that is, a unitary operator. 
	It remains to prove that $\rho^x\colon \Gamma\to \Xc$ is continuous for every $x\in \Xc$. 
	(See e.g., \cite[Lemma 5.2]{Ne10}.)
	To this end we consider the set $\Xc_0:=\{x\in\Xc\mid \rho^x\in\Cc(\Gamma,\Xc)\}$. 
	It is clear that $\Xc_0$ is a linear subspace of $\Xc$ and $A\subseteq\Xc_0$, hence $\Xc_0$ is dense in $\Xc$. 
	On the other hand, for arbitrary $x,y\in\Xc$ and $g\in \Gamma$ we have $\Vert \rho^x(g)-\rho^y(g)\Vert =\Vert \rho(g)x-\rho(g)y\Vert=\Vert x-y\Vert$. 
	This directly implies that $\Xc_0$ is closed in $\Xc$, hence $\Xc_0=\Xc$. 
\end{proof}

\begin{proof}[Proof of Theorem~\ref{unique}]
We assume $\Xc\ne\{0\}$. 
For every $v\in\Hc_\infty$ we have $\overline{\langle\cdot,v\rangle}\in(\Hc_{-\infty})'$, 
hence $\overline{\langle\cdot,v\rangle}\vert_\Xc\in\Xc'$ by \ref{unique_item1}. 
Since $\Xc$ is a complex Hilbert space, there exists a uniquely determined vector $\iota(v)\in\Xc$ satisfying 
\begin{equation}
\label{unique_proof_eq1}
\langle\cdot,v\rangle\vert_\Xc=\langle\cdot,\iota(v)\rangle_\Xc,
\end{equation} 
where $\langle\cdot,\cdot\rangle_\Xc$ denotes the scalar product of $\Xc$. 
We thus obtain a linear operator 
$$\iota\colon \Hc_\infty\to\Xc.$$
The equality \eqref{unique_proof_eq1} shows that $\iota$ is the adjoint of the inclusion map $\Xc\hookrightarrow\Hc_{-\infty}$. 
The range of the operator $\iota$ is dense in $\Xc$ since the above inclusion map is injective.
In fact, if $x_0\in\Xc$ satisfies $x_0\perp \iota(\Hc_\infty)$ in $\Xc$ 
then, by \eqref{unique_proof_eq1}, 
we have $\langle x_0,v\rangle=0$ for every $v\in\Hc_\infty$, that is, $x_0=0$.  


In order to prove that $\iota$ is a continuous operator, one can use the Closed Graph Theorem since $\Hc_\infty$ is a Fr\'echet space and $\Xc$ is a Hilbert space. 
Specifically, if $\lim\limits_{n\to\infty}v_n=v$ in $\Hc_\infty$ and $\lim\limits_{n\to\infty}\iota(v_n)=x$ in $\Xc$, 
then $\iota(v)=x$ by \eqref{unique_proof_eq1}. 

For every $g\in G$, $v\in\Hc_\infty$, and $x\in\Xc$ we have 
\begin{align*}
\langle x,\iota(\pi_\infty(g)v)\rangle_\Xc
&=\langle x,\pi_\infty(g)v\rangle
=\langle \pi_{-\infty}(g^{-1})x, v\rangle
=\langle \pi_\Xc(g^{-1})x, v\rangle \\
& =\langle \pi_\Xc(g^{-1})x,\iota(v)\rangle_\Xc 
=\langle x,\pi_\Xc(g)\iota(v)\rangle_\Xc 
\end{align*}
hence 
\begin{equation}
	\label{unique_proof_eq2}
(\forall g\in G, v\in\Hc_\infty)\quad 	\iota(\pi_\infty(g)v)=\pi_\Xc(g)\iota(v).
\end{equation} 
Since $\iota\colon\Hc_\infty\to\Xc$ is a continuous linear operator, 
and the mapping $G\ni g\mapsto\pi_\infty(g)v\in\Hc_\infty$ is smooth  
as $\pi\colon G\to\Bc(\Hc)$ is a continuous representation 
(cf. \cite[Prop. 1.2]{Po72}), 
it also follows by \eqref{unique_proof_eq2} that for every $x\in\iota(\Hc_\infty)\subseteq\Xc$ the mapping $\rho_\Xc^x\colon G\to\Xc$, $\pi_\Xc^x(g):=\pi_\Xc(g)x$, is smooth, and in particular continuous. 
We proved above that $\iota(\Hc_\infty)$ is dense in $\Xc$, 
hence by, \ref{unique_item3}, Lemma~\ref{cont} is applicable and 
ensures that $\pi_\Xc\colon G\to\Bc(\Xc)$ is a continuous unitary representation, 
and moreover $\iota(\Hc_\infty)\subseteq \Xc_\infty$.  
Then, using~\eqref{unique_proof_eq2} once again, 
we obtain 
\begin{equation*}
	\label{unique_proof_eq3}
(\forall \varphi\in\Sc(G))\quad 	
\iota\circ \pi_\infty(\varphi)
=(\pi_\Xc)_\infty(\varphi)\circ \iota\colon \Hc_\infty\to \Xc_\infty.
\end{equation*} 
This implies by Lemma~\ref{isometry} 
that there exist $\lambda_0\in\RR$ 
and an isometry $\iota_0\colon\Hc_\infty\to\Xc$ 
with $\iota=\lambda_0\iota_0$. 
Since $\iota$ is has dense range in $\Xc$ and thus is non-trivial when $\Xc\ne\{0\}$, $\lambda_0\ne 0$ and we may assume that $\lambda_0>0$, by replacing 
 $\iota_0$ by $-\iota_0$ if necessary. 

Using again that the range of $\iota$ is dense in $\Xc$ 
it follows that $\iota_0\colon\Hc_\infty\to\Xc$ extends 
by continuity to a unitary operator $\iota_0\colon\Hc\to\Xc$ that intertwines the representations $\pi$ and $\pi_\Xc$. 
In particular, the unitary representation $\pi_\Xc$ is irreducible. 


On the other hand, we recall from \eqref{triple_eq2} that  $\pi_{-\infty}(\Sc(G))\Hc_{-\infty}\subseteq\Hc_\infty$, 
in particular $\pi_{-\infty}(\Sc(G))\Xc\subseteq\Hc_\infty$, 
while the hypothesis~\ref{unique_item2} along with the continuity of the representation $\pi_\Xc(\cdot)=\pi_{-\infty}(\cdot)\vert_\Xc$ implies 
by \eqref{triple_eq2} again that 
$\pi_{-\infty}(\Sc(G))\Xc\subseteq\Xc_\infty$. 
Thus 
$$\pi_{-\infty}(\Sc(G))\Xc\subseteq\Xc_\infty\cap\Hc_\infty$$
and then the property $\Xc\ne\{0\}$ shows that $\Xc_\infty\cap\Hc_\infty\ne\{0\}$. 
As above, by the hypothesis~\ref{unique_item2} again we also have $\pi_\infty(\Sc(G))(\Xc_\infty\cap\Hc_\infty)\subseteq \Xc_\infty\cap\Hc_\infty$. 
Then, by  Lemma~\ref{alg_irred} applied for both irreducible representations $\pi$ and $\pi_\Xc$, we obtain $\Hc_\infty=\Xc_\infty\cap\Hc_\infty=\Xc_\infty$, 
that is, $\Hc_\infty=\Xc_\infty$. 

By another application of Lemma~\ref{isometry}, 
the identity map $\id_{\Hc_\infty}\colon \Hc_\infty\to\Xc$ extends to $\Hc$ and its extension is a scalar multiple of an isometry. 
Since $\Hc_\infty$ is dense in $\Hc$, and $\Xc_\infty$ is dense in $\Xc$,  we get that $\Hc \subset \Xc$,  this extension is a multiple of an unitary operator and it is nothing else than
 $\id_{\Hc}\colon\Hc\to\Xc$. 
That is, $\Xc=\Hc$ as sets, and the scalar products of these Hilbert spaces are a suitable scalar multiple of each other. 
\end{proof}

\begin{remark}\label{means}
\normalfont 
In the setting of Theorem~\ref{unique}, if we assume \ref{unique_item2}, 
then \ref{unique_item3} is equivalent to the following, apparently weaker, condition: 
\begin{enumerate}%[{\rm(H1)}]
	[start=4,label={\rm(H\arabic*)}]
	\item\label{unique_item4} 
	there exist a constant $C>0$ and an equivalent Hilbert space norm $\Vert\cdot\Vert'_\Xc$ such that for every $g\in G$ and $x\in\Xc$ we have $\Vert\pi_\Xc(g)x\Vert'_\Xc\le C\Vert x\Vert'_\Xc$.  
\end{enumerate}
In fact, clearly \ref{unique_item3}$\Rightarrow$\ref{unique_item4} with $\Vert\cdot\Vert'_\Xc=\Vert\cdot\Vert'_\Xc$ and $C=1$. 
For the converse implication, let us assume \ref{unique_item4} and denote by $G_d$ the group $G$ endowed with its discrete topology. 
Since $G_d$ is a nilpotent group, it is solvable hence amenable. 
See e.g.,  \cite[page 9]{Gr69}. 
Then, by \cite[Thm. 3.4.1]{Gr69} and its proof, one can define an equivalent Hilbert space norm $\Vert\cdot\Vert_\Xc$ on $\Xc$ for which the representation $\pi_\Xc\colon G_d\to\Bc(\Xc)$ is unitary, that is, \ref{unique_item3} holds true. 

In the special case when $G$ is a Heisenberg group and $\pi$ is a Schr\"odinger representation as in the proof of Corollary~\ref{RaToVi25_Thm0.3} below, the above remark provides a new approach to the result of \cite[Lemma 1.3]{RaToVi25}.
\end{remark}

We are now in a position to provide a new proof of \cite[Thm. 0.3]{RaToVi25} as follows. 

\begin{corollary}
\label{RaToVi25_Thm0.3}
Let $\Xc\hookrightarrow\Sc'(\RR^d)$ be a continuous inclusion of a nonzero complex Hilbert space into the space of tempered distributions on $\RR^d$, satisfying the following condition: 
 there exists a constant $C_0>0$ such that for all $f\in\Xc$ and $x,\xi\in\RR^d$ we have $f(\cdot-x)\ee^{\ie\langle \cdot,\xi\rangle}\in\Xc$ and $\Vert f(\cdot-x)\ee^{\ie\langle \cdot,\xi\rangle}\Vert_\Xc\le C_0\Vert f\Vert_\Xc$. 

Then $\Xc=L^2(\RR^d)$ as vector spaces, and the norms $\Vert\cdot\Vert_\Xc$ and $\Vert\cdot\Vert_{L^2(\RR^d)}$ are equivalent. 
\end{corollary}

\begin{proof}
We consider  
the Heisenberg group $G=H_d=\RR^d\times\RR^d\times\RR$ 
with its group operation 
$$(x,\xi,t)\cdot(y,\eta,s):=(x+y,\xi+\eta,t+s+(\langle\xi,y\rangle-\langle\eta,x\rangle)/2)$$
and the Schr\"odinger representation 
$\pi\colon H_d\to \Bc(L^2(\RR^d))$ given by 
$$(\pi(x,\xi,t)f)(y)=\ee^{\ie(\langle\xi,y\rangle+t+\langle\xi,x\rangle/2)}f(y+x).$$
(See e.g., \cite[Ex. 2.2.6]{CG90}.)
Then we have $\Hc_\infty=\Sc(\RR^d)$ hence $\Hc_{-\infty}=\Sc'(\RR^d)$. 
Thus the assumption on $\Xc$ implies that the hypotheses \ref{unique_item1} and \ref{unique_item2} in Theorem~\ref{unique}, as well as \ref{unique_item4} in Remark~\ref{means} are satisfied. 
Now the assertion follows by Theorem~\ref{unique} along with Remark~\ref{means}. 
\end{proof}





