\section{Analysis of a common model of active nematics}
\label{sec:BE}

\subsection{The Beris-Edwards (BE) model}

A common mathematical approach used for the evolution of $\mathsf{Q}$ is the
Beris-Edwards model, which in 2D is 
%
\begin{equation}
  \frac{D}{D t}  \mathsf{Q}
 = \lambda S \mathsf{E} +  [\mathsf{Q}, \Omega ] -
2 \text{Tr} (\mathsf{Q} \mathsf{E} ) \mathsf{Q}  +
\frac{1}{\gamma} \mathsf{H},
\label{r8}
\end{equation}
%
where $\lambda $ is the \emph{flow alignment parameter}, $\mathsf{H}$ is the
\emph{molecular tensor}, and $\gamma$ is the \emph{rotational viscosity}.  The first
three terms are in exact agreement with Eq.~(\ref{r2}), taking
$\lambda = 1$ and $B = 0$.  Thus, in regions where $\mathsf{H}$ can be ignored
(more precisely the part of $\mathsf{H}$ proportional to
$\mathsf{U}$; see Sect.~\ref{sec:NLEq}), the Beris-Edwards model exhibits nematic locking if $\lambda = 1$.
The molecular tensor is given by the equation
%
\begin{equation}
    \mathsf{H} = - \left(\frac{\delta F}{\delta \mathsf{Q}}
    - \frac{1}{2}\text{Tr}\frac{\delta F}{\delta \mathsf{Q}} \right).
    \label{r21}
  \end{equation}
  %
Here, $F$ is the Landau-de Gennes free energy
  %
  \begin{equation}
F = F^P + F^E,
  \end{equation}
  %
composed of the phase free energy
  %
  \begin{align}
    F^P &= \int_D   \left[ \frac{A}{2} \text{Tr}(\mathsf{Q}^2)  +
    \frac{C}{4}  \text{Tr}(\mathsf{Q}^2)^2 \right] \; da \\
    &=\int_D   \left[ \frac{A}{4} S^2  +
    \frac{C}{16}  S^4 \right] \; da, \label{r17}
  \end{align}
  %
and the elastic energy
    % 
  \begin{equation}
    F^E = \int_D  \frac{1}{2} K (\nabla_i Q_{jk}) \nabla_i Q_{jk} \; da,
  \end{equation}
  %
which are both integrated over the material domain $D$.  Note that we have used
%
\begin{equation}
    \text{Tr}(\mathsf{Q}^2) = S^2/2.
    \label{r20}
\end{equation}  
%
We have also assumed isotropic elasticity with a single elastic constant.  We consider the more general case of anisotropic elasticity in Sect.~\ref{sec:anisotropic}.  The molecular tensor is then composed of a phase and elastic term
%
\begin{align}
  \mathsf{H} & = \mathsf{H}^P +  \mathsf{H}^E, \\
  \mathsf{H}^P  & =   -\mathsf{Q}(A + C\text{Tr}(\mathsf{Q}^2)) 
  =  -\mathsf{Q}\left(A + \frac{C}{2}S^2\right), \\ 
   \mathsf{H}^E & = \frac{1}{2}
 K \nabla^2 \textsf{Q}.
 \label{r22}
  \end{align}
  %
 Note that the phase term  $\mathsf{H}^P$ does not violate nematic
 locking since it is proportional to $\mathsf{Q}$.  It is only the part of   $\mathsf{H}^E$ proportional to
 $\mathsf{U}$ that does.  We choose $C = -2A>0$ so that the integrand of Eq.~(\ref{r17}) is a double well, with $S = 1$ the location of the bottom of the right well.  Thus the phase free energy tends to drive the system toward alignment ($S = 1$).

 We now turn our attention to the fluid velocity $\mathbf{u}$, which
 is governed by the Navier-Stokes equation.  
%
\begin{equation}
 \frac{D}{Dt}\mathbf{u} =  \nabla_j \Pi_{ij},
  \label{r6}
\end{equation}
%
where we assume constant density $\rho = 1$, and where the stress tensor is
%
\begin{equation}
  \Pi = 2\eta \mathsf{E} - p \mathsf{I} +\Pi^E + \Pi^A.
\end{equation}
%
The first two terms are the viscous damping, with viscosity $\eta$,
and the pressure $p$.   The elastic stress is
%
\begin{align}
  \Pi^E & = -\mathsf{H} +
  [\mathsf{Q},\mathsf{H}] + 2 \text{Tr}(\mathsf{QH}) \mathsf{Q} -\nabla Q_{ij} \otimes \frac{\delta F}{\delta \nabla Q_{ij}},
\label{r4}
\end{align}
  %
with the Ericksen stress term 
%
\begin{equation}
-\nabla Q_{ij} \otimes \frac{\delta F}{\delta \nabla Q_{ij}} = -K
\nabla Q_{ij} \otimes
\nabla Q_{ij}.
\end{equation}
%
Combining these results, the elastic stress becomes
%
\begin{align}
  \Pi^E & = K [-\nabla^2 \mathsf{Q} +
  [\mathsf{Q},\nabla^2 \mathsf{Q}] \nonumber \\
  & \; \; \; \;  + 2 \text{Tr}(\mathsf{Q} \nabla^2 \mathsf{Q}) \mathsf{Q}  -
\nabla Q_{ij} \otimes
\nabla Q_{ij}].
\label{r9}
\end{align}
%
Note that there is no stress associated with the phase free energy, as
 $\mathsf{H}^P$ contributes nothing to Eq.~(\ref{r4}).  
Finally, the active stress driving the motion is
%
\begin{equation}
\Pi^A = -\zeta \mathsf{Q},
\label{r5}
\end{equation}
%
with activity parameter $\zeta > 0$ for extensile dynamics. 

