    \caption{The model only depends on $W$ through multiplication of activations $h(x)$.}\label{fig:weightinmodel}
\end{wrapfigure}
\paragraph{Training setup} We consider the standard training setup, with a model $f(\cdot;\theta) : \cX \to \R^c$ trained on a sample-wise loss function $\ell : \R^c \times \cY \to \R$ on data points $(x_i,y_i)_{i \in [n]}$ with $L^2$ regularization parameter $\lambda > 0$ (that is, with non-zero weight decay). The training loss is $\cL_{\lambda}(\theta) = \cL(\theta) + \frac{\lambda}{2} \|\theta\|_F^2\,, \mbox{ where } 
\cL(\theta) = \frac{1}{n} \sum_{i=1}^n \ell(f(x_i; \theta), y_i)$. Here $\cX$ and $\cY$ are the input and output domains.


Our FACT applies to any weight matrix parameter $W \in \R^{d' \times d}$ inside a trained model. The only architectural requirement is that the model only depends on $W$ via matrix multiplication of internal activations. See Figure~\ref{fig:weightinmodel}. Formally, fixing all parameters but $W$, there are functions $g,h$ such that for all $x$,
\begin{align}\label{eq:weight-matrix-in-nn}
f(x;\theta) = g(Wh(x), x)\,.
\end{align}
In this notation,\footnote{More precisely, including the dependence on the parameters other than $W$, what this means is that we can partition the parameters as $\theta = [W,\theta_{-W}]$, and $f(x;\theta) = g(Wh(x;\theta_{-W}); x; \theta_{-W})$.} $h$ is the input to the weight matrix, and $Wh$ is the output. Thus, FACT applies to any layer in neural networks that involves matrix multiplications.

For convenience, we introduce the notation to denote the gradient of the loss and the value of the model \textit{with respect to the input of the layer} containing the weight matrix $W$, at the data point $x_i$:
\begin{align*}
\nabla_{h} \ell_i := \pd{\ell(g(Wh,x);y_i)}{h} \mid_{h = h(x_i)} \in \R^{d} \quad \mbox{ and } \quad \nabla_{h} f_i := \pd{g(Wh,x)}{h} \mid_{h = h(x_i)}\in \R^{d \times c}\,.
\end{align*}

\paragraph{Neural Feature Ansatz.} In the above notation, the NFA \cite{radhakrishnan2024mechanism} posits that the neural feature matrix $W^{\top} W$ is proportional to the influence that the different subspaces of the input have on the output, which is captured by the Average Gradient Outer Product ($\agop$) matrix. Namely, there is a power $s > 0$ such that
\begin{align}
W^{\top} W \propto (\agop)^s\,, \mbox{ where } \agop := \frac{1}{n} \sum_{i=1}^n (\nabla_{h} f_i) (\nabla_{h} f_i)^{\top}\,. \tag{NFA} \label{eq:nfa}
\end{align}
\paragraph{Equivariant Neural Feature Ansatz.} In this paper, we also compare to the eNFA \cite{ziyin2025formationrepresentationsneuralnetworks}, which states
\begin{align}
 W^{\top} W \propto \enfa := \frac{1}{n} \sum_{i=1}^n (\nabla_{h} \ell_i)(\nabla_{h} \ell_i)^{\top}\,. \tag{eNFA} \label{eq:enfa}
\end{align}






\section{Neural features satisfy FACT at convergence}\label{sec:separation}

Our main observation is that, at a critical  point of the loss, the features $h(x)$ are weighted by their influence on the final loss. This is stated in the following theorem, which can be derived in just a few lines:

\begin{theorem}[Features at Convergence Theorem]\label{thm:fact}
If the parameters of the model are at a critical point of the loss with respect to $W$, then
\begin{align}%
W^{\top} W &= \fact := -\frac{1}{n \lambda} \sum_{i=1}^n (\nabla_{h} \ell_i) (h(x_i))^{\top}\,.\tag{FACT}\label{eq:fact}\end{align}
\end{theorem}
\begin{proof}
The premise of the theorem implies that $\nabla_W \cL_{\lambda}(\theta) = 0$, since $W$ is a subset of the model parameters. By left-multiplying by $W^{\top}$ and using the chain rule, we obtain
\allowdisplaybreaks\begin{align*}
0 &= W^{\top} (\nabla_W \cL_{\lambda}(\theta)) \\
&= W^{\top} (\lambda W + \nabla_W \cL(\theta)) \\
&= W^{\top} (\lambda W + \frac{1}{n} \sum_{i=1}^n \left(\pd{\ell(g(\tilde{h});y_i)}{\tilde{h}} \mid_{\tilde{h} = Wh(x_i)}\right)h(x_i)^{\top} \\
&= \lambda W^{\top} W + \frac{1}{n} \sum_{i=1}^n (\nabla_h \ell_i) h(x_i)^{\top}\,.
\end{align*}
The theorem follows by rearranging and dividing by $\lambda$.
\end{proof}


\begin{remark}[Backward form]
There is also an analogous ``backward'' version of this equation \eqref{eq:bfact}, derived and empirically validated in Appendix~\ref{app:bfact-complete}, that yields information about the left singular vectors of $W$ rather than the right singular vectors. Letting $\nabla_{Wh} \ell_i$ denote the gradient of the loss with respect to the output of the layer at data point $x_i$, we have
\begin{align}
WW^{\top} = \bfact := -\frac{1}{n\lambda} \sum_{i=1}^n (Wh(x_i))(\nabla_{Wh} \ell_i)^{\top} \,.\tag{bFACT}
\end{align}
\end{remark}


\begin{remark}[Symmetrizations of FACT] \label{remark:symmetrization} While $W^{\top} W$ is p.s.d., the quantity $\fact$ is only guaranteed to be p.s.d. at critical points of the loss. This means that we can exploit the symmetries of the left-hand-side of \eqref{eq:fact} to get several other identities at convergence. For instance, since $W^{\top} W = (W^{\top} W)^{\top}$, we may conclude that at the critical points of the loss $W^{\top} W = \fact^{\top}$ also holds. Similarly, using that $W^{\top} W = \sqrt{(W^{\top} W) (W^{\top} W)^{\top}}$, we may also conclude that at critical points $W^{\top}W = \sqrt{\fact \cdot \fact^{\top}}$ also holds. 
\end{remark}








In Section~\ref{sec:approx-real-world}, we empirically validate the FACT on deep networks trained on real-world data, comparing to the NFA and eNFA predictions. Our empirical comparisons show differences between the correlations of these methods with the ground truth, and these differences are corroborated by a theoretical result in Section~\ref{sec:approx-two-layer} which proves that the NFA and FACT predictions can be nearly uncorrelated even in the simple setting of two-layer nonlinear networks.

