\section{Proof of Theorem~\ref{thm:wagop-agop-uncorr-2-layer}, separating FACT and NFA for two-layer networks}\label{app:FACT-nfa-separation-two-layer}

We provide the proof of Theorem~\ref{thm:wagop-agop-uncorr-2-layer}, restating the theorem as Theorem~\ref{thm:wagop-agop-uncorr-2-layer-app} for convenience.

\paragraph{Setup} Consider a trained two-layer architecture $f(x;a,W) = a^{\top} \sigma(Wx)$ with quadratic activation $\sigma(t) = t^2$ and parameters $a \in \R^m$, $W \in \R^{m \times d}$. For any $p \in (0,1)$ and $\tau \in (0,1)$, define the data distribution $\cD(p,\tau)$ over $(x,y)$ such that $x$ is drawn from a mixture of distributions: $x \sim \mathrm{Unif}[\{0,1,2\}^4]$ with probability $p$ and $x = (1,1,0,0)$ with probability $1-p$, and such that $y = f_*(x) = \tau x_1x_2 + x_3x_4 \in \R\,.$ 


\begin{theorem}[Separation between NFA and FACT in two-layer networks; restated Theorem~\ref{thm:wagop-agop-uncorr-2-layer}]\label{thm:wagop-agop-uncorr-2-layer-app}
Fix $s > 0$ to be the NFA power. For any $\epsilon \in (0,1)$, there are hyperparameters $p_{\epsilon}, \tau_{\epsilon}, \lambda_{\epsilon} \in (0,1)$ such that any parameters $\theta = (a,W)$ minimizing $\cL_{\lambda_{\epsilon}}(\theta)$ on data distribution $\cD_{\epsilon} := \cD(p_{\epsilon},\tau_{\epsilon})$ are nearly-uncorrelated with the NFA prediction:
\begin{align*}
\mathrm{corr}((\agop)^s,W^{\top}W) < \epsilon\,,
\end{align*}
where $\mathrm{corr}(A,B) = \langle A,B\rangle / (\|A\|_F\|B\|_F)$ is the correlation. On the other hand, the FACT prediction holds.
\end{theorem}

\begin{proof}
Set $\tau_{\epsilon} = \epsilon^3$, $p_{\epsilon} = \epsilon^8$, $\lambda_{\epsilon} = \epsilon^{32} p_{\epsilon}$. The outline of the proof that the loss-minimizing weights and $\agop$ are uncorrelated is to first show that there is a set of weights $\bar{a}, \bar{W}$ such that the loss $\cL_{\lambda_{\epsilon}}(\bar{a}, \bar{W})$ is small. This implies that at any minimizer $a^*,W^*$ we must also have that $\cL_{\lambda_{\epsilon}}(a^*,W^*)$ is small. In turn, this means that the estimated function $\hat{f}(\cdot) = f(\cdot; a^*, W^*)$ must be close to the true function $f_*(x) = \tau_{\epsilon} x_1x_2 + x_3x_4$. Finally, this will let us compare the $\agop$ to the loss-minimizing weights $\hat{a}, \hat{W}$. 


\textul{1. Construct weights with low loss.} Construct $\bar{W} = \begin{bmatrix} \bar{w}_1,\ldots,\bar{w}_m\end{bmatrix}^{\top} \in \R^{m \times d}$ and $\bar{a} = \begin{bmatrix} \bar{a}_1,\ldots,\bar{a}_m \end{bmatrix}^{\top} \in \R^{m \times 1}$ by letting $\bar{w}_1 = e_1 + e_2$, $\bar{w}_2 = e_1$, $\bar{w}_3 = e_2$, $\bar{w}_4 = e_3 + e_4$, $\bar{w}_5 = e_3$, $\bar{w}_6 = e_4$, $\bar{a}_1 = \tau_{\epsilon} / 2$, $\bar{a}_4 = 1/2$, $\bar{a}_2 = \bar{a}_3 = -\tau_{\epsilon}$, $\bar{a}_5 = \bar{a}_6 = -1$, and $\bar{w}_j= 0$ and $\bar{a}_j = 0$ for all $j \geq 7$. One can check that $f(x;\bar{a}, \bar{W}) = f_*(x)$ for all $x$, and that $\|\bar{W}\|_F^2 + \|a\|^2 \leq 13$. Therefore
\begin{align}\cL_{\lambda_{\epsilon}}(\hat{a}, \hat{W}) \leq \cL_{\lambda_{\epsilon}}(\bar{a}, \bar{W}) \leq 169\lambda_{\epsilon}\,.\label{ineq:uncorr-loss-low}\end{align}

\textul{2. Conclude that $\hat{f} \approx f_*$.} Define $\hat{f}(\cdot) = f(\cdot; \hat{a}, \hat{W})$. Since $\hat{f}$ and $f_*$ are homogeneous quadratic functions, we may write them as
\begin{align*}
\hat{f}(x) = \sum_{1 \leq i \leq j \leq 4} \hat{c}_{ij} x_i x_j \quad \mbox{ and } \quad f_*(x) = \sum_{1 \leq i \leq j \leq 4} c_{ij} x_i x_j\,.
\end{align*}
Let us show that the coefficients $\{c_{ij}\}$ must be close to the estimated coefficients $\{\hat{c}_{ij}\}$ using a Fourier-analytic calculation. Define the distribution $\cU = \mathrm{Unif}[\{0,1,2\}^4]$ and the inner product between a pair of functions $\<g,h\>_{\cU} = \E_{x \sim \cU}[g(x)h(x)]$. Also define the functions
\begin{align*}\chi^{(0)}(t) = \begin{cases} 3, & t= 0 \\ 0, & t \in \{1,2\} \end{cases}, \quad \chi^{(1)}(t) = \begin{cases} -4.5, & t = 0 \\ 6, & t = 1 \\ -1.5 & t= 2\end{cases}, \quad \chi^{(2)}(t) = \begin{cases} 1.5, & t = 0 \\ -3, & t = 1 \\ 1.5, & t = 2 \end{cases}\,
\end{align*}
and for any vector of degrees $\alpha \in \{0,1,2\}^k$ define $\chi_{\alpha} : \{0,1,2\}^4 \to \R$ by $\chi_{\alpha}(x) = \prod_{i=1}^k \chi^{(\alpha_i)}(x_i)$. These functions have been picked so that for any $\alpha' \in \{0,1,2\}^k$ and monomial $h_{\alpha'}(x) = x_1^{\alpha'_1} x_2^{\alpha'_2} \dots x_k^{\alpha'_k}$, we have $\<h_{\alpha}, \chi_{\alpha'}\>_{\cU} = 1(\alpha = \alpha')\,.$
Therefore, for any $1 \leq i \leq j \leq 4$, there is $\alpha \in \{0,1,2\}$ such that
\begin{align*}
c_{ij} =\<f_*,\chi_{\alpha} \>_{\cU} \mbox{ and } \hat{c}_{ij} = \<\hat{f}, \chi_{\alpha}\>_{\cU}\,.
\end{align*}
Therefore, by Cauchy-Schwarz, for any $1 \leq i \leq j \leq 4$ and corresponding $\alpha$ we have
\begin{align*}
|c_{ij} - \hat{c}_{ij}| &= |\<f_* - \hat{f}, \chi_{\alpha}\>_{\cU}| \leq \|f_* - \hat{f}\|_{\cU} \|\chi_{\alpha}\|_{\cU} \leq 6^4 \|f_* - \hat{f}\|_{\cU}
\end{align*}
Now we can apply our previous bound in \eqref{ineq:uncorr-loss-low}, which implies that $\E_{(x,y) \sim \cD_{\epsilon}}[(\hat{f}(x)-f_*(x))^2] \leq \cL(\hat{a},\hat{W}) \leq 169\lambda_{\epsilon}$, and in turn means that
\begin{align*}
\|f-f_*\|_{\cU}^2 &= \<f-f^*,f-f^*\>_{\cU} = \E_{x \sim \mathrm{Unif}[\{0,1,2\}^4]}[(\hat{f}(x)-f_*(x))^2] \leq 169 \lambda_{\epsilon} / p_{\epsilon}.
\end{align*}
So the estimated coefficients $\{\hat{c}_{ij}\}$ are close to the true coefficients $\{c_{ij}\}_{ij}$, i.e., for any $1 \leq i \leq j \leq 4$,
\begin{align}
|c_{ij} - \hat{c}_{ij}| &\leq 17000 \sqrt{\lambda_{\epsilon} / p_{\epsilon}} := \delta_{\epsilon}\,.
\end{align}
Notice that $\delta_{\epsilon} \leq 17000\epsilon^{16} \leq 1/10$ for small enough $\epsilon$.

\textul{3a. Estimate the $\agop$ of $\hat{f}$.} Since we have shown $\hat{f} \approx f$, the $\agop$ of the estimated function can be well approximated as follows. 
\begin{align*}
\agop(\hat{f}, \cD_{\epsilon}) &=  \E_{(x,y) \sim \cD_{\epsilon}}[\pd{\hat{f}}{x} \pd{\hat{f}}{x}^{\top}] \\
&= (1-p_{\epsilon})\pd{\hat{f}}{x} \pd{\hat{f}}{x}^{\top} \mid_{x = (1,1,0,0)} + p_{\epsilon} \E_{(x,y) \sim \cU}[\pd{\hat{f}}{x} \pd{\hat{f}}{x}^{\top}] \\
\end{align*}
Since $|\hat{c}_{ij}| \leq |c_{ij}| + \delta_{\epsilon} \leq 1+\delta_{\epsilon} \leq 11/10$ for all $i,j$ it must hold that $\|\pd{\hat{f}}{x} \pd{\hat{f}}{x}^{\top}\|_F \leq 100$ for all $x \in \{0,1,2\}^4$, so
\begin{align}\label{ineq:uncorr-agop-1}
\|\agop(\hat{f}, \cD_{\epsilon}) - \pd{\hat{f}}{x} \pd{\hat{f}}{x}^{\top} \mid_{x = (1,1,0,0)}\|_F \leq 100p_{\epsilon}
\end{align}
Finally, $\pd{\hat{f}}{x} \mid_{x = (1,1,0,0)} = 2\hat{c}_{11} e_1 + 2\hat{c}_{22} e_2 + \hat{c}_{12} (e_1 + e_2) +  (\hat{c}_{13} + \hat{c}_{23})e_3 + (\hat{c}_{14} + \hat{c}_{24})e_4$, and $c_{11} = c_{22} = c_{13} = c_{14} = c_{23} = c_{24} = 0$ and $c_{12} = \tau_{\epsilon}$, which means that
\begin{align}\label{ineq:uncorr-agop-2}
\|\pd{\hat{f}}{x} \pd{\hat{f}}{x}^{\top} \mid_{x = (1,1,0,0)} - \tau_{\epsilon}^2 (e_1 + e_2)(e_1+e_2)^{\top}\|_F &\leq 20 \|\pd{\hat{f}}{x} \mid_{x = (1,1,0,0)} - \tau_{\epsilon} (e_1 + e_2)\|_F \leq 1000 \sqrt{\delta_{\epsilon}}\,.
\end{align}
Putting the \eqref{ineq:uncorr-agop-1} and \eqref{ineq:uncorr-agop-2} together with the triangle inequality, we conclude our estimate of the $\agop$
\begin{align}\label{ineq:uncorr-agop-3}
\|\agop(\hat{f}, \cD_{\epsilon}) - \tau_{\epsilon}^2 (e_1 + e_2)(e_1+e_2)^{\top}\|_F \leq 100p_{\epsilon} + 1000\sqrt{\delta_{\epsilon}}\,.
\end{align}

\textul{3a. Estimate powers of the $\agop$ of $\hat{f}$.} 
Next, let $s > 0$ be the power of the $\agop$ that we will take.

Let $\lambda_1 \geq \dots \geq \lambda_4 \geq 0$ be the eigenvalues of $\agop$, with a 
corresponding set of orthonormal eigenvectors $v_1,\ldots,v_4 \in \R^4$. By Weyl's inequality, since $\tau_{\epsilon}^2 \geq 100p_{\epsilon} + 1000\sqrt{\delta_{\epsilon}}$ for small enough $\epsilon$, 
\begin{align*}
\lambda_1 \geq 2\tau_{\epsilon}^2 - (100p_{\epsilon} + 1000\sqrt{\delta_{\epsilon}}) \gtrsim \epsilon^6
\end{align*}
and
\begin{align*}
\lambda_1 \lesssim \epsilon^6
\end{align*}
and
\begin{align*}
0 \leq \lambda_4 \leq \lambda_3 \leq \lambda_2 \leq 100p_{\epsilon} + 1000\sqrt{\delta_{\epsilon}} \lesssim \epsilon^8\,.
\end{align*}
Additionally, let $P_{\perp}$ be the projection to the orthogonal subspace spanned by $\{(e_1 + e_2)\}$. By the Davis-Kahan $\sin(\Theta)$ theorem \cite{davis1970rotation},
\begin{align*}\|P_{\perp} v_1\| \leq \frac{100p_{\epsilon} + 1000\sqrt{\delta_{\epsilon}}}{\tau_{\epsilon}^2} \lesssim \epsilon^2.
\end{align*}

Notice that $\agop = \sum_{i=1}^4 \lambda_i^s v_iv_i^{\top}$, which we will use later.

\textul{4. Estimate the loss-minimizing weights.} Now let us estimate the loss-minimizing weights, $\hat{a}, \hat{W}$. The argument here is split into two parts: we want to (a) show that $ \hat{W}$ is small in the first and second columns, and (b) show that $\hat{W}$ is large in the third or fourth column. These two facts combined will be enough show that $\hat{W}^{\top} \hat{W}$ is close to uncorrelated to the $\agop$.


\textul{4a. Show that $\hat{W}_{1:m,1}$ and $\hat{W}_{1:m,2}$ are small.}
Define weights $a', W'$ by letting $a' = \hat{a}$ and $W' = \begin{bmatrix} 0 & 0 & \hat{W}_{1:m,3} &  \hat{W}_{1:m,4} \end{bmatrix}$. In other words, we have zeroed out the coefficients of the variables $x_1$ and $x_2$ in the first layer. Then define
\begin{align*}
f'(x) &= (a')^{\top} \sigma((W')x)\,.
\end{align*}
If we write $f'(x) = \sum_{1 \leq i \leq j \leq 4} = c'_{ij} x_i x_j$, notice that $c'_{11} = c'_{12} = c'_{13} = c'_{14} = c'_{23} = c'_{24} = 0$ and that $c'_{34} = \hat{c}_{34}$, $c'_{33} = \hat{c}_{33}$, and $c'_{44} = \hat{c}_{44}$. Now, let $a'', W''$ be weights minimizing $\|a''\|^2 + \|W''\|_F^2$ such that 
\begin{align*}
f'(\cdot) \equiv f(\cdot; a'', W'')\,.
\end{align*}
By the construction in Lemma~\ref{lem:min-norm-weights-quad}, we may assume without loss of generality that all but 4 neurons are nonzero: i.e., that $a''_{5} = \dots = a''_{m} = 0$ and $W''_{5,1:4} = \dots W''_{m,1:4} = 0$. Now the difference between the network after the zeroing out and the current network is $\hat{f}(x)-f'(x) = \sum_{1 \leq i \leq j \leq 4} \tilde{c}_{ij} x_i x_j$ where
\begin{align*}
|\tilde{c}_{ij}| = |\hat{c}_{ij} - c'_{ij}| \leq \tau_{\epsilon} + \delta_{\epsilon}\,.
\end{align*}
So by Lemma~\ref{lem:min-norm-weights-quad}, this difference can be represented on four neurons with a cost of at most $100 (\tau_{\epsilon} + \delta_{\epsilon})^{2/3}$. Therefore, by editing the weights $a'',W''$ we can construct weights $a''',W'''$ such that $\hat{f}(\cdot) \equiv f(a''',W''')$ and
\begin{align*}
\|\hat{a}\|^2 + \|\hat{W}\|_F^2 &\leq \|a'''\|^2 + \|W'''\|_F^2 \\
&\leq \|a''\|^2 + \|W''\|_F^2 + 100(\tau_{\epsilon} + \delta_{\epsilon})^{2/3} \\
&= \|\hat{a}\|^2 + \|\hat{W}\|_F^2 - \|\hat{W}_{1:m,1}\|^2 - \|\hat{W}_{1:m,2}\|^2 + 100(\tau_{\epsilon} + \delta_{\epsilon})^{2/3}\,.
\end{align*}
So we can conclude that the norm of the weights in the first and second column is small
\begin{align}\label{ineq:uncorr-min-loss-1}
\|\hat{W}_{1:m,1}\|^2 + \|\hat{W}_{1:m,2}\|^2 \leq 100(\tau_{\epsilon} + \delta_{\epsilon})^{2/3} \lesssim \epsilon^2\,.
\end{align}

\textul{4b. Show that at least one of $\hat{W}_{1:m,3}$ or $\hat{W}_{1:m,4}$ is large.} Finally, let us show that either the third or fourth column of the weights is large.
\begin{align*}0.9 &\leq c_{34} - \delta_{\epsilon} \leq \hat{c}_{34} \leq \sum_{i=1}^m \hat{a}_i \hat{W}_{i,3} \hat{W}_{i,4} \\
&\leq \|\hat{a}\| \sqrt{\sum_{i=1}^m (\hat{W}_{i,3} \hat{W}_{i,4})^2} \\
&\leq \|\hat{a}\| \sqrt{\sum_{i=1}^m (\hat{W}_{i,3})^2} \sqrt{\sum_{i=1}^m \hat{W}_{i,4})^2} \\
&= \|\hat{a}\| \|\hat{W}_{1:m,3}\|\|\hat{W}_{1:m,4}\|\,.
\end{align*}
From the construction of the weights $\bar{a},\bar{W}$ in the first step of this proof, we know that $\|\hat{a}\|^2 \leq \|\bar{a}\|^2 + \|\bar{W}\|^2 \leq 13$. So $\|\hat{a}\| \leq 4$. We conclude that 
\begin{align}\label{ineq:uncorr-min-loss-2}\max(\|\hat{W}_{1:m,3}\|, \|\hat{W}_{1:m,4}\|) \geq 1/3.
\end{align}



\textul{5. Compare $\agop$ to loss-minimizing weights.} Finally, let us compare the NFA approximation \eqref{ineq:uncorr-agop-3} to the facts proved in \eqref{ineq:uncorr-min-loss-1} and \eqref{ineq:uncorr-min-loss-2} about the loss-minimizing weights. 
From \eqref{ineq:uncorr-agop-3} and \eqref{ineq:uncorr-min-loss-1} and $\|\hat{W}\|_F^2 \leq 13$ and the calculations in step 3b, we conclude that
\begin{align*}
\<(\agop(\hat{f}, \cD_{\epsilon}))^s, \hat{W}^{\top} \hat{W}\> &= \sum_{i=1}^4 \lambda_i^s \<v_iv_i^{\top}, \hat{W}^{\top} \hat{W}\> \\
&\lesssim (\|\hat{W}_{1:m,1}\|^2 + \|\hat{W}_{1:m,2}\|^2)(\lambda_1^s) + \lambda_1^s \|P_{\perp} v_1\|^2 
+ \lambda_2^s + \lambda_3^s + \lambda_4^s \\
&\lesssim \epsilon^2 \epsilon^{6s} + \epsilon^{8s}\,.
\end{align*}

From \eqref{ineq:uncorr-agop-3} and step 3b we conclude that
\begin{align*}
\|(\agop(\hat{f}, \cD_{\epsilon}))^s\|_F \gtrsim (2\tau_{\epsilon}^2 - 100p_{\epsilon} - 1000 \sqrt{\delta_{\epsilon}})^s \geq \tau_{\epsilon}^{2s} \gtrsim \epsilon^{6s}\,.
\end{align*}
From \eqref{ineq:uncorr-min-loss-2}, we conclude that
\begin{align*}
\|\hat{W}^{\top} \hat{W}\| \geq 1/9 \gtrsim 1\,.
\end{align*}


which implies that
\begin{align*}
\mathrm{corr}(\agop(\hat{f}, \cD_{\epsilon}), \hat{W}^{\top} \hat{W}) \lesssim (\epsilon^2 \epsilon^{6s} + \epsilon^{8s}) / \epsilon^{6s} \lesssim \epsilon^{2s} + \epsilon^2,
\end{align*}
which can be taken arbitrarily small by sending $\epsilon$ to 0.
\end{proof}

The Lemma that we used in the proof of this theorem is below.

\begin{lemma}[The minimum-norm weight solution for a network with quadratic activation]\label{lem:min-norm-weights-quad}
Let $f(x;a,W) = a^{\top} \sigma(Wx)$ be a neural network with quadratic activation function $\sigma(t) = t^2$ and weights $W \in \R^{m \times d}, a \in \R^m$ for $m \geq d$. Then, for any homogeneous quadratic function $f(x) = x^{\top} Q x$ , where $Q = Q^{\top}$, the minimum-norm neural network that represents $f$ has cost:
\begin{align*}
2\sum_{i=1}^d \sigma_i(Q)^{2/3} = \min_{a,W} \{\|a\|^2 + \|W\|_F^2 : f(\cdot;a,W) \equiv f(\cdot)\}\,,
\end{align*}
and this can be achieved with a network that has at most $d$ nonzero neurons.
\end{lemma}
\begin{proof}
We can expand the definition of the quadratic network
\begin{align*}
f(x;a,W) &= a^{\top} \sigma(Wx) = \sum_{i=1}^m x^{\top} a_i w_i w_i^{\top} x\,.
\end{align*}
For any $a,W$ such that $f(\cdot;a,W) \equiv f(\cdot)$, we must have $Q = \sum_{i=1}^m a_i w_i w_i^{\top}$. By (a) inequality (2.1) in \cite{thompson1976convex} on concave functions of the singular values of sums of matrices (originally proved in \cite{rotfel1969singular}), we must have
\begin{align*}
\|a\|^2 + \|W\|_F^2 &= \sum_{i=1}^m a_i^2 + \|w_i\|^2 \\
&\geq 2\sum_{i=1}^m \sigma_1(a_i  w_i w_i^{\top})^{2/3} \\
&= 2\sum_{i=1}^m \sum_{j=1}^m \sigma_j(a_i w_i w_i^{\top})^{2/3} \\
&\stackrel{(a)}{\geq} 2\sum_{j=1}^d \sigma_j(Q)^{2/3}\,.
\end{align*}
And notice that given an eigendecomposition $(\lambda_1,v_1),\ldots,(\lambda_d,v_d)$ of $Q$, this can be achieved by letting $a_i = \sgn(\lambda_i)|\lambda_i|^{1/3}$, and $w_i = |\lambda_i|^{1/3} v_i$ for all $1 \leq i \leq d$ and $a_i = 0$ and $w_i = 0$ for all $d+1 \leq i \leq m$.

\end{proof}











































\section{Derivation and justification of FACT-RFM update}\label{app:fact-rfm-update}

The simplest fixed-point iteration scheme would be to apply
\begin{align}
W_{t+1}  \gets \sqrt{\fact_t}\,, \label{eq:malformed-rfm-update}
\end{align}
aiming for the fixed point
\begin{align*}
W_{t+1}^{\top} W^{\top}_{t+1} = \fact_t\,.
\end{align*}
However, this scheme cannot be directly implemented because \eqref{eq:malformed-rfm-update} is not necessarily well-defined. In particular, $\fact$ is not necessary p.s.d. when the network is not at a critical point of the loss, so the square root of $\fact$ in \eqref{eq:malformed-rfm-update} is not well defined.

In order to fix it, the most natural solution is to symmetrize $\fact$ and instead run the scheme
\begin{align*}
W_{t+1} \gets (\fact_t \fact_t^{\top})^{1/4}\,,
\end{align*}
since indeed when $\fact_t = W_{t}^{\top} W_t$ we are at a fixed point with this update.

We experimented with this update, and found good performance with tabular data (this is ``no geometric averaging'' method reported in Table~\ref{tab:uci_tabular_benchmark}) and parity data, but for the modular arithmetic problem FACT-RFM with this update was unstable and the method often did not converge -- especially in data regimes with low signal.

In order to obtain a more stable update, we chose to geometrically average with the previous iterate, as follows:
\begin{align*}
W_{t+1} \gets (\fact_t (W_t^{\top} W_t) (W_t^{\top} W_t) (\fact_t)^{\top})^{1/8}\,,
\end{align*}
which again has a fixed point when $\fact_t = W_{t}^{\top} W_t$. This yielded improved performance with modular arithmetic while retaining performance with tabular data and parities. Additionally, as we discuss in Section~\ref{sec:nfa-explanation}, we then discovered that this update has an interpretation as being a close relative of the NFA-RFM update when applied to inner product kernel machines.

\section{Proofs for Section~\ref{sec:nfa-explanation}}\label{app:fact-kernel-derivation}

We first observe that the updates in FACT-RFM can be written in a convenient form in terms of the dual solution $\alpha$ and the derivatives of the estimator. This lemma does not depend on the kernel being an inner-product kernel.
\begin{lemma}[Simplified form of FACT for kernel machines]\label{lem:lgop-rewriting}
Let $(X,y)$ be training data fit by a kernel machine with the MSE loss, and let $\alpha$ be first-order optimal coefficients for kernel regression with $\lambda$-ridge regularization. Then the $\fact$ can be equivalently computed as
\begin{align*}
\fact = \sum_{i,j=1}^n (\pd{}{x} K_W(x,x_j)\mid_{x=x_i}) \alpha_j^{\top} \alpha_i x_i^{\top}\,.
\end{align*}
\end{lemma}
The proof is by using known first-order optimality conditions for $\alpha$.

Let us prove the convenient expression in Lemma~\ref{lem:lgop-rewriting} for the $\fact$ matrix for kernel machines, which can be used to simplify the implementation of FACT-based RFM.
\begin{proof}
We compute the $\fact$ for the estimator $\hat{f}(x) = \sum_{j=1}^n K_W(x,x_j)\alpha_j$. Substituting the definition of $\fact$ and applying the chain rule, this is
\begin{align*}
\fact &:= -\frac{1}{n \lambda} \sum_{i=1}^n (\pd{}{x} \ell(\hat{f}(x), y_i))\mid_{x=x_i} x_i^{\top} = -\frac{1}{n \lambda} \sum_{i=1}^n (\pd{}{x} \hat{f}(x)\mid_{x=x_i})\ell'(\hat{f}(x_i), y_i)) x_i^{\top} \\
&= -\frac{1}{n \lambda} \sum_{i,j=1}^n (\pd{}{x} K_W(x,x_j)\mid_{x=x_i})\alpha_j^{\top} \ell'(\hat{f}(x_i), y_i) x_i^{\top}\,,
\end{align*}
where $\ell' \in \R^c$ denotes the derivative in the first entry. The proof concludes by noting that $\alpha_i = -\frac{1}{n\lambda} \ell'(\hat{f}(x_i),y_i)$ because of the first-order optimality conditions for $\alpha$, proved below in Lemma~\ref{lem:helper-alpha-appendix}.
\end{proof}


\begin{lemma}[Alternative expression for representer coefficients for kernel regression]\label{lem:helper-alpha-appendix}
Let $(X,Y)$ be training data, and let $\alpha = (K(X,X) + \lambda I)^{-1} Y$ for some $\lambda > 0$. Also let $\ell(\hat{y},y) = \frac{1}{2} \|\hat{y} - y\|^2$. Then
\begin{align*}
\alpha_i = -\frac{1}{n\lambda} \ell'(\hat{y}_i,y_i),
\end{align*}
where $\hat{y}_i = K(x_i,x) \alpha$, and the derivative $\ell'$ is in the first coordinate.
\end{lemma}
\begin{proof}
Notice that $\ell'(\hat{y}_i,y_i) = \hat{y}_i - y_i$. So
\begin{align*}
\ell'(\hat{y}_i,y_i) &= [K \alpha]_{i,*} - y_i \\
&= K(K+n\lambda I)^{-1} y_i - y_i \\
&= -n\lambda (K+\lambda I)^{-1} y_i \\
&= -n\lambda \alpha_i\,.
\end{align*}
\end{proof}

\begin{remark}
A statement of this form relating the representer coefficients to the loss derivatives at optimality is more generally true beyond the MSE loss, but we do not need it here.
\end{remark}


Finally, we can prove Proposition~\ref{prop:simplified-agop-lgop}.
\begin{proposition}[Restatement of Proposition~\ref{prop:simplified-agop-lgop}]
Suppose the kernel is an inner-product kernel of the form $K_W(x,x') = k(x^{\top} M x')$, where $M = W^{\top} W$. Then, we may write the $\agop$ and the $\fact$ matrices explicitly as:
\begin{align*}%
\agop &= \sum_{i,j=1}^n \tau(x_i,x_j,M) M x_i \alpha_i^{\top} \alpha_j x_j^{\top} M^{\top}\,, \\
\fact \cdot M^{\top} &= \sum_{i,j=1}^n k'(x_i^{\top} M x_j) M x_i \alpha_i^{\top} \alpha_j x_j^{\top} M^{\top}\,, 
\end{align*}
where $\tau(x_i,M,x_j) := \frac{1}{n} \sum_{l=1}^n k'(x_l^{\top} M x_i) k'(x_l^{\top} M x_j)$.
\end{proposition}
\begin{proof}
The expressions can be derived by plugging in the expansion $\hat{f}(x) = \sum_{j=1}^n K(x,x_i)\alpha_i$.

For $\agop$, we start from its expression in Ansatz~\eqref{eq:nfa}, and obtain
\begin{align*}
\agop &= \sum_{i=1}^n (\nabla_x\sum_{j=1}^n K_W(x,x_j) \alpha_j)(\nabla_x \sum_{l=1}^n K_W(x,x_l) \alpha_l)^{\top} \\
&= \sum_{i,j,l=1}^n k'(x_j^{\top} M x_i) k'(x_l^{\top} x_i) (Mx_j \alpha_j^{\top})(M x_l \alpha_l^{\top})^{\top} \\
&= \sum_{i,j=1}^n \tau(x_i,M,x_j) Mx_i \alpha_i^{\top} \alpha_j x_j^{\top}M^{\top}.
\end{align*}

For $\fact$, we start from the expression in Lemma~\ref{lem:lgop-rewriting}:
\begin{align*}
\fact \cdot M^{\top} &= \sum_{i,j=1}^n (\pd{}{x} K_W(x,x_j) \mid_{x = x_i})\alpha_j^{\top} \alpha_i x_i^{\top} M^{\top} \\
&= \sum_{i,j=1}^n k'(x_i^{\top} M x_j) Mx_j\alpha_j^{\top} \alpha_i x_i^{\top} M^{\top}\,.
\end{align*}
\end{proof}

