%   \centering
%       \includegraphics[width=\linewidth]{images/mappingfunction.png}
%       \caption{Plot of the Error Mapping function. The position of$t$ and $t+h$ can be set manually to achieve a suitable behavior of the assistance strategy\vspace{0.5cm}}
%       \label{fig:mappingfunctiion}
% \end{Fig.}

