\section{Appendix}
To derive the formulae (\ref{eact}),(\ref{hact}),(\ref{h2act}),(\ref{fact})  it is useful to exploit a correspondence  between the algebraic action and differential operators. Making the identification   
$|{\mathcal N},m,n\}\mapsto x^m$, it is seen that  
  \begin{align*}
	e_1&\mapsto 2n x -x^2 \frac{\rm d}{{\rm d}x}, \\
	h_1&\mapsto   2x \frac{\rm d}{{\rm d}x} -2n,  \\
	f_1&\mapsto \frac{\rm d}{{\rm d}x}
	\end{align*}
is a Lie algebra isomorphism. It follows that
\begin{align*}
e_1|\Psi(u_1,\dots,u_{2n};{\mathcal N})\rangle &= 2n e_1 |\Psi(u_1,\dots,u_{2n};{\mathcal N})\rangle  -\sum_{k=1}^{2n} e^2_1|\Psi_k(u_1,\dots,u_{2n};{\mathcal N})\rangle,    \\
&=-\sum_{k=1}^{2n} u_k e_1|\Psi_k(u_1,\dots,u_{2n};{\mathcal N})\rangle  \\
&=-\sum_{k=1}^{2n} u_k |\Psi(u_1,\dots,u_{2n};{\mathcal N})\rangle  
-\sum_{k=1}^{2n} u^2_k |\Psi_k(u_1,\dots,u_{2n};{\mathcal N})\rangle, 
\end{align*}
which is Eq. (\ref{eact}). Similarly, 
\begin{align*}
h_1|\Psi(u_1,\dots,u_{2n};{\mathcal N})\rangle&=2\sum_{k=1}^{2n} e_1 |\Psi_k(u_1,\dots,u_{2n};{\mathcal N})\rangle 
-2n  |\Psi(u_1,\dots,u_{2n};{\mathcal N})\rangle  \\  
&=2\sum_{k=1}^{2n} u_k |\Psi_k(u_1,\dots,u_{2n};{\mathcal N})\rangle 
+2n  |\Psi(u_1,\dots,u_{2n};{\mathcal N})\rangle,   
\end{align*}
providing (\ref{hact}), 
while (\ref{fact}) follows directly.

The derivation of (\ref{h2act}) is more involved. Defining 
%
\begin{align*}
|\Psi_{kl}(u_1,\dots,u_{2n};{\mathcal N})\rangle&=\prod_{j\neq k,l}^{2n}(e_1-u_jI) |{\mathcal N}, 0, n\}  ,   
& k&\neq l
\end{align*}
and using 
\begin{align*}
h_1^2&\mapsto 4x^2 \frac{{\rm d}^2}{{\rm d}x^2} -4x(2n-1) \frac{\rm d}{{\rm d}x}   +4n^2 , \\
\end{align*}
results in 
 \begin{align*}  
h^2_1 |\Psi(u_1,&\dots,u_{2n};{\mathcal N})\rangle \\
&=4\sum_{k=1}^{2n} \sum_{l\neq k}^{2n} e^2_1 |\Psi_{kl}(u_1,\dots,u_{2n};{\mathcal N})\rangle 
-4(2n-1)\sum_{k=1}^{2n} e_1 |\Psi_k(u_1,\dots,u_{2n};{\mathcal N})\rangle  \\
& \qquad +4n^2  |\Psi(u_1,\dots,u_{2n};{\mathcal N})\rangle  \\     
&=4\sum_{k=1}^{2n} \sum_{l\neq k}^{2n} e^2_1 |\Psi_{kl}(u_1,\dots,u_{2n};{\mathcal N})\rangle 
- 4\sum_{k=1}^{2n} \sum_{l\neq k}^{2n} e_1(e_1-u_l) |\Psi_{kl}(u_1,\dots,u_{2n};{\mathcal N})\rangle  \\
&\qquad  +4n^2  |\Psi(u_1,\dots,u_{2n};{\mathcal N})\rangle  \\     
&=4\sum_{k=1}^{2n} \sum_{l\neq k}^{2n} u_l e_1 |\Psi_{kl}(u_1,\dots,u_{2n};{\mathcal N})\rangle 
  +4n^2  |\Psi(u_1,\dots,u_{2n};{\mathcal N})\rangle  .     
\end{align*}
Elimination of the $|\Psi_{kl}(u_1,\dots,u_{2n};{\mathcal N})\rangle$ terms is achieved through
 \begin{align*}
\sum_{k=1}^{2n} \sum_{l\neq k}^{2n} & u_l e_1 |\Psi_{kl}(u_1,\dots,u_{2n};{\mathcal N})\rangle \\
&=\sum_{k=1}^{2n} \sum_{l\neq k}^{2n} (u_k+u_l) e_1 |\Psi_{kl}(u_1,\dots,u_{2n};{\mathcal N})\rangle 
%\\&\qquad 
-\sum_{k=1}^{2n} \sum_{l\neq k}^{2n} u_k u_l |\Psi_{kl}(u_1,\dots,u_{2n};{\mathcal N})\rangle \\
&\qquad -\sum_{k=1}^{2n} \sum_{l\neq k}^{2n} u_k(e_1-u_l)  |\Psi_{kl}(u_1,\dots,u_{2n};{\mathcal N})\rangle \\ 
&=\sum_{k=1}^{2n} \sum_{l\neq k}^{2n}  \frac{u^2_k-u^2_l}{u_k-u_l} e_1|\Psi_{kl}(u_1,\dots,u_{2n};{\mathcal N})\rangle 
%\\&\qquad 
-\sum_{k=1}^{2n} \sum_{l\neq k}^{2n} \frac{u^2_k u_l- u_ku_l^2}{u_k-u_l} |\Psi_{kl}(u_1,\dots,u_{2n};{\mathcal N})\rangle \\
&\qquad -(2n-1)\sum_{k=1}^{2n} u_k  |\Psi_{k}(u_1,\dots,u_{2n};{\mathcal N})\rangle \\ 
&=\sum_{k=1}^{2n} \sum_{l\neq k}^{2n}    \frac{u^2_k}{u_k-u_l} |\Psi_{k}(u_1,\dots,u_{2n};{\mathcal N})\rangle 
%\\&\qquad 
-\sum_{l=1}^{2n} \sum_{k\neq l}^{2n}   \frac{u_l^2}{u_k-u_l} |\Psi_{l}(u_1,\dots,u_{2n};{\mathcal N})\rangle \\
&\qquad -(2n-1)\sum_{k=1}^{2n} u_k  |\Psi_{k}(u_1,\dots,u_{2n};{\mathcal N})\rangle \\ 
&=2\sum_{k=1}^{2n} \sum_{l\neq k}^{2n}    \frac{u^2_k}{u_k-u_l} |\Psi_{k}(u_1,\dots,u_{2n};{\mathcal N})\rangle 
%\\&\qquad 
-(2n-1)\sum_{k=1}^{2n} u_k  |\Psi_{k}(u_1,\dots,u_{2n};{\mathcal N})\rangle , 
\end{align*}
leading to (\ref{h2act}).


