\title{Satellite and Mobile Phone Data Reveal How Violence Affects Seasonal Migration in Afghanistan}




\author[1]{Xiao Hui Tai}
\author[2]{Suraj R. Nair}
\author[2]{Shikhar Mehra}
\author[2,*]{Joshua E. Blumenstock}

\affil[1]{Department of Statistics, University of California, Davis, CA 95616}
