The next three lemmas and propositions are crucial to construct the conformal factor we will use in the main theorem. For the standard $ dt^{2} $-metric on $ \mathbb{S}^{1}_{t} $, we fix some chart $ U \ni P $ with chart map $ \Phi : \mathbb{S}^{1} \supset U \rightarrow (-1, 1) $ such that $ \Phi(P) = 0 $ and still with locally $ t $-variable. We start with the construction of the inhomogeneous term of our partial differential equation.
\begin{lemma}\label{Set:lemma2} 
For any  $ p \in \mathbb{N} $,  $ C \gg 1 $, and any positive $ \delta \ll 1 $.  
Then there exists a positive smooth function $F:W\to\R$ and small enough constant $ \epsilon \ll 1 $ such that $ F |_{X \times (-\frac{\epsilon}{2}, \frac{\epsilon}{2})_{t}} = C+1  $, $ F \equiv 0 $ outside $ X \times [-\epsilon, \epsilon]_{t} $ and $ \lVert  F \rVert_{\calL^{p}(W, \sigma^{*}\bar{g})} < \delta. $
\end{lemma}
\begin{proof}
Fix any $ p, C $ and $ \delta $. We take a constant function $ f = C + 1 : W \rightarrow \R $. There exists a nonnegative smooth function $  \phi :\mathbb{S}^{1}_{t} \rightarrow R $ such that 
\begin{equation*}
  \phi(t) \equiv 1, t \in \left(-\frac{\epsilon}{2}, \frac{\epsilon}{2}\right), \phi(t) = 0, t \notin [-\epsilon, \epsilon].
\end{equation*}
Set $ F = f \cdot \phi : W \rightarrow \R $. It follows that
\begin{equation*}
    \lVert F \rVert_{\calL^{p}(W, \sigma^{*}\bar{g})} < \delta
\end{equation*}
provided that $ \epsilon \ll 1 $ is small enough.
\end{proof}
\begin{remark}\label{Set:re0}
The function $ F $ in any local frame $ \lbrace \partial_{1}, \dotso, \partial_{n - 1}, \partial_{n + 1} = \partial_{t} \rbrace $ of $ W $ satisfies
\begin{equation*}
\partial_{i} F \equiv 0, \forall i \in \lbrace 1, \dotso, n - 1 \rbrace
\end{equation*}
based on the construction of $ F $ in Lemma \ref{Set:lemma2}.
\end{remark}
We now construct the first candidate of our conformal factor with small enough $ \calC^{1, \alpha} $-norm. We define the $\calC^{1, \alpha} $-norm on $ W $ by fixing a chart cover $ W = \bigcup_{i} (U_{i}, \varphi_{i}) $ such that
\begin{equation*}
    \lVert u \rVert_{\calC^{1, \alpha}(W)} = \lVert u \rVert_{\calC^{0}(W)} + \sup_{i, k} \lVert \partial_{x_{i}^{k}}u \rVert_{\calC^{0}(U_{i})} + \sup_{i, k} \sup_{x \neq x', x, x' \in U_{i}} \frac{\left\lvert \partial_{x_{i}^{k}}u(x) - \partial_{x_{i}^{k}}u(x') \right\rvert}{\lvert x - x' \rvert^{\alpha}}
\end{equation*}
where $ \partial_{x_{i}^{k}} u $ are local representations in $ U_{i} $ with local coordinates $ \lbrace x_{i}^{1}, \dotso, x_{i}^{n - 1}, x_{i}^{n + 1} = t \rbrace $ and associated local frames $ \lbrace \partial_{x_{i}^{k}} \rbrace $. 
\begin{proposition}\label{Set:prop1}
Let $ (W, \sigma^{*} \bar{g}) $ be as above %and let $ W' = X \times [-\frac{1}{2}, \frac{1}{2}]_{t} \subset W $
. Assume that (\ref{Set:eqn0}) holds. For any positive constant $ \eta \ll 1 $, any positive constant $ C $, and any $ p > n = \dim W $, there exists an associated $ F $ and $ \delta $ in the sense of Lemma \ref{Set:lemma2}, such that the following partial differential equation     
\begin{equation}\label{Set:eqn3}
L u : = 4\nabla_{V} \nabla_{V} u - 4\Delta_{\sigma^{*} \bar{g}}  u + R_{\bar{g}} |_{W}u =
F  \; {\rm in} \; W
\end{equation}
admits a unique smooth solution $ u $ with
\begin{equation}\label{Set:eqn4}
\lVert u \rVert_{\calC^{1, \alpha}(W)} < \eta
\end{equation}
for some $ \alpha \in (0, 1) $ such that $ \alpha \geqslant 1 - \frac{n}{p} $.
\end{proposition}
\begin{proof}
Note that $ W $ is a closed, oriented Riemannian manifold. Fix $ \eta \ll 1, C $, and $ p > n $. We then fix some $ \alpha > 0 $ such that $ 1 + \alpha \geqslant 2 - \frac{n}{p} $. Denote $ C = C(W, g, n, p, L) $ by the constant of $ \calL^{p} $ elliptic regularity estimates with respect to $ L $, and $ C' = C'(W, g, n, p, \alpha) $ by the constant of the Sobolev embedding $ W^{2, p} \hookrightarrow \calC^{1, \alpha} $. Fix $ \delta $ such that $ \delta C C' < \eta $. Finally we  choose an associated $ F $ in the sense of Lemma \ref{Set:lemma2}.


By assumption, $ R_{g} > 0 $ on $ M $, therefore $ R_{\bar{g}} > 0 $ on $ M \times \mathbb{S}^{1}_{t} $, hence $ R_{\bar{g}} |_{W} > 0 $ uniformly. By Lemma \ref{Set:lemma1}, the operator in (\ref{Set:eqn3}) is elliptic. By maximum principle on closed manifolds, the elliptic operator is an injective operator. It follows that there exists a unique solution $ u \in H^{1}(W, \sigma^{*}\bar{g}) $ of (\ref{Set:eqn3}) by Fredholm alternative. By standard $ H^{s} $-type elliptic theory and the smoothness of $ F $, $ u \in \calC^{\infty}(W) $. 

By standard $ \calL^{p} $-regularity theory \cite{Niren4}, 
\begin{equation*}
    \lVert u \rVert_{W^{2, p}(W, \sigma^{*} \bar{g})} \leqslant C \left( \lVert F \rVert_{\calL^{p}(W, \sigma^{*} \bar{g})} + \lVert u \rVert_{\calL^{p}(W, \sigma^{*}\bar{g})} \right).
\end{equation*}
Due to the injectivity of the operator, a very similar argument of \cite[Proposition 2.1]{RX2} shows that the $ \calL^{p}$ estimates can be improved by
\begin{equation*}
     \lVert u \rVert_{W^{2, p}(W, \sigma^{*} \bar{g})} \leqslant C \lVert F \rVert_{\calL^{p}(W, \sigma^{*} \bar{g})}.
\end{equation*}
By Sobolev embedding, it follows that
\begin{equation*}
    \lVert u \rVert_{\calC^{1, \alpha}(W)} \leqslant C' \lVert u \rVert_{W^{2, p}(W, \sigma^{*}\bar{g})} \leqslant CC'\lVert F \rVert_{\calL^{p}(W, \sigma^{*} \bar{g})} < CC' \delta < \eta. 
\end{equation*}
%We claim that the constants $ C, C' $ only depends on $ W $ when we estimate the quantities in (\ref{Set:eqn4}). Set $ [-\epsilon, \epsilon] \ni s = \epsilon s' $, we have
%\begin{align*}
   % \lVert u(\cdot, s) \rVert_{\calC^{0}(W')} & = \lVert u(\cdot, \epsilon s') \rVert_{\calC^{0}(W)} \leqslant C(W)C'(W) \lVert F(\cdot, \epsilon s') \rVert_{\calL^{p}(W, \sigma^{*}g)} = C(W)C'(W) \delta < \eta, \\
    %\lVert \partial_{x^{i}} u(\cdot, s) \rVert_{\calC^{0}(U_{i} \cap W')} & = \lVert \partial_{x^{i}} u(\cdot, \epsilon s') \rVert_{\calC^{0}(U_{i} \cap W)} \leqslant C(W)C'(W) \lVert F(\cdot, \epsilon s') \rVert_{\calL^{p}(W, \sigma^{*}g)} \\
    %& = C(W)C'(W) \delta < \eta, \forall i \neq n.
%\end{align*}
\end{proof}
\begin{remark}\label{Set:re1}
By maximum principle and the nonnegativity of $ F $, the solution of (\ref{Set:eqn3}) satisfies $ u \geqslant 0, u \not\equiv 0 $ in $ W $.
\end{remark}
We now give our candidate of the conformal factor on $ M \times \mathbb{S}^{1}_{t} $. To begin with, %we extend the solution of (\ref{Set:eqn3}) to $ W $ smoothly, still denoted by $ u $. We can construct such an extension such that
%\begin{equation}\label{Set:eqn4a}
%\lVert u \rVert_{\calC^{0}(W)} 
%< 2\eta.
%\end{equation}
we define a new function
\begin{equation*}
    u_{0} : = u + 1, u_{0} : W \rightarrow \R
\end{equation*}
where $ u $ is the solution of (\ref{Set:eqn3}). With the natural projection $ \pi : M \times \mathbb{S}^{1}_{t} \rightarrow W $, we can pullback $ u_{0} $ to $ M \times \mathbb{S}_{t}^{1} $ by $ u' : = (\pi)^{*} u_{0} $. We also pullback $ u $ to $ M \times \mathbb{S}_{t}^{1} $ by $ \bar{u} : = (\pi)^{*} u $ for later use. We have
\begin{equation}\label{Set:eqn6}
u' |_{W} =u_{0} = u + 1, \partial_{\xi}^{l} u' = 0 \; {\rm on} \; M \times \mathbb{S}^{1}_{t}, \forall l \in \mathbb{Z}_{> 0}.
\end{equation}
Denote $ \tilde{u}' : = \tau_{1}^{*} u' : M \rightarrow \R $. Following our diagram (\ref{intro:eqn2}), we have
\begin{equation*}
    \imath^{*} \tilde{u}' = \imath^{*} \tau_{1}^{*} u' = \tau_{2}^{*} \sigma^{*} u' = \tau_{2}^{*} u_{0} = u_{0} |_{X \times \lbrace 0 \rbrace_{\xi} \times \lbrace P \rbrace_{t}}.
\end{equation*}
Clearly all those functions defined above are positive functions on corresponding spaces. The function $ (u')^{\frac{4}{n - 2}} $ will be our choice of conformal factor on $ M \times \mathbb{S}_{t}^{1} $. The relations above hold analogously for $ \bar{u} $ also.
\medskip

Usually, the best estimate of the solution of (\ref{Set:eqn3}) is given by (\ref{Set:eqn4}). Due to the speciality of the product metric $ \bar{g} $ and the construction of $ F $, we are able to give a partial $ \calC^{2} $-estimate in terms of $ \left\lVert \frac{\partial^{2} u}{\partial t^{2}} \right\rVert_{\calC^{0}(X \times \lbrace 0 \rbrace_{\xi} \times \lbrace P \rbrace_{t})} $, as the next lemma shows.
\begin{lemma}\label{Set:lemma3}
Choosing $ \epsilon $ defined in Lemma \ref{Set:lemma2} to be small enough that will be determined below. Let $ (W, \sigma^{*} \bar{g}) $, $ p, C, \delta $ and $ F $ be the same as in Proposition \ref{Set:prop1}. Let $ u $ be the associated solution of (\ref{Set:eqn3}). There exists a constant $ \eta' \ll 1 $ such that
\begin{equation}\label{Set:eqn5}
    \left\lVert \frac{\partial^{2} u}{\partial t^{2}} \right\rVert_{\calC^{0}\left(X \times \lbrace 0 \rbrace_{\xi} \times \left(-\frac{\epsilon}{4}, \frac{\epsilon}{4} \right)_{t} \right)} < \eta'.
\end{equation}
\end{lemma}
\begin{proof}
Set $ U_{1} = X \times \lbrace 0 \rbrace_{\xi} \times \left(-\frac{\epsilon}{4}, \frac{\epsilon}{4} \right) $, $ U_{2} =  X \times \lbrace 0 \rbrace_{\xi} \times \left(-\frac{\epsilon}{2}, \frac{\epsilon}{2} \right) $, $ O_{1} =  X \times \lbrace 0 \rbrace_{\xi} \times \left(-\frac{1}{4}, \frac{1}{4} \right) $, $ O_{2} =  X \times \lbrace 0 \rbrace_{\xi} \times \left(-\frac{1}{2}, \frac{1}{2} \right) $. Since $ \bar{g} = g \oplus dt^{2} $, the vector field $ V $ and $ \Delta_{\sigma^{*} \bar{g}} $ are constant with respect to $ t $; furthermore the scalar curvature $ R_{\bar{g}} $ is constant along $ t $-direction. In addition, $ F \equiv C + 1 $ on $ U_{2} $ by Lemma \ref{Set:lemma2}, we apply $ \frac{\partial^{2}}{\partial t^{2}} $ on both sides of (\ref{Set:eqn3}) in $ U $, which follows that
\begin{equation*}
  L_{\sigma^{*} \bar{g}} \left( \frac{\partial^{2}u}{\partial t^{2}} \right) : =  4\nabla_{V} \nabla_{V} \left( \frac{\partial^{2}u}{\partial t^{2}} \right) - 4\Delta_{\sigma^{*} \bar{g}}  \left( \frac{\partial^{2}u}{\partial t^{2}} \right) + R_{\bar{g}} |_{W}\left( \frac{\partial^{2}u}{\partial t^{2}} \right) = 0  \; {\rm in} \; U_{1}.
\end{equation*}
Now consider $ t = \epsilon t' $, the new $ t' $-variable is associated with the metric $ (dt')^{2} = \epsilon^{-2} dt^{2} $ on $ \mathbb{S}^{1} $. We have
\begin{equation*}
   (\epsilon^{-1})^{2} \left( 4\nabla_{V} \nabla_{V} \left( \frac{\partial^{2}u}{\partial (t')^{2}} \right) - 4\Delta_{\sigma^{*} \bar{g}}  \left( \frac{\partial^{2}u}{\partial (t')^{2}} \right) + R_{\bar{g}} |_{W}\left( \frac{\partial^{2}u}{\partial (t')^{2}} \right) \right)= 0  \; {\rm in} \; O_{1}.
\end{equation*}
Equivalently, the following PDE holds in $ O_{1} $ with the new metric $ \bar{g} \mapsto \epsilon^{-2} \bar{g} $,
\begin{equation}\label{Set:eqn6a}
L_{\sigma^{*}(\epsilon^{-2}\bar{g})}\left( \frac{\partial^{2}u}{\partial (t')^{2}} \right) : = 4\nabla_{V_{\epsilon^{-2}\bar{g}}} \nabla_{V_{\epsilon^{-2}\bar{g}}} \left( \frac{\partial^{2}u}{\partial (t')^{2}} \right) - 4\Delta_{\sigma^{*} (\epsilon^{-2}\bar{g})}  \left( \frac{\partial^{2}u}{\partial (t')^{2}} \right) + R_{\epsilon^{-2}\bar{g}} |_{W}\left( \frac{\partial^{2}u}{\partial (t')^{2}} \right) = 0  \; {\rm in} \; O_{1}.
\end{equation}
Here $ V_{\epsilon^{-2}\bar{g}} $ is the vector field with respect to the new metric $ \epsilon^{-2} \bar{g} $ satisfying $ V_{\epsilon^{-2}\bar{g}} = \epsilon^{-1} V $. 


We now estimate $ \lVert \frac{\partial^{2}u}{\partial (t')^{2}} \rVert_{\calC^{0}(O_{1})} $. We set $ s > 0 $ such that $ s - \frac{n}{2} = 1 + \alpha \geqslant 2 - \frac{n}{p} $, where $ p $ and $ \alpha $ are given in Proposition \ref{Set:prop1}. With usual metric $ \sigma^{*} \bar{g} $, we have $ H^{s}$-type local elliptic regularity estimates for second order elliptic operator $ L_{\sigma^{*}\bar{g}} $,
\begin{equation*}
\lVert v \rVert_{H^{s}(U, \sigma^{*} \bar{g})} \leqslant D_{s} \left( \lVert L_{\sigma^{*} \bar{g}} u \rVert_{H^{s - 2}(V, \sigma^{*} \bar{g})} + \lVert v \rVert_{\calL^{2}(V, \sigma^{*} \bar{g})} \right), \forall v \in \calC^{\infty}(V).
\end{equation*}
where the constant $ D_{s} $ only depends on the operator $ L_{\sigma^{*}\bar{g}} $, the metric, the degree $ s $ and the domain $ U, V $. For the scaled metric $ \sigma^{*} (\epsilon^{-2} \bar{g}) $, we apply the local estimates and the second order elliptic operator $ L_{\sigma^{*}(\epsilon^{-2}\bar{g})} $ in (\ref{Set:eqn6a}), 
\begin{equation}\label{Set:eqn70a}
\begin{split}
\left\lVert \frac{\partial^{2}u}{\partial (t')^{2}} \right\rVert_{H^{s}(O_{1}, \sigma^{*}(\epsilon^{-2} \bar{g}))} & \leqslant \epsilon^{-\frac{n}{2}} \left\lVert \frac{\partial^{2}u}{\partial (t')^{2}} \right\rVert_{H^{s}(O_{1}, \sigma^{*} \bar{g})} \\
& \leqslant \epsilon^{-\frac{n}{2}} D_{s} \left\lVert \frac{\partial^{2}u}{\partial (t')^{2}} \right\rVert_{\calL^{2}(O_{2}, \sigma^{*} \bar{g})} \leqslant  D_{s} \left\lVert \frac{\partial^{2}u}{\partial (t')^{2}} \right\rVert_{\calL^{2}(O_{2}, \sigma^{*}(\epsilon^{-2} \bar{g}))}.
\end{split}
\end{equation}
Applying the local $ H^{2} $-type local elliptic estimate for (\ref{Set:eqn3}) and H\"older's inequality,
\begin{equation}\label{Set:eqn7a}
    \begin{split}
        \left\lVert \frac{\partial^{2}u}{\partial (t')^{2}} \right\rVert_{\calL^{2}(O_{2}, \sigma^{*} (\epsilon^{-2} \bar{g}))} & = \epsilon^{2 - \frac{n}{2}} \left\lVert \frac{\partial^{2}u}{\partial t^{2}} \right\rVert_{\calL^{2}(O_{2}, \sigma^{*} \bar{g})} \leqslant  \epsilon^{2 - \frac{n}{2}} \lVert u \rVert_{H^{2}(O_{2}, \sigma^{*}\bar{g})} \\
        & \leqslant \epsilon^{2 - \frac{n}{2}} D_{2} \left( \lVert F \rVert_{\calL^{2}(W, \sigma^{*}\bar{g})} + \lVert u \rVert_{\calL^{2}(W, \sigma^{*}\bar{g})} \right) \\
        & \leqslant \epsilon^{2 - \frac{n}{2}}D_{2}\lVert F \rVert_{\calL^{2}(W, \sigma^{*}\bar{g})} + \epsilon^{2 - \frac{n}{2}}D_{1} D_{2}\lVert u \rVert_{\calL^{\frac{2(n + 1)}{n - 1}}(W, \sigma^{*}\bar{g})} \\
        & \leqslant \epsilon^{2} D_{2}  \lVert F \rVert_{\calL^{2}(W, \sigma^{*}(\epsilon^{-2}\bar{g}))} + \epsilon^{2 - \frac{n}{n + 1}} D_{1}D_{2} \lVert u \rVert_{\calL^{\frac{2(n + 1)}{n - 1}}(W, \sigma^{*} (\epsilon^{-2} \bar{g}))}.
    \end{split}
\end{equation}
Similarly, the Sobolev embedding inequality for the scaled metric $ \sigma^{*} (\epsilon^{-2} \bar{g}) $ says
\begin{equation}\label{Set:eqn7}
\left\lVert \frac{\partial^{2}u}{\partial (t')^{2}} \right\rVert_{\calC^{0}(O_{1})} \leqslant D_{0} \epsilon^{\frac{n}{2}} \left\lVert \frac{\partial^{2}u}{\partial (t')^{2}} \right\rVert_{H^{s}(O_{1}, \sigma^{*}(\epsilon^{-2} \bar{g}))}.
\end{equation}
Here $ D_{0}, D_{1}, D_{2} $ are independent of $ \epsilon $ and $ u $. 


On $ M \times \mathbb{S}^{1}_{t} $ with $ \dim (M \times \mathbb{S}^{1}_{t} ) = n + 1 $, the metric $ \bar{g} $ has positive relative Yamabe constant $ \lambda : = \lambda(M \times \mathbb{S}^{1}_{t}, \partial (M \times \mathbb{S}^{1}_{t}), [\bar{g}]) > 0 $. It follows from the definition of the relative Yamabe constant that for all nontrivial $ v \in \calC^{\infty}(M \times \mathbb{S}_{t}^{1}) $, the Yamabe quotient gives
\begin{align*}
\lVert v \rVert_{\calL^{\frac{2(n + 1)}{n - 1}}(M \times \mathbb{S}^{1}_{t}, \bar{g})}^{2} & \leqslant \lambda(M \times \mathbb{S}^{1}_{t}, \partial (M \times \mathbb{S}^{1}_{t}), [\bar{g}])^{-1} \left( \frac{4n}{n - 1} \lVert \nabla_{\bar{g}} v \rVert_{\calL^{2}(M \times \mathbb{S}^{1}_{t}, \bar{g})}^{2}  \right) \\
& \qquad + \lambda(M \times \mathbb{S}^{1}_{t}, \partial (M \times \mathbb{S}^{1}_{t}), [\bar{g}])^{-1} \left( \int_{M \times \mathbb{S}^{1}_{t}} R_{\bar{g}} v^{2} d\text{Vol}_{\bar{g}} + 2n \int_{\partial (M \times \mathbb{S}^{1}_{t})} h_{\bar{g}} v^{2} \sigma_{\bar{g}} \right) \\
& = \lambda^{-1} \left( \frac{4n}{n - 1} \lVert \nabla_{\bar{g}} v \rVert_{\calL^{2}(M \times \mathbb{S}^{1}_{t}, \bar{g})}^{2} + \int_{M \times \mathbb{S}^{1}_{t}} R_{\bar{g}} v^{2} d\text{Vol}_{\bar{g}} \right). 
\end{align*}
Here $ \sigma_{\bar{g}} $ is the volume form on the hypersurface $ \partial(M \times \mathbb{S}_{1}^{t}) $. The boundary term is dropped off since we have assumed that $ h_{\bar{g}} \equiv 0 $. The relative Yamabe constant $ \lambda $ is invariant under any conformal transformation of the metric $ \bar{g} $.

Since $ M \times \mathbb{S}_{t}^{1} $ is compact, there exist two positive constants $ D_{3} $ and $ D_{4} $ such that two metrics $ \bar{g} $ and $ \sigma^{*} \bar{g} \oplus d\xi^{2} $ satisfy
\begin{equation*}
   D_{4}^{-2} \sqrt{\det{\bar{g}}} \leqslant \sqrt{\det(\sigma^{*} \bar{g} \oplus d\xi^{2})} \leqslant D_{3}^{\frac{2(n + 1)}{n - 1}} \sqrt{\det{\bar{g}}}.
\end{equation*}
Set $ \xi' = \epsilon^{-1} \xi $, we have
\begin{equation*}
   D_{4}^{-2} \sqrt{\det{(\epsilon^{-2}\bar{g})}} \leqslant \sqrt{\det(\sigma^{*}(\epsilon^{-2} \bar{g}) \oplus d(\xi')^{2})} \leqslant D_{3}^{\frac{2(n + 1)}{n - 1}} \sqrt{\det{(\epsilon^{-2}\bar{g})}}
\end{equation*}
for the same $ D_{3}, D_{4} $. %Since the function $ \bar{u} $ is constant along each $ \xi $-fiber, the comapctness of $ X \times I_{\xi} \times \mathbb{S}_{t}^{1} $ and the existences of trivial diffeomorphisms between $ X \times \lbrace 0 \rbrace_{\xi} \times \mathbb{S}_{t}^{1}$ and $ X \times \lbrace \xi_{0} \rbrace \times \mathbb{S}_{t}^{1}, \forall \xi_{0} \in [0, 1] $ implies that there exists a constant $ D_{5} $ such that
%\begin{equation*}
   % \sup_{\xi_{0} \in [0, 1]} \left\lbrace \int_{X_{\xi_{0}} \times \mathbb{S}_{t}^{1}} \lvert \nabla_{\sigma_{\xi_{0}}^{*}(\epsilon^{-2}\bar{g})} \bar{u} \rvert^{2} d\text{Vol}_{\sigma_{\xi_{0}}^{*}(\epsilon^{-2}\bar{g})} \right\rbrace \leqslant D_{5} \int_{W} \lvert \nabla_{\sigma^{*}(\epsilon^{-2} \bar{g}) }\bar{u} \rvert^{2} d\text{Vol}_{\sigma^{*}(\epsilon^{-2} \bar{g})}
%\end{equation*}
%where $ \sigma_{xi_{0}} : X \times \lbrace \xi_{0} \rbrace \times \mathbb{S}_{1}^{t} \rightarrow M \times \mathbb{S}_{1}^{t}, \forall \xi_{0} \in [0, 1] $. The constant $ D_{5} $ only depends on $ \bar{g} |_{X_{\xi_{0}}} $ and $ W $, and is independent of $ \epsilon $ and $ \bar{u} $. Without loss of generality, we may assume that $ D_{5} \geqslant 1 $.


Denote the inclusion by $ \sigma_{\xi} : X_{\xi} \times \mathbb{S}^{1} \rightarrow M \times \mathbb{S}^{1} $, and the space $ X_{\xi} \times \mathbb{S}^{1} $ by $ W_{\xi} $. We now apply the three inequalities above for the function $ u $ on $ W $ and $ \bar{u} = \pi^{*}u $ on $ M \times \mathbb{S}_{t}^{1} $ with respect to the metrics $ \sigma^{*}(\epsilon^{-2} \bar{g}) $ and $ \epsilon^{-2} \bar{g} $ respectively. Recall that the function $ \bar{u} $ is constant along each $ \xi $-fiber, it follows that
\begin{align*}
& \lVert u \rVert_{\calL^{\frac{2(n + 1)}{n - 1}}(W, \sigma^{*} (\epsilon^{-2} \bar{g}))} \\
& \qquad = \epsilon^{\frac{n -1}{2(n + 1)}} \left( \int_{0}^{\epsilon^{-1}} \int_{W} \lvert \bar{u} \rvert^{\frac{2(n + 1)}{n - 1}} d\text{Vol}_{\sigma^{*} (\epsilon^{-2} \bar{g})} d\xi'  \right)^{\frac{n - 1}{2(n + 1)}} \\
& \qquad = \epsilon^{\frac{n -1}{2(n + 1)}} \left( \int_{M \times \mathbb{S}_{t'}^{1}} \lvert \bar{u} \rvert^{\frac{2(n + 1)}{n - 1}} d\text{Vol}_{\sigma^{*} \bar{g} \oplus d(\xi')^{2}}  \right)^{\frac{n - 1}{2(n + 1)}} \leqslant \epsilon^{\frac{n -1}{2(n + 1)}} D_{3}  \left( \int_{M \times \mathbb{S}^{1}_{t'}}  \lvert \bar{u} \rvert^{\frac{2(n + 1)}{n - 1}} d\text{Vol}_{\epsilon^{-2}\bar{g}} \right)^{\frac{n - 1}{2(n + 1)}} \\
& \qquad \leqslant \epsilon^{\frac{n -1}{2(n + 1)} } D_{3} \lambda^{-1} \left( \frac{4n}{n - 1} \lVert \nabla_{\epsilon^{-2}\bar{g}} \bar{u} \rVert_{\calL^{2}(M \times \mathbb{S}^{1}_{t'}, \epsilon^{-2}\bar{g})} + \int_{M \times \mathbb{S}^{1}_{t'}} R_{\epsilon^{-2}\bar{g}} \bar{u}^{2} d\text{Vol}_{\epsilon^{-2}\bar{g}} \right)^{\frac{1}{2}} \\
& \qquad \leqslant \epsilon^{\frac{n -1}{2(n + 1)}} D_{3} D_{4} \lambda^{-1} \left( \frac{4n}{n - 1}\int_{0}^{\epsilon^{-1}} \int_{W_{\xi}} \lvert \nabla_{\sigma_{\xi}^{*}(\epsilon^{-2}\bar{g})} \bar{u} \rvert^{2} d\text{Vol}_{\sigma_{\xi}^{*}(\epsilon^{-2}\bar{g})} d\xi' \right)^{\frac{1}{2}} \\
& \qquad \qquad + \epsilon^{\frac{n -1}{2(n + 1)}} D_{3} D_{4} \lambda^{-1} \left( \int_{0}^{\epsilon^{-1}} \int_{W} R_{\epsilon^{-2}\bar{g}} \bar{u}^{2} d\text{Vol}_{\sigma^{*} (\epsilon^{-2}\bar{g})} d\xi' \right)^{\frac{1}{2}} \\
& \qquad \leqslant 2D_{3} D_{4} \lambda^{-1} \epsilon^{-\frac{1}{n + 1}} \left( \frac{4n}{n - 1} \max_{\xi \in [0, 1]} \left( \lVert \nabla_{\sigma_{\xi}^{*} (\epsilon^{-2} \bar{g})}\bar{u} \rVert_{\calL^{2}(W_{\xi}, \sigma_{\xi}^{*}(\epsilon^{-2}\bar{g}))}^{2} \right) + \epsilon^{2} \max_{W} \lvert R_{\bar{g}} \rvert \lVert u \rVert_{\calL^{2}(W, \sigma^{*}(\epsilon^{-2}\bar{g}))}^{2} \right)^{\frac{1}{2}}
\end{align*}
Note that $ \lVert F \rVert_{\calL^{p}(W, \sigma^{*}\bar{g})} $ is small in the sense that $ (C + 1)^{p} \epsilon \ll 1 $, hence $ (C + 1)^{2} \epsilon \ll 1 $ since $ p > n \geqslant 3 $. Note also that there are trivial diffeomorphisms between $ W $ and $ W_{\xi} $ for every $ \xi \in [0, 1] $. Since $ \bar{u} $ is constant for each $ \xi $-fiber, and $ M \times \mathbb{S}^{1} $ is compact, we have $ \lVert \nabla_{\sigma_{\xi}^{*}\bar{g}} \bar{u} \rVert_{\calL^{2}(W_{\xi}, \sigma_{\xi}^{*} \bar{g})} \leqslant D_{5} \eta $ for some $ D_{5} $ independent of $ \bar{u} $ and $ \epsilon $. Without loss of generality, we may assume $ \max_{W} \lvert R_{\bar{g}} \rvert \leqslant D_{5} $ by increasing $ D_{5} $ if necessary. Combining (\ref{Set:eqn4}), (\ref{Set:eqn70a}), (\ref{Set:eqn7a}), (\ref{Set:eqn7}) with the above inequality, we have
\begin{align*}
\left\lVert \frac{\partial^{2}u}{\partial (t')^{2}} \right\rVert_{\calC^{0}(O_{1})} & \leqslant D_{0}\epsilon^{\frac{n}{2}} \lVert \frac{\partial^{2}u}{\partial (t')^{2}} \rVert_{H^{s}(O_{1}, \sigma^{*}(\epsilon^{-2} \bar{g}))} \leqslant D_{0} D_{s} \epsilon^{\frac{n}{2}} \left\lVert \frac{\partial^{2}u}{\partial (t')^{2}} \right\rVert_{\calL^{2}(O_{2}, \sigma^{*}(\epsilon^{-2} \bar{g}))} \\
& \leqslant \epsilon^{2 + \frac{n}{2}} D_{0}D_{2}D_{s}  \lVert F \rVert_{\calL^{2}(W, \sigma^{*}(\epsilon^{-2}g))} + \epsilon^{2 - \frac{n}{n + 1} + \frac{n}{2}} D_{0}D_{1}D_{2}D_{s} \lVert u \rVert_{\calL^{\frac{2(n + 1)}{n - 1}}(W, \sigma^{*} (\epsilon^{-2} \bar{g}))} \\
& \leqslant 2D_{0} D_{1} D_{2} D_{3}D_{4} D_{s} \lambda^{-1}  \epsilon^{1 + \frac{n}{2}} \times \\
& \qquad \times \left( \frac{4n}{n - 1} \max_{\xi \in [0, 1]} \left( \lVert \nabla_{\sigma_{\xi}^{*} (\epsilon^{-2} \bar{g})} \bar{u} \rVert_{\calL^{2}(W_{\xi}, \sigma_{\xi}^{*}(\epsilon^{-2}\bar{g}))}^{2} \right) + \epsilon^{2} \max_{W} \lvert R_{\bar{g}} \rvert \lVert u \rVert_{\calL^{2}(W, \sigma^{*}(\epsilon^{-2}\bar{g}))}^{2} \right)^{\frac{1}{2}} \\
& \qquad \qquad + \epsilon^{2 + \frac{n}{2}} D_{0}D_{2}D_{s}  \lVert F \rVert_{\calL^{2}(W, \sigma^{*}(\epsilon^{-2}\bar{g}))} \\
& : = \bar{D}_{0}  \epsilon^{2} \left( \frac{4n}{n - 1} \max_{\xi \in [0, 1]} \left( \lVert \nabla_{\sigma_{\xi}^{*}  \bar{g}} \bar{u} \rVert_{\calL^{2}(W_{\xi}, \sigma_{\xi}^{*}\bar{g})}^{2} \right) + \max_{W} \lvert R_{\bar{g}} \rvert \lVert u \rVert_{\calL^{2}(W, \sigma^{*}\bar{g})}^{2} \right)^{\frac{1}{2}} \\
& \qquad + \epsilon^{2 + \frac{n}{2}} D_{0}D_{2}D_{s}  \lVert F \rVert_{\calL^{2}(W, \sigma^{*}(\epsilon^{-2}\bar{g}))} \\
& < \frac{8n}{n - 1} \bar{D}_{0} D_{5} \epsilon^{2} \eta + D_{0}D_{2}D_{s} \epsilon^{2} \text{Vol}_{g}(X) (C + 1) \epsilon^{\frac{1}{2}} \\
& : = \bar{D} \epsilon^{2} \eta + \bar{D}' \epsilon^{2 + \frac{1}{2}} (C + 1).
\end{align*}
It follows by the smallness of $ \eta $ in Proposition \ref{Set:prop1} that
\begin{equation*}
\lVert \frac{\partial^{2}u}{\partial t^{2}} \rVert_{\calC^{0}(U_{1})} = \epsilon^{-2} \lVert \frac{\partial^{2}u}{\partial (t')^{2}} \rVert_{\calC^{0}(O_{1})} < \bar{D} \eta + \bar{D}'(C + 1) \epsilon^{\frac{1}{2}} : = \eta' \ll 1.
\end{equation*}
As desired.
\end{proof}
\begin{remark}
    Since $ u_{0} = u + 1 $, Lemma \ref{Set:lemma3} implies that
    \begin{equation*}
        \left\lVert \frac{\partial^{2} u_{0}}{\partial t^{2}} \right\rVert_{\calC^{0}(X \times \lbrace 0 \rbrace_{\xi} \times \lbrace P \rbrace_{t})} < \eta' \Rightarrow \left\lvert \frac{\partial^{2} u'}{\partial t^{2}} \bigg|_{X \times \lbrace 0 \rbrace_{\xi} \times \lbrace P \rbrace_{t}} \right\rvert < \eta'.
    \end{equation*}
\end{remark}

We close this section by comparing $ \Delta_{\bar{g}} u' $, $ \Delta_{\sigma^{*}\bar{g}} u_{0} $ and $ \Delta_{\tau_{1}^{*}\bar{g}} \tilde{u}' $ on $ X \times \lbrace 0 \rbrace_{\xi} \times \lbrace P \rbrace_{t} \subset W \times \lbrace 0 \rbrace_{\xi} \subset M \times \mathbb{S}^{1}_{t} $.
