\Delta_{\bar{g}} u' = \Delta_{\tau_{1}^{*}\bar{g}} \tilde{u}' + \frac{\partial^{2} u'}{\partial t^{2}} \; {\rm on} \; X \times \lbrace 0 \rbrace_{\xi} \times \lbrace P \rbrace_{t}, \\
\Delta_{\bar{g}}u' = \Delta_{\sigma^{*}\bar{g}} u_{0} + A_{1}(\bar{g}, M, u)
