\section{Positive Scalar Curvature on $ X $}
In this section, we show that for any metric $ g $ on the compact cylinder $ M $ with $ R_{g} > 0 $ and $ h_{g} \geqslant 0 $ and satisfying the $ g $-angle condition (\ref{intro:eqn1}), there exists a conformal metric $ \tilde{g}' \in [g] $ such that $ R_{\tilde{g}'} > 0 $ and $ R_{\imath^{*} \tilde{g}'} > 0 $ simultaneously. 

We define
\begin{equation*}
    e^{2\phi'} : = (u')^{\frac{4}{n - 2}} \Rightarrow \phi_{0} : = \sigma^{*} \phi', \tilde{\phi}' : = \tau_{1}^{*} \phi' \Rightarrow e^{2\phi_{0}} : = u_{0}^{\frac{4}{n - 2}}, e^{\tilde{\phi}'} = (\tilde{u}')^{\frac{4}{n - 2}}.
\end{equation*}
For any two functions $ \varphi, v $ with the relation $ e^{2\varphi} = v^{\frac{4}{n - 2}}, n \geqslant 3 $ and any Riemannian metric $ g_{0} $, we have
\begin{align*}
    & v^{-\frac{n+2}{n- 2}}\left(-\frac{4}{n - 2} \Delta_{g_{0}} v 
    \right) = e^{-2\varphi} \left(  
    - 2 \Delta_{g_{0}} \varphi - (n - 2) \lvert \nabla_{g_{0}} \varphi \rvert^{2} \right), \\
   &  e^{-2\varphi} \nabla_{g_{0}} \varphi = \frac{2}{n - 2} v^{-\frac{n+2}{n-2}} \nabla_{g_{0}} v,\  e^{-2\varphi} \lvert \nabla_{g_{0}} \varphi \rvert^{2} = \left( \frac{2}{n - 2} \right)^{2}v^{-\frac{2n}{n - 2}} \lvert \nabla_{g_{0}} v \rvert^{2}, \\
   & e^{-2\tilde{\phi}'} \left( 2(n - 2) \nabla_{V} \nabla_{V} \tilde{\phi}' + (n - 2)^{2} \nabla_{V} \tilde{\phi}' \nabla_{V} \tilde{\phi}' \right)   
= 4(\tilde{u}')^{-\frac{n + 2}{n - 2}}   \nabla_{V} \nabla_{V} \tilde{u}'.
\end{align*}  
Our main theorem gives the existence of the PSC metric on $ X \cong X \times \lbrace 0 \rbrace_{\xi} $. We point out that the proof of Theorem \ref{POS:thm1} follows closely the argument of \cite[Theorem 3.1]{RX2}. 
\begin{theorem}\label{POS:thm1}
Let $ X $ be a closed, oriented manifold with $ \dim X \geqslant 2 $, and $ I_{\xi} = [0, 1]_{\xi} $ be the unit interval with $ \xi $-variable. Let $ M = X \times I_{\xi} $ be the compact cylinder. Assume that $ (M, \partial M), \dim M \geqslant 3 $ admits a metic $ g $ with $ R_{g} > 0 $ and $ h_{g} \geqslant 0 $. If $ g $ satisfies the angle condition
    \begin{equation}\label{POS:eqn0}
    \cos \left(\angle_{g}\left(\nu_{g},\partial_{\xi} \right) \right) > \frac{\sqrt{2}}{2} \Leftrightarrow \frac{g(\partial_{\xi}, \partial_{\xi})}{g(\nu_{g}, \partial_{\xi})^{2}} < 2
    \end{equation}
on $ X \times \lbrace 0 \rbrace_{\xi} $, then there exists a metric $ \tilde{g} $ on $ (M, \partial M) $ such that $ \imath^{*} \tilde{g} $ has positive scalar curvature on $ X \times \lbrace 0 \rbrace_{\xi} \cong X $.
\end{theorem}
\begin{proof}
As we discussed before, we may assume that $ R_{g} > 0 $ and $ h_{g} \equiv 0 $ up to a possible conformal transformation. Recall that the $ g $-angle condition is invariant under conformal transformation, hence is unchanged.

We set $ p > n $ as in Proposition \ref{Set:prop1}. Pick $ C > 0 $ such that
\begin{equation}\label{POS:eqn1}
C > 2 \max_{\partial M} \left( \lvert R_{g} \rvert + 2 \lvert {\rm Ric}_{g}(\nu_{g}, \nu_{g}) \rvert + h_{g}^{2} + \lvert A_{g} \rvert^{2} \right)  + 3.
\end{equation}
We choose $ \eta, \eta' \ll 1 $, and associated small enough $ \delta $, $ \epsilon $ and associated $ F $ in Lemma \ref{Set:lemma2}, such that (i) the solution of (\ref{Set:eqn3}) satisfies  (\ref{Set:eqn4}) and (\ref{Set:eqn5}); (ii) $ \lvert A_{1}(\bar{g}, M, u) \rvert < 1 $ on $ X \times \lbrace 0 \rbrace_{\xi} \times \lbrace P \rbrace_{t} $. Note that $ \tau_{1}^{*}\bar{g} = g $, $ \nabla_{\tau_{1}^{*} \bar{g}} $ and $ \nabla_{V} $ do not contain $ \xi $-derivative. It follows that
\begin{equation}\label{POS:eqn1a}
   \frac{1}{2} < \lVert u_{0} \rVert_{\calC^{0}(X \times [-\frac{\epsilon}{2}, \frac{\epsilon}{2}]_{t})} < \frac{3}{2} \Rightarrow \left\lvert \frac{4}{n - 2} \frac{\left\lvert \nabla_{\tau_{1}^{*} \bar{g}} u_{0} \right\rvert^{2}}{u_{0}} + \frac{4n}{n - 2} \frac{\nabla_{V} u_{0} \nabla_{V} u_{0}}{u_{0}} \right\rvert < 1 \; {\rm on} \; X \cong X \times \lbrace 0 \rbrace_{\xi}.
\end{equation}
For the metric $ \tilde{g} = e^{2\phi'} \bar{g} = (u')^{\frac{4}{n - 2}} \bar{g} $ on $ M \times \mathbb{S}^{1}_{t} $, the normal vector field on $ X \times \lbrace 0 \rbrace_{\xi} \times \lbrace P \rbrace_{t} $ becomes $ e^{-\tilde{\phi}'}\nu_{g} $. Applying Gauss-Codazzi equation on $ X \cong X \times \lbrace 0 \rbrace_{\xi} \times \lbrace P \rbrace_{t} $ with respect to the metric $ \tau_{1}^{*}\tilde{g} $ on $ M $,
\begin{equation*}
R_{\imath^{*} \tau_{1}^{*} \tilde{g}}
 = R_{\tau_{1}^{*} \tilde{g}} - 2{\rm Ric}_{\tau_{1}^{*} \tilde{g}}\left(e^{-\tilde{\phi}'}\nu_{g}, e^{-\tilde{\phi}'}\nu_{g} \right) + h_{\tau_{1}^{*} \tilde{g}} - \lvert A_{\tau_{1}^{*} \tilde{g}} \rvert^{2}.
\end{equation*}
The conformal transformation of Ricci and scalar curvatures are given by
\begin{align*}
    {\rm Ric}_{\tau_{1}^{*} \tilde{g}}\left(e^{-\tilde{\phi}'}\nu_{g}, e^{-\tilde{\phi}'}\nu_{g}\right) & = e^{-2\tilde{\phi}'}\left({\rm Ric}_{\tau_{1}^{*}\bar{g}}\left(\nu_{g}, \nu_{g} \right) - (n - 2)(\nabla_{\nu_{g}} \nabla_{\nu_{g}} \tilde{\phi}' - \nabla_{\nu_{g}} \tilde{\phi}' \nabla_{\nu_{g}} \tilde{\phi}')\right) \\
    & \qquad - e^{-2\tilde{\phi}'}\left(\Delta_{\tau_{1}^{*}\bar{g}} \tilde{\phi}' + (n - 2) \left\lvert \nabla_{\tau_{1}^{*} \bar{g}} \tilde{\phi}' \right\rvert^{2}\right)\bar{g}_{\xi\xi},\\
  R_{\tau_{1}^{*} \tilde{g}}  &=  e^{-2\tilde{\phi}'} \left(R_{\tau_{1}^{*}\bar{g}} -2(n-1)\Delta_{\tau_{1}^{*}\bar{g}}\tilde{\phi}'
  -(n-2)(n-1)\left\lvert\nabla_{\tau_{1}^{*}\bar{g}}\tilde{\phi}'\right\rvert^2 \right).
  \end{align*}
The conformal transformation of the second fundamental form and mean curvature are given by
\begin{align*}
   \lvert A_{\tau_{1}^{*} \tilde{g}} \rvert^{2} & = e^{-2\tilde{\phi}'} \left( \lvert A_{\tau_{1}^{*} \bar{g}} \rvert^{2} + 
   2 n h_{\tau_{1}^{*}\bar{g}} \frac{\partial \tilde{\phi}'}{\partial \nu_{g}} +  n^2
   \left(\frac{\partial \tilde{\phi}'}{\partial \nu_{g}} \right)^{2}  \right),\\
    h_{\tau_{1}^{*} \tilde{g}}^{2} & = e^{-2\tilde{\phi}'} \left( h_{\tau_{1}^{*} \bar{g}}^{2} +
     2n h_{\tau_{1}^{*}\bar{g}} \frac{\partial \tilde{\phi}}{\partial \nu_{g}}  + 
       n^2\left(\frac{\partial \tilde{\phi}'}{\partial \nu_{g}} \right)^{2} \right).
\end{align*}
By (\ref{Set:eqn6}), $ \nabla_{\nu_{g}} \nabla_{\nu_{g}} \tilde{\phi}' = \nabla_{V} \nabla_{V} \tilde{\phi}' $. According to the laws of conformal transformations listed above, and the differential relations before Theorem \ref{POS:thm1}, the Gauss-Codazzi equation converts to
\begin{equation}\label{POS:eqn2}
    \begin{split}
    R_{\imath^{*} \tau_{1}^{*} \tilde{g}} & = e^{-2\tilde{\phi}'} \left(R_{\tau_{1}^{*}\bar{g}} - 2{\rm Ric}_{\tau_{1}^{*}\bar{g}}\left(\nu_{g}, \nu_{g} \right) + h_{\tau_{1}^{*} \bar{g}}^{2} - \lvert A_{\tau_{1}^{*} \bar{g}} \rvert^{2} \right) \\
    & \qquad + e^{-2\tilde{\phi}'} \left(- 2(n - 2) \Delta_{\tau_{1}^{*}\bar{g}} \tilde{\phi}' - (n - 3)(n - 2) \left\lvert \nabla_{\tau_{1}^{*}\bar{g}} \tilde{\phi}' \right\rvert \right) \\
    & \qquad \qquad + 2(n - 2)e^{-2\tilde{\phi}'}\left(\nabla_{V} \nabla_{V} \tilde{\phi}' -  \nabla_{V} \tilde{\phi}' \nabla_{V} \tilde{\phi}' \right) \\
    & = (\tilde{u}')^{-\frac{n +2}{n - 2}}\left(R_{\tau_{1}^{*}\bar{g}} \tilde{u}' - 2{\rm Ric}_{\tau_{1}^{*}\bar{g}}\left(\nu_{g}, \nu_{g} \right)\tilde{u}' + h_{\tau_{1}^{*} \bar{g}}^{2}\tilde{u}' - \lvert A_{\tau_{1}^{*} \bar{g}} \rvert^{2}\tilde{u}' \right) \\
    & \qquad + (\tilde{u}')^{-\frac{n +2}{n - 2}}\left( 4\nabla_{V} \nabla_{V} \tilde{u}' - 4\Delta_{\tau_{1}^{*}\bar{g}} \tilde{u}' \right) \\
    & \qquad \qquad + (\tilde{u}')^{-\frac{n +2}{n - 2}} \left( \frac{4}{n - 2} \frac{\left\lvert \nabla_{\tau_{1}^{*} \bar{g}} \tilde{u}' \right\rvert^{2}}{\tilde{u}'} - \frac{4n}{n - 2} \frac{\nabla_{V} \tilde{u}' \nabla_{V} \tilde{u}'}{\tilde{u}'} \right).
    \end{split}
\end{equation}
Note that on $ X \cong X \times \lbrace 0 \rbrace_{\xi} \times \lbrace P \rbrace_{t} \subset W \times \lbrace 0 \rbrace_{\xi} $, $ \tilde{u}' = u_{0} $. Recall that $ u_{0} = u + 1 $, which satisfies the following PDE
\begin{equation*}
    4\nabla_{V} \nabla_{V} u_{0} - 4\Delta_{\sigma^{*} \bar{g}} u_{0} + R_{\bar{g}} |_{W} u_{0} = F + R_{\bar{g}} |_{W} \; {\rm on} \; X.
\end{equation*}
Since $ \bar{g} = g \oplus dt^{2} $, it follows that $ R_{\bar{g}} = R_{\tau_{1}^{*}\bar{g}} = R_{g} > 0 $ on $X \times \lbrace 0 \rbrace_{\xi} $ by hypothesis. Applying (\ref{Set:eqn5}) of Lemma \ref{Set:lemma3}, (\ref{Set:eqn8}) of Lemma \ref{Set:lemma4}, Remark 2.3, and (\ref{POS:eqn1a}), the formula (\ref{POS:eqn2}) on $ X \cong X \times \lbrace 0 \rbrace_{\xi} \times \lbrace P \rbrace_{t} $ becomes
\begin{equation}\label{POS:eqn3}
\begin{split}
 R_{\imath^{*} \tau_{1}^{*} \tilde{g}} & =u_{0}^{-\frac{n +2}{n - 2}}\left(  - 2{\rm Ric}_{\tau_{1}^{*}\bar{g}}\left(\nu_{g}, \nu_{g} \right)u_{0} + h_{\tau_{1}^{*} \bar{g}}^{2} u_{0} - \lvert A_{\tau_{1}^{*} \bar{g}} \rvert^{2} u_{0} \right) \\
    & \qquad + u_{0}^{-\frac{n +2}{n - 2}}\left( 4\nabla_{V} \nabla_{V} u_{0} - 4\Delta_{\tau_{1}^{*}\bar{g}} \tilde{u}' - 4\frac{\partial^{2} \tilde{u}'}{\partial t^{2}} + 4\frac{\partial^{2} \tilde{u}'}{\partial t^{2}} + R_{\tau_{1}^{*} \bar{g}} u_{0} \right) \\
    & \qquad \qquad + u_{0}^{-\frac{n +2}{n - 2}} \left( \frac{4}{n - 2} \frac{\left\lvert \nabla_{\tau_{1}^{*} \bar{g}} u_{0} \right\rvert^{2}}{u_{0}} - \frac{4n}{n - 2} \frac{\nabla_{V} u_{0} \nabla_{V} u_{0}}{u_{0}} \right) \\
    & \geqslant u_{0}^{-\frac{n +2}{n - 2}}\left(- 2{\rm Ric}_{\tau_{1}^{*}\bar{g}}\left(\nu_{g}, \nu_{g} \right)u_{0} + h_{\tau_{1}^{*} \bar{g}}^{2} u_{0} - \lvert A_{\tau_{1}^{*} \bar{g}} \rvert^{2} u_{0} \right) \\
    & \qquad + u_{0}^{-\frac{n +2}{n - 2}}\left( 4\nabla_{V} \nabla_{V} u_{0} - 4\Delta_{\bar{g}} u' - 4\eta' + R_{\bar{g}} |_{W} u_{0}\right) + u_{0}^{-\frac{n +2}{n - 2}} \cdot (-1) \\
    & = u_{0}^{-\frac{n +2}{n - 2}}\left( - 2{\rm Ric}_{\tau_{1}^{*}\bar{g}}\left(\nu_{g}, \nu_{g} \right)u_{0} + h_{\tau_{1}^{*} \bar{g}}^{2} u_{0} - \lvert A_{\tau_{1}^{*} \bar{g}} \rvert^{2} u_{0} \right) \\
    & \qquad + u_{0}^{-\frac{n +2}{n - 2}}\left( 4\nabla_{V} \nabla_{V} u_{0} - 4\Delta_{\sigma^{*}\bar{g}} u_{0}  + R_{\bar{g}} |_{W} u_{0}\right) + u_{0}^{-\frac{n +2}{n - 2}} \cdot (-1 - 4 \eta' + A_{1}(\bar{g}, M, u)) \\
    & = u_{0}^{-\frac{n +2}{n - 2}}\left(- 2{\rm Ric}_{\tau_{1}^{*}\bar{g}}\left(\nu_{g}, \nu_{g} \right)u_{0} + h_{\tau_{1}^{*} \bar{g}}^{2} u_{0} - \lvert A_{\tau_{1}^{*} \bar{g}} \rvert^{2} u_{0} \right) \\
    & \qquad u_{0}^{-\frac{n +2}{n - 2}} \left(F + R_{\bar{g}} |_{W} -1 - 4 \eta' + A_{1}(\bar{g}, M, u) \right).
\end{split}
\end{equation}
By Lemma \ref{Set:lemma2}, $ F = C + 1 $ on $ \partial M $. By (\ref{POS:eqn1}), (\ref{POS:eqn3}) implies that
\begin{equation*}
    R_{\imath^{*} \tau_{1}^{*} \tilde{g}} \geqslant  u_{0}^{-\frac{n +2}{n - 2}} \left( C + 1 + R_{\bar{g}} - 2 \max_{\partial M} \left(2 \lvert {\rm Ric}_{g}(\nu_{g}, \nu_{g}) \rvert + h_{g}^{2} + \lvert A_{g} \rvert^{2} \right) - 3 \right) > 0. 
\end{equation*}
Therefore, the metric
\begin{equation*}
 \tau_{1}^{*} \tilde{g} = \tau_{1}^{*}(u')^{\frac{4}{n- 2}} \bar{g} = (\tilde{u}')^{\frac{4}{n- 2}} g : = g', g' \in [g]
\end{equation*}
induces a PSC metric $ \imath^{*} g' \in [\imath^{*} g] $ on $ X \cong X \times \lbrace 0 \rbrace_{\xi} $.
\end{proof}
\begin{remark}\label{POS:re1}
    Set $ X_{\xi} = X \times \lbrace \xi \rbrace, \xi \in [0, 1] $, we can define the second fundamental form, unit normal vector field, etc. on the hypersurface $ X_{\xi} $ also. We can then apply our $ g $-angle condition on $ X_{\xi} $. It follows that if $ M $ admits a metric $ g $ with $ R_{g} > 0 $ and $ h_{g} \geqslant 0 $, and the $ g $-angle condition on $ X_{\xi} $ holds, then there exists a metric $ \tilde{g} $ such that $ \imath_{\xi}^{*} \tilde{g} $ has positive scalar curvature on $ X_{\xi} $. Here $ \imath_{\xi} : X_{\xi} \rightarrow M $ is the natural inclusion.
\end{remark}

With Remark \ref{POS:re1}, we generalize the scalar and mean curvature comparison result of Gromov and Lawson \cite{GL} for $ X = \mathbb{T}^{n}, n \geqslant 1 $, and the result of R\"ade for $ \dim X \leqslant 7 $, $ \dim X \neq 4 $.
\begin{corollary}\label{POS:cor2}
     Let $ X $ be a closed, oriented manifold with $ \dim X \geqslant 2 $. If $ X $ admits no PSC metric, meanwhile $ X \times I $ admits a PSC metric $ g $. If the $ g $-angle condition holds on some hypersurface $ X_{\xi}, \xi \in [0, 1] $, then the mean curvature $ h_{g} $ must be negative somewhere.
\end{corollary}

% Need Revising Below
% Need Revising Below
We now give another geometric consequence of Theorem \ref{POS:thm1}. Theorem \ref{POS:thm1} says that for PSC metric $ g $ on $ M $, the Yamabe constant for the conformal class $ [\imath^{*} g] $ on $ X \cong X \times \lbrace 0 \rbrace_{\xi} $ is positive. The next result shows that there exits a metric in the conformal class $ [g] $ which admits PSC metric on $ M $ and induced PSC metric on $ X $.
\begin{corollary}\label{POS:cor1}
Let $(M, \partial M, g) $ be the same as in Theorem \ref{POS:thm1}, $ \dim M = n $. 
If
\begin{equation*}
\cos \left(\angle_g(\partial_{\xi}, \nu_{g}) \right) > \frac{\sqrt{2}}{2}
\end{equation*}
on $ X \times \lbrace 0 \rbrace_{\xi} $, then there exists a conformal metric $ \tilde{g} \in [g] $ such that $ R_{\tilde{g}} > 0 $ and $ R_{\imath^{*} \tilde{g}} > 0 $.
\end{corollary}
\begin{proof}
Let $ \eta_{1, g} $ be the first eigenvalue of the conformal Laplacian $ -\frac{4(n - 1)}{n- 2} \Delta_{g} + R_{g} $ on $ M $ with Neumann boundary condition. It is well-known that $ R_{g} > 0 $ and $ h_{g} \geqslant 0 $ implies that $ \eta_{1, g} > 0 $.

Let $ \zeta_{1, \imath^{*}g} $ be the first eigenvalue of the conformal Laplacian $ -\frac{4(n - 2)}{n - 3} \Delta_{\imath^{*}g} + R_{\imath^{*}g} $. By Theorem \ref{POS:thm1}, $ R_{\imath^{*} g_{1}} > 0 $ for some $ g_{1} \in [g] $. It follows that $ \zeta_{1, \imath^{*}g_{1}} > 0 $, see e.g. \cite{PL}. By \cite[Theorem 3.2]{KW}, $ \zeta_{1, \imath^{*}g} > 0 $ as the sign is preserved under conformal change.

Since $ \eta_{1, g} > 0 $, \cite[Theorem 1.1]{XU7} implies that there exists a metric $ g' \in [g] $ such that $ R_{\tilde{g}} $ is a positive constant, and $ R_{\imath^{*} g'} $ is also a constant.  Therefore $ R_{\imath^{*} g'} > 0 $ since otherwise it contradicts the positivity of $ \zeta_{1, \imath^{*} g'} $.
\end{proof}
