\begin{definition} \label{def:MNSDtype}
A sequence of positive integers $1 = m_1 \le \cdots \le m_r$ is called \emph{MNSD} if:
\begin{itemize}
    \item $r$ is odd, and each $m_i$ is odd;
    \item for all $j$, we have $m_{2j} = m_{2j+1}$.
\end{itemize}
Equivalently, such a sequence has the form
\[
(1, m_2, m_2, m_4, m_4, \dots, m_{r-1}, m_{r-1}).
\]
\end{definition}

\begin{theorem}[Corollary 8.2 in \cite{NS07}] \label{thm:OddMNSD}
Let $\mathcal{C}$ be an integral fusion category over $\mathbb{C}$ with odd Frobenius-Perron dimension. Then $\mathcal{C}$ is \emph{Maximally Non-Self Dual} (i.e., no simple object is self-dual except $\mathbf{1}$). In particular, its type is MNSD.
\end{theorem}

\begin{definition} \label{def:coMNSD}
A sequence of positive integers $n_1 \ge \cdots \ge n_r$ is called \emph{co-MNSD} if each $n_i$ divides $n_1$, and the sequence $(n_1 / n_i)$ is MNSD.
\end{definition}

\begin{definition} \label{def:EgyMNSD}
An Egyptian fraction $\sum_i 1/n_i = 1$ is called \emph{MNSD} if the sequence of positive integers $(n_i)$ is co-MNSD.
\end{definition}

\begin{proposition} \label{prop:MNSDFormalCodegrees}
Let $\mathcal{C}$ be an integral fusion category over $\mathbb{C}$ with odd Frobenius-Perron dimension. Then its formal codegrees (\S\ref{sub:formal}) form a co-MNSD sequence, and so make an MNSD Egyptian fraction.
\end{proposition}

\begin{proof}
Let $F\colon \mathcal{Z}(\mathcal{C}) \to \mathcal{C}$ denote the forgetful functor, and let $I\colon \mathcal{C} \to \mathcal{Z}(\mathcal{C})$ be its right adjoint. Suppose $A$ is a simple direct summand of $I(\mathbf{1})$ in $\mathcal{Z}(\mathcal{C})$, so that $\mathbf{1}$ appears as a subobject of $F(A)$ in~$\mathcal{C}$. Since $F$ is a tensor functor, it preserves duals, and thus $\mathbf{1}$ also appears in $F(A^*) = F(A)^*$. Therefore, $A^*$ is also a direct summand of $I(\mathbf{1})$.

As $\mathcal{C}$ is integral, it is pseudo-unitary and therefore spherical (see \cite{EGNO15}). By \cite[Theorem 2.13]{Os15}, the formal codegrees are given by $\FPdim(\mathcal{C}) / \FPdim(A)$, where $A$ runs over the simple summands of $I(\mathbf{1})$.

By \cite[Theorem 7.16.6]{EGNO15}, we have $\FPdim(\mathcal{Z}(\mathcal{C})) = \FPdim(\mathcal{C})^2$. Since $\FPdim(\mathcal{C})$ is odd, so is $\FPdim(\mathcal{Z}(\mathcal{C}))$. Hence, by Theorem~\ref{thm:OddMNSD}, the Drinfeld center $\mathcal{Z}(\mathcal{C})$ has MNSD type. The result is an immediate consequence of the preceding two paragraphs.
\end{proof}

\begin{definition} \label{def:MNSDring}
An integral Drinfeld ring is called \emph{MNSD} if:
\begin{itemize}
    \item it is Maximally Non-Self Dual (in particular, its type is MNSD);
    \item its formal codegrees form a co-MNSD sequence.
\end{itemize}
\end{definition}

It follows immediately from the above that the Grothendieck ring of any odd-dimensional integral fusion category over~$\mathbb{C}$ is an MNSD integral Drinfeld ring.



