\begin{lemma} \label{lem:excl}
The algebra \(\mathcal{R}_{\mathbb{C}}\) cannot be isomorphic to \(\mathbb{C}^{\oplus n} \oplus M_m(\mathbb{C})\) with \(n \leq 1\) and \(m \geq 2\).
\end{lemma}

\begin{proof}
The case \(n = 0\) is ruled out by the existence of the one-dimensional representation \(\FPdim\), so we must have \(n = 1\) and \(m \geq 2\). The rest of the proof follows similarly to that of Proposition~\ref{prop:min6}. Let \(a = \FPdim(\mathcal{R})\) and \(b\) be the formal codegree associated to the matrix block \(M_m(\mathbb{C})\). If \(a = mb\), then \(\mathcal{R}\) is pointed. But there is no nonabelian group \(G\) such that \(\Rep(G)\) has rank \(2\). Therefore, \(a \ne mb\), and the contradiction arises from the following inequality:
\[
1 + m^2 = \operatorname{rank}(\mathcal{R}) \leq \FPdim(\mathcal{R}) = 1 + \frac{m}{b - m} \leq 1 + m. \qedhere
\]
\end{proof}


\begin{lemma} \label{lem:NCmin}
Let $\mathcal{R}$ be a noncommutative fusion ring of rank $<9$. Then $\mathcal{R}_{\mathbb{C}}$ is isomorphic to $\mathbb{C}^{\oplus n} \oplus M_2(\mathbb{C})$ with $n \in \{2,3,4\}$.
\end{lemma}
\begin{proof}
Immediate from Lemma \ref{lem:excl}.
\end{proof}

\subsection{Drinfeld Rings} \label{DrRingsNC}
The results in this subsection apply to fusion rings that satisfy the Drinfeld condition (see~\S\ref{sub:Drin}).

%\begin{proposition} \label{prop:NCDrIntRank6}
