\subsection{Grothendieck rings}  \label{GrRingsNC}
 \begin{proposition} \label{prop:DimDet}  
Let $\mathcal{C}$ be an integral fusion category over $\mathbb{C}$, and let $\mathcal{R}$ be its Grothendieck ring. The integers  
\[
\FPdim(\mathcal{R}) \quad \text{and} \quad \prod_{V \in {\rm Irr}(\mathcal{R}_{\mathbb{C}})} n_V f_V,  
\]  
where $n_V$ is the dimension of $V$ and $f_V$ its formal codegree (see \S\ref{sub:formal}), have the same prime divisors.  
\end{proposition}  
%
\begin{proof}  
An integral fusion category is pseudo-unitary and therefore spherical \cite{EGNO15}. By \cite[Theorem 4.3]{WLL21}, the determinant of the left multiplication matrix of $Z$ (as defined in \S\ref{sub:formal}) has the same prime divisors as the Frobenius-Schur exponent of $\mathcal{C}$, which in turn shares its prime divisors with $\FPdim(\mathcal{R})$ by \cite[Theorem 8.4]{NS07}.  

Since $ Z $ is diagonalizable with eigenvalues $ n_V f_V $, each having multiplicity $ n_V^2 $, its determinant is
\[
\prod_{V \in {\rm Irr}(\mathcal{R}_{\mathbb{C}})} (n_V f_V)^{n_V^2}.  
\]  
Finally, because $f_V$ is an integer dividing $\FPdim(\mathcal{R})$ (see \S\ref{sub:formal}), we can ignore the exponent ${n_V^2}$ when considering prime divisors, proving the result.  
\end{proof}

It follows directly from Proposition \ref{prop:DimDet} that:  

\begin{corollary}   \label{cor:OddNC}
Let $ \mathcal{C} $ be an integral fusion category over $ \mathbb{C} $, and let $ \mathcal{R} $ be its Grothendieck ring. If a prime $ p $ does not divide $ \FPdim(\mathcal{R}) $, then it also does not divide $ n_V $ for all $ V \in {\rm Irr}(\mathcal{R}_{\mathbb{C}}) $. In particular, if $ \FPdim(\mathcal{R})$ is odd, then every irreducible representation of $ \mathcal{R}_{\mathbb{C}} $ is also odd-dimensional. Moreover, if $ \mathcal{R} $ is noncommutative, there exists some $ V $ with $ n_V \geq 3 $. 
\end{corollary} 

\begin{corollary} \label{cor:Odd}  
An integral Grothendieck ring of odd global $\FPdim$ has odd rank.  
\end{corollary}

\begin{proof}
The claim follows by reducing modulo $2$ the identity from~\S\ref{sub:formal}:
\[
\sum_{V \in \mathrm{Irr}(\mathcal{R}_{\mathbb{C}})} \sum_{i=1}^{n_V^2} \frac{1}{n_V f_V} = 1,
\]
combined with the fact that both $n_V$ and $f_V$ are odd by Proposition~\ref{prop:DimDet}, and that the rank equals $\sum_V n_V^2$.
\end{proof}


Following the notation used in the proof of Proposition~\ref{prop:MNSDFormalCodegrees}, the lemma below is an immediate consequence of \cite[Corollary 2.16]{Os15}:

\begin{lemma} \label{lem:MultI(1)}
Let \( V \) be an irreducible representation of the complexified integral Grothendieck ring \( \mathcal{K}(\mathcal{C})_{\mathbb{C}} \). Then the corresponding simple object \( A_V \) in \( \mathcal{Z}(\mathcal{C}) \) appears as a direct summand of \( I(\one) \) with multiplicity \( \dim(V) \).
\end{lemma}

