\subsection{Constrained quantization when the constraint is the two sides of an equilateral triangle} \label{sub12}  Let us consider the equilateral triangle with vertices $A(-3, 0)$, $B(3, 0)$, and $C(0, 3\sqrt 3)$. Let $S_1$ and $S_2$ represent the sides $AC$ and $BC$, respectively. In this subsection, we take the constraint as $S:=S_1\uu S_2$. Notice that $S_1$ and $S_2$ can be represented as follows: 
\begin{align}
S_1=\set{(x, \sqrt{3}(x + 3)) : -3\leq x\leq 0} \te{ and } S_2=\set{(x, \sqrt{3}(-x + 3)) : 0\leq x\leq 3}. 
\end{align} 


 \begin{prop1}\label{propD1} 
An optimal set of one-point is given by $\set{(-\frac{9}{4},\frac{3 \sqrt{3}}{4})}$ or $\set{(\frac{9}{4},\frac{3 \sqrt{3}}{4})}$ with constrained quantization error $V_1=\frac{43}{4}$.
\end{prop1}

\begin{proof} Let $\ga:=\set{(a, b)}$ be an optimal set of one-point. The following two cases can happen:

\tit{Case~1. $(a, b)\in S_1$.}

In this case, $b= \sqrt{3}(a + 3)$ for some $-3\leq a\leq 0$.  Then, the distortion error is given by
\[V(P; \ga)=\sum_{j=-3}^3\frac 17 \rho(t, (a, b))=4 a^2+18 a+31,\]
the minimum value of which is $\frac{43}{4}$, and it occurs when $a=-\frac 94$.


\tit{Case~2. $(a, b)\in S_2$.}

In this case, $b=\sqrt{3}(-a + 3)$ for some $0\leq a\leq 3$. Then, the distortion error is given by
\[V(P; \ga)=\sum_{j=-3}^3\frac 17 \rho(t, (a, b))=4 a^2-18 a+31,\]
the minimum value of which is $\frac{43}{4}$, and it occurs when $a=\frac 94$.


Hence, an optimal set of one-point is given by either $\set{(-\frac{9}{4},\frac{3 \sqrt{3}}{4})}$ or $\set{(\frac{9}{4},\frac{3 \sqrt{3}}{4})}$ with constrained quantization error $\frac{43}{4}$, which is the proposition.
\end{proof}


\begin{prop1} \label{propD2} 
An optimal set of two-points is $\set{(-\frac{11}{4}, \frac{\sqrt{3}}{4}), (\frac{21}{8},  \frac{3 \sqrt{3}}{8})}$, or $\set{(-\frac{21}{8},\frac{3 \sqrt{3}}{8}), (\frac{11}{4},\frac{\sqrt{3}}{4}) }$ with constrained quantization error $V_2=\frac{16}{7}.$
\end{prop1}

\begin{proof} 

Let $\ga_2$ be an optimal set of two-points. The following cases can arise: 

\tit{Case~1: Both the elements are on $S_1$.}

 Then, we can write 
 \[\ga_2:=\set{(a_1, \sqrt{3}(a_1 + 3)), (a_2, \sqrt{3}(a_2 + 3))}, \te{ where } -3\leq a_1<a_2\leq 0.\]
Let $(n_1, n_2)$ be a canonical vector associated with $\ga_2$. Then, all possible values $(n_1, n_2)$ are given by \[\{(1,6),\ (2,5),\ (3,4),\ (4,3),\ (5,2),\ (6,1)\}.\]
Using the formula \eqref{eq890}, we see that the $V_{n_1, n_2}$ is minimum if $(n_1, n_2)=(3,4) \te{ or } (4,3)$, and the minimum value is given by 
\[V_{3,4}=V_{4,3}=10.\]

\tit{Case~2: Both the elements are on $S_2$.}

This case is the reflection of Case~1 with respect to the line $x=0$. 

\tit{Case~3: One element is on $S_1$ and one element is on $S_2$.}

 In this case, we can write $\ga=\set{(a_1, \sqrt{3}(a_1 + 3)), (a_2, \sqrt{3}(-a_2 + 3))}$, where $-3\leq a_1\leq 0 \leq a_2\leq 3$ and $a_1< a_2$. 
Then, all possible values of the canonical vector $(n_1, n_2)$ are given by \[\{(1,6),\ (2,5),\ (3,4),\ (4,3),\ (5,2),\ (6,1)\}.\]
Using the formula \eqref{eq890}, we see that the $V_{n_1, n_2}$ is minimum if $(n_1, n_2)=(3,4) \te{ or } (4,3)$, and the minimum value is given by 
\[V_{3,4}=V_{4,3}=\frac{16}{7},\]
and it occurs when $(a_1= -\frac{11}{4} \te{ and } a_2=\frac{21}{8})$,  or $(a_1= -\frac{21}{8} \te{ and } a_2=\frac{11}{4})$. 

Comparing Case~1 through Case~3, we can deduce that an optimal set of two-points is given by  $\set{(-\frac{11}{4}, \frac{\sqrt{3}}{4}), (\frac{21}{8},  \frac{3 \sqrt{3}}{8})}$, or $\set{(-\frac{21}{8},\frac{3 \sqrt{3}}{8}), (\frac{11}{4},\frac{\sqrt{3}}{4}) }$ with constrained quantization error $V_2=\frac{16}{7}.$
\end{proof}

 \begin{prop1} \label{propD1} 
An optimal set of three-points is given by 
\[\set{(-\frac{23}{8},\frac{\sqrt{3}}{8}),(-\frac{19}{8},\frac{5 \sqrt{3}}{8}), (\frac{11}{4},\frac{\sqrt{3}}{4})}\] with constrained quantization error $V_3=\frac{15}{7}$.
\end{prop1}

\begin{proof}
Let $\ga_3$ be an optimal set of three-points. 
  The following two cases can arise:


\tit{Case~1: All the elements are on one side.}

In this case, without any loss of generality, we can assume that all the elements are on $S_1$. Then, we can write 
\[\ga_3=\set{(a_i, \sqrt 3 (a_i+3)) : 1\leq i\leq 3}, \te{ where } -3\leq a_1<a_2<a_3\leq 0.\]
If $(n_1, n_2, n_3)$ be a canonical vector, then $(n_1, n_2, n_3)$ can be an  element  from the set 
\begin{align*}
&\set{(1,1,5),\ (1,2,4),\ (1,3,3), (1,4,2),\ (1,5,1),   (2,1,4),\ (2,2,3),\ (2,3,2),\ (2,4,1),  \\
&
 (3,1,3),\ (3,2,2),\ (3,3,1),    (4,1,2),\ (4,2,1),\ (5,1,1)}.
 \end{align*} 

 Considering all the possible values of $V_{n_1, n_2, n_3}(P; \ga)$, we see that the minimum value of $V_{n_1, n_2, n_3}(P; \ga)$ is $\frac{69}{7}$ and it occurs when 
 \[(n_1, n_2, n_3)=(2,2,3), (2,3,2), \te{ or }(3,2,2).\]


\tit{Case~2: Two elements are on one side and one element on another side.}

Without any loss of generality, we can assume that two elements are on side $S_1$ and one element on side $S_2$. Then, we can write 
\[\ga_3=\set{(a_1, \sqrt 3 (a_1+3)),  (a_2, \sqrt 3 (a_2+3)), (a_3, \sqrt 3 (-a_3+3))}, \te{ where } -3\leq a_1<a_2\leq 0\leq a_3\leq 3.\]
 If $(n_1, n_2, n_3)$ be a canonical vector, then $(n_1, n_2, n_3)$ can be an  element  from the set 
\begin{align*}
&\set{(1,1,5),\ (1,2,4),\ (1,3,3), (1,4,2),\ (1,5,1),   (2,1,4),\ (2,2,3),\ (2,3,2),\ (2,4,1),  \\
&
 (3,1,3),\ (3,2,2),\ (3,3,1),    (4,1,2),\ (4,2,1),\ (5,1,1)}.
 \end{align*}
  Considering all the possible values of $V_{n_1, n_2, n_3}(P; \ga)$, we see that the minimum value of $V_{n_1, n_2, n_3}(P; \ga)$ is $\frac{15}{7}$ and it occurs when 
$(n_1, n_2, n_3)=(2,2,3),$ 
 and $a_1=-\frac{23}{8}, \, a_2=-\frac{19}{8}$, and $a_3=\frac{11}{4}$. 

Taking into account, Case~1 and Case~2, we deduce that the set $\set{(-\frac{23}{8},\frac{\sqrt{3}}{8}),(-\frac{19}{8},\frac{5 \sqrt{3}}{8}), (\frac{11}{4},\frac{\sqrt{3}}{4})}$ forms an optimal set of three-points with constrained quantization error $V_3=\frac{15}{7}$. 
 \end{proof} 

 \begin{remark1}
Due to the maximum symmetry of the equilateral triangle with respect to the median passing through the vertex $C$, there is another optimal set of three-points which is the reflection with respect to the median with the same constrained quantization error $V_3=\frac{15}{7}$. 
 \end{remark1} 

  \begin{prop1}  
The set $\set{(-3,0),  (-\frac{21}{8},\frac{3 \sqrt{3}}{8}), (\frac{19}{8},\frac{5 \sqrt{3}}{8}), (\frac{23}{8},\frac{\sqrt{3}}{8})}$ forms an optimal set of four-points with constrained quantization error $V_4= \frac{117}{56}$, and there are four different optimal sets of four-points
\end{prop1}
 \begin{proof}
 Let $\ga_4$ be an optimal set of four-points. Due to the maximum symmetry of the equilateral triangle with respect to the median passing through the vertex $C$, we can assume that $\ga_4$ will contain two elements from $S_1$ and two elements from $S_2$. In fact, it is not difficult to show it.  Then, we can write 
\[\ga_4=\set{(a_1, \sqrt 3 (a_1+3)),  (a_2, \sqrt 3 (a_2+3)), (a_3, \sqrt 3 (-a_3+3)), (a_4, \sqrt 3 (-a_4+3))},\]
 where $-3\leq a_1<a_2\leq 0\leq a_3<a_4\leq 3$. 
 If $(n_1, n_2, n_3,n_4)$ be a canonical vector, then $(n_1, n_2, n_3, n_4)$ can be an  element  from the set 
\begin{align*}
