& (1,4,1,1),(2,1,1,3),(2,1,2,2),(2,1,3,1),(2,2,1,2),(2,2,2,1),(2,3,1,1),(3,1,1,2),(3,1,2,1),\\
&(3,2,1,1),(4,1,1,1)}.
 \end{align*}
  Considering all the possible values of $V_{n_1, n_2, n_3, n_4}(P; \ga)$, we see that the minimum value of $V_{n_1, n_2, n_3}(P; \ga)$ is $\frac{117}{56}$, and it occurs when 
 \[(n_1, n_2, n_3, n_4)=(1,2,2,2), (2,1,2,2), (2,2,1,2), \te{ or } (2,2,2,1).\]
 We see that
 \begin{equation} \label{eq90}  
\begin{aligned}
 (n_1, n_2, n_3, n_4)&=(1,2,2,2) \im  a_1= -3, a_2= -\frac{21}{8}, a_3= \frac{19}{8}, a_4= \frac{23}{8},\\
  (n_1, n_2, n_3, n_4)&=(2, 1, 2, 2) \im  a_1= -\frac{23}{8}, a_2= -\frac{5}{2}, a_3= \frac{19}{8}, a_4= \frac{23}{8},\\
   (n_1, n_2, n_3, n_4)&=(2, 2, 1, 2) \im  a_1= -\frac{23}{8}, a_2= -\frac{19}{8}, a_3= \frac{5}{2}, a_4= \frac{23}{8},\\ 
   (n_1, n_2, n_3, n_4)&=(2, 2, 2, 1) \im  a_1= -\frac{23}{8}, a_2= -\frac{19}{8}, a_3= \frac{21}{8},a_4= 3. 
