 \section{Constrained quantization for a finite nonuniform discrete distribution} \label{sec2} 
Let $P$ be a finite nonuniform distribution with support $\set{-3, -2, -1, 0, 1, 2, 3}$ such that the probability mass function $f$ for $P$ is given by
 \[f(x)=P(X : X=j)=\left\{\begin{array}{cc}
 \frac 1{2^{4+j}},  & \te{ where } j\in \set{-3, -2, -1, 0, 1, 2},   \\
 \frac 1{2^6} &\te { if } j=3\\
  0 & \te{otherwise}.
 \end{array}
 \right.\]
In the following two subsection we calculate the constrained optimal set of $n$-points for the probability distribution $P$ for all possible values of $n\in \D N$ with respect to two different constraints. 

 \subsection{Constrained quantization when the constraint is a semicircular arc} As mentioned in Subsection~\ref{sub11}, here the constraint is the semicircular arc
 \[S=\set{(3\cos \gq, 3\sin \gq): 0\leq \gq\leq \pi}.\]
Due to the same reasoning as mentioned in Subsection~\ref{sub11}, we can say that the optimal sets of $n$-points exist only for $n=1$ and $n=2$, and they do not exist for any $n\geq 3$.

In the following two propositions, we calculate the optimal sets of $n$-points for $n=1$ and $n=2$. 
\begin{prop1}
	The set $\set{(-3, 0)}$ forms the optimal set of one-point with constrained quantization error $V_1=\frac{177}{64}$.
\end{prop1}

\begin{proof} Let $(3\cos \gq, 3\sin \gq)$ be an element on the circle. Then, the distortion error for $P$ with respect to the element is given by
	\begin{align*}
		V(P; \set{(3\cos \gq, 3\sin \gq)})&= \sum_{j=-3}^2 f(j)\rho(j, (3\cos \gq, 3\sin \gq))+f(3)\rho(3,(3\cos \gq, 3\sin \gq))\\
& = \frac{1}{64} (774 \cos \gq +951)
		\end{align*}
	which is minimum when $\gq=\pi$. Hence, the  set $\set{(-3, 0)}$ forms the optimal set of one-point with constrained quantization error $V_1=\frac{177}{64}$.
\end{proof}

\begin{prop1} \label{prop11} 
	The set $\set{(-3, 0), (3, 0)}$ forms an optimal set of two-points with constrained  quantization error $V_2=\frac{93}{64}$.
\end{prop1}
\begin{proof} Let $\set{(3\cos \gq_1, 3\sin \gq_1), (3\cos \gq_2, 3\sin \gq_2)}$ be an optimal set of two-points, where $0\leq \gq_1<\gq_2\leq \pi$. 
As mentioned in Proposition~\ref{prop110}, the support element $0$ falls on the boundary of the two Voronoi regions. Hence, without any loss of generality, we can assume that the support element $0$ belongs to the Voronoi region of $(3\cos \gq_2, 3\sin \gq_2)$. Then, the distortion error is given by 
	\begin{align*}
		&V(P; \set{(3\cos \gq_1, 3\sin \gq_1), (3\cos \gq_2, 3\sin \gq_2)})\\
&= \sum_{j=-3}^{0}f(j)\rho(j, (3\cos \gq_2, 3\sin \gq_2))+\sum_{j=1}^{2}f(j)\rho(j, (3\cos \gq_1, 3\sin \gq_1))+f(3)\rho(3, (3\cos \gq_1, 3\sin \gq_1))\\
&=\frac{1}{64} \left(-42 \cos \gq_1+816 \cos \gq_2+951\right)
		\end{align*}
which is minimum if $\gq_1=0$ and $\gq_2=\pi$, and the minimum value is $\frac{93}{64}$. Thus, the set $\set{(-3, 0), (3, 0)}$ forms an optimal set of two-points with constrained  quantization error $V_2=\frac{93}{64}$.
\end{proof} 
\subsection{Constrained quantization when the constraint is the two sides of an equilateral triangle}  As mentioned in Subsection~\ref{sub12}, here the constraint is  $S:=S_1\uu S_2$, where $S_1$ and $S_2$ are the sides $AC$ and $BC$ of the equilateral triangle $ABC$. 
 Recall that \begin{align}
S_1=\set{(x, \sqrt{3}(x + 3)) : -3\leq x\leq 0} \te{ and } S_2=\set{(x, \sqrt{3}(-x + 3)) : 0\leq x\leq 3}. 
\end{align} 
The following proposition gives the main results in this subsection. The techniques of the proof are similar to the proofs given in the propositions in Subsection~\ref{sub12}. 
