   \begin{enumerate}
  \item $\ga_1=\set{(-\frac{705}{256},\frac{63 \sqrt{3}}{256})}$ with $V_1=\frac{41343}{16384}$.
      \medskip
    \item $\ga_2=\set{(-\frac{45}{16},\frac{3 \sqrt{3}}{16}), (\frac{21}{8},\frac{3 \sqrt{3}}{8})}$ with $V_2=\frac{259}{1024}$.
