 \item $\ga_3=\set{(-\frac{23}{8},\frac{\sqrt{3}}{8}), (-\frac{19}{8},\frac{5 \sqrt{3}}{8}), (\frac{11}{4},\frac{\sqrt{3}}{4})} \te{ with } V_3=\frac{361}{1536}.$
     \medskip
  \item $\ga_4=\set{(-3,0), (-\frac{21}{8},\frac{3 \sqrt{3}}{8}), (\frac{19}{8},\frac{5 \sqrt{3}}{8}), (\frac{23}{8},\frac{\sqrt{3}}{8})} \te{ with } V_4=\frac{117}{512}.$
