\section{Constrained quantization for an infinite discrete distribution with support $\set{\frac 1 n : n\in \D N}$} \label{sec3}

Let $\D N:=\set{1, 2, 3, \cdots}$ be the set of natural numbers, and let $P$ be a Borel probability measure on the set $\set{\frac 1 n : n \in \D N}$ with probability mass function $f$ given by
\[f(x)=\left\{\begin{array} {ll} \vspace{0.05 in}
\frac 1{2^k} & \te{ if } x =\frac 1 k \te { for } k\in \D N,\\ \vspace{0.05 in}
0 &  \te{ otherwise}.
\end{array}
\right.\]
Then, $P$ is a Borel probability measure on $\D R$, and the support of $P$ is given by supp$(P)=\set{\frac 1 n :  n \in \D N}$.  
  In this section, for the probability measure $P$, we investigate the constrained optimal sets of $n$-points and the $n$th constrained quantization errors for $n\in \D N$ with respect to two constraints: one is the semicircular arc with base the closed interval $[0, 1]$, and one is the two sides of an equilateral triangle with base $[0, 1]$ 

 \subsection{Constrained quantization when the constraint is a semicircular arc}  
  In this case let us take the constraint $S$ as the upper semicircular arc of the circle $(x-\frac 12)^2+y^2=\frac 1 4$, i.e.,  
 \[S:=\set{(x, y) : (x-\frac 12)^2+y^2=\frac 12  \te{ and } y\geq 0}.\]
 Notice that $S$ can also be represented by 
 \[S=\set{(\frac 12 (1+\cos \gq), \frac 12 \sin \gq): 0\leq \gq\leq \pi}.\]
We know that an optimal set of one-point always exists. For any $n\geq 2$, since the boundary of the Voronoi regions of any two optimal elements, in this case, passes through the center of the circle, from the geometry, we see that among $n$ Voronoi regions, only two Voronoi regions contain elements from the support of $P$, i.e., only two Voronoi regions have positive probability. Hence, the optimal sets of $n$-points exist only for $n=1$ and $n=2$, and they do not exist for any $n\geq 3$. 

We now calculate the optimal sets of one-point and the two-points in the following propositions.

\begin{prop1}
	An optimal set of one-point is given by $\set{(1, 0)}$  with constrained quantization error $V_1=\frac{1}{12} \left(\pi ^2-6 \left(-2+\log ^22+\log 16\right)\right)$.
\end{prop1}

\begin{proof} Let $(\frac 12 (1+\cos \gq), \frac 12 \sin \gq)$ be an element on the circle. Then, the distortion error for $P$ with respect to this element is given by
	\begin{align*}
		&V(P; \set{(\frac 12 (1+\cos \gq), \frac 12 \sin \gq)})= \sum_{j=1}^\infty \frac 1{2^j} \rho\Big(\frac 1 j, (\frac 12 (1+\cos \gq), \frac 12 \sin \gq)\Big) \\
&=\frac{1}{12} \left((6-12 \log 2) \cos \theta +\pi ^2-6 \left(-1+\log ^22+\log 4\right)\right),
		\end{align*}
	which is minimum when $\gq=0$, and the minimum value is $\frac{1}{12} \left(\pi ^2-6 \left(-2+\log ^22+\log 16\right)\right)$. Thus, the proposition is yielded. 
\end{proof}

\begin{prop1} \label{prop11}
	The set $\set{(1, 0), (0, 0)}$ forms an optimal set of two-points with constrained  quantization error $V_2=\frac{1}{12} \left(\pi ^2-6-6 \log ^22-12 \log 2+6 \log 4\right)$.
\end{prop1}
\begin{proof} Let $\ga:=\set{(\frac 12 (1+\cos \gq_1), \frac 12 \sin \gq_1), (\frac 12 (1+\cos \gq_2), \frac 12 \sin \gq_2)}$ be an optimal set of two-points, where $0\leq \gq_1<\gq_2\leq \pi$. 
Since the boundary of any two elements on the circle passes through the center of the circle, in an optimal set of two-points, one Voronoi region will contain the elements to the left of $\frac 12$, and the other Voronoi region will contain the elements to the right of $\frac 12$. Notice that the support element $\frac 12$ falls on the boundary of the two Voronoi regions. In that case, as mentioned in Remark~\ref{rem1}, we can assume that  $\frac 12$ belongs to the Voronoi region of $(\frac 12 (1+\cos \gq_2), \frac 12 \sin \gq_2)$. Then, the distortion error is given by 
	\begin{align*}
		&V(P; \ga)\\
&= \sum_{j=2}^\infty \frac 1{2^j} \rho\Big(\frac 1 j, (\frac 12 (1+\cos \gq_2), \frac 12 \sin \gq_2)\Big)+\frac 12\rho\Big(1, (\frac 12 (1+\cos \gq_1), \frac 12 \sin \gq_1)\Big)\\
&=\frac{1}{12} \left(-3 \cos \theta _1+(9-6 \log 4) \cos \theta _2+\pi ^2+6-6 \log ^22-12 \log 2\right)
		\end{align*}
which is minimum if $\gq_1=0$ and $\gq_2=\pi$, and  $\frac{1}{12} \left(\pi ^2-6-6 \log ^22-12 \log 2+6 \log 4\right)$ is the minimum value. Thus, the proposition is yielded. 
\end{proof}
\subsection{Constrained quantization when the constraint is the two sides of an equilateral triangle}

Let us consider the equilateral triangle with vertices $A(0, 0)$, $B(1, 0)$, and $C(\frac 12, \frac{\sqrt 3}2)$. Let $S_1$ and $S_2$ represent the sides $BC$ and $AC$, respectively. In this subsection, we take the constraint as $S:=S_1\uu S_2$. Notice that $S_1$ and $S_2$ can be represented as follows: 
\begin{align}
S_1=\set{(x, \sqrt{3}(1-x)) : \frac 12 \leq x\leq 1} \te{ and }  S_2=\set{(x, \sqrt{3}x) : 0\leq x\leq \frac 12}. 
\end{align} 
 For $k, \ell\in \D N$, where $k\leq \ell$, write
\[[k, \ell]:=\set{\frac 1 n : n \in \D N \te{ and } k\leq n\leq \ell}, \te{ and } [k, \infty]:=\set{\frac 1 n : n\in \D N \te{ and } n\geq k}.\]
Further, write
\[Av[k, \ell]: =E\Big (X : X \in [k, \ell]\Big)=\frac{\sum _{n=k}^{\ell} \frac{1}{2^n} \frac 1 n}{\sum_{n=k}^{\ell}\frac{1}{2^n}}, \  Av[k, \infty]: =E\Big (X : X \in [k, \infty)\Big)=\frac{\sum _{n=k}^{\infty} \frac{1}{2^n} \frac 1 n}{\sum_{n=k}^{\infty}\frac{1}{2^n}},\]
\[Er[k, \ell]:=\sum _{n=k}^{\ell} \frac{1}{2^n} \Big(\frac 1 n-Av[k, \ell]\Big)^2, \te{ and } Er[k, \infty]:=\sum _{n=k}^{\infty} \frac{1}{2^n} \Big(\frac 1 n-Av[k,\infty)\Big)^2.\]

\begin{note} \label{note11}
The perpendicular through a point $(a, \sqrt 3(1-a))$ on the line $y=\sqrt 3(1-x)$ intersects the segment $[0, 1]$ at the point $(4a-3,0)$, where  $0\leq 4a-3\leq 1$, i.e., $\frac 34\leq a\leq 1$. 
The perpendicular through a point $(b, b\sqrt 3)$ on the line $y= \sqrt 3x$ intersects the segment $[0, 1]$ at the point $(4b, 0)$, where $0\leq 4b\leq 1$, i.e., $0\leq b\leq \frac 14$. 
Write
\begin{align*}
S_1^{(1)}:&=\set{(x, \sqrt 3(1-x)) : \frac 34\leq x\leq 1}, \te{ and } \\
S_2^{(2)}:&=\set{(x, \sqrt 3x) : 0\leq x\leq \frac 14}.
\end{align*} 
Then, there exist two bijective functions $U_1$ and $U_2$, such that 

\begin{equation} \label{eq1} 
\begin{aligned} &U_1 : [0, 1] \to S_1^{(1)} \te{ such that } U_1(x)=(\frac 14 (3+x), \frac{\sqrt 3}4 (1-x)), \te { and } \\
&U_2 : [0, 1] \to S_2^{(2)} \te{ such that } U_2(x)=(\frac 14 x, \frac{\sqrt 3}4 x).
\end{aligned} 
\end{equation} 
Let $\ga_n$ be an optimal set of $n$-points for some $n\in \D N$. Then, we must have 
\[\ga_n=(\ga_n\ii S_1^{(1)})\uu (\ga_n\ii S_2^{(2)}).\]
Suppose that both $\ga_n\ii S_1^{(1)}$ and $\ga_n\ii S_2^{(2)}$ are nonempty. Then, for some $\ell, m\in \D N$, we can write 
\begin{align*}
\ga_n\ii S_1^{(1)} &=\set{(a_\ell,  \sqrt 3(1-a_\ell)), (a_{\ell-1}, \sqrt 3 (1-a_{\ell-1})), \cdots, (a_1, \sqrt 3(1-a_1))}, \te{ and }\\
 \ga_n\ii S_2^{(2)} & =\set{ (a_{\ell+m},  \sqrt 3 a_{\ell+m}), (a_{\ell+m-1},  \sqrt 3 a_{\ell+m-1}), \cdots, (a_{\ell+2},  \sqrt 3 a_{\ell+2}), (a_{\ell+1},  \sqrt 3 a_{\ell+1}))}.
 \end{align*} 
 such they satisfy the following order:
 \[ 0\leq a_{\ell+m}<a_{\ell+m-1}<\cdots<a_{\ell+1}\leq \frac 12 \leq a_{\ell} <a_{\ell-1}<\cdots<a_2\leq a_1.\]
Then, the elements $(a_i, \sqrt 3(1-a_i))$ and $(a_{i+1}, \sqrt 3(1-a_{i+1}))$ for $1\leq i\leq \ell-1$;  $(a_\ell,\sqrt 3(1-a_\ell))$ and $(a_{\ell+1},  \sqrt 3 a_{\ell+1})$; and $(a_{\ell+j},  \sqrt 3 a_{\ell+j})$ and $(a_{\ell+j+1},  \sqrt 3 a_{\ell+j+1})$ for $1\leq j\leq m-1$, are the adjacent elements. 
\end{note}

\begin{notation}
To be specific, in this subsection,  $V_n^{(c)}$ represents the constrained quantization error for $n$-points, and $V_n^{(u)}$ represents the unconstrained quantization error for $n$-means with respect to the probability distribution $P$.
\end{notation} 


The following proposition plays an important role.

\begin{prop1} \label{propim} 
Let $\ga_n:=\set{c_j : 1\leq j\leq k+m}$, where $\te{card}(\ga_n\ii S_1^{(1)})=k$ and $\te{card}(\ga_n\ii S_1^{(2)})=m$. Then,  $\ga_n$ is a  constrained optimal set of $n$-points for $P$ if and only if  $U_1^{-1}(\ga_n\ii S_1^{(1)})\uu U_2^{-1}(\ga_n\ii S_2^{(2)})$ forms an unconstrained optimal set of $n$-means for $P$, and \begin{equation*} V_n^{(c)}=V_n^{(u)}+\frac 34 \sum_{j=1}^{k}\sum_{i=q_j^{(1)}}^{q_j^{(2)}}\frac 1{2^i}(1-Av[q_j^{(1)}, q_j^{(2)}])^2 +\frac 34 \sum_{j=k+1}^{k+m}\sum_{i=q_j^{(1)}}^{q_j^{(2)}}\frac 1{2^i}(Av[q_j^{(1)}, q_j^{(2)}])^2,
\end{equation*} 
where the Voronoi region of $c_j$ contains the set $[q_j^{(1)}, q_j^{(2)}]$ from the support of $P$ for $1\leq j\leq n$, where $q_n^{(2)}=\infty$. 
\end{prop1} 

\begin{proof}
Let $\ga_n$ be a constrained optimal set of $n$-points for $P$. Let $\te{card}(\ga_n\ii S_1^{(1)})=k$ and $\te{card}(\ga_n\ii S_2^{(2)})=m$. Then, we can write 
\[\ga_n=\Big\{(a_1, \sqrt 3(1-a_1)), (a_2, \sqrt 3(1-a_2)), \cdots, (a_k, \sqrt 3 (1-a_k)), (a_{k+1}, \sqrt 3a_{k+1}), \cdots, (a_{k+m}, \sqrt 3 a_{k+m})\Big\},\]
where $0\leq a_{k+m}<a_{k+m-1}<\cdots<a_{k+1}\leq \frac 12 \leq a_k<\cdots<a_2<a_1\leq 1$ and $k+m=n$. Let $c_j=(a_j, \sqrt 3(1-a_j))$ if $1\leq j\leq k$, and $c_j=(a_j, \sqrt 3a_j)$ if $k+1\leq j\leq k+m$.   Let the Voronoi region of $c_j$ contains the set $[q_j^{(1)}, q_j^{(2)}]$ from the support of $P$ for $1\leq j\leq n$, where $q_n^{(2)}=\infty$. 
Then, we have 
\begin{align*}
V_n^{(c)}=\sum_{j=1}^k \sum_{i=q_j^{(1)}}^{q_j^{(2)}}\frac 1{2^i} \rho\Big(\frac 1 i, (a_j, \sqrt 3(1-a_j))\Big)+ \sum_{j=k+1}^{k+m} \sum_{i=q_j^{(1)}}^{q_j^{(2)}}\frac 1{2^i} \rho\Big(\frac 1 i, (a_j, \sqrt 3 a_j)\Big). 
\end{align*}
Notice that for $1\leq j\leq k$, the distortion error contributed by $c_j$ on its own Voronoi region is given by 
\begin{align*}
 &\sum_{i=q_j^{(1)}}^{q_j^{(2)}}\frac 1{2^i} \rho\Big(\frac 1 i, (a_j, \sqrt 3(1-a_j))\Big)\\
 &=\sum_{i=q_j^{(1)}}^{q_j^{(2)}}\frac 1{2^i}\Big((\frac 1 i -a_j)^2+(\sqrt 3(1-a_j))^2\Big)\\
 &=\sum_{i=q_j^{(1)}}^{q_j^{(2)}}\frac 1{2^i} \Big(\Big((\frac 1 i -\frac 14(3+Av[q_j^{(1)}, q_j^{(2)}]))+(\frac 14(3+Av[q_j^{(1)}, q_j^{(2)}])-a_j)\Big)^2 +(\sqrt 3 (1-a_j))^2\Big)\\
&=\sum_{i=q_j^{(1)}}^{q_j^{(2)}}\frac 1{2^i} \Big( (\frac 1 i -\frac 14(3+Av[q_j^{(1)}, q_j^{(2)}]))^2+2(\frac 1 i -\frac 14(3+Av[q_j^{(1)}, q_j^{(2)}]))(\frac 14(3+Av[q_j^{(1)}, q_j^{(2)}])-a_j)\\
&\qquad \qquad + (\frac 14(3+Av[q_j^{(1)}, q_j^{(2)}])-a_j)^2 +(\sqrt 3 (1-a_j))^2\Big)\\
&=\sum_{i=q_j^{(1)}}^{q_j^{(2)}}\frac 1{2^i} \Big((\frac 1 i -\frac 14(3+Av[q_j^{(1)}, q_j^{(2)}]))^2+(\sqrt 3 (1-a_j))^2\Big) \\
&+2(\frac 14(3+Av[q_j^{(1)}, q_j^{(2)}])-a_j)\sum_{i=q_j^{(1)}}^{q_j^{(2)}}\frac 1{2^i}(\frac 1 i -\frac 14(3+Av[q_j^{(1)}, q_j^{(2)}]))+(\frac 14(3+Av[q_j^{(1)}, q_j^{(2)}])-a_j)^2 \sum_{i=q_j^{(1)}}^{q_j^{(2)}}\frac 1{2^i}  \\
&=\sum_{i=q_j^{(1)}}^{q_j^{(2)}}\frac 1{2^i} \Big((\frac 1 i -\frac 14(3+Av[q_j^{(1)}, q_j^{(2)}]))^2+(\sqrt 3 (1-a_j))^2\Big)  +(\frac 14(3+Av[q_j^{(1)}, q_j^{(2)}])-a_j)^2 \sum_{i=q_j^{(1)}}^{q_j^{(2)}}\frac 1{2^i}.
\end{align*}
Notice that the above distortion error is minimum if $a_j=\frac 14(3+Av[q_j^{(1)}, q_j^{(2)}])$,
 and then
\[c_j=(\frac 14(3+Av[q_j^{(1)}, q_j^{(2)}]), \frac{\sqrt 3}4 (1- Av[q_j^{(1)}, q_j^{(2)}]))=U_1(Av[q_j^{(1)}, q_j^{(2)}])\] and the distortion error contributed by $c_j$ on its own Voronoi region is given by 
\[\sum_{i=q_j^{(1)}}^{q_j^{(2)}}\frac 1{2^i} \rho(\frac 1 i, U_1(Av[q_j^{(1)}, q_j^{(2)}])).\]
Similarly, for $k+1\leq j\leq k+m$, the distortion error  $\sum_{i=q_j^{(1)}}^{q_j^{(2)}}\frac 1{2^i} \rho\Big(\frac 1 i, (a_j, \sqrt 3 a_j)\Big)$ is minimum if $a_j=\frac 14 Av[q_j^{(1)}, q_j^{(2)}]$, and then 
\[c_j=(\frac 14 Av[q_j^{(1)}, q_j^{(2)}], \frac{\sqrt 3}4 Av[q_j^{(1)}, q_j^{(2)}])=U_2(Av[q_j^{(1)}, q_j^{(2)}])\] and the distortion error contributed by $c_j$ on its own Voronoi region is given by 
\[\sum_{i=q_j^{(1)}}^{q_j^{(2)}}\frac 1{2^i} \rho(\frac 1 i, U_2(Av[q_j^{(1)}, q_j^{(2)}])).\]
Thus, we see that 
\begin{equation} \label{eq001}
\ga_n=\Big\{U_1(Av[q_j^{(1)}, q_j^{(2)}]) : 1\leq j\leq k\Big\}\UU\Big\{U_2(Av[q_j^{(1)}, q_j^{(2)}]) : k+1\leq j\leq k+m\Big\}
\end{equation} 
forms a constrained optimal set of $n$-points for $P$ with constrained quantization error 
\begin{align*}
V_n^{(c)}=\sum_{j=1}^k \sum_{i=q_j^{(1)}}^{q_j^{(2)}}\frac 1{2^i} \rho(\frac 1 i, U_1(Av[q_j^{(1)}, q_j^{(2)}]))+\sum_{j=k+1}^{k+m}\sum_{i=q_j^{(1)}}^{q_j^{(2)}}\frac 1{2^i} \rho(\frac 1 i, U_2(Av[q_j^{(1)}, q_j^{(2)}]))
\end{align*} 
Let us consider the set $\gb_n$ given by 
\begin{equation} \label{eq002}\gb_n=\Big\{Av[q_j^{(1)}, q_j^{(2)}] : 1\leq j\leq k+m\Big\}.\end{equation} 
Notice that the unconstrained distortion error for $P$ with respect to the set $\gb_n$, denoted by $V(P; \gb_n)$, is defined as  
\[V(P; \gb_n)=\sum_{j=1}^{k+m} \sum_{i=q_j^{(1)}}^{q_j^{(2)}}\frac 1{2^i}(\frac 1 i -Av[q_j^{(1)}, q_j^{(2)}])^2.\]
After some calculation, we see that 
\begin{equation} \label{eqim} V_n^{(c)}=V(P; \gb_n)+\frac 34 \sum_{j=1}^{k}\sum_{i=q_j^{(1)}}^{q_j^{(2)}}\frac 1{2^i}(1-Av[q_j^{(1)}, q_j^{(2)}])^2 +\frac 34 \sum_{j=k+1}^{k+m}\sum_{i=q_j^{(1)}}^{q_j^{(2)}}\frac 1{2^i}(Av[q_j^{(1)}, q_j^{(2)}])^2.
\end{equation}
From the above expression, we see that $V_n^{(c)}$ will be minimum if and only if the distortion error $V(P; \gb_n)$ is minimum with respect to all possible subsets of $\te{supp}(P)$ with cardinality $n$, i.e., when $V(P; \gb_n)$ becomes $V_n^{(u)}$. Thus, we can say that the set $\ga_n$ given by \eqref{eq001}  will be a constrained optimal set of $n$-points for $P$ if and only if the set $\gb_n$ given by \eqref{eq002}  becomes an unconstrained optimal set of $n$-means for $P$. 

As $U_1$ and $U_2$ are bijective functions, by \eqref{eq001} and \eqref{eq002}, we see that if $\ga_n$ is a constrained optimal set of $n$-points and $\gb_n$ is an unconstrained optimal set of $n$-means, then 
\[U_1^{-1}(\ga_n\ii S_1^{(1)})\uu U_2^{-1}(\ga_n\ii S_2^{(2)})=\gb_n,\] 
and by \eqref{eqim}, we have 
\begin{equation*} V_n^{(c)}=V_n^{(u)}+\frac 34 \sum_{j=1}^{k}\sum_{i=q_j^{(1)}}^{q_j^{(2)}}\frac 1{2^i}(1-Av[q_j^{(1)}, q_j^{(2)}])^2 +\frac 34 \sum_{j=k+1}^{k+m}\sum_{i=q_j^{(1)}}^{q_j^{(2)}}\frac 1{2^i}(Av[q_j^{(1)}, q_j^{(2)}])^2.
\end{equation*} Thus, the proof of the proposition is complete. 
\end{proof} 
 \begin{prop1}\label{propD1} 
An constrained optimal set of one-point is given by $\set{(\frac{1}{4} (3+\log 2),\frac{1}{4} \sqrt{3} (1-\log 2))}$ with constrained quantization error \[V_1^{(c)}=\frac{1}{12} \left(\pi ^2-9 \left(-1+\log ^22+\log 4\right)\right).\]
\end{prop1}


\begin{proof} Let $\ga:=\set{(a, b)}$ be an optimal set of one-point. The following two cases can happen:

\tit{Case~1. $(a, b)\in S_1$.}

In this case, $b= \sqrt{3}(1-a)$ for some $\frac 12\leq a\leq 1$.  Then, the distortion error is given by
\[V(P; \ga)=\sum_{j=1}^\infty \frac 1{2^j} \rho(j, (a, b))=4 a^2-2 a (3+\log 2)+\frac{1}{12} \left(\pi ^2+36-6 \log ^22\right),\]
the minimum value of which is $\frac{1}{12} \left(\pi ^2-9 \left(-1+\log ^22+\log 4\right)\right)\approx 0.172407$, and it occurs when $a=\frac{1}{4} (3+\log 2)$.


\tit{Case~2. $(a, b)\in S_2$.}

In this case, $b=\sqrt{3}a$ for some $0\leq a\leq \frac 12$. Then, the distortion error is given by
\[V(P; \ga)=\sum_{j=1}^\infty \frac 1{2^j} \rho(j, (a, b))=4 a^2-a \log 4+\frac{1}{12} \left(\pi ^2-6 \log ^22\right),\]
the minimum value of which is $\frac{1}{12} \left(\pi ^2-\log ^28\right)\approx 0.462127$, and it occurs when $a=\frac{\log 2}{4}$.


Comparing the two distortion errors, we deduce that an optimal set of one-point is given by $\set{(\frac{1}{4} (3+\log 2),-\frac{1}{4} \sqrt{3} (\log 2-1))}$ with constrained quantization error $V_1=\frac{1}{12} \left(\pi ^2-9 \left(-1+\log ^22+\log 4\right)\right)$. 
\end{proof}

 \begin{remark1} \label{rem11}  Notice that
$E(X):=E(X : X \in \te{supp}(P)) =\sum _{n=1}^\infty \frac 1{2^n} \frac 1 n=Av[1, \infty]=\log 2$, and so the unconstrained optimal set of one-mean is the set $\set{\log 2}$ with unconstrained quantization error
\[V_1^{(u)}=\sum _{n=1}^{\infty} \frac 1 {2^n} \Big (\frac{1}{n}-\log 2\Big)^2=Er[1, \infty] =\frac{1}{12} \left(\pi ^2-18 \log ^2 2\right)=0.101788.\]
By Prposition~\ref{propD1}, we have $\ga_1=\set{(\frac{1}{4} (3+\log 2),\frac{1}{4} \sqrt{3} (1-\log 2))}$. Notice that 
\[U_1^{-1}(\ga_1\ii S_1^{(1)})\uu U_2^{-1}(\ga_n\ii S_2^{(2)})=U_1^{-1}(\ga_1\ii S_1^{(1)})=\set{\log 2},\]
which supports Proposition~\ref{propim} for $n=1$. 
\end{remark1} 
\begin{prop1} \label{propD2}
An optimal set of two-points is given by  
$\set{(1,0), (\frac{1}{4} (2\log 2-1),\frac{1}{4} \sqrt{3} (2\log 2-1))}$ with constrained quantization error 
\[ V_2^{(c)}=\frac{\pi ^2}{12}+\frac{1}{8} \left(-5-8 \log ^22+\log 16\right)\approx 0.0635876.\]
\end{prop1}

\begin{proof} 

Let $\ga_2$ be an optimal set of two-points. 

The following cases can arise:

\tit{Case~1: Both the elements are on $S_1$.}

Then, we can write $\ga_2=\set{(a_1, \sqrt 3(1-a_1)),  (a_2, \sqrt 3(1-a_2))}$ such that $\frac 12\leq a_2<a_1\leq 1$. 

Notice that the Voronoi region of $(a_1, \sqrt 3(1-a_1))$ must contain the element $1$ from the support of $P$. Assume that the Voronoi region of $(a_1, \sqrt 3(1-a_1))$ contains first $m$ elements from the support of $P$. Then, the remaining elements will be contained in the Voronoi region of $(a_2, \sqrt 3(1-a_2))$. Let $F(m)$ denote the minimum distortion error when the Voronoi region of $(a_1, \sqrt 3(1-a_1))$ contains first $m$ elements from the support of $P$. Then, we have 
\begin{align*}
F(m)=\min\Big\{ \sum_{j=1}^m \frac 1{2^j} \rho\Big(\frac 1 j, (a_1, \sqrt 3(1-a_1))\Big)+\sum_{j=m+1}^\infty \frac 1{2^j} \rho\Big(\frac 1 j, (a_2, \sqrt 3(1-a_2))\Big)   : \frac 12\leq a_2<a_1\leq 1\Big\}. 
\end{align*} 
Using some simple calculation, we see that $F(m)$ is an increasing sequence in $m\in \D N$. Thus, we see that 
\[\min\set{F(m) : m\in \D N}=F(1)=-2+\frac{1}{12} \left(\pi ^2+36-6 \log ^22\right)-\frac{1}{8} (2+\log 4)^2\approx 0.148867,\]
 and it occurs when $a_1=1$ and $a_2=\frac{1}{4} (2+\log 4)$.


\tit{Case~2: One element is on $S_1$ and one element is on $S_2$.}




Then, we can write $\ga_2=\set{(a_1, \sqrt 3(1-a_1)),  (a_2, \sqrt 3 a_2)}$ such that $0 \leq a_2\leq \frac 12 \leq a_1\leq 1$. 

Assume that the Voronoi region of $(a_1, \sqrt 3(1-a_1))$ contains first $m$ elements from the support of $P$. Then, the remaining elements will be contained in the Voronoi region of $(a_2, \sqrt 3 a_2)$. Let $G(m)$ denote the minimum distortion error when the Voronoi region of $(a_1, \sqrt 3(1-a_1))$ contains first $m$ elements from the support of $P$. Then, we have 
\begin{align*}
G(m)=\min\Big\{ \sum_{j=1}^m \frac 1{2^j} \rho\Big(\frac 1 j, (a_1, \sqrt 3(1-a_1))\Big)+\sum_{j=m+1}^\infty \frac 1{2^j} \rho\Big(\frac 1 j, (a_2, \sqrt 3 a_2)\Big)   :0 \leq a_2\leq \frac 12 \leq a_1\leq 1\Big\}. 
\end{align*} 
Using some simple calculation, we see that $G(m)$ is an increasing sequence in $m\in \D N$. Thus, we see that 
\[\min\set{G(m) : m\in \D N}=G(1)=\frac{\pi ^2}{12}+\frac{1}{8} \left(-5-8 \log ^22+\log 16\right)\approx 0.0635876,\]
 and it occurs when $a_1=1$ and $a_2=\frac{1}{4} (\log 4-1)$.

\tit{Case~3: Both elements are on $S_2$.}


Then, we can write $\ga_2=\set{(a_1, \sqrt 3 a_1),  (a_2, \sqrt 3 a_2}$ such that $0 \leq a_2< a_1\leq \frac 12$. 

Assume that the Voronoi region of $(a_1, \sqrt3 a_1)$ contains first $m$ elements from the support of $P$. Then, the remaining elements will be contained in the Voronoi region of $(a_2, \sqrt 3 a_2)$. Let $H(m)$ denote the minimum distortion error when the Voronoi region of $(a_1, \sqrt 3a_1)$ contains first $m$ elements from the support of $P$. Then, we have 
\begin{align*}
H(m)=\min\Big\{ \sum_{j=1}^m \frac 1{2^j} \rho\Big(\frac 1 j, (a_1, \sqrt 3a_1)\Big)+\sum_{j=m+1}^\infty \frac 1{2^j} \rho\Big(\frac 1 j, (a_2, \sqrt 3 a_2)\Big)   :0 \leq a_2\leq \frac 12 \leq a_1\leq 1\Big\}. 
\end{align*} 
Using some simple calculation, we see that $H(m)$ is an increasing sequence in $m\in \D N$. Thus, we see that 
\[\min\set{H(m) : m\in \D N}=H(1)=\frac{\pi ^2}{12}+\frac{1}{8} \left(-1-8 \log ^2(2)+\log 16\right)\approx 0.563588,\]
 and it occurs when $a_1=\frac 12$ and $a_2=\frac{1}{4} (\log 4-1)$.

Comparing Case~1 through Case~3, we can deduce that an optimal set of two-points occurs in Case~2, i.e.,  an optimal set of two-points is given by  
$\set{(1,0), (\frac{1}{4} (\log 4-1),\frac{1}{4} \sqrt{3} (\log 4-1))}$ with constrained quantization error 
\[ V_2^{(c)}=\frac{\pi ^2}{12}+\frac{1}{8} \left(-5-8 \log ^22+\log 16\right)\approx 0.0635876.\]
which yields the proposition. 
\end{proof}

\begin{remark1}
By Proposition~\ref{propD2}, we have $\ga_2=\set{(1,0), (\frac{1}{4} (2\log 2-1),\frac{1}{4} \sqrt{3} (2\log 2-1))}$. Then, by Proposition~\ref{propim}, we obtain an unconstrained optimal set of two-means as 
\[U_1^{-1}(\ga_2\ii S_1^{(1)})\uu U_2^{-1}(\ga_2\ii S_2^{(2)})=\set{1, 2\log 2-1}\]
In fact, $\set{1, 2\log 2-1}$ forms an unconstrained optimal set of two-means (see \cite {CHMR}).
\end{remark1} 

\begin{lemma1} \label{lemma22} 
Let $\ga_n$ be a constrained optimal set of $n$-points for $n\geq 2$. Then, $\ga_n$ contains elements from both $S_1$ and $S_2$. 
\end{lemma1} 

\begin{proof}
By Proposition~\ref{propD2}, the lemma is true for $n=2$. We now prove that the lemma is true for $n\geq 3$. 
Let $\ga_n$ be an optimal set of $n$-points for some $n\geq 3$, and the corresponding $n$th constrained quantization error is $V_n$. Then, 
$V_n\leq V_2$, i.e., $V_n\leq  0.0635876$. For the sake of contradiction, assume that $\ga_n$ does not contain any element from $S_1$. Then, the element $1$ from the support of $P$ must be contained in the Voronoi region of an element $(a_1, \sqrt  3 a_1)\in \ga_n\ii S_2$. Then, 
\[V_n\geq \frac 1{2} \rho\Big(1,  (a_1, \sqrt 3 a_1)\Big)=2 a_1^2-a_1+\frac{1}{2},\]
the minimum value of which is $\frac{3}{8}$ and it occurs when $a_1=\frac 14$. Thus, we have $V_n\geq \frac 38>V_n$, which is a contradiction. 
Hence, $\ga_n$ contains an element from $S_1$. Next, for the sake of contradiction, assume that $\ga_n$ does not contain any element from $S_2$. Then, we can write 
\[\ga_n:=\set{(a_1, \sqrt 3(1-a_1)), (a_2, \sqrt 3(1-a_2)), \cdots}, \te{ where } \frac 12\leq \cdots<a_2<a_1.\]
 Clearly the Voronoi region of $(a_1, \sqrt 3 (1-a_1))$ contains $1$ from the support of $P$. Suppose that the Voronoi region of $(a_1, \sqrt 3 (1-a_1))$ also contains $1$, $\frac 12$ and $\frac 13$. Then,
\[V_n\geq \sum_{j=1}^3 \frac 1{2^j} \rho\Big(\frac 1 j,  (a_1, \sqrt 3(1-a_1))\Big)=\frac{1}{144} \left(12 a_1 \left(42 a_1-79\right)+461\right),\]
the minimum value of which is $\frac{71}{672}$ and it occurs when $a_1=\frac{79}{84}$. Thus, we see that $V_n\geq \frac{79}{84}>V_n$, which is a contradiction. 
 Suppose that the Voronoi region of $(a_1, \sqrt 3 (1-a_1))$ contains only $1$ and $\frac 12$. Then, the Voronoi region of $(a_2, \sqrt 3 (1-a_2))$ must contain $\frac 13$. Then,  
\begin{align*}
V_n&\geq \sum_{j=1}^2 \frac 1{2^j} \rho\Big(\frac 1 j,  (a_1, \sqrt 3(1-a_1))\Big)+\frac 1{2^3} \rho\Big(\frac 13,  (a_2, \sqrt 3(1-a_2))\Big)=3 a_1^2-\frac{23 a_1}{4}+\frac{1}{6} a_2 \left(3 a_2-5\right)+\frac{461}{144},
\end{align*} 
the minimum value of which is $\frac{19}{192}$ and it occurs when $a_1=\frac{23}{24}$ and $a_2=\frac{5}{6}$. Thus, we see that $V_n\geq \frac{19}{192}>V_n$, which leads to a contradiction. Hence, we can assume that the Voronoi region of $(a_1, \sqrt 3 (1-a_1))$ contains only the element $1$. Hence, the Voronoi region of $(a_2, \sqrt 3 (1-a_2))$ must contain the element $\frac 12$ from the support of $P$. Suppose that it also contains $\frac 13$. Then, 
\begin{align*}
V_n&\geq   \frac 1{2} \rho\Big(1,  (a_1, \sqrt 3(1-a_1))\Big)+\sum_{j=2}^3 \frac 1{2^j} \rho\Big(\frac 1 j,  (a_2, \sqrt 3(1-a_2))\Big)=2 a_1^2-4 a_1+\frac{3 a_2^2}{2}-\frac{31 a_2}{12}+\frac{461}{144},
\end{align*}
the minimum value of which is $\frac{77}{864}$ and it occurs when $a_1=1$ and $a_2= \frac{31}{36}$. Thus, we see that $V_n\geq \frac{77}{864}>V_n$, which yields a contradiction. 
Hence, we can assume that the Voronoi region of $(a_2, \sqrt 3 (1-a_2))$ contains only the element $\frac 12$. Hence, the Voronoi region of $(a_3, \sqrt 3 (1-a_3))$ must contain the element $\frac 13$. Then, 

\begin{align*}
V_n&\geq   \frac 1{2} \rho\Big(1,  (a_1, \sqrt 3(1-a_1))\Big)+\frac 1{2^2} \rho\Big(\frac 12,  (a_2, \sqrt 3(1-a_2))\Big)+ \frac 1{2^3} \rho\Big(\frac 1 j,  (a_3, \sqrt 3(1-a_3))\Big)\\
&=2 a_1^2-4 a_1+a_2^2+\frac{a_3^2}{2}-\frac{7 a_2}{4}-\frac{5 a_3}{6}+\frac{461}{144},
\end{align*}
the minimum value of which is $\frac{17}{192}$, and it occurs when $a_1= 1, \, a_2=\frac{7}{8}$, and $a_3=\frac{5}{6}$. 
Hence, $V_n\geq \frac{17}{192}>V_n$, which is a contradiction. 

Thus, we see that if $\ga_n$ does not contain any element from $S_2$, we get into a contradiction. Thus, we see that $\ga_n$ contains an element from $S_2$. 
In the beginning we have shown that $\ga_n$ contains an element from $S_1$. Thus, the proof of the lemma is complete. 
\end{proof} 


Recall Lemma~\ref{lemma22}. Then, using a similar technique as Proposition~\ref{propD2}, the following proposition can be proved.  

\begin{prop1} \label{propD3} 
Let $\ga_3$ be an optimal set of three-points with constrained quantization error $V_3$. Then, 
\begin{align*}
\ga_3=\set{(1,0), & (\frac{7}{8},\frac{\sqrt{3}}{8}),  (\frac{1}{8} (8 \log 2-5),\frac{1}{8} \sqrt{3} (8 \log 2-5))},  \te{ or } \\
& \set{(1,0),  (\frac{1}{8},\frac{\sqrt{3}}{8}),  (\frac{1}{8} (8 \log 2-5),\frac{1}{8} \sqrt{3} (8 \log 2-5))}
\end{align*} with
\[ V_3^{(c)}=\frac{1}{96} \left(8 \pi ^2-87-144 \log ^22+120 \log 2\right)\approx 0.0619715.\]
\end{prop1}
\begin{remark1}
By Proposition~\ref{propD3}, we know the constrained optimal set $\ga_3$ of three-points. Then, by Proposition~\ref{propim}, we obtain an unconstrained optimal set of three-means as 
\[U_1^{-1}(\ga_3\ii S_1^{(1)})\uu U_2^{-1}(\ga_3\ii S_2^{(2)})=\set{1, \frac 12, \frac{1}{2} (8 \log 2-5)}.\]
In fact, $\set{1, \frac 12, \frac{1}{2} (8 \log 2-5)}$ forms an unconstrained optimal set of three-means (see \cite {CHMR}).
\end{remark1}
\begin{lemma1} \label{lemmaIm} 
For $ n \geq 3 $, let $ \ga_n $ denote a constrained optimal set of $ n $-points for the probability measure $ P $. Then, the cardinality of $ \ga_n \cap S_1 $, denoted by $ \mathrm{card}(\ga_n \cap S_1) $, is either one or two, and not more than two. 
\end{lemma1} 
\begin{proof}
Let $\ga_n$ be a constrained optimal set of $n$-points for any $n\geq 3$ with constrained quantization error $V_n$. Then, 
\[V_n\leq V_3\leq 0.0619715.\]
 By Lemma~\ref{lemma22}, we see that $\te{card}(\ga_n\ii S_1)\geq 1$. We now show that $\te{card}(\ga_n\ii S_1)<3$. For the sake of contradiction assume that $\te{card}(\ga_n\ii S_1)\geq 3$. Then,  we can write 
\[\ga_n:=\set{(a_1, \sqrt 3(1-a_1)), (a_2, \sqrt 3(1-a_2)), \cdots}, \te{ where } \frac 12\leq \cdots<a_2<a_1.\]
As shown in Lemma~\ref{lemma22}, we can see that the Voronoi region of $(a_1, \sqrt 3 (1-a_1))$ contains only the element $1$, and the Voronoi region of $(a_2, \sqrt 3 (1-a_2))$ contains only the element $\frac 12$. Hence, the Voronoi region of $(a_3, \sqrt 3 (1-a_3))$ must contain the element $\frac 13$. Then, 
\begin{align*}
V_n&\geq   \frac 1{2} \rho\Big(1,  (a_1, \sqrt 3(1-a_1))\Big)+\frac 1{2^2} \rho\Big(\frac 12,  (a_2, \sqrt 3(1-a_2))\Big)+ \frac 1{2^3} \rho\Big(\frac 1 j,  (a_3, \sqrt 3(1-a_3))\Big)\\
&=2 a_1^2-4 a_1+a_2^2+\frac{a_3^2}{2}-\frac{7 a_2}{4}-\frac{5 a_3}{6}+\frac{461}{144},
\end{align*}
the minimum value of which is $\frac{17}{192}$, and it occurs when $a_1= 1, \, a_2=\frac{7}{8}$, and $a_3=\frac{5}{6}$. 
Hence, $V_n\geq \frac{17}{192}>V_n$, which is a contradiction. Hence, $\te{card}(\ga_n\ii S_1)<3$. We now show that $\te{card}(\ga_n\ii S_1)$ can be either one or two. By Proposition~\ref{propD3}, we see that $\te{card}(\ga_n\ii S_1)$ can be either one or two for $n=3$. We now claim that $\te{card}(\ga_n\ii S_1)$ can be either one or two for $n\geq 4$. The distortion error contributed by the set
\[\gb:= \set{(1,0), (\frac{1}{8},\frac{\sqrt{3}}{8}), (\frac{1}{12},\frac{1}{4 \sqrt{3}}),  (\frac{2}{3} (3 \log (2)-2),\frac{2 (3 \log (2)-2)}{\sqrt{3}})},\]
is given by 
\begin{align*}
 V(P; \gb)&=\frac 1{2} \rho\Big(1,  (1,0))\Big)+ \frac 1{2^2} \rho\Big(\frac 1 2,  (\frac{1}{8},\frac{\sqrt{3}}{8})\Big)+ \frac 1{2^3} \rho\Big(\frac 1 2,  (\frac{1}{12},\frac{1}{4 \sqrt{3}})\Big)\\
 & +\sum_{j=4}^\infty \frac 1{2^j} \rho\Big(\frac 1 j,   (\frac{2}{3} (3 \log 2-2),\frac{2 (3 \log 2-2)}{\sqrt{3}})\Big)=0.0617409.
\end{align*}
Let $\ga_n:=\set{c_1, c_2, c_3, \cdots}$ be a constrained optimal set of $n$-points for $n\geq 4$ with constrained quantization error $V_n$. Then,
\[V_n\leq V_4\leq0.0617409.\] By Lemma~\ref{lemma22}, we know $c_1\in S_1$.
For sure, we know that $c_j\in S_2$ for all $j\geq 3$. We now show that the Voronoi region of $c_2$ contains only the element $\frac 12$.  

The following two cases can arise. 

\tit{Case~1. $c_2\in S_1$.}  

Then, as shown in the proof of Lemma~\ref{lemma22}, we can say that the Voronoi region of $c_2$ contains only the element $\frac 12$. 

\tit{Case~2. $c_2\in S_2$.}

Then, we can write $c_1=(a_1, \sqrt 3(1-a_1))$ and $c_j=(a_j, \sqrt 3 a_j)$ for $j\geq 2$ such that $0<\cdots <a_{j+1}<a_j\leq \frac 12 \leq  a_1\leq 1$.  The Voronoi region of $(a_1, \sqrt 3(1-a_1))$ must contain $1$. Suppose that it also contains $\frac 12$ and $\frac 13$. 
Then, 
\[V_n\geq \sum_{j=1}^3\frac 1 {2^j} \rho\Big(\frac 1 j,  (a_1, \sqrt 3(1-a_1))\Big)\geq \frac{71}{672}>V_n,\]
and the minimum value occurs when $a_1=\frac{79}{84}$.  
 Thus, we arrive at a contradiction. Now, assume that the Voronoi region of $(a_1, \sqrt 3(1-a_1))$ contains only the elements $1$ and $\frac 12$. Then, the Voronoi region of $(a_2, \sqrt 3 a_2)$ must contain $\frac 13$. Then, 
 \[V_n\geq \sum_{j=1}^2\frac 1 {2^j} \rho\Big(\frac 1 j,  (a_1, \sqrt 3(1-a_1))\Big)+\frac 1{2^3}  \rho\Big(\frac 1 3,  (a_2, \sqrt 3a_2)\Big) \geq\frac{13}{192}>V_n,\] 
 and the minimum value occurs when $a_1=\frac{23}{24}$ and $a_2=\frac 1 {12}$. Thus, we see a contradiction arises. Hence, we can assume that the Voronoi region of $(a_1, \sqrt 3(1-a_1))$ contains only the element $1$. Then, the Voronoi region of $(a_2,\sqrt 3 a_2)$ must contain the element $\frac 12$. Suppose that the Voronoi region of $(a_2,\sqrt 3 a_2)$ also contains the elements $\frac 13$, $\frac 14$ and $\frac 15$. Then, 
 \[V_n\geq \sum_{j=1}^1\frac 1 {2^j} \rho\Big(\frac 1 j,  (a_1, \sqrt 3(1-a_1))\Big)+\sum_{j=2}^5\frac 1 {2^j} \rho\Big(\frac 1 j,   (a_2, \sqrt 3a_2)\Big) \geq\frac{108149}{1728000}>V_n,\] 
 and the minimum value occurs when $a_1=1$ and $a_2=\frac{181}{1800}$. Thus, we get a contradiction arises. Hence, we can assume that the Voronoi region of $(a_2, \sqrt 3 a_2)$ contains only the element $\frac 12$, $\frac 13$ and $\frac 14$. Then,  the Voronoi region of $(a_3, \sqrt 3 a_3)$ must contain the element $\frac 15$. Then,  
 \[V_n\geq \sum_{j=1}^1\frac 1 {2^j} \rho\Big(\frac 1 j,  (a_1, \sqrt 3(1-a_1))\Big)+\sum_{j=2}^4\frac 1 {2^j} \rho\Big(\frac 1 j,   (a_2, \sqrt 3a_2)\Big) +\sum_{j=5}^5\frac 1 {2^j} \rho\Big(\frac 1 j,   (a_3, \sqrt 3a_3)\Big)\geq\frac{14341}{230400}>V_n,\] 
 and the minimum value occurs when $a_1=1$, $a_2=\frac{5}{48}$, and $a_3=\frac{1}{20}$, which is a contradiction. Hence, we can assume that the Voronoi region of $(a_2, \sqrt 3 a_2)$ contains only the element $\frac 12$ and $\frac 13$. Then,  the Voronoi region of $(a_3, \sqrt 3 a_3)$ must contain the element $\frac 14$. Suppose it also contains $\frac 15$.  Then,  
 \[V_n\geq \sum_{j=1}^1\frac 1 {2^j} \rho\Big(\frac 1 j,  (a_1, \sqrt 3(1-a_1))\Big)+\sum_{j=2}^3\frac 1 {2^j} \rho\Big(\frac 1 j,   (a_2, \sqrt 3a_2)\Big) +\sum_{j=4}^5\frac 1 {2^j} \rho\Big(\frac 1 j,   (a_3, \sqrt 3a_3)\Big)\geq \frac{21341}{345600}>V_n,\] 
 and the minimum value occurs when $a_1=1$, $a_2=\frac{1}{9}$, and $a_3=\frac{7}{120}$,  which is a contradiction. Thus, we can assume that  the Voronoi region of $(a_3, \sqrt 3 a_3)$ contains only the element $\frac 14$. Then, the Voronoi region of $(a_4, \sqrt 3 a_4)$ must contain $\frac 15$. Notice that if $n=4$, then the Voronoi region of $(a_4, \sqrt 3 a_4)$ will also contain $\frac 16$, and as before we can see that a contradiction arises. Hence, for $n=4$, we can assume that the Voronoi region of $a_2$ contains only the element $\frac 12$. Suppose that $n\geq 5$. 
 Then, if the Voronoi region of $(a_4, \sqrt 3 a_4)$ also contains $\frac 16$, likewise, we can show a contradiction arises. Suppose that the Voronoi region of $(a_4, \sqrt 3 a_4)$ contains only the element $\frac 15$. Then, the Voronoi region of $(a_5, \sqrt 3 a_5)$ must contains $\frac 16$. Then, 
\begin{align*}
V_n&\geq \sum_{j=1}^1\frac 1 {2^j} \rho\Big(\frac 1 j,  (a_1, \sqrt 3(1-a_1))\Big)+\sum_{j=2}^3\frac 1 {2^j} \rho\Big(\frac 1 j,   (a_2, \sqrt 3a_2)\Big) +\sum_{j=4}^4\frac 1 {2^j} \rho\Big(\frac 1 j,   (a_3, \sqrt 3a_3)\Big)\\
& +\sum_{j=5}^5\frac 1 {2^j} \rho\Big(\frac 1 j,   (a_4, \sqrt 3a_4)\Big)+\sum_{j=6}^6\frac 1 {2^j} \rho\Big(\frac 1 j,   (a_5, \sqrt 3a_5)\Big)\geq \frac{21449}{345600}>V_n,
\end{align*} 
 and the minimum value occurs when $a_1=1$, $a_2=\frac 1 9$, $a_3=\frac{1}{16}$, $a_4=\frac{1}{20}$, and $a_5=\frac{1}{24}$, which gives a contradiction. Hence, we can assume that the Voronoi region of $c_2:=(a_2, \sqrt 3 a_2)$ contains only the element $\frac 12$. 

 Thus, in both the cases we see that the Voronoi region of $c_2$ contains only the element $\frac 12$. Notice that if $c_2:=(a_2, \sqrt 3(1-a_2))\in S_1$, then the distortion error contributed by $c_2$ in its own Voronoi region is given by 
 \[\frac 1 2^{2} \rho\Big(\frac 12,(a_2, \sqrt 3(1-a_2)\Big),\]
the minimum value of which is $\frac 3{64}$, and it occurs when $a_2=\frac 78$. If $c_2:=(a_2, \sqrt 3a_2)\in S_2$, then the distortion error contributed by $c_2$ in its own Voronoi region is given by 
 \[\frac 1 2^{2} \rho\Big(\frac 12,(a_2, \sqrt 3a_2\Big),\]
the minimum value of which is $\frac 3{64}$, and it occurs when $a_2=\frac 18$. 
Since the distortion error given by $c_2$ when $c_2\in S_1$ is same as the distortion error when $c_2\in S_2$, we can say that in an optimal set of $n$-points for $n\geq 3$, $c_2$ can belong to either $S_1$ or $S_2$, which yields the fact that $\te{card}(\ga_n \cap S_1)$, attain either one or two. We have also shown that $\te{card}(\ga_n \cap S_1)<3$. Thus, the proof of the lemma is complete. 
\end{proof} 

 \begin{remark1} \label{rem45} 
 Because of Lemma~\ref{lemmaIm}, in the sequel in calculating the constrained optimal sets of $n$-points for any $n\geq 4$, we will assume that $\ga_n$ takes only one element from $S_1$ and the remaining $(n-1)$ elements it takes from $S_2$. Moreover, not directly calculating the constrained optimal sets of $n$-points for any $n\geq 4$, we will use our knowledge of unconstrained optimal sets of $n$-means for $n\geq 4$, and then will use Proposition~\ref{propim} to calculate the constrained optimal sets of $n$-points and the corresponding $n$th constrained quantization error as follows: 
Let  $\gb_n:=\Big\{Av[q_j^{(1)}, q_j^{(2)}] : 1\leq j\leq n\Big\}$ be an unconstrained optimal set of $n$-means for $P$ with the $n$th unconstrained quantization error $V_n^{(u)}(P)$, and let $\ga_n$ be a constrained optimal wet of $n$-points for $P$ with $n$th constrained quantization error $V_n^{(c)}(P)$. Then, 
\begin{equation} \label{eqM1} \begin{aligned}
\ga_n &=\set{U_1(Av[q_1^{(1)}, q_1^{(2)}])}\UU \set{U_2(Av[q_j^{(1)}, q_j^{(2)}]) : 2\leq j\leq n}, \te{ and } \\
V_n^{(c)}(P)&=V_n^{(u)}(P)+ \frac 34 \sum_{j=2}^n\sum_{i=q_j^{(1)}}^{q_j^{(2)}}\frac 1{2^i}(Av[q_j^{(1)}, q_j^{(2)}])^2.    
\end{aligned}
\end{equation} 
 \end{remark1} 
The following theorem gives the constrained optimal set of $n$-points and the corresponding $n$th constrained quantization errors for $1\leq n\leq 2000$. 
\begin{theo1} \label{theo1}
For any positive integer $n$, if $1\leq n\leq 5$, then the sets 
\[\set{U_2(Av[n, \infty)), U_2(\frac 1 {n-1}),  \cdots, U_2(\frac 13), U_2(\frac 12), U_1(1)},\] where $1\leq n\leq 5$, form  constrained optimal sets of $n$-points;  on the other hand, if $6\leq n\leq 2000$, then the sets $\set{U_2(Av[n+1, \infty)), U_2(Av[n-1, n]), U_2(\frac 1 {n-2}), \cdots, U_2(\frac 13), U_2(\frac 12), U_1(1)}$ form constrained optimal sets of $n$-points for the probability measure $P$. The corresponding $n$th constrained quantization errors are given by 
\begin{align*} 
 V_n^{(c)}(P)=\left\{\begin{array}{cc}
 Er[n, \infty]+\frac 34 \mathop{\sum}\limits_{j=2}^{n-1}\frac 1 {2^j} (\frac 1 j)^2+\frac 34 \mathop{\sum}\limits_{j=n}^\infty \frac 1{2^j} (Av[n, \infty])^2 & \te{ if } 1\leq n\leq 5, \\
\Big(Er[n+1, \infty]+Er[n-1, n]+\frac 34 \mathop{\sum}\limits_{j=2}^{n-2}\frac 1 {2^j} (\frac 1 j)^2+\frac 34\frac 1{2^{n-1}} (Av[n-1, n])^2 \\
+\frac 34 \mathop{\sum}\limits_{j=n}^\infty \frac 1{2^j} (Av[n, \infty])^2\Big)  & \te{ if } 6\leq n\leq 2000.
\end{array}
\right.
\end{align*} 
\end{theo1}

 \begin{proof}
 By \cite[Theorem~4.8]{CHMR}, it is known that 
for any positive integer $n$, the sets 
\begin{equation} \label{eqM4567} \set{Av[n, \infty], \frac 1 {n-1},  \cdots, \frac 13, \frac 12, 1},
\end{equation}  where $1\leq n\leq 5$, form unconstrained optimal sets of $n$-means for the probability measure $P$ with unconstrained quantization errors
\begin{equation} \label{eqM4568 }V_n(P):=Er[n, \infty].
\end{equation} 
Write 
\begin{equation} \label{eqM45}  \ga_n:=\set{Av[n+1, \infty], Av[n-1, n], \frac 1 {n-2}, \cdots, \frac 13, \frac 12, 1}
\end{equation}  and 
\begin{equation} \label{eqM46} V_n(P):=Er[n+1, \infty]+Er[n-1, n].
\end{equation} 
We now prove the following claim: 

\tit{Claim. The set $\ga_n$ given by \eqref{eqM45} for $n=2000$ form an optimal set of $n$-means with unconstrained quantization error $V_n(P)$ given by \eqref{eqM46}. }

The distortion error contributed by the set $\gb:=\set{Av[2001, \infty], Av[1999, 2000], \frac 1{1998}, \cdots, \frac 12, 1}$ is given by 
\[V(P; \gb)=Er[2001, \infty]+Er[1999, 2000]=1.4444190239372496100\times 10^{-615}. \]
Since $V_{2000}$ is the unconstrained quantization error, we have 
\[V_{2000}\leq 1.4444190239372496100\times 10^{-615}.\]
Let $\ga_n:=\set{a_{2000}, a_{1999}, a_{1997}, \cdots, a_2, a_1}$ form an optimal set of $n$-means for $P$ with unconstrained quantization error $V_n$. We show that $a_1=1$. Clearly, the Voronoi region of $a_1$ contains $1$. Suppose it also contains the element $\frac 12$. Then, 
\[V_n\geq Er[1,2]>V_n,\]
which is a contradiction. Hence, the Voronoi region of $a_1$ contains only the element $1$, i.e., $a_1=1$. Similarly, we can show it $a_i=\frac 1 i$ for all $1\leq i\leq 1997$. Now, we show that $a_{1998}=\frac 1{1998}$. As $a_i=\frac 1i$ for $1\leq i\leq 1997$, the Voronoi region of $a_{1998}$ must contain $\frac 1{1998}$. Suppose that the Voronoi region of $a_{1998}$ also contains $\frac 1{1999}$ and $\frac 1{2000}$. Then, 
\[V_n\geq Er[1998, 2000]=2.0264380104700818609 \times 10^{-615}>V_n,\]
which leads to a contradiction. Suppose that the Voronoi region of $a_{1998}$ contains only $\frac 1{1998}$ and $\frac 1{1999}$. Then, the Voronoi region of $a_{1999}$ must contain $\frac 1{2000}$. Suppose that the Voronoi region of $a_{1999}$ also contains $\frac 1{i}$ for $i=2001, 2002, 2003$. Then, 
\[V_n\geq Er[1998, 1999]+Er[2000, 2003]=1.6059068732253525792\times 10^{-615}>V_n,\]
which leads to a contradiction. Suppose that the Voronoi region of $a_{1999}$ contains only the elements $\frac 1{i}$ for $i=2000, 2001, 2002$. Then, the Voronoi region of $a_{2000}$ contains all the remaining elements $\frac 1 i$ for $i\geq 2003$. Then, 
\[V_n\geq Er[1998, 1999]+Er[2000, 2002]+Er[2003, 2010]=1.4671459164463424875\times 10^{-615}>V_n,\]
which yields a contradiction. Suppose that the Voronoi region of $a_{1999}$ contains only the elements $\frac 1{i}$ for $i=2000, 2001$. Then, the Voronoi region of $a_{2000}$ contains all the remaining elements $\frac 1 i$ for $i\geq 2002$. Then,
\[V_n\geq Er[1998, 1999]+Er[2000, 2001]+Er[2002, 2015]=1.4455437344001957110\times 10^{-615}>V_n,\]
which yields a contradiction. Suppose that the Voronoi region of $a_{1999}$ contains only the elements $\frac 1{i}$ for $i=2000$. Then, the Voronoi region of $a_{2000}$ contains all the remaining elements $\frac 1 i$ for $i\geq 2001$. Thus,  
\[V_n\geq Er[1998, 1999]+Er[2001, 2015]=1.8054463072890087690\times 10^{-615}>V_n,\]
which leads to a contradiction.  

Thus, we can assume that the Voronoi region of $a_{1998}$ contains only $\frac 1{1998}$, i.e., $a_{1998}=\frac 1{1998}$. We now show that the Voronoi region of $a_{1999}$ contains only the element $Av[1999, 2000]$. The Voronoi region of $a_{1999}$ must contain $\frac 1{1999}$. Suppose that it also contains $\frac 1 i$ for $i=2000, 2001, 2002$. Then, 
\[V_n\geq Er[1999, 2002]=1.7593293901236548092 \times 10^{-615}>V_n,\]
which gives  a contradiction. Suppose that the Voronoi region of $a_{1999}$ contains only $\frac 1{1999}$, $\frac 1{2000}$, and $\frac 1{2001}$. Then, the Voronoi region of $a_{2000}$ must contain the remaining elements. Then, 
\[V_n\geq Er[1999, 2001]+Er[2002, 2010]=1.5071509625668501342\times 10^{-615}>V_n,\]
which yields a contradiction. Suppose that the Voronoi region of $a_{1999}$ contains only $\frac 1{1999}$. Then, the Voronoi region of $a_{2000}$ must contain the remaining elements. Then, 
\[V_n\geq Er[2000, 2010]=1.5159843420767176934\times 10^{-615}>V_n,\]
which leads to a contradiction. Hene, we can assume that the Voronoi region of $a_{1999}$ contains only the elements $\frac 1{1999}$ and $\frac 1{2000}$, and then the remaining elements are contained in the Voronoi region of $a_{2000}$. Thus, we have 
\[a_{1999}=Av[1999, 2000] \te{ and } a_{2000}=Av[2001, \infty],\]
i.e., the set $\ga_n$ given by \eqref{eqM45} for $n=2000$ form an optimal set of $n$-means with unconstrained quantization error $V_n(P)$ given by \eqref{eqM46}. Thus, the claim is true.  

Proceeding in the similar way as the proof of the claim, it can be proved that the set $\ga_n$ given by \eqref{eqM45} form optimal sets of $n$-means with unconstrained quantization errors $V_n(P)$ given by \eqref{eqM46} for all $6\leq n\leq 1999$, i.e., the set $\ga_n$ given by \eqref{eqM45} form optimal sets of $n$-means with unconstrained quantization errors $V_n(P)$ given by \eqref{eqM46} for all $6\leq n\leq 2000$. Hence, by Proposition~\ref{propim}, the proof of the theorem is obtained. 
 \end{proof} 

 As a consequence of Theorem~\ref{theo1}, the following open problem arises. 
 \begin{open}
It is still not known whether the sets $\set{Av[n+1, \infty], Av[n-1, n], \frac 1 {n-2}, \cdots, \frac 13, \frac 12, 1}$ give the unconstrained optimal sets of $n$-means for all positive integers $n\geq 2001$. If not, then the least upper bound of $n\in \D N$ for which such sets give the unconstrained optimal sets of $n$-means for the probability measure $P$ is not known yet. Consequently, constrained optimal sets of $n$-points for all positive integers $n\geq 2001$ are not known yet. 
 \end{open} 

